import argparse
import random
import string
class ClientPluginConnectionManager:
    def __init__(self):
        self.parser = argparse.ArgumentParser(description='Client-Plugin Connection Manager')
        self.add_arguments(self.parser)
    def add_arguments(self, parser):
        parser.add_argument(
            '-p', '--port',
            help=f'client-plugin connection port.',
            metavar='port',
            default='5431',
        )
        parser.add_argument(
            '-t', '--token',
            help=f'client-plugin connection token (default: random token).',
            metavar='token',
            default=None,
        )
    def generate_random_token(self):
        return ''.join(random.choices(string.ascii_letters + string.digits, k=10))
    def establish_connection(self, port, token):
        print(f"Establishing connection using port {port} and token {token}.")
    def run(self):
        args = self.parser.parse_args()
        port = args.port
        token = args.token if args.token else self.generate_random_token()
        self.establish_connection(port, token)
if __name__ == "__main__":
    manager = ClientPluginConnectionManager()
    manager.run()

