# Define a WebSocket route `/ws` that handles incoming WebSocket connections.
@router.websocket("/ws")
async def websocket_endpoint(websocket: WebSocket):
    await websocket.accept()
    while True:
        data = await websocket.receive_text()
        try:
            message = json.loads(data)
            # Implement a subscription mechanism where clients can subscribe to a specific topic.
            if message.get("action") == "subscribe":
                topic = message.get("topic")
                pubsub.subscribe(topic, websocket)
            # Handle incoming messages from clients and publish them to the appropriate topic.
            elif message.get("action") == "publish":
                topic = message.get("topic")
                payload = message.get("payload")
                pubsub.publish(topic, payload)
        except json.JSONDecodeError:
            pass

from typing import List
def escapeGhosts(ghosts: List[List[int]], target: List[int]) -> bool:
    player_distance = abs(target[0]) + abs(target[1])  # Manhattan distance from player to target
    for ghost in ghosts:
        ghost_distance = abs(target[0] - ghost[0]) + abs(target[1] - ghost[1])  # Manhattan distance from ghost to target
        if ghost_distance <= player_distance:
            return False  # Player can be caught by this ghost
    return True  # Player can reach the target without being caught by any ghosts

