import pytest
class Quaternion:
    def __init__(self, w, x, y, z):
        self.w = w
        self.x = x
        self.y = y
        self.z = z
    @property
    def one(self):
        return Quaternion(1, 0, 0, 0)
    @property
    def x(self):
        return Quaternion(0, 1, 0, 0)
    @property
    def y(self):
        return Quaternion(0, 0, 1, 0)
    @property
    def z(self):
        return Quaternion(0, 0, 0, 1)
    def __mul__(self, scalar):
        result = Quaternion(self.w * scalar, self.x * scalar, self.y * scalar, self.z * scalar)
        if not np.isclose(np.linalg.norm([result.w, result.x, result.y, result.z]), 1):
            raise ValueError("Resulting quaternion is not a unit quaternion")
        return result
# Test cases
def test_quaternion_constants():
    assert np.equal(Quaternion.one, Quaternion(1, 0, 0, 0))
    assert np.equal(Quaternion.x, Quaternion(0, 1, 0, 0))
    assert np.equal(Quaternion.y, Quaternion(0, 0, 1, 0))
def test_scalar_multiplication():
    q = Quaternion(1, 2, 3, 4)
    with pytest.raises(ValueError):
        q *= 1.2

