import subprocess
import shlex
def shell_pipe(command: str) -> str:
    commands = command.split('|')
    output = None
    for cmd in commands:
        popen_kw = {
            'stdout': subprocess.PIPE,
            'stderr': subprocess.PIPE,
            'stdin': subprocess.PIPE,
        }
        command_split = shlex.split(cmd)
        if output is not None:
            popen_kw['stdin'] = subprocess.PIPE
            process = subprocess.Popen(command_split, **popen_kw, stdin=subprocess.PIPE, stdout=subprocess.PIPE)
            output, _ = process.communicate(input=output.encode())
        else:
            process = subprocess.Popen(command_split, **popen_kw)
            output, _ = process.communicate()
    return output.decode()

