import random
def selection_sort(arr, n):
    for i in range(n-1):
        min_index = i
        for j in range(i+1, n):
            if arr[j] < arr[min_index]:
                min_index = j
        arr[i], arr[min_index] = arr[min_index], arr[i]
def print_list(arr, n):
    for i in range(n):
        print(arr[i], end=" ")
    print()
