import threading
def thread_worker(thread_id):
    print(f"Thread {thread_id} is doing some work")
def main():
    toLock = True  # Set to True if the lock needs to be released and acquired
    imp = threading.Lock()  # Initialize a lock
    # Create a list of threads
    threads = [threading.Thread(target=thread_worker, args=(i,)) for i in range(5)]
    # Start all threads in this batch
    if toLock:
        imp.release()  # Release the lock if toLock is True
    for thread in threads:
        thread.start()
    # Wait for them all to finish
    for thread in threads:
        thread.join()
    # Reset lock state
    if toLock:
        imp.acquire()  # Acquire the lock again
if __name__ == "__main__":
    main()

