function disableTextSelection(elementId) {
    const element = document.getElementById(elementId);
    if (element) {
        element.style.userSelect = 'none';  // For standard browsers
        element.style.webkitUserSelect = 'none';  // For webkit-based browsers
        element.style.MozUserSelect = 'none';  // For Mozilla Firefox
        element.style.msUserSelect = 'none';  // For Internet Explorer/Edge
        element.style.pointerEvents = 'none';  // Disable pointer events to prevent selection
        element.onselectstart = function() { return false; };  // Disable text selection on mouse drag
        element.onmousedown = function() { return false; };  // Disable text selection on mouse click
        element.onkeydown = function(e) { e.preventDefault(); };  // Disable text selection on keyboard input
    }
}
