import json
class Stream:
    @staticmethod
    def parse_error_channel(error_message: bytes) -> dict:
        try:
            json_length = error_message[0]
            json_payload = error_message[1:1+json_length]
            error_data = json.loads(json_payload)
            return error_data
        except (ValueError, IndexError, json.JSONDecodeError):
            return {"exit_code": 1}
# Test the implementation
def test_parse_error_channel_success():
    result = Stream.parse_error_channel(b'\x03{"metadata":{},"status":"Success"}')
    assert result == {"metadata": {}, "status": "Success"}
def test_parse_error_channel_failure():
    result = Stream.parse_error_channel(b'\x02{"metadata":{},"status":"Error"}')
    assert result == {"exit_code": 1}

