import torch.nn as nn
class Net(nn.Module):
    def __init__(self, num_layers, img_dim, in_chan, act_func, latent_vector_size):
        super(Net, self).__init__()
        assert act_func in ("ReLU", "LeakyReLU"), "Activation function that can be used now are ReLU and LeakyReLU"

        self.layers = nn.ModuleList()
        self.layers.append(nn.Conv2d(in_chan, 64, kernel_size=3, stride=1, padding=1))
        self.layers.append(nn.MaxPool2d(kernel_size=2, stride=2))

        for _ in range(num_layers - 1):
            self.layers.append(nn.Conv2d(64, 64, kernel_size=3, stride=1, padding=1))
            self.layers.append(nn.MaxPool2d(kernel_size=2, stride=2))

        self.fc = nn.Linear(64 * (img_dim // (2 ** num_layers)) * (img_dim // (2 ** num_layers)), latent_vector_size)

        if act_func == "ReLU":
            self.activation = nn.ReLU()
        else:
            self.activation = nn.LeakyReLU()

    def forward(self, x):
        for layer in self.layers:
            x = layer(x)
        x = x.view(x.size(0), -1)
        x = self.fc(x)
        x = self.activation(x)
        return x

