import numpy as np
from scipy.spatial import cKDTree
class NearestNeighborData(LowResHighResDataset):
    def __init__(self, dataset: LowResHighResDataset, num_models=None, model_index=None, k=16):
        super().__init__(dataset.low_res_data, dataset.high_res_data, dataset.region_geometries)
        self.num_models = num_models if num_models is not None else len(dataset)
        self.model_index = model_index
        self.k = k
        self.high_res_tree = self._build_high_res_tree()
    def _build_high_res_tree(self):
        high_res_points = self.high_res_data if self.model_index is None else self.high_res_data[self.model_index]
        return cKDTree(high_res_points)
    def retrieve_nearest_neighbors(self, low_res_point):
        if self.model_index is not None:
            low_res_point = np.expand_dims(low_res_point, axis=0)
        _, indices = self.high_res_tree.query(low_res_point, k=self.k)
        if self.model_index is not None:
            indices = indices[0]
        return self.high_res_data[indices]

import os
def filter_and_sort_files(folder, prefix=None, suffix=None, sort=False):
    if prefix is not None and suffix is not None:
        filter_condition = lambda i: i.startswith(prefix) and i.endswith(suffix)
    elif prefix is not None:
        filter_condition = lambda i: i.startswith(prefix)
    elif suffix is not None:
        filter_condition = lambda i: i.endswith(suffix)
    else:
        filter_condition = lambda i: True
    file_list = [i for i in os.listdir(folder) if os.path.isfile(os.path.join(folder, i)) and filter_condition(i)]
    if sort:
        file_list.sort()
    return file_list

