from enum import Enum
from typing import List
import json
class Status(Enum):
    on = 1
    off = 0
class Config:
    def __init__(self, label: str, key: str, value: str, status: Status):
        self.label = label
        self.key = key
        self.value = value
        self.status = status
def validate_config(config_instance: Config) -> List[str]:
    errors = []
    if not config_instance.label or len(config_instance.label) > 200:
        errors.append("Label must not be empty and should not exceed 200 characters.")
    if not config_instance.key or len(config_instance.key) > 20:
        errors.append("Key must not be empty and should not exceed 20 characters.")
    try:
        json.loads(config_instance.value)
    except json.JSONDecodeError:
        errors.append("Value must be a valid JSON object.")
    if config_instance.status not in [Status.on, Status.off]:
        errors.append("Status must be a valid enumeration value.")
    return errors

