import mlx.core as mx
class RMSNorm:
    def __init__(self, dim: int, weight: mx.array, eps: float = 1e-5):
        self.dim = dim
        self.eps = eps
        self.weight = weight.astype(mx.float32)
    def __call__(self, x: mx.array) -> mx.array:
        orig_dtype = x.dtype
        x = x.astype(mx.float32)
        return (
            self.weight
            * x
            * mx.rsqrt(mx.mean(mx.square(x), axis=-1, keepdims=True) + self.eps)
        ).astype(orig_dtype)

import logging
import threading
import time
from typing import Dict
logger = logging.getLogger(__name__)
class CircuitBreaker:
    """
    Simple circuit breaker that opens when error rate is high.
    """
    def __init__(self, failure_threshold: int = 5, recovery_timeout: int = 60):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.failure_count: Dict[str, int] = {}
        self.last_failure_time: Dict[str, float] = {}
        self.state: Dict[str, str] = {}  # 'closed', 'open', 'half-open'
        self.lock = threading.Lock()
    def call(self, provider: str) -> bool:
        """Check if call is allowed."""
        with self.lock:
            state = self.state.get(provider, "closed")
            if state == "closed":
                return True
            elif state == "open":
                if time.time() - self.last_failure_time.get(provider, 0) > self.recovery_timeout:
                    self.state[provider] = "half-open"
                    logger.info(f"Circuit breaker for {provider} entering half-open state")
                    return True
                return False
            elif state == "half-open":
                return True
    def record_success(self, provider: str):
        """Record successful call."""
        with self.lock:
            if self.state.get(provider) == "half-open":
                self.state[provider] = "closed"
                self.failure_count[provider] = 0
                logger.info(f"Circuit breaker for {provider} closed")
            elif self.state.get(provider) == "closed":
                self.failure_count[provider] = 0
    def record_failure(self, provider: str):
        """Record failed call."""
        with self.lock:
            self.failure_count[provider] = self.failure_count.get(provider, 0) + 1
            self.last_failure_time[provider] = time.time()
            if self.failure_count[provider] >= self.failure_threshold:
                self.state[provider] = "open"
                logger.warning(
                    f"Circuit breaker for {provider} opened due to {self.failure_count[provider]} failures"
                )
# Global instance
circuit_breaker = CircuitBreaker()
def alert_callback(provider: str, rate: float):
    """Alert callback to trigger circuit breaker."""
    circuit_breaker.record_failure(provider)
def is_call_allowed(provider: str) -> bool:
    """Check if call is allowed by circuit breaker."""
    return circuit_breaker.call(provider)
def record_call_success(provider: str):
    """Record successful call."""
    circuit_breaker.record_success(provider)

from concurrent.futures import ProcessPoolExecutor, as_completed
def _worker(file_path, mod, extra_visitors, full_scan=True):
    from skylos.analyzer import proc_file
    out = proc_file(file_path, mod, extra_visitors=extra_visitors, full_scan=full_scan)
    return str(file_path), out
def run_proc_file_parallel(
    files,
    modmap,
    extra_visitors=None,
    jobs=0,
    progress_callback=None,
    custom_rules_data=None,
    changed_files=None,
):
    import os
    if os.getenv("PYTEST_CURRENT_TEST"):
        jobs = 1
    if jobs <= 1:
        outs = []
        total = len(files)
        for i, f in enumerate(files, 1):
            if progress_callback:
                progress_callback(i, total or 1, f)
            from skylos.analyzer import proc_file
            full_scan = changed_files is None or str(f) in changed_files
            out = proc_file(
                f, modmap[f], extra_visitors=extra_visitors, full_scan=full_scan
            )
            outs.append(out)
        return outs
    if jobs <= 0:
        jobs = max(1, (os.cpu_count() or 4) - 1)
    pending = []
    for f in files:
        pending.append((f, modmap[f]))
    results = {}
    with ProcessPoolExecutor(max_workers=jobs) as ex:
        fut_to_file = {}
        for f, mod in pending:
            full_scan = changed_files is None or str(f) in changed_files
            fut = ex.submit(_worker, f, mod, extra_visitors, full_scan)
            fut_to_file[fut] = f
        total = len(pending)
        done = 0
        for fut in as_completed(fut_to_file):
            f = fut_to_file[fut]
            try:
                file_str, out = fut.result()
            except Exception:
                file_str = str(f)
                out = None
            results[file_str] = out
            done += 1
            if progress_callback:
                progress_callback(done, total, f)
    ordered = []
    for f in files:
        ordered.append(results.get(str(f)))
    return ordered

import logging
import os
import torch
logger = logging.getLogger("gpu-service")
def get_device() -> torch.device:
    """Auto-detect GPU or fall back to CPU. Supports CUDA (NVIDIA) and ROCm (AMD)."""
    override = os.environ.get("TORCH_DEVICE")
    if override:
        logger.info(f"Device override via TORCH_DEVICE={override}")
        return torch.device(override)
    if torch.cuda.is_available():
        name = torch.cuda.get_device_name(0)
        logger.info(f"GPU detected: {name}")
        return torch.device("cuda")
    logger.warning("No GPU detected - falling back to CPU (inference will be slow)")
    return torch.device("cpu")
def get_device_info(device: torch.device) -> dict:
    """Return device diagnostics."""
    info = {
        "device": str(device),
        "pytorch_version": torch.__version__,
        "cuda_version": torch.version.cuda if torch.cuda.is_available() else None,
    }
    if device.type == "cuda":
        info["device_name"] = torch.cuda.get_device_name(0)
        mem = torch.cuda.get_device_properties(0).total_memory
        info["vram_total_mb"] = round(mem / 1024 / 1024)
        info["vram_used_mb"] = round(torch.cuda.memory_allocated(0) / 1024 / 1024)
    else:
        info["device_name"] = "cpu"
    return info

