from typing import List
from ripperdoc.utils.file_watch import ChangedFileNotice
def _format_changed_file_notice(notices: List[ChangedFileNotice]) -> str:
    """Render a system notice about files that changed on disk."""
    lines: List[str] = [
        "System notice: Files you previously read have changed on disk.",
        "Please re-read the affected files before making further edits.",
        "",
    ]
    for notice in notices:
        lines.append(f"- {notice.file_path}")
        summary = (notice.summary or "").rstrip()
        if summary:
            indented = "\n".join(f"    {line}" for line in summary.splitlines())
            lines.append(indented)
    return "\n".join(lines)

import json
import sys
from pathlib import Path
import requests
import time
from cache_manager import load_cached_activities, update_cache_with_new_activities
CONFIG_PATH = Path.home() / ".config" / "strava" / "config.json"
def load_config():
    if not CONFIG_PATH.exists():
        print("Error: Configuration not found.", file=sys.stderr)
        sys.exit(1)

    with open(CONFIG_PATH) as f:
        return json.load(f)
def refresh_token_if_needed(config):
    """Refresh access token if expired."""
    if config['expires_at'] < time.time():
        url = "https://www.strava.com/oauth/token"
        data = {
            'client_id': config['client_id'],
            'client_secret': config['client_secret'],
            'refresh_token': config['refresh_token'],
            'grant_type': 'refresh_token'
        }

        response = requests.post(url, data=data)
        response.raise_for_status()

        token_data = response.json()
        config['access_token'] = token_data['access_token']
        config['refresh_token'] = token_data['refresh_token']
        config['expires_at'] = token_data['expires_at']

        with open(CONFIG_PATH, 'w') as f:
            json.dump(config, f, indent=2)

    return config
def fetch_recent_activities(config, limit=10):
    """Fetch recent activities from Strava."""
    config = refresh_token_if_needed(config)

    url = "https://www.strava.com/api/v3/athlete/activities"
    headers = {'Authorization': f"Bearer {config['access_token']}"}
    params = {'per_page': limit}

    response = requests.get(url, headers=headers, params=params)
    response.raise_for_status()

    return response.json()
def find_new_virtual_rides():
    """Check for new virtual rides since last check."""
    config = load_config()

    # Get cached activities
    cached = load_cached_activities()
    cached_ids = {a['id'] for a in cached}

    # Fetch recent activities
    recent = fetch_recent_activities(config, limit=20)

    # Find new virtual rides
    new_rides = []
    for activity in recent:
        if activity['id'] not in cached_ids and activity.get('type') == 'VirtualRide':
            new_rides.append(activity)

    # Update cache
    if new_rides:
        update_cache_with_new_activities(recent)

    return new_rides
def main():
    try:
        new_rides = find_new_virtual_rides()

        if new_rides:
            print(f"Found {len(new_rides)} new virtual ride(s):")
            for ride in new_rides:
                print(f"  - {ride['name']} ({ride['id']})")

            # Output ride IDs for processing
            for ride in new_rides:
                print(f"NEW_RIDE:{ride['id']}")
        else:
            print("No new rides found")

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
if __name__ == '__main__':
    main()

import requests
from typing import Tuple, Dict, Any
import logging
from .base import BaseDnsProvider
logger = logging.getLogger(__name__)
class PorkbunDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "porkbun"
    PROVIDER_NAME = "Porkbun"
    PROVIDER_DESCRIPTION = "Porkbun DNS API"
    REQUIRED_CREDENTIALS = ["api_key", "secret_api_key"]

    BASE_URL = "https://api.porkbun.com/api/json/v3"

    def _auth_body(self, extra=None):
        body = {
            'apikey': self.credentials['api_key'],
            'secretapikey': self.credentials['secret_api_key'],
        }
        if extra:
            body.update(extra)
        return body

    def _request(self, path, data=None):
        body = self._auth_body(data)
        try:
            resp = requests.post(f"{self.BASE_URL}{path}", json=body, timeout=30)
            result = resp.json()
            if result.get('status') == 'SUCCESS':
                return True, result
            return False, result.get('message', 'Unknown error')
        except requests.RequestException as e:
            logger.error(f"Porkbun API error: {e}")
            return False, str(e)

    def create_txt_record(self, domain, record_name, record_value, ttl=300):
        zone = self.get_zone_for_domain(domain)
        relative = self.get_relative_record_name(record_name, zone)
        success, result = self._request(f'/dns/create/{zone}', {
            'name': relative, 'type': 'TXT', 'content': record_value, 'ttl': str(ttl)
        })
        if not success:
            return False, f"Failed: {result}"
        return True, "Record created"

    def delete_txt_record(self, domain, record_name):
        zone = self.get_zone_for_domain(domain)
        relative = self.get_relative_record_name(record_name, zone)

        success, result = self._request(f'/dns/retrieveByNameType/{zone}/TXT/{relative}')
        if success:
            for rec in result.get('records', []):
                self._request(f'/dns/delete/{zone}/{rec["id"]}')
        return True, "Record deleted"

    def test_connection(self):
        success, result = self._request('/ping')
        if success:
            return True, "Connected successfully"
        return False, f"Connection failed: {result}"

    @classmethod
    def get_credential_schema(cls):
        return [
            {'name': 'api_key', 'label': 'API Key', 'type': 'password', 'required': True,
             'help': 'porkbun.com > Account > API Access'},
            {'name': 'secret_api_key', 'label': 'Secret API Key', 'type': 'password', 'required': True,
             'help': 'Porkbun Secret API Key'},
        ]

