AUTHORIZED_TYPES = ["text", "audio", "image", "any"]
def create_inputs(tool_inputs: Dict[str, Dict[Union[str, type], str]]):
    inputs = {}
    for input_name, input_desc in tool_inputs.items():
        input_type = input_desc["type"]
        if input_type == "text":
            inputs[input_name] = "Text input"
        elif input_type == "image":
            inputs[input_name] = Image.open(
                Path(get_tests_dir("fixtures/tests_samples/COCO")) / "000000039769.png"
            ).resize((512, 512))
        elif input_type == "audio":
            inputs[input_name] = np.ones(3000)
        else:
            raise ValueError(f"Invalid type requested: {input_type}")
    return inputs
def output_type(output):
    if isinstance(output, (str, AgentText)):
        return "text"
    elif isinstance(output, (Image.Image, AgentImage)):
        return "image"
    elif isinstance(output, (torch.Tensor, AgentAudio)):
        return "audio"
    else:
        raise TypeError(f"Invalid output: {output}")
@is_agent_test
class ToolTesterMixin:
    def test_inputs_output(self):
        self.assertTrue(hasattr(self.tool, "inputs"))
        self.assertTrue(hasattr(self.tool, "output_type"))
        inputs = self.tool.inputs
        self.assertTrue(isinstance(inputs, dict))
        for _, input_spec in inputs.items():
            self.assertTrue("type" in input_spec)
            self.assertTrue("description" in input_spec)
            self.assertTrue(input_spec["type"] in AUTHORIZED_TYPES)
            self.assertTrue(isinstance(input_spec["description"], str))
        output_type = self.tool.output_type
        self.assertTrue(output_type in AUTHORIZED_TYPES)
    def test_common_attributes(self):
        self.assertTrue(hasattr(self.tool, "description"))
        self.assertTrue(hasattr(self.tool, "name"))
        self.assertTrue(hasattr(self.tool, "inputs"))
        self.assertTrue(hasattr(self.tool, "output_type"))
    def test_agent_type_output(self):
        inputs = create_inputs(self.tool.inputs)
        output = self.tool(**inputs)
        agent_type = AGENT_TYPE_MAPPING[self.tool.output_type]
        self.assertTrue(isinstance(output, agent_type))
    def test_agent_types_inputs(self):
        inputs = create_inputs(self.tool.inputs)
        _inputs = []
        for _input, expected_input in zip(inputs, self.tool.inputs.values()):
            input_type = expected_input["type"]
            _inputs.append(AGENT_TYPE_MAPPING[input_type](_input))
        output_type = AGENT_TYPE_MAPPING[self.tool.output_type]
        # Should not raise an error
        output = self.tool(**inputs)
        self.assertTrue(isinstance(output, output_type))

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F
class EntropyTemperature(nn.Module):
    """
    Temperature module for SAC automatic entropy tuning.
    """
    def __init__(
        self,
        initial_alpha: float,
        alpha_type: str = "softplus",
        device=None,
        dtype=torch.float32,
    ):
        super().__init__()
        self.alpha_type = alpha_type
        if alpha_type == "exp":
            init = np.log(initial_alpha)
        elif alpha_type == "softplus":
            # softplus^{-1}(x) = log(exp(x) - 1)
            init = np.log(np.exp(initial_alpha) - 1.0)
        elif alpha_type == "fixed_alpha":
            self.register_buffer(
                "fixed_alpha",
                torch.tensor(
                    [initial_alpha],
                    device=device,
                    dtype=dtype,
                ),
                persistent=True,
            )
            init = initial_alpha
        else:
            raise NotImplementedError(f"Unknown alpha_type: {alpha_type}")
        self.base_alpha = nn.Parameter(torch.tensor(init, device=device, dtype=dtype))
    def compute_alpha(self) -> torch.Tensor:
        if self.alpha_type == "exp":
            return self.base_alpha.exp()
        elif self.alpha_type == "softplus":
            return F.softplus(self.base_alpha)
        elif self.alpha_type == "fixed_alpha":
            return self.fixed_alpha
        else:
            raise NotImplementedError
    @property
    def alpha(self) -> float:
        return self.compute_alpha().item()

import torch
from mindspeed.fsdp.utils.str_match import module_name_match
from ..params.model_args import ModelArguments
from ..features.memory.async_offload import async_offload_modules, get_offload_modules
from ..features.memory.chunkloss_lm_head import apply_chunkloss_module, get_chunkloss_module
class FeaturesApplier:
    def __init__(self, model_config: ModelArguments):
        self.config = model_config
    def get_needed_modules(self, modules, plan):
        matched_submodules = []
        for plan_name in plan:
            for name, module in modules.named_modules():
                if module_name_match(plan_name, name):
                    if (name, module) not in matched_submodules:
                        matched_submodules.append((name, module))
        return matched_submodules
    def apply_activation_offload_modules(self, model):
        if getattr(self.config, "activation_offload_plan", None) is None or getattr(self.config.activation_offload_plan, "apply_modules", None) is None:
            return
        activation_offload_modules = get_offload_modules(model, getattr(self.config.activation_offload_plan, "apply_modules"))
        async_offload_modules(activation_offload_modules)
    def apply_chunkloss(self, model):
        if not self.config.enable_chunk_loss:
            return
        setattr(model, "enable_chunk_loss", True)
        chunkloss_module = get_chunkloss_module(model, self.config.chunkloss_plan)
        apply_chunkloss_module(chunkloss_module)
    def __call__(self, model):
        self.apply_activation_offload_modules(model=model)
        self.apply_chunkloss(model=model)

