#/* Define block */
verbosity = False
#/* Usage method */
def print_usage(name):
    """ Simple method to output usage when needed """
    sys.stderr.write("\nUsage: %s [-/-h/-help] [-v/-verbose]\n" % name);
    sys.stderr.write("Enter purpose here.\n");
    sys.stderr.write("-/-h/-help        :show this information\n");
    sys.stderr.write("-v/-verbose       :run more verbosely\n");
    sys.stderr.write("-i/-infile file   :name of binary file to process\n");
    sys.stderr.write("\n\n");
#/* Main */
def main():
    global verbosity
    infilename = None
    i = 1
    while i < len(sys.argv):
        if sys.argv[i] == '-' or sys.argv[i] == '-h' or sys.argv[i] == '-help':
            print_usage(sys.argv[0]);
            sys.exit(0);
        elif sys.argv[i] == '-v' or sys.argv[i] == '-verbose':
            verbosity = True
        elif sys.argv[i] == '-i' or sys.argv[i] == '-infile':
            i += 1
            if i < len(sys.argv):
                infilename = sys.argv[i]
        else:
            sys.stderr.write("\nWhoops - Unrecognized argument: %s\n" % sys.argv[i]);
            print_usage(sys.argv[0]);
            sys.exit(10);
        i += 1
    blockSizes = tables.getBinarysizes()
    print('blockSizes:', blockSizes)
    if infilename is None: exit()
    f = open(infilename, 'rb')
    line = f.read(blockSizes[0])
    sys.stdout.write('Time,Digital')
    for i in range(0, blockSizes[3], 4):
        sys.stdout.write(',On%d,Off%d' % (i>>2, i>>2))
    sys.stdout.write('\n')
    while len(line) > 0:
        time = int.from_bytes(line[0:blockSizes[1]], 'little')
        digital = int.from_bytes(line[blockSizes[1]:blockSizes[1] + blockSizes[2]], 'little')
        sys.stdout.write("%8d,'%16x'" % (time, digital))
        for i in range(blockSizes[1] + blockSizes[2], blockSizes[0], 4):
            onval = int.from_bytes(line[i:i+2],
                'little')
            offval = int.from_bytes(line[i+2:i+4],
                'little')
            sys.stdout.write(",'%04x','%04x'" % (onval, offval))
        sys.stdout.write('\n')
        line = f.read(blockSizes[0])
if __name__ == "__main__":
    main()

import argparse
import sys
import logging
def main():
    parser = argparse.ArgumentParser(description='Scrapling fetch')
    parser.add_argument('url', help='URL to fetch')
    parser.add_argument('--mode', choices=['http', 'stealth', 'dynamic'], default='http',
                        help='Fetcher mode: http (fast), stealth (anti-bot), dynamic (JS rendering)')
    parser.add_argument('--selector', '-s', help='CSS selector to extract elements')
    parser.add_argument('--attr', default='text', help='Attribute to extract (text, href, src, etc.)')
    parser.add_argument('--json', action='store_true', help='Output as JSON array')
    parser.add_argument('-q', '--quiet', action='store_true', help='Suppress INFO logs')
    args = parser.parse_args()
    if args.quiet:
        logging.disable(logging.INFO)
    try:
        page = _fetch(args.url, args.mode)
    except Exception as e:
        print(f"ERROR: {e}", file=sys.stderr)
        sys.exit(1)
    if not args.selector:
        # Default: return all visible text
        text = page.get_all_text(' ', ignore_tags=('script', 'style', 'noscript'))
        print(text)
        return
    elements = page.css(args.selector)
    if not elements:
        print(f"No elements matched: {args.selector}", file=sys.stderr)
        sys.exit(1)
    results = []
    for el in elements:
        if args.attr == 'text':
            val = el.text or el.get_all_text()
        elif args.attr == 'html':
            val = el.html_content
        else:
            val = el.attrib.get(args.attr, '')
        results.append(val.strip())
    if args.json:
        import json
        print(json.dumps(results, ensure_ascii=False, indent=2))
    else:
        for r in results:
            if r:
                print(r)
def _fetch(url, mode):
    if mode == 'http':
        from scrapling.fetchers import Fetcher
        return Fetcher.get(url)
    elif mode == 'stealth':
        from scrapling.fetchers import StealthyFetcher
        return StealthyFetcher.fetch(url, headless=True, network_idle=True)
    elif mode == 'dynamic':
        from scrapling.fetchers import DynamicFetcher
        return DynamicFetcher.fetch(url, headless=True, network_idle=True)
if __name__ == '__main__':
    main()

