from typing import TypeVar, Generic, Union
T = TypeVar("T")
class Optional(Generic[T]):
    def __init__(self, value: Union[T, None]):
        self._value = value
    def reset(self, that):
        assert isinstance(that, Optional)
        self._value = that._value
    def is_some(self) -> bool:
        return self._value is not None
    def unwrap(self) -> T:
        """Returns the value or raises an error if None."""
        if self._value is None:
            raise ValueError("Tried to unwrap a None value!")
        return self._value
    def unwrap_or(self, default: T) -> T:
        """Returns the value or a default if None."""
        return self._value if self._value is not None else default

from datetime import UTC, datetime, timedelta
import bcrypt
import jwt
from api.constants import OSS_JWT_EXPIRY_HOURS, OSS_JWT_SECRET
def hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")
def verify_password(password: str, password_hash: str) -> bool:
    return bcrypt.checkpw(password.encode("utf-8"), password_hash.encode("utf-8"))
def create_jwt_token(user_id: int, email: str) -> str:
    payload = {
        "sub": str(user_id),
        "email": email,
        "exp": datetime.now(UTC) + timedelta(hours=OSS_JWT_EXPIRY_HOURS),
        "iat": datetime.now(UTC),
    }
    return jwt.encode(payload, OSS_JWT_SECRET, algorithm="HS256")
def decode_jwt_token(token: str) -> dict:
    return jwt.decode(token, OSS_JWT_SECRET, algorithms=["HS256"])

