    encoder = Encoder()
    if os.path.exists(checkpoint_path):
        ckpt = torch.load(checkpoint_path)
    else:
        ckpt = torch.hub.load_state_dict_from_url(checkpoint_path)
    if isinstance(ckpt, Encoder):
        ckpt = ckpt.state_dict()
    encoder.load_state_dict(ckpt)
    if config_path is not None:
        config = FlavaImageCodebookConfig.from_pretrained(config_path)
    else:
        config = FlavaImageCodebookConfig()
    hf_model = FlavaImageCodebook(config).eval()
    state_dict = encoder.state_dict()
    hf_state_dict = upgrade_state_dict(state_dict)
    hf_model.load_state_dict(hf_state_dict)
    hf_state_dict = hf_model.state_dict()
    hf_count = count_parameters(hf_state_dict)
    state_dict_count = count_parameters(state_dict)
    assert torch.allclose(hf_count, state_dict_count, atol=1e-3)
    if save_checkpoint:
        hf_model.save_pretrained(pytorch_dump_folder_path)
    else:
        return hf_state_dict
if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--pytorch_dump_folder_path", default=None, type=str, help="Path to the output PyTorch model.")
    parser.add_argument("--checkpoint_path", default=None, type=str, help="Path to flava checkpoint")
    parser.add_argument("--config_path", default=None, type=str, help="Path to hf config.json of model to convert")
    args = parser.parse_args()
    convert_dalle_checkpoint(args.checkpoint_path, args.pytorch_dump_folder_path, args.config_path)

import os
import re
import json
import argparse
import sys
# Constants
DEFAULT_PATTERNS_PATH = os.path.join(os.path.dirname(__file__), "../references/threat_patterns.json")
def load_patterns(path):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except Exception as e:
        print(f"Error loading patterns: {e}")
        sys.exit(1)
def audit_directory(target_path, patterns):
    report = {
        "target": target_path,
        "findings": [],
        "risk_score": 0,
        "status": "SAFE"
    }

    if not os.path.isdir(target_path):
        print(f"Error: {target_path} is not a directory.")
        sys.exit(1)
    for root, dirs, files in os.walk(target_path):
        for file in files:
            # Skip hidden files or specific extensions if needed
            if file.startswith('.') or file.endswith(('.pyc', '.skill', '.zip')):
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
                    content = f.read()

                    for category, regex_list in patterns.items():
                        for pattern in regex_list:
                            if re.search(pattern, content, re.IGNORECASE):
                                finding = {
                                    "file": os.path.relpath(file_path, target_path),
                                    "category": category,
                                    "pattern": pattern
                                }
                                report["findings"].append(finding)
                                # Scoring logic: 20 points per match, capped per category
                                report["risk_score"] += 20
            except Exception as e:
                print(f"Could not read {file_path}: {e}")
    # Normalize score and status
    if report["risk_score"] >= 80:
        report["status"] = "DANGEROUS"
    elif report["risk_score"] >= 40:
        report["status"] = "SUSPICIOUS"
    elif report["risk_score"] > 0:
        report["status"] = "CAUTION"

    return report
def main():
    parser = argparse.ArgumentParser(description="ClawGuard: Audit agent skills for security risks.")
    parser.add_argument("path", help="The path to the skill directory to audit.")
    parser.add_argument("--json", action="store_true", help="Output report in JSON format.")
    args = parser.parse_args()
    patterns = load_patterns(DEFAULT_PATTERNS_PATH)
    report = audit_directory(args.path, patterns)
    if args.json:
        print(json.dumps(report, indent=2))
    else:
        print(f"\n--- ClawGuard Audit Report ---")
        print(f"Target: {report['target']}")
        print(f"Status: {report['status']}")
        print(f"Risk Score: {report['risk_score']}")
        print(f"Findings: {len(report['findings'])}")
        print("-" * 30)
        for f in report['findings']:
            print(f"[{f['category'].upper()}] in {f['file']}: Match '{f['pattern']}'")
        print("-" * 30 + "\n")
if __name__ == "__main__":
    main()

import socket
import time
from typing import Iterable, Optional
from src.models.config import Config
from src.utils.logger import setup_logger
logger = setup_logger(__name__)
def resolve_host(host: str, port: int) -> Iterable[tuple[int, tuple]]:
    """Resolve host to addresses for TCP connection attempts."""
    try:
        return [
            (family, sockaddr)
            for family, _, _, _, sockaddr in socket.getaddrinfo(
                host, port, type=socket.SOCK_STREAM
            )
        ]
    except socket.gaierror:
        return []
def connect_latency(
    host: str, port: int, timeout: float, retries: int
) -> Optional[int]:
    """Return TCP connection latency in ms or None if unreachable."""
    addresses = resolve_host(host, port)
    if not addresses:
        return None
    for _ in range(retries + 1):
        for family, sockaddr in addresses:
            start_time = time.perf_counter()
            try:
                with socket.socket(family, socket.SOCK_STREAM) as sock:
                    sock.settimeout(timeout)
                    sock.connect(sockaddr)
                end_time = time.perf_counter()
                return int((end_time - start_time) * 1000)
            except (socket.timeout, OSError) as exc:
                logger.debug("Connection attempt failed: %s", exc)
                continue
    return None
class ConfigTester:
    """Tests V2Ray configurations for connectivity."""
    def __init__(self, timeout: float, retries: int, threshold_ms: int) -> None:
        self.timeout = timeout
        self.retries = retries
        self.threshold_ms = threshold_ms
    def test(self, config: Config) -> Config:
        """Test a single config and return with latency if valid."""
        latency = connect_latency(
            config.host, config.port, self.timeout, self.retries
        )
        if latency is not None and latency < self.threshold_ms:
            config.latency_ms = latency
        return config

