# Graph search function using homsearch interface
def graph_search(G, H, results_limit, only_count, partmap, max_depth):
    # Import required modules and functions
    from homsearch import HomsearchInterface, graph_to_adjlist, graphmap_to_fmap

    # Ensure graphs are undirected
    assert not G.is_directed()
    assert not H.is_directed()

    # Initialize homsearch interface
    hs = HomsearchInterface(
        graph_to_adjlist(G), 
        graph_to_adjlist(H),
        results_limit, 
        (not only_count), 
        False, 
        max_depth=max_depth
    )

    # Perform search based on provided partition map
    if partmap is None:
        hs.search()
    else:
        hs.search_from(graphmap_to_fmap(G, H, partmap))

    # Return count or mappings based on only_count flag
    if only_count:
        return hs.count()
    else:
        return hs.mappings()

