        # Check if flag is a single boolean value
        if isinstance(flag, bool):
            return flag

        # Check if flag is a list of booleans
        elif isinstance(flag, list):
            return any(flag)

        # Handle invalid input types
        else:
            raise ValueError("Invalid input type. Expected bool or List[bool].")

