# Function to compare two dictionaries with nested structure
def custom_dict_comparison(dict1, dict2):
    # Check if all keys match and values are equal (considering OrderedDict for nested dicts)
    return all(
        dict1.get(key) == dict2.get(key) or
        OrderedDict(dict1.get(key)) == OrderedDict(dict2.get(key))
        for key in set(dict1.keys()) | set(dict2.keys())
    )

# Test function
def test_custom_dict_comparison():
    # First test case: identical dictionaries
    dict1 = {
        'a': {'x': 1, 'y': 2},
        'b': {'z': 3}
    }
    dict2 = {
        'a': {'x': 1, 'y': 2},
        'b': {'z': 3}
    }
    assert custom_dict_comparison(dict1, dict2) == True

    # Second test case: same content but different key order in nested dict
    dict3 = {
        'a': {'x': 1, 'y': 2},
        'b': {'z': 3}
    }
    dict4 = {
        'a': {'y': 2, 'x': 1},
        'b': {'z': 3}
