# Abstract base class for JSON resources
from abc import ABC, abstractmethod

class IJSONResource(ABC):
    @abstractmethod
    def get_signature(self) -> str:
        pass

# Base resource subscriber class
class IBaseResourceSubscriber:
    def __init__(self):
        self.registered_protocol = None

    def register_protocol(self, protocol: IJSONResource) -> None:
        self.registered_protocol = protocol

    def verify_signature(self, request: dict) -> bool:
        # Check if protocol is registered
        if self.registered_protocol is None:
            raise ValueError("No protocol registered for signature verification")

        # Extract signature from request
        request_signature = request.get('signature', None)
        if request_signature is None:
            raise ValueError("Request signature not found")

        # Get protocol signature and compare
        protocol_signature = self.registered_protocol.get_signature()
        return request_signature == protocol_signature

# Validates if brackets in a string are balanced
def multi_bracket_validation(input_string):
    stack = []
    opening_brackets = "({["
    closing_brackets = ")}]"
    bracket_pairs = {')': '(', '}': '{', ']': '['}

    for char in input_string:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or stack.pop() != bracket_pairs[char]:
                return False

    # Return True if stack is empty (all brackets matched), False otherwise
    return not stack

# Test cases
def test_mbv_true_case_empty_str():
    assert multi_bracket_validation('') == True

def test_mbv_true_case_valid_brackets():
    assert multi_bracket_validation('[{()}]') == True

def test_mbv_false_case_invalid_brackets():
    assert multi_bracket_validation('[{()}') == False

def test_mbv_false_case_invalid_order():
    assert multi_bracket_validation('{[}]') == False

def test_mbv_false_case_extra_closing_bracket():
    assert multi_bracket_validation('[{()}](') == False

from typing import List

class Scorer:
    def __init__(self):
        # Initialize scores list with 13 elements (indices 0-12)
        self.scores = [None] * 13

    def score_three_of_kind(self, dice: List[int]) -> int:
        # Score for three of a kind (index 6)
        if self.scores[6] is None:
            self.scores[6] = sum(dice) if any(dice.count(x) >= 3 for x in dice) else 0
        return self.scores[6]

    def score_four_of_kind(self, dice: List[int]) -> int:
        # Score for four of a kind (index 7)
        if self.scores[7] is None:
            self.scores[7] = sum(dice) if any(dice.count(x) >= 4 for x in dice) else 0
        return self.scores[7]

    def score_full_house(self, dice: List[int]) -> int:
        # Score for full house (index 8)
        if self.scores[8] is None:
            counts = [dice.count(x) for x in set(dice)]
            self.scores[8] = 25 if 2 in counts and 3 in counts else 0
        return self.scores[8]

    def score_small_straight(self, dice: List[int]) -> int:
        # Score for small straight (index 9)
        if self.scores[9] is None:
            sorted_dice = sorted(set(dice))
            self.scores[9] = 30 if len(sorted_dice) >= 4 and max(sorted_dice) - min(sorted_dice) >= 3 else 0
        return self.scores[9]

    def score_large_straight(self, dice: List[int]) -> int:
        # Score for large straight (index 10)
        if self.scores[10] is None:
            sorted_dice = sorted(set(dice))
            self.scores[10] = 40 if len(sorted_dice) == 5 and max(sorted_dice) - min(sorted_dice) == 4 else 0
        return self.scores[10]

    def score_chance(self, dice: List[int]) -> int:
        # Score for chance (index 11)
        if self.scores[11] is None:
            self.scores[11] = sum(dice)
        return self.scores[11]

    def total_score(self) -> int:
        # Calculate total score from indices 6 to 11
        above = sum(score for score in self.scores[6:12] if score is not None)
        return above

