# Check if two digits appear in a die's representation
def digits_match(die1: int, die2: int, digit1: int, digit2: int) -> bool:
    # Both digits must be present in either die
    return (str(digit1) in str(die1) and str(digit2) in str(die1)) or \
           (str(digit1) in str(die2) and str(digit2) in str(die2))


# Determine if two dice are compatible based on digit requirements
def are_dice_compatible(die1: int, die2: int) -> bool:
    # Must have 3 and 6 or 3 and 9 (since 9 can be flipped from 6)
    if not digits_match(die1, die2, 3, 6) and not digits_match(die1, die2, 3, 9):
        return False

    # Must have 4 and 9 or 4 and 6
    if not digits_match(die1, die2, 4, 9) and not digits_match(die1, die2, 4, 6):
        return False

    # Must have 6 and 4 or 9 and 4 (redundant with above but explicit)
    if not digits_match(die1, die2, 6, 4) and not digits_match(die1, die2, 9, 4):
        return False

    # Must have 8 and 1
    if not digits_match(die1, die2, 8, 1):
        return False

    return True

# Class representing an attachment with content type validation
class Attachment:
    def __init__(self, content_type):
        self._content_type = content_type

    # Property to get the content type
    @property
    def content_type(self):
        return self._content_type

    # Setter for content type with validation
    @content_type.setter
    def content_type(self, content_type):
        """Sets the content_type of this Attachment.

        The content type of the attachment.  # noqa: E501

        :param content_type: The content_type of this Attachment.  # noqa: E501
        """
        # Validate that content_type is a string
        if not isinstance(content_type, str):
            raise ValueError("Content type must be a string")

        # Split and validate format (must be exactly two non-empty parts)
        parts = content_type.split('/')
        if len(parts) != 2 or not all(parts):
            raise ValueError("Invalid content type format")

        # Set the validated content type
        self._content_type = content_type

