from typing import List, Tuple
from enforce_typing import enforce_types

# Define score constants
draw: int = 0
loss: int = -25
illegal_move: int = -1
legal_move: int = 1
capture_move: int = 5
king_move: int = 5

@enforce_types
def tuple_subtract(t1: Tuple[int, int], t2: Tuple[int, int]) -> Tuple[int, int]:
    # Subtract corresponding elements of two tuples
    return tuple(map(lambda i, j: i - j, t1, t2))

@enforce_types
def tuple_add(t1: Tuple[int, int], t2: Tuple[int, int]) -> Tuple[int, int]:
    # Add corresponding elements of two tuples
    return tuple(map(lambda i, j: i + j, t1, t2))

@enforce_types
def calculate_score(moves: List[Tuple[Tuple[int, int], Tuple[int, int]]]) -> int:
    # Calculate total score for a list of moves
    score = 0

    for move in moves:
        start, end = move
        diff = tuple_subtract(end, start)

        # Check move type and add appropriate score
        if diff == (1, 1) or diff == (-1, -1) or diff == (1, -1) or diff == (-1, 1):
            score += legal_move
        elif diff == (2, 2) or diff == (-2, -2) or diff == (2, -2) or diff == (-2, 2):
            score += capture_move
        elif diff == (3, 3) or diff == (-3, -3) or diff == (3, -3) or diff == (-3, 3):
            score += king_move
        else:
            score += illegal_move

    return score

# Decorator to mark methods in a class as chainable
def chainable(func):
    """
    Decorator to mark methods in a class as chainable.
    """
    def wrapper(self, *args, **kwargs):
        func(self, *args, **kwargs)
        return self
    return wrapper

# Function to mark a method as deferred execution
def make_deferred(func):
    """
    Function to mark a method as deferred execution.
    """
    def wrapper(self, *args, **kwargs):
        def deferred_execution():
            func(self, *args, **kwargs)
        setattr(self, f"deferred_{func.__name__}", deferred_execution)
    return wrapper

# Function to return a specific value
def return_value(value):
    """
    Function to return a specific value.
    """
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            return value
        return wrapper
    return decorator

# Function to lock a method from being called
def lock(func):
    """
    Function to lock a method from being called.
    """
    def wrapper(self, *args, **kwargs):
        raise AttributeError(f"Method {func.__name__} is locked and cannot be called")
    return wrapper

class ChainableExample:
    @chainable
    def method1(self, value):
        print(f"Method 1 called with value: {value}")

    @chainable
    def method2(self, value):
        print(f"Method 2 called with value: {value}")

    @make_deferred
    def deferred_method(self):
        print("Deferred method called")

    @return_value(100)
    def value_method(self):
        pass

    @lock
    def locked_method(self):
        print("This method is locked")

