import json

class Stream:
    @staticmethod
    def parse_error_channel(error_message: bytes) -> dict:
        try:
            # Extract JSON length from first byte
            json_length = error_message[0]
            # Extract JSON payload based on length
            json_payload = error_message[1:1+json_length]
            # Parse JSON and return data
            error_data = json.loads(json_payload)
            return error_data
        except (ValueError, IndexError, json.JSONDecodeError):
            # Return default error response on failure
            return {"exit_code": 1}

