class Cache:
    def __init__(self):
        # Hash map to store cached files
        self.cache = {}
        # Set to track populated file types
        self.populated_types = set()

    def retrieve_from_cache_or_external_storage(self, file_path):
        # Extract file type from path
        file_type = file_path.split('.')[-1]

        if file_path in self.cache:
            print(f"Retrieving {file_path} from cache")
        else:
            if file_type in self.populated_types:
                print(f"Retrieving {file_path} from external storage")
                # Simulate retrieval from external storage and store in cache
                self.cache[file_path] = f"Contents of {file_path}"
            else:
                print(f"File type {file_type} is not allowed to be accessed from external storage")

    def populate_cache(self, file_path):
        # Extract file type from path
        file_type = file_path.split('.')[-1]

        if file_type not in self.populated_types:
            self.populated_types.add(file_type)

        # Simulate populating cache with file contents
        self.cache[file_path] = f"Contents of {file_path}"

