# Class definition for GroupXData
class GroupXData:
    def __init__(self, **kwargs):
        # Initialize instance variables from keyword arguments
        self.data = kwargs.get('X', None)
        self.doc_range = kwargs.get('doc_range', None)
        self.nDocTotal = kwargs.get('nDocTotal', None)

    @classmethod
    def read_npz(cls, npzfilepath, nDocTotal=None, **kwargs):
        ''' Constructor for building an instance of GroupXData from disk
        '''
        import numpy as np

        # Load data from npz file
        var_dict = np.load(npzfilepath)

        # Validate required fields
        if 'X' not in var_dict:
            raise KeyError('Stored npz file needs to have data in field named X')
        if 'doc_range' not in var_dict:
            raise KeyError('Stored npz file needs to have field named doc_range')

        # Override nDocTotal if provided
        if nDocTotal is not None:
            var_dict['nDocTotal'] = nDocTotal

        return cls(**var_dict)

    @classmethod
    def read_mat(cls, matfilepath, nDocTotal=None, **kwargs):
        ''' Constructor for building an instance of GroupXData from disk
        '''
        import scipy.io

        # Load data from mat file
        InDict = scipy.io.loadmat(matfilepath)

        # Validate required fields
        if 'X' not in InDict:
            raise KeyError('Stored mat file needs to have data in field named X')
        if 'doc_range' not in InDict:
            raise KeyError('Stored mat file needs to have field named doc_range')

        # Override nDocTotal if provided
        if nDocTotal is not None:
            InDict['nDocTotal'] = nDocTotal

        return cls(**InDict)

# Import subprocess module for running shell commands
import subprocess

def run(command: str) -> str:
    try:
        # Execute the command and capture output
        output = subprocess.check_output(
            command, 
            shell=True, 
            text=True
        )
        return output
    except subprocess.CalledProcessError as e:
        # Handle errors gracefully
        return f"Error: {e}"

def run_cli() -> None:
    while True:
        user_input = input("Enter a CLI command (or 'exit' to quit): ")

        # Exit condition
        if user_input.lower() == 'exit':
            break

        # Run the command and print result
        output = run(user_input)
        print(output)

# Main entry point
