# Ansible module to manage Foreman locations
from ansible.module_utils.basic import AnsibleModule
import requests

def main():
    # Define module arguments
    module = AnsibleModule(
        argument_spec=dict(
            name=dict(type='str', required=True),
            attributes=dict(type='dict', required=False, default={}),
            state=dict(type='str', required=False, default='present', choices=['present', 'absent'])
        )
    )

    # Configuration for Foreman API
    base_url = 'https://foreman.example.com/api/v2/locations'
    headers = {'Content-Type': 'application/json', 'Accept': 'application/json'}
    auth = ('username', 'password')  # Replace with actual Foreman credentials

    # Extract parameters from module
    name = module.params['name']
    attributes = module.params['attributes']
    state = module.params['state']

    # Handle 'present' state - create or update location
    if state == 'present':
        payload = {'name': name, **attributes}
        response = requests.post(base_url, json=payload, auth=auth, headers=headers)

    # Handle 'absent' state - delete location if it exists
    elif state == 'absent':
        location_id = get_location_id(name, auth, headers)
        if location_id:
            delete_url = f'{base_url}/{location_id}'
            response = requests.delete(delete_url, auth=auth, headers=headers)
        else:
            module.exit_json(changed=False, msg=f"Location '{name}' not found, no action required.")

    # Process response and exit accordingly
    if response.status_code == 201 or response.status_code == 200:
        module.exit_json(changed=True, msg=f"Location '{name}' {state}ed successfully.")
    else:
        module.fail_json(msg=f"Failed to {state} location '{name}'. Error: {response.text}")


def get_location_id(name, auth, headers):
    """Helper function to retrieve location ID by name"""
    base_url = 'https://foreman.example.com/api/v2/locations'
    response = requests.get(base_url, auth=auth, headers=headers)
    locations = response.json()['results']

    for location in locations:
        if location['name'] == name:
            return location['id']

    return None


if __name__ == '__main__':
    main()

# Reverses the tempering which is applied to outputs of MT19937
def untemper(self, v):
    v = self.untemperRightShiftXor(v, 18)
    v = self.untemperLeftShiftAndXor(v, 15, 0xefc60000)
    v = self.untemperLeftShiftAndXor(v, 7, 0x9d2c5680)
    v = self.untemperRightShiftXor(v, 11)

    return v


def untemperRightShiftXor(self, v, shift):
    mask = (1 << shift) - 1
    result = v

    for i in range(31, -1, -1):
        if i > 0:
            result = v ^ (result >> shift)
            v = v ^ (result >> shift)
        else:
            result = result
            v = v

    return result


def untemperLeftShiftAndXor(self, v, shift, mask):
    result = v

    for i in range(32):
        if i > 0:
            result = v ^ ((result << shift) & mask)
            v = v ^ ((result << shift) & mask)
        else:
            result = result
            v = v

    return result

