import abc

# Define abstract base class for docstrings
class Docstring(abc.ABC):
    @abc.abstractmethod
    def __init__(self, docstring: str) -> None:
        # Initialize with a docstring
        pass

    @abc.abstractmethod
    def __str__(self) -> str:
        # Return string representation
        pass

# Concrete implementation of Docstring
class Document(Docstring):
    def __init__(self, docstring: str) -> None:
        self.docstring = docstring

    def __str__(self) -> str:
        return self.docstring

