# Import required modules
from datetime import datetime

def generate_date_query(start_date: str = None, end_date: str = None, date: str = None) -> dict:
    # Handle range query with start and end dates
    if start_date and end_date:
        start_date_obj = datetime.strptime(start_date, "%d/%m/%Y")
        end_date_obj = datetime.strptime(end_date, "%d/%m/%Y")

        # Validate date order
        assert (start_date_obj < end_date_obj), "The first date must be lower than the second."

        return {POST_PUB_DATE: {
            "$gte": start_date_obj,
            "$lt": end_date_obj
        }}

    # Handle single date query
    elif date:
        post_pub_date = datetime.strptime(date, "%d/%m/%Y")
        return {POST_PUB_DATE: post_pub_date}

    # Error handling for missing parameters
    else:
        raise ValueError("At least one of start_date, end_date, or date must be provided.")

# Import necessary modules
import copy
from typing import MutableMapping, List
import types

def validate_output_artifacts(output_artifacts, executor_output):
    # Deep copy output_artifacts to avoid modifying the original
    output_artifacts = copy.deepcopy(output_artifacts) or {}

    # Cast to proper type annotation
    output_artifacts = cast(MutableMapping[str, List[types.Artifact]], output_artifacts)

    # Validate if executor_output exists
    if executor_output:
        # Check if all keys in executor_output.output_artifacts are present in output_artifacts
        if not set(executor_output.output_artifacts.keys()).issubset(output_artifacts.keys()):
            raise RuntimeError('Executor output contains more keys than output skeleton.')

        # Iterate through output_artifacts to check for missing keys
        for key, artifact_list in output_artifacts.items():
            # Skip if key is not in executor_output
            if key not in executor_output.output_artifacts:
                continue

# Import necessary module
import os

def filter_and_sort_files(folder, prefix=None, suffix=None, sort=False):
    # Define filter condition based on provided parameters
    if prefix is not None and suffix is not None:
        filter_condition = lambda i: i.startswith(prefix) and i.endswith(suffix)
    elif prefix is not None:
        filter_condition = lambda i: i.startswith(prefix)
    elif suffix is not None:
        filter_condition = lambda i: i.endswith(suffix)
    else:
        filter_condition = lambda i: True

    # Get list of files that match the filter condition
    file_list = [
        i for i in os.listdir(folder)
        if os.path.isfile(os.path.join(folder, i)) and filter_condition(i)
    ]

    # Sort the list if requested
    if sort:
        file_list.sort()

    return file_list

# Import required modules from pysnmp
from pysnmp.smi import builder, view, error
from pysnmp.smi.rfc1902 import MibScalarInstance

def process_snmp_mib_data(mib_data: dict) -> dict:
    # Initialize MIB builder
    mibBuilder = builder.MibBuilder()

    try:
        # Import symbols from the specified module
        (snmpTargetSpinLock, snmpUnavailableContexts, snmpUnknownContexts) = mibBuilder.importSymbols(
            mib_data['module_name'],
            *mib_data['symbols']
        )

        # Create scalar instance with cloned syntax
        _snmpTargetSpinLock = MibScalarInstance(
            snmpTargetSpinLock.name,
            (mib_data['scalar_instance_value'],),
            snmpTargetSpinLock.syntax.clone(mib_data['scalar_instance_value'])
        )

        # Build and return result dictionary
        return {
            'imported_symbols': {
                symbol: mibBuilder.importSymbols(mib_data['module_name'], symbol)[0]
                for symbol in mib_data['symbols']
            },
            'scalar_instance': {
                'name': mib_data['scalar_instance_name'],
                'value': mib_data['scalar_instance_value']
            }
        }

    except error.SmiError as e:
        # Return error message if SmiError occurs
        return {'error': str(e)}

