# Import necessary modules
import torch
import torch.nn as nn

from cosmos_rl.utils.logging import logger
from transformers.activations import ACT2CLS


class MLPFusedActMul(nn.Module):
    def __init__(self, fused_fn: torch.autograd.Function):
        super().__init__()
        self.fused_fn = fused_fn

    def forward(self, a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
        return self.fused_fn.apply(a, b)


class MLPActMulFunc(nn.Module):
    def __init__(self, act_fn: nn.Module):
        super().__init__()
        self.act_fn = act_fn

    def forward(self, a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
        # Apply activation function and multiply with b
        return self.act_fn(a) * b

    def liger_equivalent(self):
        # Check if activation function is SiLU
        if isinstance(self.act_fn, ACT2CLS["silu"]):
            from liger_kernel.ops.swiglu import LigerSiLUMulFunction
            return MLPFusedActMul(LigerSiLUMulFunction)

        # Check if activation function is GELU
        elif isinstance(self.act_fn, ACT2CLS["gelu"]):
            from liger_kernel.ops.geglu import LigerGELUMulFunction
            return MLPFusedActMul(LigerGELUMulFunction)

        # Fallback for unsupported activation functions
        else:
            logger.warning(
                f"Unsupported activation function: {self.act_fn}. Will fallback to the default implementation."
            )
            return self

import base64
import re
import time
from io import BytesIO

from cosmos_rl_reward.handler.reward_base import BaseRewardHandler
from cosmos_rl_reward.handler.registry import RewardRegistry
from cosmos_rl_reward.utils.logging import logger


@RewardRegistry.register()
class UnifiedReward(BaseRewardHandler):
    NEEDS_LATENT_DECODER = False
    reward_name = "unified_reward"

    def __init__(self, endpoint_url="", endpoint_api_key="", **kwargs):
        super().__init__()
        self.endpoint_url = endpoint_url
        self.endpoint_api_key = endpoint_api_key

    def set_up(self):
        from openai import OpenAI
        self.client = OpenAI(api_key=self.endpoint_api_key, base_url=self.endpoint_url)

    def pil_image_to_base64(self, image):
        buffered = BytesIO()
        image.save(buffered, format="PNG")
        encoded_image_text = base64.b64encode(buffered.getvalue()).decode("utf-8")
        base64_qwen = f"data:image;base64,{encoded_image_text}"
        return base64_qwen

    def _extract_scores(self, text_outputs):
        scores = []
        pattern = r"Final Score:\s*([1-5](?:\.\d+)?)"
        for text in text_outputs:
            match = re.search(pattern, text)
            if match:
                try:
                    scores.append(float(match.group(1)))
                except ValueError:
                    scores.append(0.0)
            else:
                scores.append(0.0)
        return scores

    def evaluate_image(self, prompt, image):
        question = (
            f"<image>\nYou are given a text caption and a generated image based on that caption. "
            f"Your task is to evaluate this image based on two key criteria:\n"
            f"1. Alignment with the Caption: Assess how well this image aligns with the provided caption. "
            f"Consider the accuracy of depicted objects, their relationships, and attributes as described in the caption.\n"
            f"2. Overall Image Quality: Examine the visual quality of this image, including clarity, detail preservation, "
            f"color accuracy, and overall aesthetic appeal.\n"
            f"Based on the above criteria, assign a score from 1 to 5 after 'Final Score:'.\n"
            f"Your task is provided as follows:\n"
            f"Text Caption: [{prompt}]"
        )
        images_base64 = self.pil_image_to_base64(image)
        response = self.client.chat.completions.create(
            model="UnifiedReward-7b-v1.5",
            messages=[
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image_url",
                            "image_url": {"url": images_base64},
                        },
                        {
                            "type": "text",
                            "text": question,
                        },
                    ],
                },
            ],
            temperature=0,
            stream=False,
        )
        return response.choices[0].message.content

    def evaluate_batch_image(self, images, prompts):
        results = [
            self.evaluate_image(prompt, img) for prompt, img in zip(prompts, images)
        ]
        return results

    def calculate_reward(self, images, metadata):
        import torch
        from PIL import Image

        def _error(msg: str):
            logger.error(msg)
            return {
                "error": msg,
                "scores": None,
                "input_info": metadata.get("input_info", {}),
                "duration": "0.00",
                "decoded_duration": metadata.get("decode_duration", "N/A"),
                "type": self.reward_name,
            }

        t0 = time.perf_counter()

        # Validate inputs
        if images is None:
            return _error("[unified_reward] images tensor is None.")

        if not isinstance(images, torch.Tensor) or images.dim() != 4:
            return _error(
                f"[unified_reward] expects 4D torch.Tensor in BHWC/NHWC layout (B,H,W,C); "
                f"got type={type(images)} shape={getattr(images, 'shape', None)} dtype={getattr(images, 'dtype', None)}"
            )

        if images.shape[0] == 0:
            return _error("[unified_reward] images batch size is zero.")

        x = images
        if x.dtype != torch.uint8:
            x = x.to(torch.uint8)

        # Ensure NHWC layout
        if x.shape[-1] == 3:
            x_nhwc = x
        elif x.shape[1] == 3:
            x_nhwc = x.permute(0, 2, 3, 1).contiguous()
        else:
            raise ValueError(f"channel dim must be 3, got shape {x.shape}")

        # Convert tensors to PIL Images
        pil_images = [
            Image.fromarray(x_nhwc[i].cpu().numpy()) for i in range(x_nhwc.shape[0])
        ]

        # Handle prompts
        prompts = metadata.get("prompts")
        if prompts is None:
            return _error("[unified_reward] prompts are required and cannot be None.")
        if isinstance(prompts, str):
            prompts = [prompts]
        if len(prompts) != len(pil_images):
            return _error(
                f"[unified_reward] prompts length ({len(prompts)}) must match batch size ({len(pil_images)})."
            )

        # Evaluate images
        text_outputs = self.evaluate_batch_image(pil_images, prompts)
        scores = self._extract_scores(text_outputs)

        # Normalize scores to [0, 1]
        scores = [sc / 5.0 for sc in scores]

        duration = f"{(time.perf_counter() - t0):.2f}"

        return {
            "scores": {"unified_reward": scores},
            "input_info": metadata.get("input_info", {}),
            "duration": duration,
            "decoded_duration": metadata.get("decode_duration", "N/A"),
            "type": self.reward_name,
        }

# Validation result model for volcengine-api
from typing import Any, Dict, List, Optional

class ValidationResult:
    """
    Lightweight validation result model used by volcengine-api.

    This model intentionally keeps a simple surface: whether the validation
    passed, a collection of error messages, and an optional details dictionary
    with extra context.
    """
    __slots__ = ("is_valid", "errors", "details")

    def __init__(
        self,
        is_valid: bool,
        errors: Optional[List[str]] = None,
        details: Optional[Dict[str, Any]] = None
    ):
        # Ensure boolean type for is_valid
        self.is_valid = bool(is_valid)

        # Initialize errors list if provided, otherwise empty list
        self.errors = list(errors) if errors is not None else []

        # Initialize details dict if provided, otherwise empty dict
        self.details = dict(details) if details is not None else {}

    def to_dict(self) -> Dict[str, Any]:
        """Convert validation result to dictionary representation."""
        return {
            "is_valid": self.is_valid,
            "errors": self.errors,
            "details": self.details
        }

    def __eq__(self, other: object) -> bool:
        """Check equality with another ValidationResult instance."""
        if not isinstance(other, ValidationResult):
            return NotImplemented
        return (
            self.is_valid == other.is_valid and
            self.errors == other.errors and
            self.details == other.details
        )

    def __repr__(self) -> str:
        """Return string representation of the ValidationResult."""
        return (
            f"ValidationResult("
            f"is_valid={self.is_valid}, "
            f"errors={self.errors}, "
            f"details={self.details})"
        )

