import math
import pytest
import torch
import tilegym

from tests import common


class Test_MLADecodingSplitKV(common.PyTestCase):
    @staticmethod
    def reference(q, qpe, kv, kpe, sm_scale=None, compute_dtype=torch.half):
        """Reference implementation using PyTorch for MLA decoding (same as test_mla_decoding.py)"""
        if sm_scale is None:
            sm_scale = 1.0 / (math.sqrt(q.size(-1) + qpe.size(-1)))

        qkv_dtype = q.dtype

        # Cast inputs to compute dtype
        q = q.to(compute_dtype)
        qpe = qpe.to(compute_dtype)
        kv = kv.to(compute_dtype)
        kpe = kpe.to(compute_dtype)

        # Compute attention scores: Q*K^T + QPE*KPE^T
        qk = torch.matmul(q, kv.transpose(1, 2)).float()

        if kpe.numel() > 0:
            qk = qk + torch.matmul(qpe, kpe.transpose(1, 2)).float()

        qk = qk * sm_scale

        # Apply softmax
        m = torch.max(qk, dim=-1)[0]
        p = torch.exp(qk - m.unsqueeze(-1))
        l = torch.sum(p, dim=-1)
        p = p / (l.unsqueeze(-1))

        # Apply attention to values
        o = torch.matmul(p.to(qkv_dtype).to(compute_dtype), kv).to(qkv_dtype)

        return o

    @staticmethod
    def _get_sm_scale(q, qpe):
        """Calculate the default attention scale factor"""
        return 1.0 / (math.sqrt(q.size(-1) + qpe.size(-1)))

    _backends = ["cutile"]

    @pytest.mark.parametrize("num_heads", [16, 32])
    @pytest.mark.parametrize("seq_len", [129, 1024, 8192, 11049])
    @pytest.mark.parametrize("kv_len_per_split", [128, 512])
    @pytest.mark.parametrize("dtype", [torch.float16])
    @pytest.mark.parametrize("backend", _backends)
    def test_op(self, num_heads, seq_len, kv_len_per_split, dtype, backend, arch):
        """Test functional correctness of MLA decoding with split-kv"""
        # Set backend if available
        if tilegym.is_backend_available(backend):
            tilegym.set_backend(backend)
        else:
            pytest.skip(f"Backend {backend} is not available")

        self.setUp()

        # Skip test if CUDA is not available
        if not torch.cuda.is_available():
            pytest.skip("CUDA not available, skipping MLA Split-KV test")

        # Test parameters
        batch_size = 1
        head_dim = 512
        kpe_dim = 64

        # Create random input tensors
        torch.manual_seed(42)  # For reproducibility
        device = torch.device("cuda")
        q = torch.randn(batch_size, num_heads, head_dim, device=device).to(dtype)
        qpe = torch.randn(batch_size, num_heads, kpe_dim, device=device).to(dtype)
        kv = torch.randn(batch_size, seq_len, head_dim, device=device).to(dtype)
        kpe = torch.randn(batch_size, seq_len, kpe_dim, device=device).to(dtype)

        # Compute softmax scale
        sm_scale = self._get_sm_scale(q, qpe)

        def split_kv_fn():
            return tilegym.ops.mla_decoding_split_kv(q, qpe, kv, kpe, sm_scale, kv_len_per_split)

        def ref_fn():
            return self.reference(q, qpe, kv, kpe, sm_scale)

        self.assertCorrectness(split_kv_fn, ref_fn, {}, atol=1e-2, rtol=1e-2, multiple_outputs=False)

import torch
import habana_frameworks.torch.core as htcore
import habana_frameworks.torch.utils.experimental as htexp

# Check if device is Gaudi2
is_hpu_gaudi2 = htexp._get_device_type() == htexp.synDeviceType.synDeviceGaudi2


def get_hpu_gaudi2_scale_factor():
    return (torch.finfo(torch.float8_e4m3fn).max / torch.finfo(torch.float8_e4m3fnuz).max)


# Exponent width for different dtypes
EXP_WIDTH = {
    torch.float32: 8,
    torch.bfloat16: 8,
    torch.float8_e4m3fn: 4,
    torch.float8_e5m2: 5,
}


def get_default_exp_bias(dtype):
    exp_width = EXP_WIDTH[dtype]
    return 2**(exp_width - 1) - 1


# Supported exponent bias sets per device and dtype
EXP_BIAS_SETS = {
    ("GAUDI2", torch.float8_e4m3fn): [3, 7, 11, 15],
    ("GAUDI2", torch.float8_e5m2): [15],
    ("GAUDI3", torch.float8_e4m3fn): range(0, 63),
    ("GAUDI3", torch.float8_e5m2): range(0, 63),
}


# Maximum representable values for various dtypes
MAX_RANGE = {
    torch.float32:
    torch.finfo(torch.float32).max,
    torch.bfloat16:
    torch.finfo(torch.bfloat16).max,
    torch.float8_e4m3fn:
    torch.finfo(torch.float8_e4m3fn).max,
    # float8_e4m3fn data type is 8-bit floating point consist of Exponent: 4, Mantissa: 3, bias: 7. It's supported by Gaudi3.
    torch.float8_e5m2:
    torch.finfo(torch.float8_e5m2).max
    # float8_e5m2 data type is 8-bit floating point consist of Exponent: 5, Mantissa: 2, bias: 15. IEEE 754, with NaN and inf.
}

# Attempt to add float8_e4m3fnuz max range (Gaudi2-specific)
try:
    MAX_RANGE[torch.float8_e4m3fnuz] = torch.finfo(torch.float8_e4m3fnuz).max
    # float8_e4m3fnuz data type is 8-bit floating point consist of Exponent: 4, Mantissa: 3, bias: 8 with 1 sign bit. It's supported by Gaudi2.
except AttributeError as e:
    pass


def get_fullscale(dtype, device, exp_bias=None):
    default_exp_bias = get_default_exp_bias(dtype)
    fullscale = 1

    # Special handling for GAUDI2 with float8_e4m3fn
    if device == "GAUDI2" and dtype == torch.float8_e4m3fn:
        try:
            fullscale = MAX_RANGE[torch.float8_e4m3fnuz]
        except AttributeError as e:
            pass
    else:
        fullscale = MAX_RANGE[dtype]

    # Use provided exp_bias or default
    exp_bias = default_exp_bias if exp_bias is None else exp_bias

    # Adjust fullscale based on exponent bias difference
    fullscale = fullscale * (2**(default_exp_bias - exp_bias))
    return float(fullscale)


def get_fullscales_by_expbias_set(dtype, device, expbias_set):
    return [get_fullscale(dtype, device, exp_bias=eb) for eb in expbias_set]


def get_fp8_hw_alligned_scales(dtype, device):
    exp_bias_set = EXP_BIAS_SETS.get((device, dtype), None)
    return (None if exp_bias_set is None else
            [x / get_fullscale(dtype, device) for x in get_fullscales_by_expbias_set(dtype, device, exp_bias_set)])


# Scale factors per device
DEVICES_SCALE_FACTORS = {
    "GAUDI2": 4,
    "GAUDI3": 1,
}


# Precomputed FP8 1.4.3 scales for each device
FP8_143_SCALES = {
    device: get_fp8_hw_alligned_scales(torch.float8_e4m3fn, device)
    for device in DEVICES_SCALE_FACTORS.keys()
}


# Extract min, max, and scale factor traits for each device
FP8_143_SCALES_TRAITS = {
    device: (
        min(FP8_143_SCALES[device]),
        max(FP8_143_SCALES[device]),
        DEVICES_SCALE_FACTORS[device],
    )
    for device in DEVICES_SCALE_FACTORS.keys()
}


class ScaleToPow2:
    def calc(self, scale):
        scale_pow2 = 2.0**torch.ceil(torch.log2(scale))
        return scale_pow2


class ConvertScaleToHwAligned:
    def __init__(self, device_type="GAUDI3"):
        self.device_type = "GAUDI2" if is_hpu_gaudi2 else "GAUDI3"

    def calc(self, scale):
        # Apply Gaudi2-specific scaling factor if needed
        if self.device_type == "GAUDI2":
            scale = scale * get_hpu_gaudi2_scale_factor()

        # Convert to power-of-2 scale
        scale_pow2 = ScaleToPow2().calc(scale)

        # Get hardware constraints
        min_scale, max_scale, scale_factor = FP8_143_SCALES_TRAITS[self.device_type]

        # Clamp the scale within hardware-supported bounds
        scale_pow2_hw = torch.minimum(
            torch.maximum(
                2.0**(torch.ceil(torch.log2(scale_pow2) / scale_factor) * scale_factor),
                torch.tensor(min_scale, dtype=scale.dtype, device=scale.device),
            ),
            torch.tensor(max_scale, dtype=scale.dtype, device=scale.device),
        )
        return scale_pow2_hw

import base64
