import mimetypes
import os

# Define allowed file extensions
ALLOWED_EXTENSIONS = {".txt", ".md", ".json", ".csv"}

def validate_file(filepath):
    """
    Safely validate file - SAFE IMPLEMENTATION
    This function checks if a file is valid based on extension, existence, and size.
    """
    # Safe: Uses basename to prevent path traversal attacks
    filename = os.path.basename(filepath)

    # Check file extension
    _, ext = os.path.splitext(filename)
    if ext not in ALLOWED_EXTENSIONS:
        return {"valid": False, "reason": "Invalid extension"}

    # Safe: Restricts file access to a specific directory
    safe_dir = os.path.expanduser("~/documents/")
    full_path = os.path.join(safe_dir, filename)

    # Check if file exists
    if not os.path.exists(full_path):
        return {"valid": False, "reason": "File not found"}

    # Check file size (limit to 10MB)
    size = os.path.getsize(full_path)
    if size > 10 * 1024 * 1024:
        return {"valid": False, "reason": "File too large"}

    return {"valid": True, "filename": filename, "size": size}

def check_mime_type(filepath):
    """Check MIME type safely using the mimetypes module"""
    # Safe: Uses mimetypes module to guess MIME type
    mime_type, _ = mimetypes.guess_type(filepath)
    return mime_type

