import dataclasses
import einops
import numpy as np

from openpi import transforms
from openpi.models import model as _model


def make_metaworld_example() -> dict:
    """Creates a random input example for the Metaworld policy."""
    return {
        "observation/state": np.random.rand(4),
        "observation/image": np.random.randint(256, size=(3, 480, 480), dtype=np.uint8),
        "prompt": "do something",
    }


def _parse_image(image) -> np.ndarray:
    # Convert input to numpy array
    image = np.asarray(image)

    # Handle floating-point images: scale to [0, 255] and convert to uint8
    if np.issubdtype(image.dtype, np.floating):
        image = (255 * image).astype(np.uint8)

    # Rearrange channel-first format (c h w) to channel-last (h w c)
    if image.shape[0] == 3:
        image = einops.rearrange(image, "c h w -> h w c")

    return image


@dataclasses.dataclass(frozen=True)
class MetaworldInputs(transforms.DataTransformFn):
    model_type: _model.ModelType

    def __call__(self, data: dict) -> dict:
        # Parse base image
        base_image = _parse_image(data["observation/image"])

        # Construct inputs dictionary
        inputs = {
            "state": data["observation/state"],
            "image": {
                "base_0_rgb": base_image,
                "left_wrist_0_rgb": np.zeros_like(base_image),
                # Pad any non-existent images with zero-arrays of the appropriate shape.
                "right_wrist_0_rgb": np.zeros_like(base_image),
            },
            "image_mask": {
                "base_0_rgb": np.True_,
                "left_wrist_0_rgb": np.False_,
                # We only mask padding images for pi0 model, not pi0-FAST. Do not change this for your own dataset.
                "right_wrist_0_rgb": np.False_,
            },
        }

        # Add actions if present in input data
        if "actions" in data:
            inputs["actions"] = data["actions"]

        # Add prompt if present in input data
        if "prompt" in data:
            inputs["prompt"] = data["prompt"]

        return inputs


@dataclasses.dataclass(frozen=True)
class MetaworldOutputs(transforms.DataTransformFn):
    def __call__(self, data: dict) -> dict:
        # Extract first 4 dimensions of actions
        return {"actions": np.asarray(data["actions"][:, :4])}

