# Slack integration module
import os
import requests
import json
import sys


class SlackHub:
    def __init__(self):
        # Initialize with Slack bot token from environment variable
        self.token = os.getenv("SLACK_BOT_TOKEN")
        self.base_url = "https://slack.com/api"

    def _call(self, endpoint, data=None):
        # Internal method to make API calls to Slack
        headers = {
            "Authorization": f"Bearer {self.token}",
            "Content-Type": "application/json; charset=utf-8"
        }
        response = requests.post(
            f"{self.base_url}/{endpoint}", 
            headers=headers, 
            json=data
        )
        return response.json()

    def send(self, target, message, thread_ts=None):
        # Send a message to a channel or user
        data = {"channel": target, "text": message}
        if thread_ts:
            data["thread_ts"] = thread_ts
        return self._call("chat.postMessage", data)

    def search(self, query):
        # Search messages in Slack using the search API
        params = {"query": query}
        headers = {"Authorization": f"Bearer {self.token}"}
        response = requests.get(
            f"{self.base_url}/search.messages", 
            headers=headers, 
            params=params
        )
        return response.json()


if __name__ == "__main__":
    import argparse

    hub = SlackHub()

    parser = argparse.ArgumentParser()
    parser.add_argument("action", choices=["send", "search", "list"])
    parser.add_argument("--target")
    parser.add_argument("--message")
    parser.add_argument("--query")
    args = parser.parse_args()

    if args.action == "list":
        print(json.dumps(hub._call("conversations.list", {"types": "public_channel,private_channel"})))
    elif args.action == "send":
        print(json.dumps(hub.send(args.target, args.message)))
    elif args.action == "search":
        print(json.dumps(hub.search(args.query)))

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F


class EntropyTemperature(nn.Module):
    """
    Temperature module for SAC automatic entropy tuning.
    """

    def __init__(
        self,
        initial_alpha: float,
        alpha_type: str = "softplus",
        device=None,
        dtype=torch.float32,
    ):
        super().__init__()
        self.alpha_type = alpha_type

        # Initialize based on alpha_type
        if alpha_type == "exp":
            init = np.log(initial_alpha)
        elif alpha_type == "softplus":
            # softplus^{-1}(x) = log(exp(x) - 1)
            init = np.log(np.exp(initial_alpha) - 1.0)
        elif alpha_type == "fixed_alpha":
            self.register_buffer(
                "fixed_alpha",
                torch.tensor(
                    [initial_alpha],
                    device=device,
                    dtype=dtype,
                ),
                persistent=True,
            )
            init = initial_alpha
        else:
            raise NotImplementedError(f"Unknown alpha_type: {alpha_type}")

        self.base_alpha = nn.Parameter(torch.tensor(init, device=device, dtype=dtype))

    def compute_alpha(self) -> torch.Tensor:
        """Compute alpha value based on the configured transformation."""
        if self.alpha_type == "exp":
            return self.base_alpha.exp()
        elif self.alpha_type == "softplus":
            return F.softplus(self.base_alpha)
        elif self.alpha_type == "fixed_alpha":
            return self.fixed_alpha
        else:
            raise NotImplementedError("Alpha type not implemented.")

    @property
    def alpha(self) -> float:
        """Return current alpha value as a Python float."""
        return self.compute_alpha().item()

import json

from volcengine.ApiInfo import ApiInfo
from typing import Any
from volcengine import Credentials
from volcengine import ServiceInfo
from volcengine.base import Service


class BaseApi(Service.Service):
    def __init__(self, region, endpoint, api_info, service, ak, sk):
        """
        init function.

        :param region:   region of request
        :param api_info: an object of volcengine.ApiInfo.ApiInfo()
        :param endpoint: endpoint of top gateway
        :param service:  a specific service name registered on top gateway
        :param ak:       account ak
        :param sk:       account sk
        """
        self.connection_timeout = 10
        self.socket_timeout = 10
        self.schema = 'https'
        self.header = dict()
        self.header["Content-Type"] = "application/json"
        self.endpoint = endpoint
        self.credential = Credentials.Credentials(ak, sk, service, region)
        self.service_info = ServiceInfo.ServiceInfo(
            self.endpoint,
            self.header,
            self.credential,
            self.connection_timeout,
            self.socket_timeout,
            self.schema
        )
        self.api_info = api_info
        Service.Service.__init__(self, self.service_info, self.api_info)

    def get(self, action, params, doseq=0):
        res = super(BaseApi, self).get(action, params, doseq)
        try:
            res_json = json.loads(res)
        except Exception as e:
            raise Exception("res body is not json, %s, %s" % (e, res))
        if "ResponseMetadata" not in res_json:
            raise Exception("ResponseMetadata not in resp body, action %s, resp %s" % (action, res))
        elif "Error" in res_json["ResponseMetadata"]:
            raise Exception("%s failed, %s" % (action, res))
        return res_json


