# Import required modules
from __future__ import annotations
import csv
import io
import math
import urllib.request
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Tuple

def _utc_now_iso() -> str:
    # Return current UTC time in ISO format
    return datetime.now(timezone.utc).isoformat()

def _http_get(url: str, timeout_s: float = 10.0) -> str:
    # Perform HTTP GET request with custom User-Agent header
    req = urllib.request.Request(url, headers={"User-Agent": "invest-agent/1.0"})
    with urllib.request.urlopen(req, timeout=timeout_s) as resp:
        return resp.read().decode("utf-8", errors="replace")

def _stooq_quote_symbol(ticker: str) -> str:
    # Normalize ticker symbol for Stooq API
    t = (ticker or "").strip().lower()
    # Remove leading caret for indices
    if t.startswith("^"):
        t = t[1:]
    # Append .us suffix for US equities/ETFs not already having a domain
    if "." not in t:
        return f"{t}.us"
    return t

def get_quote(ticker: str) -> Dict[str, Any]:
    """Get last quote snapshot (best-effort) from Stooq."""
    ts = _utc_now_iso()
    sym = _stooq_quote_symbol(ticker)
    url = f"https://stooq.com/q/l/?s={sym}&f=sd2t2ohlcv&h&e=csv"

    try:
        text = _http_get(url)
        rows = list(csv.DictReader(io.StringIO(text)))

        if not rows:
            raise RuntimeError("empty csv")

        r = rows[0]

        def fnum(x: Optional[str]) -> Optional[float]:
            # Helper function to safely convert string to float
            try:
                return float(x) if x not in (None, "", "N/A") else None
            except Exception:
                return None

        price = fnum(r.get("Close"))
        low = fnum(r.get("Low"))
        high = fnum(r.get("High"))

        day_range = None
        if low is not None or high is not None:
            day_range = {"low": low, "high": high}

        # Construct timestamp from date and time fields
        quote_ts = f"{r.get('Date','')}T{r.get('Time','')}".strip("T") or ts

        return {
            "ticker": ticker,
            "price": price,
            "day_range": day_range,
            "timestamp": quote_ts,
            "source": "stooq",
            "fetched_at": ts,
        }

    except Exception as exc:
        return {
            "ticker": ticker,
            "price": None,
            "day_range": None,
            "timestamp": ts,
            "source": "stooq",
            "error": f"public quote failed: {exc}",
        }

def get_daily_history(ticker: str, limit: int = 60) -> List[Tuple[str, float]]:
    """Return list of (date, close) ascending by date."""
    sym = _stooq_quote_symbol(ticker)
    url = f"https://stooq.com/q/d/l/?s={sym}&i=d"

    text = _http_get(url)
    rows = list(csv.DictReader(io.StringIO(text)))

    out: List[Tuple[str, float]] = []
    for r in rows[-limit:]:
        try:
            out.append((r["Date"], float(r["Close"])))
        except Exception:
            continue

    return out

def realized_vol_20d(ticker: str) -> Dict[str, Any]:
    """Calculate 20-day realized volatility using daily closing prices."""
    ts = _utc_now_iso()

    try:
        hist = get_daily_history(ticker, limit=40)

        if len(hist) < 21:
            raise RuntimeError("insufficient history")

        closes = [c for _, c in hist]
        rets = [math.log(closes[i] / closes[i - 1]) for i in range(1, len(closes))]

        window = rets[-20:]
        mean = sum(window) / len(window)
        var = sum((x - mean) ** 2 for x in window) / (len(window) - 1)
        rv20 = math.sqrt(var) * math.sqrt(252.0)

        return {"ticker": ticker, "rv20": rv20, "timestamp": ts, "source": "stooq"}

    except Exception as exc:
        return {"ticker": ticker, "rv20": None, "timestamp": ts, "source": "stooq", "error": str(exc)}

from collections import OrderedDict
from functools import wraps


def flip_mapping(mapping):
    # Flip key-value pairs and reverse order if mapping is not empty
    if mapping:
        mapping = {value: key for key, value in mapping.items()}
        return OrderedDict(reversed(mapping.items()))
    else:
        return None


def replace_name(name, str_replace_mapping: dict):
    # Replace substrings in 'name' according to the provided mapping
    for old_str, new_str in str_replace_mapping.items():
        if len(old_str) > 1:
            name = name.replace(old_str, new_str)
    return name


# Wrapper to check if a method is supported by the converter
def check_method_support(func):
    @wraps(func)
    def wrapper(self, *args, **kwargs):
        # Retrieve set of supported methods from instance
        supported_methods = getattr(self, '_supported_methods', set())
        version = getattr(self, 'version', '')

        # Determine current method name
        method_name = func.__name__

        # Verify method support
        if method_name not in supported_methods:
            raise NotImplementedError(
                f"Method '{method_name}' is not supported by Converter '{self.__class__.__name__}.{version}'."
            )

        return func(self, *args, **kwargs)

    return wrapper


# Wrapper to validate parallel configuration support
def check_parallel_config_support(func):
    @wraps(func)
    def wrapper(self, *args, **kwargs):
        version = getattr(self, 'version', '')

        # Extract configuration object (from kwargs or positional args)
        cfg = kwargs.get('cfg', None) or args[1]
        tp_size = cfg.tp_size
        pp_layers = cfg.pp_layers

        # Check tensor parallelism support
        if tp_size > 1 and not getattr(self, '_enable_tp', False):
            raise NotImplementedError(
                f"Tensor Parallel is not support by Converter '{self.__class__.__name__}.{version}'"
            )

        # Check pipeline parallelism support
        if len(pp_layers) > 1 and not getattr(self, '_enable_pp', False):
            raise NotImplementedError(
                f"Pipeline Parallel is not support by Converter '{self.__class__.__name__}.{version}'"
            )

        # Check virtual pipeline parallelism support
        if len(pp_layers) > 1 and isinstance(pp_layers[0], list) and not getattr(self, '_enable_vpp', False):
            raise NotImplementedError(
                f"Virtual Pipeline Parallel is not support by Converter '{self.__class__.__name__}.{version}'"
            )

        return func(self, *args, **kwargs)

    return wrapper

