import argparse
import random
import string

class PluginConnectionHandler:
    def __init__(self):
        self.arg_parser = argparse.ArgumentParser(description='Client-Plugin Connection Handler')
        self.configure_arguments(self.arg_parser)

    def configure_arguments(self, parser):
        parser.add_argument(
            '-p', '--port',
            help=f'Port for client-plugin communication.',
            metavar='port_number',
            default='5431',
        )
        parser.add_argument(
            '-t', '--token',
            help=f'Authentication token for client-plugin connection (default: auto-generated).',
            metavar='auth_token',
            default=None,
        )

    def create_random_token(self):
        return ''.join(random.choices(string.ascii_letters + string.digits, k=10))

    def connect(self, port, token):
        print(f"Connecting to plugin using port {port} and token {token}.")

    def execute(self):
        options = self.arg_parser.parse_args()
        port = options.port
        token = options.token if options.token else self.create_random_token()
        self.connect(port, token)

if __name__ == "__main__":
