import numpy as np
import pytest

class Quaternion:
    def __init__(self, w_val, x_val, y_val, z_val):
        self.w = w_val
        self.x = x_val
        self.y = y_val
        self.z = z_val

    @property
    def unit_w(self):
        return Quaternion(1, 0, 0, 0)

    @property
    def unit_x(self):
        return Quaternion(0, 1, 0, 0)

    @property
    def unit_y(self):
        return Quaternion(0, 0, 1, 0)

    @property
    def unit_z(self):
        return Quaternion(0, 0, 0, 1)

    def multiply_scalar(self, scalar_value):
        result = Quaternion(self.w * scalar_value, self.x * scalar_value, 
                           self.y * scalar_value, self.z * scalar_value)
        if not np.isclose(np.linalg.norm([result.w, result.x, result.y, result.z]), 1.0):
            raise ValueError("Resulting quaternion is not normalized")
        return result

