# Calculate pairwise Euclidean distances for numeric DataFrame
import numpy as np
import pandas as pd

def compute_all_pairwise_distances(dataframe):
    # Validate input type
    if not isinstance(dataframe, pd.DataFrame):
        raise TypeError("Input must be a pandas DataFrame")

    # Handle edge cases: empty or single-row DataFrames
    if dataframe.empty or len(dataframe) == 1:
        return np.array([])

    # Check all columns are numeric
    if not all(dataframe.dtypes.apply(pd.api.types.is_numeric_dtype)):
        raise ValueError("DataFrame contains non-numeric values")

    # Initialize distance matrix
    n_samples = len(dataframe)
    n_features = len(dataframe.columns)
    dist_matrix = np.zeros((n_samples, n_samples))

    # Compute symmetric distance matrix
    for idx_i in range(n_samples):
        for idx_j in range(idx_i, n_samples):
            if idx_i == idx_j:
                dist_matrix[idx_i, idx_j] = 0.0
            else:
                vec_i = dataframe.iloc[idx_i].values
                vec_j = dataframe.iloc[idx_j].values
                dist_matrix[idx_i, idx_j] = np.linalg.norm(vec_i - vec_j)
                dist_matrix[idx_j, idx_i] = dist_matrix[idx_i, idx_j]

    return dist_matrix

