# Decorator to validate function inputs based on shape, scope, and custom constraints
def check_parameters(expected_types=None, allowed_module=None, validation_func=None):
    def apply(func):
        def inner(*params, **options):
            if expected_types is not None:
                if len(params) != len(expected_types):
                    raise ValueError(f"Expected {len(expected_types)} parameters, received {len(params)}")
                for idx, value in enumerate(params):
                    if not isinstance(value, expected_types[idx]):
                        raise TypeError(f"Parameter at index {idx+1} must be of type {expected_types[idx]}")
            if allowed_module is not None:
                import inspect
                caller_frame = inspect.currentframe().f_back
                caller_context = inspect.getmodule(caller_frame)
                if caller_context.__name__ != allowed_module:
                    raise ValueError(f"Function invoked from unauthorized module: {caller_context.__name__}")
            if validation_func is not None:
                if not validation_func(*params, **options):
                    raise ValueError("Validation failed: arguments do not meet the required condition")
            return func(*params, **options)
        return inner
    return apply

