# Execute shell commands piped together and return the result
import subprocess
import shlex

def execute_piped_commands(cmd_string: str) -> str:
    cmd_list = cmd_string.split('|')
    result_data = None

    for single_cmd in cmd_list:
        popen_args = {
            'stdout': subprocess.PIPE,
            'stderr': subprocess.PIPE,
            'stdin': subprocess.PIPE,
        }

        parsed_cmd = shlex.split(single_cmd)

        if result_data is not None:
            popen_args['stdin'] = subprocess.PIPE
            proc = subprocess.Popen(
                parsed_cmd, 
                **popen_args, 
                stdin=subprocess.PIPE, 
                stdout=subprocess.PIPE
            )
            result_data, _ = proc.communicate(input=result_data.encode())
        else:
            proc = subprocess.Popen(parsed_cmd, **popen_args)
            result_data, _ = proc.communicate()

    return result_data.decode()

