# Abstract base class for constraints with importance management
from abc import ABCMeta

class InvalidImportanceResetException(Exception):
    pass

class BaseConstraint:
    __metaclass__ = ABCMeta

    def __init__(self, parameters: dict):
        self.parameters = parameters
        self.result = None
        self.processed = False
        self.initial_weight = None
        self.weight = None

    def process_result(self, result: bool):
        self.result = result
        self.processed = True

    def assign_weight(self, weight: float):
        self.initial_weight = weight
        self.weight = weight

