        # Allow safe methods (GET, HEAD, OPTIONS) for everyone
        # Allow write methods only for authenticated staff users
        if request.method in permissions.SAFE_METHODS:
            return True
        if request.user and request.user.is_staff:
            return True
        return False

    def has_object_permission(self, request, view, obj):
        # Same logic as above: safe methods allowed for all, others require staff status
        if request.method in permissions.SAFE_METHODS:
            return True
        if request.user and request.user.is_staff:
            return True
        return False

