# Check if the system is in a deadlock state using Banker's algorithm
def is_deadlock(used_resources, request_limit, free_resources):
    process_count = len(used_resources)  # Total number of processes
    resource_types = len(free_resources)  # Total number of resource kinds

    # Set up working copy of available resources and completion status
    current_work = free_resources.copy()
    completed = [False] * process_count

    # Look for a process that can complete with current resources
    while True:
        progress_made = False
        for idx in range(process_count):
            if not completed[idx] and all(req <= curr for req, curr in zip(request_limit[idx], current_work)):
                # This process can finish with available resources
                progress_made = True
                completed[idx] = True
                current_work = [current_work[r] + used_resources[idx][r] for r in range(resource_types)]
                break

        if not progress_made:
            break

    return all(completed)

