# Perform graph homomorphism search between two undirected graphs
def find_homomorphisms(source_graph, target_graph, limit_results, count_only, initial_mapping, depth_limit):
    from homsearch import HomsearchInterface, graph_to_adjlist, graphmap_to_fmap

    # Ensure both input graphs are undirected
    assert not source_graph.is_directed()
    assert not target_graph.is_directed()

    # Initialize the homomorphism search interface
    hs = HomsearchInterface(
        graph_to_adjlist(source_graph), 
        graph_to_adjlist(target_graph),
        limit_results, 
        (not count_only), 
        False, 
        max_depth=depth_limit
    )

    # Start search either from scratch or with a partial mapping
    if initial_mapping is None:
        hs.search()
    else:
        hs.search_from(graphmap_to_fmap(source_graph, target_graph, initial_mapping))

    # Return either count or actual mappings based on flag
    if count_only:
        return hs.count()
    else:
        return hs.mappings()

# Apache Beam pipeline to process CSV data and compute average age of adults
import apache_beam as beam
from apache_beam.options.pipeline_options import PipelineOptions
import csv

class AgeFilterDoFn(beam.DoFn):
    def process(self, record):
        if int(record['age']) >= 18:
            yield record

class AgeAverageCombiner(beam.CombineFn):
    def create_accumulator(self):
        return (0, 0)  # (total_age, count)

    def add_input(self, accumulator, item):
        return accumulator[0] + int(item['age']), accumulator[1] + 1

    def merge_accumulators(self, partial_accumulators):
        totals, counts = zip(*partial_accumulators)
        return sum(totals), sum(counts)

    def extract_output(self, final_accumulator):
        return final_accumulator[0] / final_accumulator[1] if final_accumulator[1] > 0 else 0

def execute_pipeline(source_file, destination_file):
    pipeline_opts = PipelineOptions()
    with beam.Pipeline(options=pipeline_opts) as pipe:
        raw_lines = pipe | 'LoadData' >> beam.io.ReadFromText(source_file, skip_header_lines=1)
        parsed_data = raw_lines | 'ConvertToDict' >> beam.Map(lambda line: next(csv.DictReader([line], fieldnames=['id', 'name', 'age'])))
        adult_records = parsed_data | 'SelectAdults' >> beam.ParDo(AgeFilterDoFn())
        avg_age_result = adult_records | 'ComputeMeanAge' >> beam.CombineGlobally(AgeAverageCombiner())
        avg_age_result | 'SaveResults' >> beam.io.WriteToText(destination_file)

if __name__ == '__main__':
    input_path = 'input.csv'
    output_path = 'output.csv'
    execute_pipeline(input_path, output_path)

# Find the nth node from the end of a linked list
def get_node_from_tail(linked_list_head, position):
    if linked_list_head is None or position <= 0:
        return None

    pointer_slow = linked_list_head
    pointer_fast = linked_list_head

    # Advance the fast pointer by 'position' nodes
    for _ in range(position):
        if pointer_fast is None:
            return None
        pointer_fast = pointer_fast.next

    # Move both pointers until the fast pointer reaches the end
    while pointer_fast is not None:
        pointer_slow = pointer_slow.next
        pointer_fast = pointer_fast.next

    return pointer_slow.data if pointer_slow is not None else None

