import threading

def worker_function(thread_number):
    print(f"Executing thread {thread_number} performing tasks")

def run_program():
    should_lock = False  # Set to True if lock operations are required
    lock_obj = threading.Lock()  # Create a lock object

    # Generate a collection of threads
    thread_list = [threading.Thread(target=worker_function, args=(i,)) for i in range(5)]

    # Launch all threads in current group
    if should_lock:
        lock_obj.acquire()  # Acquire the lock first when needed

    for t in thread_list:
        t.start()

    # Ensure all threads complete execution
    for t in thread_list:
        t.join()

    # Restore lock state as necessary
    if should_lock:
        lock_obj.release()  # Release the lock after use

if __name__ == "__main__":
    run_program()

