# Abstract base class for JSON resources
from abc import ABC, abstractmethod

class IJSONResource(ABC):
    @abstractmethod
    def get_signature(self) -> str:
        pass

class IBaseResourceSubscriber:
    def __init__(self):
        self.protocol = None

    def set_protocol(self, protocol: IJSONResource) -> None:
        self.protocol = protocol

    def check_signature(self, data: dict) -> bool:
        if self.protocol is None:
            raise ValueError("No protocol has been assigned for signature verification")

        signature = data.get('signature', None)
        if signature is None:
            raise ValueError("Signature missing in the request")

        expected_signature = self.protocol.get_signature()
        return signature == expected_signature

# Check if brackets in a string are balanced and properly nested
def check_bracket_balance(text):
    stack = []
    left_brackets = "({["
    right_brackets = ")}]"
    bracket_map = {')': '(', '}': '{', ']': '['}

    for symbol in text:
        if symbol in left_brackets:
            stack.append(symbol)
        elif symbol in right_brackets:
            if not stack or stack.pop() != bracket_map[symbol]:
                return False

    return len(stack) == 0  # True when no unmatched opening brackets remain

# Unit tests
def test_empty_string_returns_true():
    assert check_bracket_balance('') == True

def test_valid_nested_brackets_returns_true():
    assert check_bracket_balance('[{()}]') == True

def test_unclosed_brackets_returns_false():
    assert check_bracket_balance('[{()}') == False

def test_improperly_nested_brackets_returns_false():
    assert check_bracket_balance('{[}]') == False

def test_extra_closing_bracket_returns_false():
    assert check_bracket_balance('[{()}](') == False

