        self.length = length
        self.note = note

async def timeout_member(
    context: commands.Context,
    targets: commands.Greedy[discord.Member],
    *,
    duration_and_note: TimeoutConfig = {},
):
    for member in targets:
        if context.author.guild_permissions.mute_members:
            if member.voice and member.voice.channel:
                if duration_and_note.length > 0:
                    await member.edit(mute=True, reason=duration_and_note.note)
                    await context.send(f'{member.display_name} has been muted for {duration_and_note.length} minutes.')
                    await asyncio.sleep(duration_and_note.length * 60)
                    await member.edit(mute=False, reason='Mute duration expired')
                    await context.send(f'{member.display_name} has been unmuted.')
                else:
                    await member.edit(mute=True, reason=duration_and_note.note)
                    await context.send(f'{member.display_name} has been permanently muted.')
            else:
                await context.send(f'{member.display_name} is not in a voice channel.')
        else:
            await context.send('You do not have permission to mute members.')

# AWS Secret Manager utility for retrieving parameters from SSM
import boto3
from pathlib import Path
import secrets

class AWSSecretManager:
    def __init__(self, parameter_prefix):
        self.parameter_prefix = parameter_prefix

    def fetch_secrets(self):
        if self.parameter_prefix is None:
            return secrets

        secret_path = Path(self.parameter_prefix)
        ssm_client = boto3.client('ssm')
        response = ssm_client.get_parameters_by_path(
            Path=secret_path,
            Recursive=True,
            WithDecryption=True
        )

        secret_dict = {}
        for param in response['Parameters']:
            param_name = param['Name'].split('/')[-1]
            param_value = param['Value']
            secret_dict[param_name] = param_value

        return secret_dict

