        self.points = [None] * 13  # Initialize points list with 13 elements

    def check_three_of_a_kind(self, rolls: List[int]) -> int:
        if self.points[6] is None:
            self.points[6] = sum(rolls) if any(rolls.count(val) >= 3 for val in rolls) else 0
        return self.points[6]

    def check_four_of_a_kind(self, rolls: List[int]) -> int:
        if self.points[7] is None:
            self.points[7] = sum(rolls) if any(rolls.count(val) >= 4 for val in rolls) else 0
        return self.points[7]

    def check_full_house(self, rolls: List[int]) -> int:
        if self.points[8] is None:
            frequency = [rolls.count(val) for val in set(rolls)]
            self.points[8] = 25 if 2 in frequency and 3 in frequency else 0
        return self.points[8]

    def check_small_straight(self, rolls: List[int]) -> int:
        if self.points[9] is None:
            unique_rolls = sorted(set(rolls))
            self.points[9] = 30 if len(unique_rolls) >= 4 and max(unique_rolls) - min(unique_rolls) >= 3 else 0
        return self.points[9]

    def check_large_straight(self, rolls: List[int]) -> int:
        if self.points[10] is None:
            unique_rolls = sorted(set(rolls))
            self.points[10] = 40 if len(unique_rolls) == 5 and max(unique_rolls) - min(unique_rolls) == 4 else 0
        return self.points[10]

    def check_chance(self, rolls: List[int]) -> int:
        if self.points[11] is None:
            self.points[11] = sum(rolls)
        return self.points[11]

