# AWS DynamoDB utility class for table management
import boto3
from boto3.dynamodb import types as dynamodb_types

class DynamoTableHandler:
    def __init__(self, aws_region):
        self.dynamodb_resource = boto3.resource('dynamodb', region_name=aws_region)

    def establish_table(self, table_identifier, key_field, key_data_type):
        table = self.dynamodb_resource.create_table(
            TableName=table_identifier,
            KeySchema=[
                {
                    'AttributeName': key_field,
                    'KeyType': 'HASH'  # Defines the partition key
                }
            ],
            AttributeDefinitions=[
                {
                    'AttributeName': key_field,
                    'AttributeType': key_data_type
                }
            ],
            ProvisionedThroughput={
                'ReadCapacityUnits': 5,
                'WriteCapacityUnits': 5
            }
        )
        # Wait until the table is fully created
        table.meta.client.get_waiter('table_exists').wait(TableName=table_identifier)

