# Check if two dice have matching digits for compatibility
def has_digit_pair(die_val1: int, die_val2: int, first_digit: int, second_digit: int) -> bool:
    return (str(first_digit) in str(die_val1) and str(second_digit) in str(die_val1)) or \
           (str(first_digit) in str(die_val2) and str(second_digit) in str(die_val2))

def are_dice_compatible(die_a: int, die_b: int) -> bool:
    # Check required digit pairs for compatibility
    if not has_digit_pair(die_a, die_b, 3, 6) and not has_digit_pair(die_a, die_b, 3, 9):
        return False
    if not has_digit_pair(die_a, die_b, 4, 9) and not has_digit_pair(die_a, die_b, 4, 6):
        return False
    if not has_digit_pair(die_a, die_b, 6, 4) and not has_digit_pair(die_a, die_b, 9, 4):
        return False
    if not has_digit_pair(die_a, die_b, 8, 1):
        return False
    return True

