# Calculate the score based on game moves
from typing import List, Tuple
from enforce_typing import enforce_types

draw_score: int = 0
penalty_loss: int = -25
invalid_action: int = -1
valid_action: int = 1
capture_bonus: int = 5
promotion_bonus: int = 5

@enforce_types
def vector_difference(v1: Tuple[int, int], v2: Tuple[int, int]) -> Tuple[int, int]:
    return tuple(map(lambda x, y: x - y, v1, v2))

@enforce_types
def vector_sum(v1: Tuple[int, int], v2: Tuple[int, int]) -> Tuple[int, int]:
    return tuple(map(lambda x, y: x + y, v1, v2))

@enforce_types
def compute_points(actions: List[Tuple[Tuple[int, int], Tuple[int, int]]]) -> int:
    points = 0
    for action in actions:
        origin, destination = action
        displacement = vector_difference(destination, origin)
        if displacement == (1, 1) or displacement == (-1, -1) or displacement == (1, -1) or displacement == (-1, 1):
            points += valid_action
        elif displacement == (2, 2) or displacement == (-2, -2) or displacement == (2, -2) or displacement == (-2, 2):
            points += capture_bonus
        elif displacement == (3, 3) or displacement == (-3, -3) or displacement == (3, -3) or displacement == (-3, 3):
            points += promotion_bonus
        else:
            points += invalid_action
    return points

