import torch.nn as nn

class Network(nn.Module):
    def __init__(self, layers_count, image_size, input_channels, nonlinearity, embedding_dim):
        super(Network, self).__init__()
        assert nonlinearity in ("ReLU", "LeakyReLU"), "Supported activation functions are ReLU and LeakyReLU"

        self.convs = nn.ModuleList()
        self.convs.append(nn.Conv2d(input_channels, 64, kernel_size=3, stride=1, padding=1))
        self.convs.append(nn.MaxPool2d(kernel_size=2, stride=2))

        for _ in range(layers_count - 1):
            self.convs.append(nn.Conv2d(64, 64, kernel_size=3, stride=1, padding=1))
            self.convs.append(nn.MaxPool2d(kernel_size=2, stride=2))

        self.classifier = nn.Linear(64 * (image_size // (2 ** layers_count)) * (image_size // (2 ** layers_count)), embedding_dim)

        if nonlinearity == "ReLU":
            self.nonlinearity = nn.ReLU()
        else:
            self.nonlinearity = nn.LeakyReLU()

    def forward(self, input_tensor):
        for conv_layer in self.convs:
            input_tensor = conv_layer(input_tensor)
        input_tensor = input_tensor.view(input_tensor.size(0), -1)
        input_tensor = self.classifier(input_tensor)
        output = self.nonlinearity(input_tensor)
        return output

