# XOR-based file encryption/decryption tool
import sys

def transform_file(input_path, output_path, secret):
    try:
        with open(input_path, 'rb') as in_file, open(output_path, 'wb') as out_file:
            secret_bytes = secret.encode('utf-8')
            secret_len = len(secret_bytes)
            pos = 0
            while True:
                chunk = in_file.read(1)
                if not chunk:
                    break
                transformed_byte = bytes([chunk[0] ^ secret_bytes[pos]])
                out_file.write(transformed_byte)
                pos = (pos + 1) % secret_len
    except FileNotFoundError:
        print("Input file missing!")
        sys.exit(2)

def revert_file(input_path, output_path, secret):
