import base64
from Crypto.Cipher import AES
from Crypto.Protocol.KDF import PBKDF2
from Crypto.Random import get_random_bytes

class SecureConfigParser(ConfigParser):
    def __init__(self, *args, **kwargs):
        encryption_key = kwargs.pop('encryption_password', None)
        if encryption_key is not None:
            self.encryption_key = encryption_key
        else:
            self.encryption_key = None
        ConfigParser.__init__(self, *args, **kwargs)

    def get(self, section, option, *args, **kwargs):
        raw_value = ConfigParser.get(self, section, option, *args, **kwargs)
        if self.encryption_key is not None and raw_value.startswith('ENCRYPTED:'):
            encrypted_payload = base64.b64decode(raw_value[len('ENCRYPTED:'):])
            salt_material = encrypted_payload[:16]
            cipher_text = encrypted_payload[16:]
            derived_key = PBKDF2(self.encryption_key, salt_material, dkLen=32)
            aes_cipher = AES.new(derived_key, AES.MODE_GCM, nonce=cipher_text[:16])
            decrypted_content = aes_cipher.decrypt_and_verify(cipher_text[16:], cipher_text[16:])
            return decrypted_content.decode('utf-8')
        else:
            return raw_value

