        self.dataset = kwargs.get('X', None)
        self.document_limits = kwargs.get('doc_range', None)
        self.total_docs = kwargs.get('nDocTotal', None)

    @classmethod
    def load_from_npz(cls, npz_file_path, total_docs_count=None, **kwargs):
        ''' Factory method to create a DocumentGroupData instance from an npz file on disk
        '''
        import numpy as np
        loaded_vars = np.load(npz_file_path)
        if 'X' not in loaded_vars:
            raise KeyError('Required field X missing in the npz file')
        if 'doc_range' not in loaded_vars:
            raise KeyError('Required field doc_range missing in the npz file')
        if total_docs_count is not None:
            loaded_vars['nDocTotal'] = total_docs_count
        return cls(**loaded_vars)

    @classmethod
    def load_from_mat(cls, mat_file_path, total_docs_count=None, **kwargs):
        ''' Factory method to create a DocumentGroupData instance from a MATLAB .mat file on disk
        '''
        import scipy.io
        loaded_data = scipy.io.loadmat(mat_file_path)
        if 'X' not in loaded_data:
            raise KeyError('Required field X missing in the mat file')
        if 'doc_range' not in loaded_data:
