    def isSubtree(self, root1: TreeNode, root2: TreeNode) -> bool:
        def are_identical_trees(node1: TreeNode, node2: TreeNode) -> bool:
            if not node1 and not node2:
                return True
            if not node1 or not node2:
                return False
            return (node1.val == node2.val and 
                    are_identical_trees(node1.left, node2.left) and 
                    are_identical_trees(node1.right, node2.right))

