# Module for handling basic authentication identification
import base64

class AuthenticationException(Exception):
    pass

class BasicAuthenticationHandler:
    def authenticate(self, request_headers):
        auth_header = request_headers.get('HTTP_AUTHORIZATION')

        if not auth_header:
            raise AuthenticationException("Invalid credentials in HTTP_AUTHORIZATION header")

        auth_parts = auth_header.split()
        if len(auth_parts) != 2 or auth_parts[0] != 'Basic':
            raise AuthenticationException("Invalid credentials in HTTP_AUTHORIZATION header")

        encoded_credentials = auth_parts[1]
        try:
            decoded_bytes = base64.b64decode(encoded_credentials)
            decoded_text = decoded_bytes.decode('utf-8')
            return decoded_text
        except (TypeError, UnicodeDecodeError):
            raise AuthenticationException("Invalid credentials in HTTP_AUTHORIZATION header")

