from scipy.spatial import cKDTree

class NearestNeighborData(LowResHighResDataset):
    def __init__(self, dataset: LowResHighResDataset, num_models=None, model_index=None, k_neighbors=16):
        super().__init__(dataset.low_res_data, dataset.high_res_data, dataset.region_geometries)
