        self.selected_model = model_index
        self.k_neighbors = k_neighbors
        self.high_resolution_tree = self._construct_high_res_tree()

    def _construct_high_res_tree(self):
        points = self.high_res_data if self.selected_model is None else self.high_res_data[self.selected_model]
        return cKDTree(points)

    def find_nearest_neighbors(self, low_res_point):
        query_point = low_res_point
        if self.selected_model is not None:
            query_point = np.expand_dims(query_point, axis=0)

        distances, neighbor_indices = self.high_resolution_tree.query(query_point, k=self.k_neighbors)

