# Test file system mapper functionality 
import os
import fsspec

class StorageHandler:
    def __init__(self, root_directory):
        self.root_directory = root_directory

    def save_file(self, relative_path, data):
        absolute_path = os.path.join(self.root_directory, relative_path)
        with open(absolute_path, "w") as f:
            f.write(data)

    def load_file(self, relative_path):
        absolute_path = os.path.join(self.root_directory, relative_path)
        with open(absolute_path, "r") as f:
            return f.read()

    def check_existence(self, relative_path):
        absolute_path = os.path.join(self.root_directory, relative_path)
        return os.path.exists(absolute_path)

    @staticmethod
    def are_same_mapper(storage1, storage2):
        return storage1 == storage2

def validate_storage_handler(tmpdir):
    storage_handler = StorageHandler(tmpdir)
    storage_handler.save_file("subdir/secondfile", "sample2")

    assert storage_handler.check_existence("firstfile") == False
    assert storage_handler.load_file("subdir/secondfile") == "sample2"

    mapper = fsspec.get_mapper("file://" + tmpdir)
    assert "firstfile" in mapper
    assert mapper["subdir/secondfile"] == b"sample2"

    fs_backend = fsspec.filesystem("file")
    mapper_b = fs_backend.get_mapper(tmpdir)
    mapper_c = fs_backend.get_mapper("file://" + tmpdir)
    assert StorageHandler.are_same_mapper(mapper, mapper_b) == True
    assert StorageHandler.are_same_mapper(mapper, mapper_c) == True

