# Validate configuration settings for a system
from enum import Enum
from typing import List
import json

class State(Enum):
    active = 1
    inactive = 0

class Settings:
    def __init__(self, name: str, identifier: str, data: str, state: State):
        self.name = name
        self.identifier = identifier
        self.data = data
        self.state = state

def check_settings(settings_obj: Settings) -> List[str]:
    issues = []
    if not settings_obj.name or len(settings_obj.name) > 200:
        issues.append("Name must not be empty and should not exceed 200 characters.")
    if not settings_obj.identifier or len(settings_obj.identifier) > 20:
        issues.append("Identifier must not be empty and should not exceed 20 characters.")
    try:
        json.loads(settings_obj.data)
    except json.JSONDecodeError:
        issues.append("Data must be a valid JSON object.")
    if settings_obj.state not in [State.active, State.inactive]:
        issues.append("State must be a valid enumeration value.")
    return issues

