def fetch_todos(user_identifier: int, filter_status: Optional[str] = None, 
                filter_priority: Optional[str] = None, max_results: int = 50) -> List[Todo]:
    return todo_repository.fetch_todos(user_identifier, status=filter_status, priority=filter_priority, limit=max_results)

def retrieve_todo(user_identifier: int, todo_identifier: str) -> Optional[Todo]:
    return todo_repository.retrieve_todo(user_identifier, todo_identifier)

def add_todo(
    user_identifier: int,
    title: str,
    description: Optional[str] = None,
    tag_list: Optional[List[str]] = None,
    deadline: Optional[str] = None,
    severity: Optional[str] = None,
) -> Todo:
    new_todo = Todo(
        todo_id=generate_unique_id(),
        name=title,
        desc=description,
        tags=tag_list,
        due_date=deadline,
        priority=severity,
        status="pending",
        history=[TodoHistoryEntry(
            timestamp=get_current_utc_timestamp_iso(), 
            unix_timestamp=get_current_unix_time(), 
            action="created"
        )],
    )
    return todo_repository.store_todo(user_identifier, new_todo)

def modify_todo(user_identifier: int, todo_identifier: str, **updates) -> Optional[Todo]:
    target_todo = todo_repository.retrieve_todo(user_identifier, todo_identifier)
    if not target_todo:
        return None

    modified_fields = []
    for field_name, new_value in updates.items():
        if hasattr(target_todo, field_name) and getattr(target_todo, field_name) != new_value:
            setattr(target_todo, field_name, new_value)
            modified_fields.append(field_name)

    if modified_fields:
        current_history = target_todo.history or []
        current_history.append(TodoHistoryEntry(
            timestamp=get_current_utc_timestamp_iso(),
            unix_timestamp=get_current_unix_time(),
            action="updated",
            note=f"modified: {', '.join(f'{attr}= {getattr(target_todo, attr)!r}' for attr in modified_fields)}",
        ))
        target_todo.history = current_history
        return todo_repository.store_todo(user_identifier, target_todo)

    return target_todo

def complete_todo(user_identifier: int, todo_identifier: str) -> Optional[Todo]:
    target_todo = todo_repository.retrieve_todo(user_identifier, todo_identifier)
    if not target_todo:
        return None

    target_todo.status = "completed"
    target_todo.completed_at = get_current_utc_timestamp_iso()

    current_history = target_todo.history or []
    current_history.append(TodoHistoryEntry(
