# Script to scan GitHub repositories and extract summaries from README files
import json
import sys
from pathlib import Path

def fetch_repo_description(repo_directory):
    """Attempt to retrieve a brief description from README or repository metadata."""
    possible_readmes = ["README.md", "README.MD", "readme.md", "README", "README.txt"]
    for readme_name in possible_readmes:
        readme_file = repo_directory / readme_name
        if readme_file.is_file():
            try:
                with open(readme_file, "r", encoding="utf-8") as f:
                    text = f.read()
                    non_empty_lines = [line.strip() for line in text.split("\n") if line.strip()]
                    if not non_empty_lines:
                        continue
                    for line in non_empty_lines:
                        if not line.startswith("#"):
                            return line[:200]
                    # If first non-empty line is a header, strip the '#' and use it
                    first_line = non_empty_lines[0].lstrip("#").strip()
                    return first_line[:200]
            except Exception:
                continue
    return "No description available"

def list_github_repos(base_dir):
    """Traverse the given directory and collect information about GitHub repositories."""
    base_path = Path(base_dir)
    if not base_path.exists():
        return {"error": "Directory does not exist", "path": str(base_path)}

    repositories = []
    for entry in base_path.iterdir():
        if entry.is_dir() and not entry.name.startswith(".") and (entry / ".git").exists():
            repositories.append({
                "name": entry.name,
                "path": str(entry),
                "description": fetch_repo_description(entry),
            })

    return {"repos": repositories, "path": str(base_path)}

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: scan_repos.py <github_directory>")
        raise SystemExit(1)

    output = list_github_repos(sys.argv[1])
    print(json.dumps(output, indent=2, ensure_ascii=False))

