# Import necessary modules for neural network operations and logging
import torch
import torch.nn as nn
from cosmos_rl.utils.logging import logger
from transformers.activations import ACT2CLS

class MLPFusedActMul(nn.Module):
    def __init__(self, fused_op: torch.autograd.Function):
        super().__init__()
        self.fused_op = fused_op

    def forward(self, x: torch.Tensor, y: torch.Tensor) -> torch.Tensor:
        return self.fused_op.apply(x, y)

class MLPActMulFunc(nn.Module):
    def __init__(self, activation_module: nn.Module):
        super().__init__()
        self.activation_module = activation_module

    def forward(self, input_a: torch.Tensor, input_b: torch.Tensor) -> torch.Tensor:
        return self.activation_module(input_a) * input_b

    def liger_equivalent(self):
        if isinstance(self.activation_module, ACT2CLS["silu"]):
            from liger_kernel.ops.swiglu import LigerSiLUMulFunction
            return MLPFusedActMul(LigerSiLUMulFunction)
        elif isinstance(self.activation_module, ACT2CLS["gelu"]):
            from liger_kernel.ops.geglu import LigerGELUMulFunction
            return MLPFusedActMul(LigerGELUMulFunction)
        else:
            logger.warning(
                f"Unsupported activation function: {self.activation_module}. Will fallback to the default implementation."
            )
            return self

# Verify agent reported hook testing outcomes
from __future__ import annotations
import logging
from typing import TYPE_CHECKING
from rossum_agent.agent.models import ToolResultStep
from regression_tests.custom_checks._utils import call_haiku_check, get_final_answer

if TYPE_CHECKING:
    from rossum_agent.agent.models import AgentStep

logger = logging.getLogger(__name__)

_HOOK_TEST_PROMPT = """Evaluate the agent's final response regarding serverless hook development and validation.
Final response:
{final_response}
Does it:
1. Include outcomes of hook testing (e.g., results from test_hook)
2. Specify if the hook ran successfully or encountered an error?
Respond with a JSON object:
{{"success": true/false, "justification": "Concise rationale"}}"""

def verify_hook_test_outcome(steps: list[AgentStep], _api_base_url: str, _api_token: str) -> tuple[bool, str]:
    """Confirm agent invoked test_hook and communicated its outcome."""
    tool_names = [tc.name for step in steps if isinstance(step, ToolResultStep) for tc in step.tool_calls]
    if "test_hook" not in tool_names:
        return False, "test_hook was not executed"

    for step in steps:
        if not isinstance(step, ToolResultStep):
            continue
        for tr in step.tool_results:
            if tr.name == "test_hook":
                logger.debug("test_hook output: %s", tr.content)

    final_response = get_final_answer(steps)
    if not final_response:
        return False, "No concluding statement found"

