import base64
import re
import time
from io import BytesIO
from cosmos_rl_reward.handler.reward_base import BaseRewardHandler
from cosmos_rl_reward.handler.registry import RewardRegistry
from cosmos_rl_reward.utils.logging import logger

@RewardRegistry.register()
class UnifiedReward(BaseRewardHandler):
    NEEDS_LATENT_DECODER = False
    reward_name = "unified_reward"

    def __init__(self, endpoint_url="", endpoint_api_key="", **kwargs):
        super().__init__()
        self.endpoint_url = endpoint_url
        self.endpoint_api_key = endpoint_api_key

    def set_up(self):
        from openai import OpenAI
        self.client = OpenAI(api_key=self.endpoint_api_key, base_url=self.endpoint_url)

    def image_to_base64(self, img):
        buffer = BytesIO()
        img.save(buffer, format="PNG")
        encoded_str = base64.b64encode(buffer.getvalue()).decode("utf-8")
        return f"data:image;base64,{encoded_str}"

    def _parse_scores(self, text_list):
        score_values = []
        regex_pattern = r"Final Score:\s*([1-5](?:\.\d+)?)"
        for text in text_list:
            found = re.search(regex_pattern, text)
            if found:
                try:
                    score_values.append(float(found.group(1)))
                except ValueError:
                    score_values.append(0.0)
            else:
                score_values.append(0.0)
        return score_values

    def assess_image(self, caption, picture):
        instruction = f"<image>\nYou are given a text caption and a generated image based on that caption. Your task is to evaluate this image based on two key criteria:\n1. Alignment with the Caption: Assess how well this image aligns with the provided caption. Consider the accuracy of depicted objects, their relationships, and attributes as described in the caption.\n2. Overall Image Quality: Examine the visual quality of this image, including clarity, detail preservation, color accuracy, and overall aesthetic appeal.\nBased on the above criteria, assign a score from 1 to 5 after 'Final Score:'.\nYour task is provided as follows:\nText Caption: [{caption}]"
        encoded_img = self.image_to_base64(picture)
        response = self.client.chat.completions.create(
            model="UnifiedReward-7b-v1.5",
            messages=[
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image_url",
                            "image_url": {"url": encoded_img},
                        },
                        {
                            "type": "text",
                            "text": instruction,
                        },
                    ],
                },
            ],
            temperature=0,
            stream=False,
        )
        return response.choices[0].message.content

    def assess_batch_images(self, images_list, captions_list):
        outputs = [
            self.assess_image(caption, img) for caption, img in zip(captions_list, images_list)
        ]
        return outputs

    def compute_reward(self, images_data, info_dict):
        import torch
        from PIL import Image

        def _handle_error(msg: str):
            logger.error(msg)
            return {
                "error": msg,
                "scores": None,
                "input_info": info_dict.get("input_info", {}),
                "duration": "0.00",
                "decoded_duration": info_dict.get("decode_duration", "N/A"),
                "type": self.reward_name,
            }

        start_time = time.perf_counter()

        # Validate input images
        if images_data is None:
            return _handle_error("[unified_reward] images tensor is None.")

        if not isinstance(images_data, torch.Tensor) or images_data.dim() != 4:
            return _handle_error(
                f"[unified_reward] expects 4D torch.Tensor in BHWC/NHWC layout (B,H,W,C); got type={type(images_data)} shape={getattr(images_data, 'shape', None)} dtype={getattr(images_data, 'dtype', None)}"
            )

        if images_data.shape[0] == 0:
            return _handle_error("[unified_reward] images batch size is zero.")

        # Process tensor data
        processed_images = images_data
        if processed_images.dtype != torch.uint8:
            processed_images = processed_images.to(torch.uint8)

        # Ensure NHWC layout
        if processed_images.shape[-1] == 3:
            nhwc_images = processed_images
        elif processed_images.shape[1] == 3:
            nhwc_images = processed_images.permute(0, 2, 3, 1).contiguous()
        else:
            raise ValueError(f"channel dim must be 3, got shape {processed_images.shape}")

        # Convert to PIL images
        pil_images = [
            Image.fromarray(nhwc_images[i].cpu().numpy()) for i in range(nhwc_images.shape[0])
        ]

        # Handle prompts/captions
        captions = info_dict.get("prompts")
        if captions is None:
            return _handle_error("[unified_reward] prompts are required and cannot be None.")

        if isinstance(captions, str):
            captions = [captions]

        if len(captions) != len(pil_images):
            return _handle_error(
                f"[unified_reward] prompts length ({len(captions)}) must match batch size ({len(pil_images)})."
            )

        # Evaluate images
        evaluation_results = self.assess_batch_images(pil_images, captions)
        raw_scores = self._parse_scores(evaluation_results)

        # Normalize scores to [0, 1]
        normalized_scores = [score / 5.0 for score in raw_scores]

        elapsed_time = time.perf_counter() - start_time
        duration_str = f"{elapsed_time:.2f}"

        return {
            "scores": {"unified_reward": normalized_scores},
            "input_info": info_dict.get("input_info", {}),
            "duration": duration_str,
            "decoded_duration": info_dict.get("decode_duration", "N/A"),
            "type": self.reward_name,
        }

# Validation result model for API validation checks
from typing import Any, Dict, List, Optional

class CheckResult:
    """Simple validation outcome representation used by volcengine-api.
    This class maintains a minimal interface: indicates if validation succeeded,
    holds error messages, and optionally includes additional contextual data.
    """
    __slots__ = ("passed", "messages", "metadata")

    def __init__(self, passed: bool, messages: Optional[List[str]] = None, metadata: Optional[Dict[str, Any]] = None):
        self.passed = bool(passed)
        self.messages = list(messages) if messages is not None else []
        self.metadata = dict(metadata) if metadata is not None else {}

    def to_dict(self) -> Dict[str, Any]:
        return {"passed": self.passed, "messages": self.messages, "metadata": self.metadata}

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, CheckResult):
            return NotImplemented
        return (self.passed == other.passed and 
                self.messages == other.messages and 
                self.metadata == other.metadata)

    def __repr__(self) -> str:
