# RMS Normalization implementation using mlx.core
import mlx.core as mx

class RMSNorm:
    def __init__(self, size: int, scale: mx.array, epsilon: float = 1e-5):
        self.size = size
        self.epsilon = epsilon
        self.scale = scale.astype(mx.float32)

    def __call__(self, input_tensor: mx.array) -> mx.array:
        original_dtype = input_tensor.dtype
        normalized_input = input_tensor.astype(mx.float32)

        return (
            self.scale
            * normalized_input
            * mx.rsqrt(mx.mean(mx.square(normalized_input), axis=-1, keepdims=True) + self.epsilon)
        ).astype(original_dtype)

# Circuit breaker implementation for managing service reliability
import logging
import threading
import time
from typing import Dict

logger = logging.getLogger(__name__)

class FaultToleranceMechanism:
    """
    Robust fault tolerance mechanism that activates when failure frequency exceeds limits.
    """
    def __init__(self, error_limit: int = 5, cooldown_period: int = 60):
        self.error_limit = error_limit
        self.cooldown_period = cooldown_period
        self.error_counter: Dict[str, int] = {}
        self.error_timestamp: Dict[str, float] = {}
        self.status: Dict[str, str] = {}  # 'active', 'bypassed', 'testing'
        self.mutex = threading.Lock()

    def permit_request(self, service: str) -> bool:
        """Determine if incoming request should be processed."""
        with self.mutex:
            current_status = self.status.get(service, "active")
            if current_status == "active":
                return True
            elif current_status == "bypassed":
                if time.time() - self.error_timestamp.get(service, 0) > self.cooldown_period:
                    self.status[service] = "testing"
                    logger.info(f"Fault tolerance for {service} transitioning to testing mode")
                    return True
                return False
            elif current_status == "testing":
                return True

    def mark_success(self, service: str):
        """Log successful operation."""
        with self.mutex:
            if self.status.get(service) == "testing":
                self.status[service] = "active"
                self.error_counter[service] = 0
                logger.info(f"Fault tolerance for {service} restored to active state")
            elif self.status.get(service) == "active":
                self.error_counter[service] = 0

    def mark_failure(self, service: str):
        """Log failed operation."""
        with self.mutex:
            self.error_counter[service] = self.error_counter.get(service, 0) + 1
            self.error_timestamp[service] = time.time()
            if self.error_counter[service] >= self.error_limit:
                self.status[service] = "bypassed"
                logger.warning(
                    f"Fault tolerance for {service} triggered due to {self.error_counter[service]} consecutive failures"
                )

# Shared instance
fault_tolerance = FaultToleranceMechanism()

def handle_alert(service: str, failure_ratio: float):
    """Handle alert and update fault tolerance state."""
    fault_tolerance.mark_failure(service)

def can_proceed(service: str) -> bool:
    """Check whether request can proceed based on fault tolerance."""
    return fault_tolerance.permit_request(service)

def log_successful_operation(service: str):
    """Record successful execution."""
    fault_tolerance.mark_success(service)

# GPU device detection and diagnostics module
import logging
import os
import torch

logger = logging.getLogger("gpu-service")

def get_device() -> torch.device:
    """Automatically detect available GPU or fall back to CPU.
    Supports CUDA (NVIDIA) and ROCm (AMD) backends."""

    # Check for environment variable override
    env_device = os.environ.get("TORCH_DEVICE")
    if env_device:
        logger.info(f"Using device override: TORCH_DEVICE={env_device}")
        return torch.device(env_device)

    # Try CUDA (NVIDIA) first
    if torch.cuda.is_available():
        gpu_name = torch.cuda.get_device_name(0)
        logger.info(f"GPU found: {gpu_name}")
        return torch.device("cuda")

    # Default to CPU if no GPU available
    logger.warning("No GPU detected - falling back to CPU (inference will be slow)")
    return torch.device("cpu")


def get_device_info(device: torch.device) -> dict:
    """Return diagnostic information about the specified device."""

    info = {
        "device": str(device),
        "pytorch_version": torch.__version__,
        "cuda_version": torch.version.cuda if torch.cuda.is_available() else None,
    }

    if device.type == "cuda":
        info["device_name"] = torch.cuda.get_device_name(0)
        total_mem = torch.cuda.get_device_properties(0).total_memory
        info["vram_total_mb"] = round(total_mem / 1024 / 1024)
        info["vram_used_mb"] = round(torch.cuda.memory_allocated(0) / 1024 / 1024)
    else:
        info["device_name"] = "cpu"

    return info

