# Set permissions for a directory and its contents
import os
from pathlib import Path
from checkpoint.common.constant import DIR_MODE, FILE_MODE

def configure_directory_access(target_path: str | Path) -> None:
    # Apply permissions to the main directory
    target_path.chmod(DIR_MODE)
    # Recursively process all subdirectories and files
    try:
        for current_root, subdirs, filenames in os.walk(target_path):
            # Convert root path to Path object for consistent operations
            current_path = Path(current_root)
            # Set permissions for each subdirectory
            for subdir in subdirs:
                (current_path / subdir).chmod(DIR_MODE)
            # Set permissions for each file
            for filename in filenames:
                (current_path / filename).chmod(FILE_MODE)
    except OSError as error:
        raise OSError(f"Failed to set permissions for directory: {target_path}") from error

