# Trust-aware scheduler for GPU tile processing with attention computation
import torch
from torch.backends.cuda import sdp_kernel
import heapq, math

class TrustScheduler:
    def __init__(self, top_k=8):
        self.top_k = top_k
        self.stream_focus = torch.cuda.Stream(priority=-1)
        self.stream_periph = torch.cuda.Stream(priority=0)

    def select_top_tiles(self, trust_scores):
        # trust_scores: dict {tile_id: score}
        return heapq.nlargest(self.top_k, trust_scores.items(), key=lambda item: item[1])

    def execute_cycle(self, trust_scores, peripheral_data, tile_data):
        """
        trust_scores: {tile_id: score}
        peripheral_data: iterable of small records (bytes-like)
        tile_data: {tile_id: (q,k,v) torch.cuda tensors}
        """
        selected_tiles = self.select_top_tiles(trust_scores)

        # Handle peripheral communication (placeholder)
        with torch.cuda.stream(self.stream_periph):
            pass  # call into CUDA ext to push peripheral_data

        # Process focus tiles with deep analysis
        with torch.cuda.stream(self.stream_focus):
            for tile_id, score in selected_tiles:
                q, k, v = tile_data[tile_id]
                with sdp_kernel(enable_flash=True, enable_mem_efficient=True, enable_math=True):
                    _ = torch.nn.functional.scaled_dot_product_attention(q, k, v, is_causal=False)

        torch.cuda.synchronize()

if __name__ == "__main__":
    torch.cuda.init()
    scheduler = TrustScheduler(top_k=4)

    # Generate trust scores using sine function
    trust_scores = {i: math.sin(i) + 1.0 for i in range(16)}

    # Define tensor dimensions
    B, H, S, D = 1, 2, 128, 64

    # Create tile tensors on GPU
    tile_tensors = {
        i: (
            torch.randn(B, H, S, D, device='cuda', dtype=torch.float16),
            torch.randn(B, H, S, D, device='cuda', dtype=torch.float16),
            torch.randn(B, H, S, D, device='cuda', dtype=torch.float16)
        ) 
        for i in range(16)
    }

    # Run the scheduling cycle
    scheduler.execute_cycle(trust_scores, peripheral_data=[], tile_data=tile_tensors)
    print("cycle complete")

# Test module for MLA decoding with split KV cache
import math
import pytest
import torch
import tilegym
from tests import common

class Test_MLADecodingSplitKV(common.PyTestCase):
    @staticmethod
    def baseline(q, q_pos_emb, kv_cache, k_pos_emb, scale=None, dtype=torch.half):
        """Baseline implementation using PyTorch for MLA decoding (equivalent to test_mla_decoding.py)"""
        if scale is None:
            scale = 1.0 / (math.sqrt(q.size(-1) + q_pos_emb.size(-1)))
        original_dtype = q.dtype
        q = q.to(dtype)
        q_pos_emb = q_pos_emb.to(dtype)
        kv_cache = kv_cache.to(dtype)
        k_pos_emb = k_pos_emb.to(dtype)

        # Compute attention scores: Q*K^T + QPE*KPE^T
        attn_scores = torch.matmul(q, kv_cache.transpose(1, 2)).float()
        if k_pos_emb.numel() > 0:
            attn_scores = attn_scores + torch.matmul(q_pos_emb, k_pos_emb.transpose(1, 2)).float()
        attn_scores = attn_scores * scale

        # Apply softmax
        max_vals = torch.max(attn_scores, dim=-1)[0]
        exp_scores = torch.exp(attn_scores - max_vals.unsqueeze(-1))
        sum_exp = torch.sum(exp_scores, dim=-1)
        probs = exp_scores / (sum_exp.unsqueeze(-1))

        # Apply attention to values
        output = torch.matmul(probs.to(original_dtype).to(dtype), kv_cache).to(original_dtype)
        return output

    @staticmethod
    def _compute_scale(q, qpe):
        """Compute the default scaling factor for attention"""
        return 1.0 / (math.sqrt(q.size(-1) + qpe.size(-1)))

    _supported_backends = ["cutile"]

    @pytest.mark.parametrize("num_heads", [16, 32])
    @pytest.mark.parametrize("sequence_length", [129, 1024, 8192, 11049])
    @pytest.mark.parametrize("kv_chunk_size", [128, 512])
    @pytest.mark.parametrize("precision", [torch.float16])
    @pytest.mark.parametrize("backend", _supported_backends)
    def test_operation(self, num_heads, sequence_length, kv_chunk_size, precision, backend, arch):
        """Verify functional correctness of MLA decoding with split-kv"""
        if tilegym.is_backend_available(backend):
            tilegym.set_backend(backend)
        else:
            pytest.skip(f"Backend {backend} is not supported")

        self.setUp()

        # Skip test if CUDA is unavailable
        if not torch.cuda.is_available():
            pytest.skip("CUDA not available, skipping MLA Split-KV test")

        # Configuration parameters
        batch_size = 1
        embedding_dim = 512
        positional_dim = 64

        # Initialize random inputs for reproducibility
        torch.manual_seed(42)
        device = torch.device("cuda")
        query = torch.randn(batch_size, num_heads, embedding_dim, device=device).to(precision)
        query_pe = torch.randn(batch_size, num_heads, positional_dim, device=device).to(precision)
        key_values = torch.randn(batch_size, sequence_length, embedding_dim, device=device).to(precision)
        key_pe = torch.randn(batch_size, sequence_length, positional_dim, device=device).to(precision)

        # Calculate softmax scale
        scale_factor = self._compute_scale(query, query_pe)

        def split_kv_call():
            return tilegym.ops.mla_decoding_split_kv(query, query_pe, key_values, key_pe, scale_factor, kv_chunk_size)

        def reference_call():
            return self.baseline(query, query_pe, key_values, key_pe, scale_factor)

        self.assertCorrectness(split_kv_call, reference_call, {}, atol=1e-2, rtol=1e-2, multiple_outputs=False)

# Remove outputs and execution counts from Jupyter notebooks
import json
import sys

def clean_notebook(path: str) -> bool:
    """Clear outputs and reset execution counts. Return True if changes were made."""
    with open(path) as file:
        notebook = json.load(file)
    changed = False
    for cell in notebook["cells"]:
        if cell["cell_type"] == "code":
            if cell["outputs"]:
                cell["outputs"] = []
                changed = True
            if cell["execution_count"] is not None:
                cell["execution_count"] = None
                changed = True
    if changed:
        with open(path, "w") as file:
            json.dump(notebook, file, indent=1, ensure_ascii=False)
            file.write("\n")
    return changed

if __name__ == "__main__":
    for filepath in sys.argv[1:]:
        if clean_notebook(filepath):
            print(f"Cleaned notebook: {filepath}")

# Utility functions for handling JSON, images, and file operations
import base64
import io
import json
import mimetypes
import os
from multiprocessing import Lock
import numpy as np
from PIL import Image

image_lock = Lock()

def convert_int64_keys(obj):
    converted = {}
    for key, value in obj.items():
        if str(key).isdigit():
            key = np.int64(key)
        elif isinstance(value, dict):
            updated_value = {}
            for sub_key, sub_val in value.items():
                if str(sub_val).isdigit():
                    updated_value[sub_key] = int(sub_val)
                else:
                    updated_value[sub_key] = sub_val
            value = updated_value
        converted[key] = value
    return converted

def read_json_file(json_path):
    if not os.path.isfile(json_path):
        raise FileNotFoundError(f"File not found: {json_path}")
    with open(json_path, 'r') as file:
        content = json.load(file)
    return convert_int64_keys(content)

def write_json_file(data, json_path):
    if not isinstance(data, dict):
        raise ValueError("Input data must be a dictionary.")
    transformed_data = {int(k) if isinstance(k, (np.integer, np.int64)) else k: v for k, v in data.items()}
    with open(json_path, 'w') as file:
        json.dump(transformed_data, file)

def check_image_validity(image_file):
    if not os.path.exists(image_file):
        return False
    try:
        with Image.open(image_file) as img:
            w, h = img.size
        if w <= 0 or h <= 0:
            raise ValueError('Invalid image dimensions')
        return True
    except Exception as error:
        print(f"Failed to process image '{image_file}': {error}")
        return False

def analyze_file_path(path_str):
    if os.path.exists(path_str) and path_str != '.':
        if not os.path.isfile(path_str):
            raise ValueError(f'{path_str} is not a valid file')
        ext = os.path.splitext(path_str)[1].lower()
        mime_type = mimetypes.types_map.get(ext, 'application/octet-stream')
        return (mime_type, path_str)
    else:
        return (None, path_str)

def save_base64_to_image(base64_data, output_path, max_dimension=-1):
    with image_lock:
        pil_image = decode_base64_to_pil_image(base64_data, max_dimension=max_dimension)
        pil_image.save(output_path)

def decode_base64_to_pil_image(base64_string, max_dimension=-1):
    raw_bytes = base64.b64decode(base64_string)
    with Image.open(io.BytesIO(raw_bytes)) as img:
        if img.mode in ('RGBA', 'P'):
            img = img.convert('RGB')
        if max_dimension > 0:
            img.thumbnail((max_dimension, max_dimension))
        return img.copy()

