from .p0_kernel_core import validate_with_understanding

def check_candidate(context: dict, proposal: dict) -> dict:
    """Validate a proposed action or message.
    context: info about where/how this is being used, e.g.:
      {
        "channel": "moltx|clawchat|internal",
        "task": "post|reply|tool_call|memory_write",
        "user_intent": "string description",
        "risk_tolerance": "low|medium|high"
      }
    proposal: {
      "content": "text of reply or description of action",
      "metadata": {... optional ...}
    }
    """
    text = proposal.get("content", "")
    decision = validate_with_understanding(text, context)
    return decision

def protection_decorator(func):
    """Decorator to wrap a generation function with Guardian checks.
    Example:
    @protection_decorator
    def produce_response(context, *args, **kwargs):
        return llm_call(...)
    """
    def inner_wrapper(context, *args, **kwargs):
        unfiltered = func(context, *args, **kwargs)
        assessment = check_candidate(context, {"content": unfiltered})
        outcome = assessment.get("action", "allow")

        if outcome == "allow":
            return unfiltered
        elif outcome == "flag":
            explanation = assessment.get("understanding") or "Guardian flagged this content as risky."
            return f"{unfiltered}\n\n[LYGO Guardian Note]: {explanation}"
        elif outcome == "isolate":
            return "[BLOCKED BY LYGO GUARDIAN: content failed Nano-Kernel validation]"
        # fallback / default case
        return "[LYGO GUARDIAN REQUESTS REVIEW BEFORE SENDING THIS]"

    return inner_wrapper

