# Enhanced figure parsing using vision models for document processing
from concurrent.futures import ThreadPoolExecutor, as_completed
from PIL import Image
from app.core.rag.common.constants import LLMType
from app.core.rag.common.connection_utils import timeout
from app.core.rag.app.picture import vision_llm_chunk as picture_vision_llm_chunk
from app.core.rag.prompts.generator import vision_llm_figure_describe_prompt

def _prepare_figures_data(figures_data_without_positions):
    return [
        (
            (figure_data[1], [figure_data[0]]),
            [(0, 0, 0, 0, 0)],
        )
        for figure_data in figures_data_without_positions
        if isinstance(figure_data[1], Image.Image)
    ]

def _process_docx_sections(sections, tbls, callback=None, vision_model=None, **kwargs):
    if vision_model:
        figures_data = _prepare_figures_data(sections)
        try:
            figure_processor = VisionFigureProcessor(vision_model=vision_model, figures_data=figures_data, **kwargs)
            enhanced_figures = figure_processor(callback=callback)
            tbls.extend(enhanced_figures)
        except Exception as error:
            callback(0.8, f"Visual model error: {error}. Skipping figure parsing enhancement.")
    return tbls

def _process_pdf_tables(tbls, callback=None, vision_model=None, **kwargs):
    if vision_model:
        def is_valid_figure(item):
            return (
                isinstance(item[0][0], Image.Image) and
                isinstance(item[0][1], list)
            )
        figures_data = [item for item in tbls if is_valid_figure(item)]
        try:
            figure_processor = VisionFigureProcessor(vision_model=vision_model, figures_data=figures_data, **kwargs)
            enhanced_figures = figure_processor(callback=callback)
            tbls = [item for item in tbls if not is_valid_figure(item)]
            tbls.extend(enhanced_figures)
        except Exception as error:
            callback(0.8, f"Visual model error: {error}. Skipping figure parsing enhancement.")
    return tbls

shared_thread_pool = ThreadPoolExecutor(max_workers=10)

class VisionFigureProcessor:
    def __init__(self, vision_model, figures_data, *args, **kwargs):
        self.vision_model = vision_model
        self._extract_figure_info(figures_data)
        assert len(self.figures) == len(self.descriptions)
        assert not self.positions or (len(self.figures) == len(self.positions))

    def _extract_figure_info(self, figures_data):
        self.figures = []
        self.descriptions = []
        self.positions = []
        for item in figures_data:
            # position info handling
            if len(item) == 2 and isinstance(item[0], tuple) and len(item[0]) == 2 and \
               isinstance(item[1], list) and isinstance(item[1][0], tuple) and len(item[1][0]) == 5:
                img_desc = item[0]
                assert len(img_desc) == 2 and isinstance(img_desc[0], Image.Image) and isinstance(img_desc[1], list), \
                    "Should be (figure, [description])"
                self.figures.append(img_desc[0])
                self.descriptions.append(img_desc[1])
                self.positions.append(item[1])
            else:
                assert len(item) == 2 and isinstance(item[0], Image.Image) and isinstance(item[1], list), \
                    f"Unexpected form of figure data: get {len(item)=}, {item=}"
                self.figures.append(item[0])
                self.descriptions.append(item[1])

    def _combine_results(self):
        self.combined = []
        self.has_position_data = len(self.positions) != 0
        for i in range(len(self.figures)):
            figure = self.figures[i]
            desc = self.descriptions[i]
            pos = self.positions[i] if self.has_position_data else None
            figure_desc = (figure, desc)
            if pos is not None:
                self.combined.append((figure_desc, pos))
            else:
                self.combined.append((figure_desc,))
        return self.combined

    def __call__(self, **kwargs):
        callback = kwargs.get("callback", lambda prog, msg: None)

        @timeout(30, 3)
        def _analyze_image(idx, image_data):
            description_text = picture_vision_llm_chunk(
                binary=image_data,
                vision_model=self.vision_model,
                prompt=vision_llm_figure_describe_prompt(),
                callback=callback,
            )
            return idx, description_text

        futures = []
        for index, img_data in enumerate(self.figures or []):
            futures.append(shared_thread_pool.submit(_analyze_image, index, img_data))

        for future in as_completed(futures):
            figure_index, text = future.result()
            if text:
                self.descriptions[figure_index] = text + "\n".join(self.descriptions[figure_index])

        self._combine_results()
        return self.combined

# LIFO queue implementation using deque for efficient appends and pops from both ends
import collections
from ..packages import six
from ..packages.six.moves import queue

if six.PY2:
    # Queue is imported for side effects on MS Windows. See issue #229.
    import Queue as _unused_module_Queue  # noqa: F401

class LifoQueue(queue.Queue):
    def _init(self, _):
        self.container = collections.deque()

    def _qsize(self, len=len):
        return len(self.container)

    def _put(self, item):
        self.container.append(item)

    def _get(self):
        return self.container.pop()

