import deepinv as dinv
import torch
import torchvision.transforms as tfs

def retrieve_physics(problem, device='cuda'):
    if problem == 'CS_satellite':
        imsize = (3, 128, 128)
        physics = dinv.physics.CompressedSensing(m=int(128*128/4), channelwise=True, img_shape=imsize, device=device, fast=True, noise_model=dinv.physics.GaussianNoise(sigma=.05))
        physics.load_state_dict(torch.load(f'./finetuning/{problem}/physics0.pt'))
    elif problem == 'SPAD':
        physics = dinv.physics.Inpainting(tensor_size=(1, 256, 256),
                                          mask=None,
                                          noise_model=dinv.physics.PoissonNoise(gain=.2, clip_positive=True),
                                          device=device)
    elif problem == 'cryo_em':
        physics = dinv.physics.Denoising(dinv.physics.PoissonGaussianNoise(sigma=0.98), device=device)
    elif problem == 'demosaicing_satellite':
        imsize = (3, 128, 128)
        physics = dinv.physics.Demosaicing(img_size=imsize, noise_model=dinv.physics.GaussianNoise(.05), device=device)
    else:
        raise NotImplementedError("Problem not implemented")
    return physics

class CryoDataset(torch.utils.data.Dataset):
    def __init__(self, dataset, validation=False):
        # locate all files in folder
        self.dataset = dataset
        self.validation = validation
    def __len__(self):
        return len(self.dataset) if self.validation else 100
    def __getitem__(self, idx):
        input_img, target_img = self.dataset[idx % len(self.dataset)]
        if not self.validation:
            top, left, height, width = tfs.RandomCrop.get_params(input_img, output_size=(256, 256))
        else:
            # center crop of (1024, 1024)
            top, left, height, width = 384, 384, 1024, 1024
        input_img = tfs.functional.crop(input_img, top, left, height, width)
        target_img = tfs.functional.crop(target_img, top, left, height, width)
        return input_img, target_img

class PansharpenDataset(torch.utils.data.Dataset):
    def __init__(self):
        data_home = dinv.utils.demo.get_data_home()
        self.dataset = dinv.datasets.NBUDataset(root_dir=data_home, return_pan=True, satellite='worldview-2',
                                                download=True, transform_ms=lambda x: x[[4, 2, 1], ...])
        self.dataset = torch.utils.data.Subset(self.dataset, torch.arange(2, 27))
    def __len__(self):
        return len(self.dataset)
    def __getitem__(self, idx):
        MS, pan = self.dataset[idx]
        y = dinv.utils.TensorList([MS, pan])
        x = pan.expand(MS.size(0), pan.size(1), pan.size(1))
        return x, y

def obtain_dataset(problem):
    import os
    save_dir = f'./finetuning/{problem}'
    if not os.path.exists(save_dir):
        # fetch from hfhub
        from huggingface_hub import hf_hub_download
        repo_id = "jtachella/finetuning"
        filename = f"{problem}/dinv_dataset0.h5"
        # Download the file
        hf_hub_download(repo_id=repo_id, filename=filename, local_dir=f"./finetuning/", repo_type="dataset")
        if problem == 'CS_satellite':
            hf_hub_download(repo_id=repo_id, filename=f"{problem}/physics0.pt", local_dir=f"./finetuning/", repo_type="dataset")
    if problem == 'cryo_em':
        base = dinv.datasets.HDF5Dataset(f'{save_dir}/dinv_dataset0.h5')
        val_dataset = CryoDataset(base, validation=True)
        train_dataset = CryoDataset(base)
    elif problem == 'SPAD':
        train_dataset = dinv.datasets.HDF5Dataset(f'{save_dir}/dinv_dataset0.h5', load_physics_generator_params=True)
        val_dataset = train_dataset
    elif problem == 'real_pansharpening':
        train_dataset = PansharpenDataset()
        val_dataset = train_dataset
    else:
        train_dataset = dinv.datasets.HDF5Dataset(f'{save_dir}/dinv_dataset0.h5', load_physics_generator_params=False, train=True)
        val_dataset = dinv.datasets.HDF5Dataset(f'{save_dir}/dinv_dataset0.h5', load_physics_generator_params=False, train=False)
    return train_dataset, val_dataset

# Register and manage advantage functions and policy losses for RL algorithms
from functools import wraps
from typing import Callable, Optional
import torch
from rlinf.algorithms.utils import (
    calculate_scores,
    postprocess_embodied_advantages_outputs,
    postprocess_loss_metric,
    postprocess_reasoning_advantages_outputs,
    preprocess_embodied_advantages_inputs,
    preprocess_loss_inputs,
    preprocess_reasoning_advantages_inputs,
)

# Registry dictionaries for advantages and losses
ADVANTAGE_REGISTRY: dict[str, Callable] = {}
LOSS_FUNCTION_REGISTRY: dict[str, Callable] = {}

def register_advantage_function(name: str):
    """Decorator to register an advantage computation function."""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            return fn(*args, **kwargs)
        ADVANTAGE_REGISTRY[name.lower()] = wrapper
        return wrapper
    return decorator

def get_advantage_by_name(name: str) -> Callable:
    """Fetch a registered advantage function by its name."""
    if name.lower() not in ADVANTAGE_REGISTRY:
        raise ValueError(
            f"Advantage '{name}' is not registered. Available options: {list(ADVANTAGE_REGISTRY.keys())}"
        )
    return ADVANTAGE_REGISTRY[name.lower()]

def register_policy_loss_function(name: str):
    """Decorator to register a policy loss function."""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            return fn(*args, **kwargs)
        LOSS_FUNCTION_REGISTRY[name.lower()] = wrapper
        return wrapper
    return decorator

def get_policy_loss_function(name: str):
    """Retrieve a registered policy loss function by name."""
    if name.lower() not in LOSS_FUNCTION_REGISTRY:
        raise ValueError(f"Loss function '{name}' is not registered")
    return LOSS_FUNCTION_REGISTRY[name.lower()]

def compute_actor_loss(**kwargs) -> tuple[torch.Tensor, dict]:
    """
    Unified actor loss computation entry point.
    Handles preprocessing, dispatch, and postprocessing based on task type.
    """
    loss_identifier = kwargs["loss_type"]
    loss_function = get_policy_loss_function(loss_identifier)
    environment_type = kwargs["task_type"]

    if environment_type == "embodied":
        kwargs = preprocess_loss_inputs(**kwargs)

    loss_value, metric_data = loss_function(**kwargs)

    if environment_type == "embodied":
        metric_data = postprocess_loss_metric(metric_data)

    return loss_value, metric_data

def compute_advantage_and_returns(**kwargs) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
    """
    Unified method for computing advantages and returns.
    Routes to appropriate algorithm via registry after preprocessing inputs.
    """
    advantage_type = kwargs["adv_type"]
    algorithm_fn = get_advantage_by_name(advantage_type)
    environment_type = kwargs["task_type"]

    if environment_type == "embodied":
        # Preprocess inputs for embodied tasks
        kwargs = preprocess_embodied_advantages_inputs(**kwargs)

        # Compute scores if needed (except for GAE)
        if advantage_type != "gae":
            kwargs = calculate_scores(**kwargs)

        # Compute advantages and returns
        advantages, returns = algorithm_fn(**kwargs)

        # Postprocess outputs for embodied tasks
        result = postprocess_embodied_advantages_outputs(
            advantages=advantages, returns=returns, **kwargs
        )
    else:
        # Handle reasoning tasks
        kwargs = preprocess_reasoning_advantages_inputs(**kwargs)
        advantages, returns = algorithm_fn(**kwargs)
        result = postprocess_reasoning_advantages_outputs(advantages, returns)

    return result

