# Register replay list for MoE models
from megatron.core.transformer.transformer_block import get_num_layers_to_build
from megatron.core.transformer.transformer_layer import get_transformer_layer_offset
from miles.utils.replay_base import BaseReplayManager, RoutingReplayManager

def _register_replay_list_moe(replay_list, replay_data, models):
    layer_ids = []
    idx = 0
    for vp_stage_idx, model in enumerate(models):
        cfg = model.module.config
        layers_to_build = get_num_layers_to_build(cfg, vp_stage=vp_stage_idx)
        start_offset = get_transformer_layer_offset(cfg, vp_stage=vp_stage_idx)
        for local_layer_id in range(start_offset, start_offset + layers_to_build):
            if isinstance(cfg.moe_layer_frequency, int):
                if local_layer_id % cfg.moe_layer_frequency != 0:
                    continue
            elif isinstance(cfg.moe_layer_frequency, list):
                assert len(cfg.moe_layer_frequency) == cfg.num_layers
                if cfg.moe_layer_frequency[local_layer_id] == 0:
                    continue
            layer_ids.append(local_layer_id)

    for idx, global_layer_id in enumerate(layer_ids):
        layer_data = replay_data[:, global_layer_id]
        replay_list[idx].record(layer_data)

def get_register_replay_list_function(replay_manager: BaseReplayManager):
    if isinstance(replay_manager, RoutingReplayManager):
        return _register_replay_list_moe
    else:
        raise ValueError(f"Unsupported manager type: {type(replay_manager)}")

