# Script to check for new virtual rides from Strava and update cache accordingly
import json
import sys
from pathlib import Path
import requests
import time
from cache_manager import load_cached_activities, update_cache_with_new_activities

CONFIG_FILE = Path.home() / ".config" / "strava" / "config.json"

def get_configuration():
    """Load configuration from JSON file."""
    if not CONFIG_FILE.exists():
        print("Error: Configuration file missing.", file=sys.stderr)
        sys.exit(1)

    with open(CONFIG_FILE) as config_file:
        return json.load(config_file)

def refresh_access_token_if_expired(config):
    """Refresh the access token if it has expired."""
    current_time = time.time()
    if config['expires_at'] < current_time:
        token_endpoint = "https://www.strava.com/oauth/token"
        payload = {
            'client_id': config['client_id'],
            'client_secret': config['client_secret'],
            'refresh_token': config['refresh_token'],
            'grant_type': 'refresh_token'
        }

        api_response = requests.post(token_endpoint, data=payload)
        api_response.raise_for_status()

        token_info = api_response.json()
        config['access_token'] = token_info['access_token']
        config['refresh_token'] = token_info['refresh_token']
        config['expires_at'] = token_info['expires_at']

        with open(CONFIG_FILE, 'w') as config_out:
            json.dump(config, config_out, indent=2)

    return config

def retrieve_recent_activities(config, max_count=10):
    """Retrieve recent activities from the Strava API."""
    config = refresh_access_token_if_expired(config)

    activity_url = "https://www.strava.com/api/v3/athlete/activities"
    auth_headers = {'Authorization': f"Bearer {config['access_token']}"}
    query_params = {'per_page': max_count}

    response = requests.get(activity_url, headers=auth_headers, params=query_params)
    response.raise_for_status()

    return response.json()

def detect_new_virtual_rides():
    """Identify new virtual rides since the last check."""
    app_config = get_configuration()

    # Load previously cached activities
    previous_activities = load_cached_activities()
    previous_ids = {a['id'] for a in previous_activities}

    # Fetch latest activities
    latest_activities = retrieve_recent_activities(app_config, limit=20)

    # Identify new virtual rides
    fresh_rides = []
    for activity in latest_activities:
        if activity['id'] not in previous_ids and activity.get('type') == 'VirtualRide':
            fresh_rides.append(activity)

    # Update cache if new rides found
    if fresh_rides:
        update_cache_with_new_activities(latest_activities)

    return fresh_rides

def main():
    try:
        fresh_rides = detect_new_virtual_rides()

        if fresh_rides:
            print(f"Discovered {len(fresh_rides)} new virtual ride(s):")
            for ride in fresh_rides:
                print(f"  - {ride['name']} ({ride['id']})")

            # Output ride IDs for downstream processing
            for ride in fresh_rides:
                print(f"NEW_RIDE:{ride['id']}")
        else:
            print("No newly discovered rides")

    except Exception as error:
        print(f"Error: {error}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

# Porkbun DNS API provider implementation  
import requests
from typing import Tuple, Dict, Any
import logging
from .base import BaseDnsProvider

logger = logging.getLogger(__name__)

class PorkbunDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "porkbun"
    PROVIDER_NAME = "Porkbun"
    PROVIDER_DESCRIPTION = "Porkbun DNS API"
    REQUIRED_CREDENTIALS = ["api_key", "secret_api_key"]

    BASE_URL = "https://api.porkbun.com/api/json/v3"

    def _auth_body(self, extra=None):
        payload = {
            'apikey': self.credentials['api_key'],
            'secretapikey': self.credentials['secret_api_key'],
        }
        if extra:
            payload.update(extra)
        return payload

    def _request(self, path, data=None):
        body = self._auth_body(data)
        try:
            response = requests.post(f"{self.BASE_URL}{path}", json=body, timeout=30)
            result = response.json()
            if result.get('status') == 'SUCCESS':
                return True, result
            return False, result.get('message', 'Unknown error')
        except requests.RequestException as e:
            logger.error(f"Porkbun API error: {e}")
            return False, str(e)

    def create_txt_record(self, domain, record_name, record_value, ttl=300):
        zone = self.get_zone_for_domain(domain)
        relative = self.get_relative_record_name(record_name, zone)
        success, result = self._request(f'/dns/create/{zone}', {
            'name': relative, 'type': 'TXT', 'content': record_value, 'ttl': str(ttl)
        })
        if not success:
            return False, f"Failed: {result}"
        return True, "Record created"

    def delete_txt_record(self, domain, record_name):
        zone = self.get_zone_for_domain(domain)
        relative = self.get_relative_record_name(record_name, zone)

        success, result = self._request(f'/dns/retrieveByNameType/{zone}/TXT/{relative}')
        if success:
            for rec in result.get('records', []):
                self._request(f'/dns/delete/{zone}/{rec["id"]}')
        return True, "Record deleted"

    def test_connection(self):
        success, result = self._request('/ping')
        if success:
            return True, "Connected successfully"
        return False, f"Connection failed: {result}"

    @classmethod
    def get_credential_schema(cls):
        return [
            {'name': 'api_key', 'label': 'API Key', 'type': 'password', 'required': True,
             'help': 'porkbun.com > Account > API Access'},
            {'name': 'secret_api_key', 'label': 'Secret API Key', 'type': 'password', 'required': True,
             'help': 'Porkbun Secret API Key'},
        ]

