# Calculate linguistic features from conversation turns using predefined lexicons
import regex as re
from typing import List, Dict, Iterable, Tuple
from .config import WINDOW_SIZE, WINDOW_STEP

def _load_word_list(filepath: str):
    with open(filepath, "r", encoding="utf-8") as file:
        return [line.strip() for line in file if line.strip()]

def build_lexicon(base_dir: str) -> Dict[str, List[str]]:
    import os
    lexicon = {}
    filenames = [
        "hedges.txt","modals.txt","meta_markers.txt","backtracks.txt",
        "action_verbs.txt","verify_markers.txt","positive_words.txt","negative_words.txt"
    ]
    for filename in filenames:
        key = filename.split(".")[0]
        lexicon[key] = _load_word_list(os.path.join(base_dir, "resources", "lexicons", filename))
    return lexicon

def tokenize_simple(text: str) -> List[str]:
    return re.findall(r"\p{L}[\p{L}\p{N}'-]*", text.lower())

def phrase_frequency(text: str, phrase_list: List[str]) -> int:
    normalized_text = text.lower()
    occurrences = 0
    for phrase in phrase_list:
        occurrences += len(re.findall(re.escape(phrase), normalized_text))
    return occurrences

def sliding_window(sequence: List[Dict], window_length: int = WINDOW_SIZE, step_size: int = WINDOW_STEP):
    for start_index in range(0, max(0, len(sequence) - window_length + 1), step_size):
        yield start_index, sequence[start_index:start_index + window_length]

def compute_features(turns: List[Dict], lexicon: Dict[str, List[str]]) -> List[Dict]:
    feature_vectors = []
    for turn in turns:
        utterance = turn.get("text", "")
        tokens = tokenize_simple(utterance)
        token_count = max(1, len(tokens))

        features = {
            "hedges": phrase_frequency(utterance, lexicon["hedges"]) / token_count,
            "modals": phrase_frequency(utterance, lexicon["modals"]) / token_count,
            "meta": phrase_frequency(utterance, lexicon["meta_markers"]) / token_count,
            "backtrack": phrase_frequency(utterance, lexicon["backtracks"]) / token_count,
            "action": phrase_frequency(utterance, lexicon["action_verbs"]) / token_count,
            "verify": phrase_frequency(utterance, lexicon["verify_markers"]) / token_count,
            "question_ratio": utterance.count("?") / max(1, utterance.count(".") + utterance.count("?") + utterance.count("!")),
            "exclamation_density": utterance.count("!") / max(1, len(utterance)),
            "positive_sentiment": sum(1 for token in tokens if token in set(lexicon["positive_words"])) / token_count,
            "negative_sentiment": sum(1 for token in tokens if token in set(lexicon["negative_words"])) / token_count,
            "token_count": token_count
        }
        feature_vectors.append(features)
    return feature_vectors

