# Generate valid current ratio pairs for TI stimulation
from itertools import product

def create_current_pairs(total_intensity, intensity_step, electrode_limit):
    """Create valid current pair configurations.

    Returns:
        tuple: (pairs, limit_violated)
            - pairs: List of (electrode1_current, electrode2_current) tuples
            - limit_violated: bool indicating if channel limits were exceeded
    """
    pairs = []
    tolerance = intensity_step * 0.01
    lower_bound = max(total_intensity - electrode_limit, intensity_step)
    limit_violated = lower_bound < intensity_step - tolerance

    if limit_violated:
        lower_bound = intensity_step

    electrode1_current = electrode_limit
    while electrode1_current >= lower_bound - tolerance:
        electrode2_current = total_intensity - electrode1_current

        if (
            electrode1_current <= electrode_limit + tolerance and
            electrode2_current <= electrode_limit + tolerance and
            electrode1_current >= intensity_step - tolerance and
            electrode2_current >= intensity_step - tolerance
        ):
            pairs.append((electrode1_current, electrode2_current))

        electrode1_current -= intensity_step

    return pairs, limit_violated


def _generate_electrode_sets(pos1, neg1, pos2, neg2, use_all_combos):
    """Generate valid electrode 4-tuples based on configuration."""
    if use_all_combos:
        for combo in product(pos1, repeat=4):
            if len(set(combo)) == 4:
                yield combo
    else:
        yield from product(pos1, neg1, pos2, neg2)


def create_montage_configurations(
    pos1, neg1, pos2, neg2, current_pairs, use_all_combos
):
    """Yield (e1p, e1m, e2p, e2m, (ch1_mA, ch2_mA)) configuration tuples."""
    for electrodes in _generate_electrode_sets(
        pos1, neg1, pos2, neg2, use_all_combos
    ):
        for pair in current_pairs:
            yield (*electrodes, pair)


def calculate_total_configurations(
    pos1, neg1, pos2, neg2, current_pairs, use_all_combos
):
    """Calculate total number of montage configurations without generating them."""
    electrode_count = sum(
        1
        for _ in _generate_electrode_sets(
            pos1, neg1, pos2, neg2, use_all_combos
        )
    )
    return electrode_count * len(current_pairs)

