# Import necessary modules
import importlib
import torch
import yaml
from omegaconf import OmegaConf
from taming.models.vqgan import VQModel

def load_configuration(config_file, show=False):
    cfg = OmegaConf.load(config_file)
    if show:
        print(yaml.dump(OmegaConf.to_container(cfg)))
    return cfg

def initialize_vqgan(device, config_path=None, checkpoint_path=None):
    if config_path is None:
        config_path = "./model_checkpoints/vqgan_only.yaml"
    config = load_configuration(config_path, display=False)
    model = VQModel(**config.model.params)
    if checkpoint_path is None:
        checkpoint_path = "./model_checkpoints/vqgan_only.pt"
    state_dict = torch.load(checkpoint_path, map_location=device)
    if ".ckpt" in checkpoint_path:
        state_dict = state_dict["state_dict"]
    model.load_state_dict(state_dict, strict=True)
    model.to(device)
    del state_dict
    return model

def reconstruct_image_with_vqgan(input_tensor, model):
    latent, _, [_, _, indices] = model.encode(input_tensor)
    print(f"VQGAN --- {model.__class__.__name__}: latent shape: {latent.shape[2:]}")
    reconstructed = model.decode(latent)
    return reconstructed

def get_class_from_string(class_string, reload_module=False):
    module_name, class_name = class_string.rsplit(".", 1)
    if reload_module:
        imported_module = importlib.import_module(module_name)
        importlib.reload(imported_module)
    return getattr(importlib.import_module(module_name, package=None), class_name)

def create_instance_from_config(config_dict):
    if "target" not in config_dict:
        raise KeyError("Expected key `target` to instantiate.")
    return get_class_from_string(config_dict["target"])(**config_dict.get("params", {}))

def build_model_from_config(model_config, state_dict, use_gpu=True, set_eval=True):
    model = create_instance_from_config(model_config)
    if state_dict is not None:
        model.load_state_dict(state_dict)
    if use_gpu:
        model.cuda()
    if set_eval:
        model.eval()
    return {"model": model}

def load_checkpoint_and_build_model(config, checkpoint_file, use_gpu, evaluation_mode):
    # Load the specified checkpoint
    if checkpoint_file:
        pl_state_dict = torch.load(checkpoint_file, map_location="cpu")
        global_step = pl_state_dict["global_step"]
        print(f"loaded model from global step {global_step}.")
    else:
        pl_state_dict = {"state_dict": None}
        global_step = None
    model = build_model_from_config(config.model, pl_state_dict["state_dict"], use_gpu=use_gpu, set_eval=evaluation_mode)["model"]
    return model, global_step

# File validation module with secure practices
import mimetypes
import os

# Define allowed file extensions
SAFE_EXTENSIONS = {".txt", ".md", ".json", ".csv"}

def validate_document(filepath):
    """Securely validate a document file - SAFE IMPLEMENTATION"""
    # Safe: Uses basename to prevent path traversal attacks
    filename = os.path.basename(filepath)

    # Extract and check file extension
    _, ext = os.path.splitext(filename)
    if ext.lower() not in SAFE_EXTENSIONS:
        return {"valid": False, "reason": "Unsupported file format"}

    # Safe: Restricts file access to a specific directory
    restricted_dir = os.path.expanduser("~/documents/")
    absolute_path = os.path.join(restricted_dir, filename)

    # Verify file existence
    if not os.path.exists(absolute_path):
        return {"valid": False, "reason": "File does not exist"}

    # Validate file size (10MB limit)
    file_size = os.path.getsize(absolute_path)
    if file_size > 10 * 1024 * 1024:
        return {"valid": False, "reason": "Exceeds maximum size limit"}

    return {"valid": True, "filename": filename, "size": file_size}

def verify_content_type(filepath):
    """Safely determine MIME type of a file"""
    # Safe: Uses standard library mimetypes module
    content_type, _ = mimetypes.guess_type(filepath)
    return content_type

if __name__ == "__main__":
    print(validate_document("sample.txt"))

