def generate_calvin_sample() -> dict:
    """Generates a synthetic input example for the Calvin policy."""
    return {
        "observation/state": np.random.rand(7),
        "observation/image": np.random.randint(256, size=(200, 200, 3), dtype=np.uint8),
        "observation/wrist_image": np.random.randint(
            256, size=(84, 84, 3), dtype=np.uint8
        ),
        "prompt": "execute task",
    }


def _process_image(img) -> np.ndarray:
    # Convert input to numpy array if not already
    img_array = np.asarray(img)

    # Handle floating-point images: scale to [0, 255] and convert to uint8
    if np.issubdtype(img_array.dtype, np.floating):
        img_array = (255 * img_array).astype(np.uint8)

    # Reorder channels from CHW to HWC if needed
    if img_array.shape[0] == 3:
        img_array = einops.rearrange(img_array, "c h w -> h w c")

    return img_array


@dataclasses.dataclass(frozen=True)
class CalvinInputProcessor(transforms.DataTransformFn):
    architecture_type: _model.ModelType

    def __call__(self, sample: dict) -> dict:
        # Process base and wrist images
        main_img = _process_image(sample["observation/image"])
        gripper_img = _process_image(sample["observation/wrist_image"])

        # Extract and concatenate robot state components
        ee_position = sample["observation/state_ee_pos"]
        ee_orientation = sample["observation/state_ee_rot"]
        gripper_state = sample["observation/state_gripper"]
        full_state = np.concatenate([ee_position, ee_orientation, gripper_state])

        # Construct input dictionary
        processed_inputs = {
            "state": full_state,
            "image": {
                "base_rgb": main_img,
                "left_wrist_rgb": gripper_img,
                "right_wrist_rgb": np.zeros_like(main_img),
            },
            "image_mask": {
                "base_rgb": np.True_,
                "left_wrist_rgb": np.True_,
                "right_wrist_rgb": np.True_
                if self.architecture_type == _model.ModelType.PI0_FAST
                else np.False_,
            },
        }

        # Add actions if present in input data
        if "actions/delta_ee_pos" in sample:
            delta_pos = sample["actions/delta_ee_pos"]
            delta_rot = sample["actions/delta_ee_rot"]
            gripper_cmd = sample["actions/gripper"]
            action_tensor = np.concatenate([delta_pos, delta_rot, gripper_cmd], axis=1)
            processed_inputs["actions"] = action_tensor

        # Include prompt if available
        if "prompt" in sample:
            processed_inputs["prompt"] = sample["prompt"]

        return processed_inputs


@dataclasses.dataclass(frozen=True)
class CalvinOutputProcessor(transforms.DataTransformFn):
    def __call__(self, sample: dict) -> dict:
        # Extract first 7 dimensions of actions
        return {"actions": np.asarray(sample["actions"][:, :7])}

