# Unit tests for the has_fault_at function
import unittest
from graph_net.fault_locator.fault_detector import has_fault_at, ES

class TestHasFaultAtFunction(unittest.TestCase):
    def test_fault_detection_condition(self):
        """Scenario: ES[t-1] is less than ES[max], indicating a fault."""
        # Tolerance set to 5, thus checking ES[4]
        es_values: ES = {0: 0.1, 4: 0.5, 10: 0.9}
        tolerance_value = 5
        # 0.5 < 0.9 evaluates to True
        self.assertTrue(has_fault_at(es_values, tolerance_value))

    def test_no_fault_condition(self):
        """Scenario: ES[t-1] is greater than or equal to ES[max], no fault detected."""
        # Tolerance set to 11, thus checking ES[10], which is also the max key
        es_values: ES = {0: 0.1, 5: 0.5, 10: 0.9}
        tolerance_value = 11
        # 0.9 < 0.9 evaluates to False
        self.assertFalse(has_fault_at(es_values, tolerance_value))

    def test_missing_key_assertion(self):
        """Scenario: The required key (tolerance-1) is absent from ES."""
        es_values: ES = {0: 0.1, 1: 0.2}
        tolerance_value = 5  # Key 4 is missing in es_values
        with self.assertRaises(AssertionError):
            has_fault_at(es_values, tolerance_value)

    def test_single_element_case(self):
        """Scenario: ES contains only one entry, so max key equals the only key."""
        es_values: ES = {0: 0.5}
        tolerance_value = 1
        # 0.5 < 0.5 evaluates to False
        self.assertFalse(has_fault_at(es_values, tolerance_value))

if __name__ == "__main__":
    unittest.main()

