# Base class for defining security confirmation policies
from abc import ABC, abstractmethod
from pydantic import field_validator
from openhands.sdk.security.risk import SecurityRisk
from openhands.sdk.utils.models import DiscriminatedUnionMixin

class ConfirmationStrategyBase(DiscriminatedUnionMixin, ABC):
    @abstractmethod
    def requires_approval(self, threat: SecurityRisk = SecurityRisk.UNKNOWN) -> bool:
        """Evaluate whether an operation with the specified threat level needs approval.
        This method implements the core logic for deciding if operator approval
        is necessary before proceeding with an operation based on its security threat level.
        Args:
            threat: The security threat level of the operation to be assessed.
                 Defaults to SecurityRisk.UNKNOWN if not provided.
        Returns:
            True if the operation requires operator approval before execution,
            False if the operation can proceed without approval.
        """

class AlwaysSeekApproval(ConfirmationStrategyBase):
    def requires_approval(
        self,
        threat: SecurityRisk = SecurityRisk.UNKNOWN,  # noqa: ARG002
    ) -> bool:
        return True

class NeverSeekApproval(ConfirmationStrategyBase):
    def requires_approval(
        self,
        threat: SecurityRisk = SecurityRisk.UNKNOWN,  # noqa: ARG002
    ) -> bool:
        return False

class ApproveIfThreatening(ConfirmationStrategyBase):
    danger_level: SecurityRisk = SecurityRisk.HIGH
    approve_unknown: bool = True

    @field_validator("danger_level")
    def check_danger_level(cls, v: SecurityRisk) -> SecurityRisk:
        if v == SecurityRisk.UNKNOWN:
            raise ValueError("Danger level cannot be UNKNOWN")
        return v

    def requires_approval(self, threat: SecurityRisk = SecurityRisk.UNKNOWN) -> bool:
        if threat == SecurityRisk.UNKNOWN:
            return self.approve_unknown
        # This comparison is reflexive by default, so if the danger level is HIGH we will
        # still require approval for HIGH threat operations. And since the danger level is
        # guaranteed to never be UNKNOWN (by the validator), we're guaranteed to get a
        # boolean here.
        return threat.is_riskier(self.danger_level)

