# Slack integration utility for sending messages and searching messages
import os
import requests
import json
import sys

class SlackConnector:
    def __init__(self):
        self.api_token = os.getenv("SLACK_BOT_TOKEN")
        self.api_base = "https://slack.com/api"

    def _execute_request(self, method, endpoint, params=None, payload=None):
        headers = {
            "Authorization": f"Bearer {self.api_token}",
            "Content-Type": "application/json; charset=utf-8"
        }
        url = f"{self.api_base}/{endpoint}"
        if method == "GET":
            response = requests.get(url, headers=headers, params=params)
        else:
            response = requests.post(url, headers=headers, json=payload)
        return response.json()

    def deliver(self, channel_id, text, parent_thread=None):
        message_payload = {"channel": channel_id, "text": text}
        if parent_thread:
            message_payload["thread_ts"] = parent_thread
        return self._execute_request("POST", "chat.postMessage", payload=message_payload)

    def find_messages(self, search_term):
        # Using Slack's search API with query parameters
        query_params = {"query": search_term}
        auth_headers = {"Authorization": f"Bearer {self.api_token}"}
        response = requests.get(f"{self.api_base}/search.messages", headers=auth_headers, params=query_params)
        return response.json()

if __name__ == "__main__":
    import argparse

    connector = SlackConnector()

    cli_parser = argparse.ArgumentParser(description="Slack Hub Utility")
    cli_parser.add_argument("command", choices=["send", "search", "list"])
    cli_parser.add_argument("--channel")
    cli_parser.add_argument("--content")
    cli_parser.add_argument("--search-term")
    arguments = cli_parser.parse_args()

    if arguments.command == "list":
        print(json.dumps(connector._execute_request("POST", "conversations.list", payload={"types": "public_channel,private_channel"})))
    elif arguments.command == "send":
        print(json.dumps(connector.deliver(arguments.channel, arguments.content)))
    elif arguments.command == "search":
        print(json.dumps(connector.find_messages(arguments.search_term)))

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

class EntropyTemperature(nn.Module):
    """
    Temperature module for SAC automatic entropy tuning.
    """
    def __init__(
        self,
        init_alpha: float,
        alpha_mode: str = "softplus",
        device=None,
        dtype=torch.float32,
    ):
        super().__init__()
        self.alpha_mode = alpha_mode
        if alpha_mode == "exp":
            init_val = np.log(init_alpha)
        elif alpha_mode == "softplus":
            # softplus^{-1}(x) = log(exp(x) - 1)
            init_val = np.log(np.exp(init_alpha) - 1.0)
        elif alpha_mode == "fixed_alpha":
            self.register_buffer(
                "const_alpha",
                torch.tensor(
                    [init_alpha],
                    device=device,
                    dtype=dtype,
                ),
                persistent=True,
            )
            init_val = init_alpha
        else:
            raise NotImplementedError(f"Unknown alpha_mode: {alpha_mode}")
        self.logit_alpha = nn.Parameter(torch.tensor(init_val, device=device, dtype=dtype))

    def compute_alpha(self) -> torch.Tensor:
        if self.alpha_mode == "exp":
            return self.logit_alpha.exp()
        elif self.alpha_mode == "softplus":
            return F.softplus(self.logit_alpha)
        elif self.alpha_mode == "fixed_alpha":
            return self.const_alpha
        else:
            raise NotImplementedError

    @property
    def alpha_value(self) -> float:
        return self.compute_alpha().item()

# Apply various memory and training features to the model
import torch
from mindspeed.fsdp.utils.str_match import module_name_match
from ..params.model_args import ModelArguments
from ..features.memory.async_offload import async_offload_modules, get_offload_modules
from ..features.memory.chunkloss_lm_head import apply_chunkloss_module, get_chunkloss_module

class ModelFeatureApplier:
    def __init__(self, config_args: ModelArguments):
        self.settings = config_args

    def find_matching_modules(self, modules_list, target_patterns):
        selected_modules = []
        for pattern in target_patterns:
            for module_path, module_obj in modules_list.named_modules():
                if module_name_match(pattern, module_path):
                    if (module_path, module_obj) not in selected_modules:
                        selected_modules.append((module_path, module_obj))
        return selected_modules

    def enable_activation_offloading(self, network_model):
        if getattr(self.settings, "activation_offload_config", None) is None or \
           getattr(self.settings.activation_offload_config, "target_layers", None) is None:
            return

        offloaded_layers = get_offload_modules(network_model, 
                                               getattr(self.settings.activation_offload_config, "target_layers"))
        async_offload_modules(offloaded_layers)

    def enable_chunked_loss(self, neural_network):
        if not self.settings.use_chunk_loss:
            return

        setattr(neural_network, "use_chunk_loss", True)
        chunked_module = get_chunkloss_module(neural_network, self.settings.chunk_loss_schedule)
        apply_chunkloss_module(chunked_module)

    def __call__(self, model_instance):
        self.enable_activation_offloading(model_instance)
        self.enable_chunked_loss(model_instance)

