# Modified version with renamed variables and reordered statements
from contextlib import contextmanager
from io import StringIO
import sys
import os

class TTYStream(StringIO):
    def isatty(self):
        return True

class NonTTYStream(StringIO):
    def isatty(self):
        return False

@contextmanager
def set_os_name(name):
    original_name = os.name
    os.name = name
    try:
        yield
    finally:
        os.name = original_name

@contextmanager
def redirect_streams(stream):
    original_stdout = sys.stdout
    original_stderr = sys.stderr
    sys.stdout = stream
    sys.stderr = stream
    try:
        yield
    finally:
        sys.stdout = original_stdout
        sys.stderr = original_stderr

@contextmanager
def redirect_original_streams(stream):
    original_stdout = sys.__stdout__
    original_stderr = sys.__stderr__
    sys.__stdout__ = stream
    sys.__stderr__ = stream
    try:
        yield
    finally:
        sys.__stdout__ = original_stdout
        sys.__stderr__ = original_stderr

@contextmanager
def simulate_pycharm():
    os.environ["PYCHARM_HOSTED"] = "1"
    try:
        non_tty_stream = NonTTYStream()
        with redirect_streams(non_tty_stream), redirect_original_streams(non_tty_stream):
            yield
    finally:
        del os.environ["PYCHARM_HOSTED"]

# Command-line tool for fetching and extracting content from web pages
import argparse
import sys
import logging

def main():
    # Set up argument parser
    parser = argparse.ArgumentParser(description='Web content extractor')
    parser.add_argument('target_url', help='Target URL to process')
    parser.add_argument('--mode', choices=['standard', 'evasive', 'rendered'], default='standard',
                        help='Fetching strategy: standard (quick), evasive (anti-detection), rendered (JavaScript support)')
    parser.add_argument('--pattern', '-p', help='CSS selector for element extraction')
    parser.add_argument('--field', default='text', help='Field to extract (text, href, src, etc.)')
    parser.add_argument('--output-json', action='store_true', help='Format output as JSON array')
    parser.add_argument('-v', '--silent', action='store_true', help='Disable informational messages')
    arguments = parser.parse_args()

    # Adjust logging based on quiet mode
    if arguments.silent:
        logging.disable(logging.INFO)

    try:
        document = _retrieve(arguments.target_url, arguments.mode)
    except Exception as error:
        print(f"FAILURE: {error}", file=sys.stderr)
        sys.exit(1)

    # Handle default behavior (no selector specified)
    if not arguments.pattern:
        content = document.get_all_text(' ', ignore_tags=('script', 'style', 'noscript'))
        print(content)
        return

    # Extract elements using CSS selector
    matched_items = document.css(arguments.pattern)
    if not matched_items:
        print(f"No matches found for: {arguments.pattern}", file=sys.stderr)
        sys.exit(1)

    # Process extracted elements
    extracted_values = []
    for item in matched_items:
        if arguments.field == 'text':
            value = item.text or item.get_all_text()
        elif arguments.field == 'html':
            value = item.html_content
        else:
            value = item.attrib.get(arguments.field, '')
        extracted_values.append(value.strip())

    # Output results
    if arguments.output_json:
        import json
        print(json.dumps(extracted_values, ensure_ascii=False, indent=2))
    else:
        for item in extracted_values:
            if item:
                print(item)

def _retrieve(url, strategy):
    if strategy == 'standard':
        from scrapling.fetchers import StandardFetcher
        return StandardFetcher.get(url)
    elif strategy == 'evasive':
        from scrapling.fetchers import StealthFetcher
        return StealthFetcher.fetch(url, headless=True, network_idle=True)
    elif strategy == 'rendered':
        from scrapling.fetchers import JavaScriptFetcher
        return JavaScriptFetcher.fetch(url, headless=True, network_idle=True)

if __name__ == '__main__':
    main()

