# Script to fetch Google Autocomplete suggestions using DataForSEO API
import argparse
from dataforseo_api import api_post, get_result

def main():
    # Set up command-line argument parsing
    parser = argparse.ArgumentParser(description="Fetch keyword suggestions from Google Autocomplete")
    parser.add_argument("keyword", help="Initial keyword to query autocomplete")
    parser.add_argument("--location", "-loc", type=int, default=2840,
                        help="Location identifier (default: 2840 for United States)")
    arguments = parser.parse_args()

    payload = [{
        "keyword": arguments.keyword,
        "location_code": arguments.location,
        "language_code": "en"
    }]

    # Send request and process response
    api_response = api_post("serp/google/autocomplete/live/advanced", payload)
    output_data = get_result(api_response)

    print(f"Keyword: {arguments.keyword}")
    print(f"Location: {arguments.location}")
    print()

    if output_data:
        found_suggestions = []

        for entry in output_data:
            # Extract items list with fallbacks for different response formats
            items_list = entry.get("items", [])

            if not items_list:
                items_list = entry.get("autocomplete", [])
                if not items_list:
                    items_list = entry.get("suggestions", [])

            for element in items_list:
                # Parse suggestion text based on data type
                suggestion_text = None

                if isinstance(element, dict):
                    if element.get("type") == "autocomplete_item":
                        suggestion_text = element.get("title", "").strip()
                    elif "value" in element:
                        suggestion_text = element.get("value", "").strip()
                elif isinstance(element, str):
                    suggestion_text = element.strip()

                if suggestion_text:
                    found_suggestions.append(suggestion_text)

