# Profiler for embedding layers in the model
from typing import Optional
import torch
from primus.core.projection.base_module_profiler import BaseModuleProfiler
from .utils import benchmark_layer

class EmbeddingProfiler(BaseModuleProfiler):
    def __init__(self, config, sub_profilers=None):
        super().__init__(config, sub_profilers)
        self.layer = None  # Will be assigned during profiling
        self._stored_results = None  # Cache to hold (forward_duration, backward_duration, activation_bytes)
        self._cache_identifier = None  # Identifier for cache: (batch_size, sequence_length)

    def assign_layer(self, layer):
        """Assign the actual layer to be profiled."""
        self.layer = layer
        # Clear cache when the layer changes
        self._stored_results = None
        self._cache_identifier = None

    def estimated_parameter_count(self, rank: Optional[int] = None) -> int:
        return self.config.model_config.padded_vocab_size * self.config.model_config.hidden_dimension

    def estimated_activation_footprint(self, batch_size: int, sequence_length: int) -> int:
        return (
            batch_size
            * sequence_length
            // self.config.model_parallel_config.tensor_model_parallel_degree
            // self.config.model_parallel_config.context_model_parallel_degree
            * self.config.model_config.hidden_dimension
            * 2
        )  # Using bf16 precision

    def _acquire_profiling_data(self, batch_size: int, sequence_length: int) -> tuple[float, float, int]:
        """Retrieve or compute profiling data with caching."""
        cache_id = (batch_size, sequence_length)
        if self._stored_results is None or self._cache_identifier != cache_id:
            # Handle context parallel / sequence parallel adjustments
            cp_degree = self.config.model_parallel_config.context_model_parallel_degree
            # Adjusted sequence length per rank when CP is active
            effective_seq_len = sequence_length // cp_degree
            self._stored_results = benchmark_layer(
                self.layer,
                [
                    ((batch_size, effective_seq_len), torch.int64),
                ],
            )
            self._cache_identifier = cache_id
        return self._stored_results

    def get_forward_latency(self, batch_size: int, sequence_length: int) -> float:
        forward_duration, _, _ = self._acquire_profiling_data(batch_size, sequence_length)
        return forward_duration

    def get_backward_latency(self, batch_size: int, sequence_length: int) -> float:
        _, backward_duration, _ = self._acquire_profiling_data(batch_size, sequence_length)
        return backward_duration

    def get_activation_memory_usage(self, batch_size: int, sequence_length: int) -> int:
        _, _, activation_bytes = self._acquire_profiling_data(batch_size, sequence_length)
        return activation_bytes

