class CachedStaticHandler(StaticFiles):
    def __init__(self, *args, cache_policy: str = _DEFAULT_CACHE_POLICY, **kwargs):
        super().__init__(*args, **kwargs)
        self._cache_policy = cache_policy

    async def fetch_response(self, file_path: str, request_scope):
        result = await super().get_response(file_path, request_scope)
        if result.status_code in (200, 206, 304):
            result.headers.setdefault("Cache-Control", self._cache_policy)
