def determine_attention_backend():
    env_value = os.environ.get('DIFFSYNTH_ATTENTION_IMPLEMENTATION')
    if env_value is not None:
        return env_value.strip().lower()
    elif HAS_FLASH_ATTN_3:
        return "flash_attention_3"
    elif HAS_FLASH_ATTN_2:
        return "flash_attention_2"
    elif HAS_SAGE_ATTN:
        return "sage_attention"
    elif HAS_XFORMERS:
        return "xformers"
    else:
        return "torch"

SELECTED_ATTENTION_BACKEND = determine_attention_backend()

def prepare_qkv_tensors(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", target_format="b n s d", extra_dims=None):
    extra_dims = {} if extra_dims is None else extra_dims
    if q_format != target_format:
        query = re_arrange(query, f"{q_format} -> {target_format}", **extra_dims)
    if k_format != target_format:
        key = re_arrange(key, f"{k_format} -> {target_format}", **extra_dims)
    if v_format != target_format:
        value = re_arrange(value, f"{v_format} -> {target_format}", **extra_dims)
    return query, key, value

def finalize_output_tensor(output, output_format="b n s d", target_format="b n s d", extra_dims=None):
    extra_dims = {} if extra_dims is None else extra_dims
    if output_format != target_format:
        output = re_arrange(output, f"{target_format} -> {output_format}", **extra_dims)
    return output

def pytorch_scaled_dot_product(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", extra_dims=None, mask=None, scaling_factor=None):
    input_target, output_target = "b n s d", "b n s d"
    query, key, value = prepare_qkv_tensors(query, key, value, q_format, k_format, v_format, input_target, extra_dims)
    result = torch.nn.functional.scaled_dot_product_attention(query, key, value, mask, scale=scaling_factor)
    result = finalize_output_tensor(result, out_format, output_target, extra_dims)
    return result

def flash_attn_v3_impl(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", extra_dims=None, scaling_factor=None):
    input_target, output_target = "b s n d", "b s n d"
    query, key, value = prepare_qkv_tensors(query, key, value, q_format, k_format, v_format, input_target, extra_dims)
    result = flash_attn_interface.flash_attn_func(query, key, value, softmax_scale=scaling_factor)
    if isinstance(result, tuple):
        result = result[0]
    result = finalize_output_tensor(result, out_format, output_target, extra_dims)
    return result

def flash_attn_v2_impl(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", extra_dims=None, scaling_factor=None):
    input_target, output_target = "b s n d", "b s n d"
    query, key, value = prepare_qkv_tensors(query, key, value, q_format, k_format, v_format, input_target, extra_dims)
    result = flash_attn.flash_attn_func(query, key, value, softmax_scale=scaling_factor)
    result = finalize_output_tensor(result, out_format, output_target, extra_dims)
    return result

def sage_attn_impl(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", extra_dims=None, scaling_factor=None):
    input_target, output_target = "b n s d", "b n s d"
    query, key, value = prepare_qkv_tensors(query, key, value, q_format, k_format, v_format, input_target, extra_dims)
    result = sage_attention_func(query, key, value, sm_scale=scaling_factor)
    result = finalize_output_tensor(result, out_format, output_target, extra_dims)
    return result

def xformers_efficient_impl(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", extra_dims=None, scaling_factor=None):
    input_target, output_target = "b s n d", "b s n d"
    query, key, value = prepare_qkv_tensors(query, key, value, q_format, k_format, v_format, input_target, extra_dims)
    result = xops_module.memory_efficient_attention(query, key, value, scale=scaling_factor)
    result = finalize_output_tensor(result, out_format, output_target, extra_dims)
    return result

def execute_attention(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", extra_dims=None, mask=None, scaling_factor=None, legacy_mode=False):
    if legacy_mode or (mask is not None):
        return pytorch_scaled_dot_product(query, key, value, q_format, k_format, v_format, out_format, extra_dims, mask=mask, scaling_factor=scaling_factor)
    else:
        if SELECTED_ATTENTION_BACKEND == "flash_attention_3":
            return flash_attn_v3_impl(query, key, value, q_format, k_format, v_format, out_format, extra_dims, scaling_factor=scaling_factor)
        elif SELECTED_ATTENTION_BACKEND == "flash_attention_2":
            return flash_attn_v2_impl(query, key, value, q_format, k_format, v_format, out_format, extra_dims, scaling_factor=scaling_factor)
        elif SELECTED_ATTENTION_BACKEND == "sage_attention":
            return sage_attn_impl(query, key, value, q_format, k_format, v_format, out_format, extra_dims, scaling_factor=scaling_factor)
        elif SELECTED_ATTENTION_BACKEND == "xformers":
            return xformers_efficient_impl(query, key, value, q_format, k_format, v_format, out_format, extra_dims, scaling_factor=scaling_factor)
        else:
            return pytorch_scaled_dot_product(query, key, value, q_format, k_format, v_format, out_format, extra_dims, scaling_factor=scaling_factor)

