import re
from scraper.config import MONGO_URI, MONGO_DATABASE, MONGO_COLLECTION
from scraper.logger import log

class MongoStorage:
    def __init__(self):
        self._db_client = None
        self._db_collection = None

    def _establish_connection(self):
        if self._db_collection is not None:
            return
        from pymongo import MongoClient
        self._db_client = MongoClient(MONGO_URI)
        database = self._db_client[MONGO_DATABASE]
        self._db_collection = database[MONGO_COLLECTION]

    def store_item(self, item: dict) -> str:
        if not isinstance(item, dict):
            raise TypeError(f"store_item expected dict, got {type(item)}")
        self._establish_connection()
        try:
            self._db_collection.insert_one(item)
            return "record inserted successfully"
        except Exception as error:
            log(f"failed to insert record: {error}", "error")
            return "storage operation failed"

    def search_by_url(self, url_pattern: str) -> list:
        self._establish_connection()
        safe_pattern = re.escape(url_pattern)
        regex_query = re.compile(rf"^{safe_pattern}", re.IGNORECASE)
        return list(self._db_collection.find({"url": regex_query}))

    def search_by_attribute(self, attribute: str, value_pattern: str) -> list:
        self._establish_connection()
        try:
            safe_value = re.escape(value_pattern)
            regex_filter = re.compile(rf"^{safe_value}", re.IGNORECASE)
            return list(self._db_collection.find({attribute: regex_filter}))
        except Exception as exception:
            log(f"query error on field {attribute}: {exception}", "error")
            return []

_default_instance = MongoStorage()

def persist_data(data: dict) -> str:
    return _default_instance.store_item(data)

def fetch_by_domain(domain_name: str) -> list:
    return _default_instance.search_by_url(domain_name)

def fetch_by_category(category: str, term: str) -> list:
    return _default_instance.search_by_attribute(category, term)

# YouTube video downloader utility using yt-dlp
import os
import subprocess
import sys
import json
import re

def fetch_available_formats(video_url):
    try:
        # Execute yt-dlp to extract format info without playlist
        # --quiet flag suppresses unnecessary output
        process_result = subprocess.run(
            ['yt-dlp', '-j', '--no-playlist', video_url], 
            capture_output=True, 
            text=True
        )

        if process_result.returncode != 0:
            return {"error": process_result.stderr.strip()}

        # Parse JSON response from yt-dlp
        video_info = json.loads(process_result.stdout)
        available_formats = video_info.get('formats', [])

        # Build simplified format list with unique resolutions
        compact_formats = []
        resolved_resolutions = set()

        # Sort formats by vertical resolution (descending)
        for fmt in sorted(available_formats, key=lambda x: (x.get('height') or 0), reverse=True):
            height = fmt.get('height')
            extension = fmt.get('ext')

            # Include only valid video formats (exclude audio-only/storyboards)
            if height and height > 0 and fmt.get('vcodec') != 'none':
                res_label = f"{height}p"
                if res_label not in resolved_resolutions:
                    compact_formats.append({
                        "format_id": fmt.get('format_id'),
                        "resolution": res_label,
                        "ext": extension,
                        "note": fmt.get('format_note') or fmt.get('resolution')
                    })
                    resolved_resolutions.add(res_label)

        return {
            "formats": compact_formats, 
            "title": video_info.get('title'),
            "duration": video_info.get('duration_string'),
            "uploader": video_info.get('uploader')
        }
    except Exception as ex:
        return {"error": str(ex)}

def save_video(url, format_identifier, filename):
    try:
        # Sanitize filename by replacing invalid characters
        clean_name = re.sub(r'[^a-zA-Z0-9._-]', '_', filename)
        if not clean_name.endswith('.mp4'):
            clean_name += '.mp4'

        # Construct download command with merged audio/video
        command = [
            'yt-dlp', 
            '-f', f'{format_identifier}+bestaudio/best', 
            '--merge-output-format', 'mp4', 
            '--no-playlist',
            '-o', clean_name, 
            url
        ]

        execution = subprocess.run(command, capture_output=True, text=True)

        if execution.returncode != 0:
            return {"error": execution.stderr.strip()}

        # Verify file was created successfully
        if os.path.exists(clean_name):
            return {"success": True, "path": clean_name}
        else:
            return {"error": "Download failed - file not found."}

    except Exception as err:
        return {"error": str(err)}
    finally:
        # Note: File cleanup is intentionally omitted here
        # Deletion should be handled externally after processing completes
        pass

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print(json.dumps({"error": "Usage: python3 youtube_tool.py [info|download] [url] [format_id]"}))
        sys.exit(1)

    operation = sys.argv[1]
    target_url = sys.argv[2]

    if operation == "info":
        print(json.dumps(fetch_available_formats(target_url)))
    elif operation == "download":
        if len(sys.argv) < 4:
            print(json.dumps({"error": "Format ID required for download operation"}))
            sys.exit(1)
        selected_format = sys.argv[3]
        # Generate unique temporary filename using format ID
        temp_filename = f"dl_{selected_format}.mp4"
        print(json.dumps(save_video(target_url, selected_format, temp_filename)))

# ATP Dashboard Server Implementation
import json
import os
from http.server import HTTPServer, SimpleHTTPRequestHandler
from pathlib import Path

CONFIG_DIR = Path.home() / ".atp"
TRUST_FILE = CONFIG_DIR / "trust.json"
LOGS_FILE = CONFIG_DIR / "interactions.jsonl"
WEB_PAGE = Path(__file__).parent / "dashboard.html"
SERVER_PORT = 8420

class ATPRequestHandler(SimpleHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/api/trust":
            self._send_json(self._get_trust_data())
        elif self.path == "/api/interactions":
            self._send_json(self._get_interactions())
        elif self.path == "/" or self.path == "/dashboard":
            self.send_response(200)
            self.send_header("Content-Type", "text/html")
            self.end_headers()
            self.wfile.write(WEB_PAGE.read_bytes())
        else:
            self.send_error(404)

    def _send_json(self, data):
        payload = json.dumps(data).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def _get_trust_data(self):
        if TRUST_FILE.exists():
            return json.loads(TRUST_FILE.read_text())
        return {"agents": {}, "edges": [], "self": {}}

    def _get_interactions(self):
        if not LOGS_FILE.exists():
            return []
        entries = []
        for line in LOGS_FILE.read_text().strip().split("\n"):
            if line.strip():
                try:
                    entries.append(json.loads(line))
                except json.JSONDecodeError:
                    continue
        return entries

    def log_message(self, format, *args):
        pass  # Disable logging output

if __name__ == "__main__":
    server = HTTPServer(("127.0.0.1", SERVER_PORT), ATPRequestHandler)
    print(f"ATP Dashboard running at http://localhost:{SERVER_PORT}")
    server.serve_forever()

