# Convert model to float16 or bfloat16 with optional AE module handling
import torch
from megatron.training import get_args
from megatron.core import mpu
from megatron.core.transformer.module import fp32_to_float16, float16_to_fp32, Float16Module

def _convert_module_dtype(module, conversion_func, skip_modules):
    for submodule in module.children():
        if submodule in skip_modules:
            continue
        submodule = conversion_func(submodule)
    return module

def float16_module_init(self, config, network_module):
    super(Float16Module, self).__init__(config)

    # Check if AEModel uses fp32
    ae_config = getattr(config.mm.model, "ae", None)
    use_ae_fp32 = False
    if ae_config is not None and getattr(ae_config, "dtype", None) == torch.float32:
        network_module.ae = network_module.ae.float()
        use_ae_fp32 = True

    if config.fp16:
        if use_ae_fp32:
            self.add_module("module", _convert_module_dtype(network_module, lambda mod: mod.half(), [network_module.ae]))
        else:
            self.add_module("module", network_module.half())

        def half_converter(value):
            return value.half()

    elif config.bf16:
        if use_ae_fp32:
            self.add_module("module", _convert_module_dtype(network_module, lambda mod: mod.bfloat16(), [network_module.ae]))
        else:
            self.add_module("module", network_module.bfloat16())

        def bf16_converter(value):
            return value.bfloat16()
    else:
        raise ValueError("Invalid precision configuration")

    self.precision_converter = half_converter if config.fp16 else bf16_converter

def float16_module_forward(self, *inputs, **kwargs):
    args = get_args()

    if mpu.is_pipeline_first_stage():
        ae_config = getattr(args.mm.model, "ae", None)
        if ae_config is not None and getattr(ae_config, "dtype", None) != torch.float32:
            inputs = fp32_to_float16(inputs, self.precision_converter)

    outputs = self.module(*inputs, **kwargs)

    if mpu.is_pipeline_last_stage():
        outputs = float16_to_fp32(outputs)

    return outputs

