# Helper functions to convert Narwhals frames to Polars frames
from typing import Any, overload
import narwhals as nw
import polars as pl
from narwhals.typing import DataFrameT, Frame, FrameT, LazyFrameT

def convert_to_eager_polars(frame: Frame) -> pl.DataFrame:
    """Convert a Narwhals frame to an eager Polars DataFrame."""
    return frame.lazy().collect().to_polars()

def convert_lazy_to_polars(frame: nw.LazyFrame[Any]) -> pl.LazyFrame:
    """Convert a Narwhals lazy frame to a Polars lazy frame.
    If the Narwhals LazyFrame is already backed by Polars, this is a no-op."""
    if frame.implementation == nw.Implementation.POLARS:
        return frame.to_native()
    return frame.collect().to_polars().lazy()

@overload
def adapt_to_polars_implementation(frame: DataFrameT) -> DataFrameT: ...
@overload
def adapt_to_polars_implementation(frame: LazyFrameT) -> LazyFrameT: ...
def adapt_to_polars_implementation(frame: FrameT) -> FrameT:
    if frame.implementation == nw.Implementation.POLARS:
        return frame
    elif isinstance(frame, nw.DataFrame):
        return nw.from_native(frame.to_polars())
    elif isinstance(frame, nw.LazyFrame):
        return nw.from_native(
            frame.collect().to_polars(),
        ).lazy()
    else:
        raise ValueError(f"Unsupported frame type: {type(frame)}")

__all__ = ["convert_to_eager_polars"]

# Time step embedding utilities for neural networks
import math
import torch
import torch.nn as nn
from einops import rearrange, repeat

def generate_timestep_features(timesteps, feature_dim, max_duration=10000, only_repeat=False, tensor_dtype=torch.float32):
    if not only_repeat:
        half_features = feature_dim // 2
        angular_freqs = torch.exp(-math.log(max_duration) * torch.arange(start=0, end=half_features, dtype=torch.float32, device=timesteps.device) / half_features)
        arguments = timesteps[:, None].float() * angular_freqs[None]
        combined_features = torch.cat([torch.cos(arguments), torch.sin(arguments)], dim=-1)
        if feature_dim % 2:
            combined_features = torch.cat([combined_features, torch.zeros_like(combined_features[:, :1])], dim=-1)
    else:
        combined_features = repeat(timesteps, "b -> b d", d=feature_dim)
    return combined_features.to(tensor_dtype)

class TemporalFeatureEmbedder(nn.Module):
    def __init__(self, internal_dim, projection_dim=None, max_duration=10000, only_repeat=False):
        super().__init__()
        self.internal_dim = internal_dim
        self.projection_dim = projection_dim if projection_dim is not None else internal_dim
        self.max_duration = max_duration
        self.only_repeat = only_repeat
        self.temporal_projector = nn.Sequential(
            nn.Linear(self.internal_dim, projection_dim),
            nn.SiLU(),
            nn.Linear(projection_dim, projection_dim),
        )

    @property
    def data_type(self) -> torch.dtype:
        """The data type of the module (assuming that all the module parameters have the same data type)."""
        parameters = tuple(self.parameters())
        if len(parameters) > 0:
            return parameters[0].dtype
        else:
            buffers = tuple(self.buffers())
            return buffers[0].dtype

    def forward(self, time_steps):
        features = generate_timestep_features(time_steps, self.internal_dim, self.max_duration, self.only_repeat, dtype=self.data_type)
        return self.temporal_projector(features)

# Modified version of the Code class with renamed variables and reordered logic
from collections.abc import Mapping as _Mapping

class JavaScriptCode(str):
    """BSON's JavaScript code type.
    Raises :class:`TypeError` if `code` is not an instance of
    :class:`basestring` (:class:`str` in python 3) or `context`
    is not ``None`` or an instance of :class:`dict`.
    Context variables can be set by passing a dictionary as the `context`
    argument or by using keyword arguments. If a variable is set as a
    keyword argument it will override any setting for that variable in
    the `context` dictionary.
    :Parameters:
      - `code`: A string containing JavaScript code to be evaluated or another
        instance of JavaScriptCode. In the latter case, the context of `code` becomes this
        JavaScriptCode's :attr:`context`.
      - `context` (optional): dictionary representing the context in which
        `code` should be evaluated - a mapping from identifiers (as
        strings) to values. Defaults to ``None``. This is applied after any
        context associated with a given `code` above.
      - `**kwargs` (optional): context variables can also be passed as
        keyword arguments. These are applied after `context` and `code`.
    .. versionchanged:: 3.4
      The default value for :attr:`context` is ``None`` instead of ``{}``.
    """
    _type_marker = 13

    def __new__(cls, code, context=None, **kwargs):
        # Validate input types first
        if not isinstance(code, str):
            raise TypeError("code must be an instance of str")

        # Create the new instance
        self = str.__new__(cls, code)

        # Initialize scope from existing Code object if available
        try:
            self._scope_dict = code._scope_dict
        except AttributeError:
            self._scope_dict = None

        # Apply context dictionary if provided
        if context is not None:
            if not isinstance(context, _Mapping):
                raise TypeError("context must be an instance of dict")
            if self._scope_dict is not None:
                self._scope_dict.update(context)
            else:
                self._scope_dict = context

        # Apply keyword arguments last (highest priority)
        if kwargs:
            if self._scope_dict is not None:
                self._scope_dict.update(kwargs)
            else:
                self._scope_dict = kwargs

        return self

    @property
    def context(self):
        """Context dictionary for this instance or ``None``."""
        return self._scope_dict

    def __repr__(self):
        return "JavaScriptCode(%s, %r)" % (str.__repr__(self), self._scope_dict)

    def __eq__(self, other):
        if isinstance(other, JavaScriptCode):
            return (self._scope_dict, str(self)) == (other._scope_dict, str(other))
        return False

    __hash__ = None

    def __ne__(self, other):
        return not self == other

