import re

def extract_sections(text: str):
    """Parse individual character blocks from combined SOUL markdown (approximate parsing)."""
    regex = r'## ([^\n]+)\n(.*?)(?=\n## [^\n]+\n|\Z)'
    return re.findall(regex, text, re.DOTALL)

def combine_soul_text(base: str, addition: str) -> str:
    """Merge without duplication by matching section headings and body content."""
    if not base.strip():
        return addition
    if addition.strip() in base:
        return base
    return base.rstrip() + "\n\n" + addition.lstrip()

