# Implementation for removing files or directories
from ..process import Process
from ..command_decorators import command
from . import register_command

@command(needs_path_resolution=True)
@register_command('delete')
def cmd_delete(process: Process) -> int:
    """
    Delete file or directory
    Usage: delete [-r] path...
    """
    if not process.args:
        process.stderr.write("delete: missing operand\n")
        return 1

    if not process.filesystem:
        process.stderr.write("delete: filesystem not available\n")
        return 1

    recursive_mode = False
    target_paths = []

    for argument in process.args:
        if argument == '-r' or argument == '-rf':
            recursive_mode = True
        else:
            target_paths.append(argument)

    if not target_paths:
        process.stderr.write("delete: missing file operand\n")
        return 1

    return_status = 0
    for target in target_paths:
        try:
            # Utilize AGFS client to remove file/directory
            process.filesystem.client.rm(target, recursive=recursive_mode)
        except Exception as error:
            error_description = str(error)
            process.stderr.write(f"delete: {target}: {error_description}\n")
            return_status = 1

    return return_status

# Convert hex-encoded audio data to bytes and save to file
import binascii
import pathlib
import requests

def hex_to_binary(hex_string: str) -> bytes:
    """Transform a hexadecimal string into its binary representation."""
    return binascii.unhexlify(hex_string)

def write_bytes_to_file(binary_data: bytes, destination: str) -> str:
    target = pathlib.Path(destination)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(binary_data)
    return str(target)

def fetch_and_save(url: str, file_path: str) -> str:
    response = requests.get(url, timeout=60)
    response.raise_for_status()
    return write_bytes_to_file(response.content, file_path)

