import logging
from app.collectors.base import Collector, CollectorResult
from .client import SpeedtestClient
from .storage import SpeedtestStorage

logger = logging.getLogger("docsis.collector.speedtest")

class SpeedtestCollector(Collector):
    """Retrieves and stores speed test data from Speedtest Tracker with local caching."""
    name = "speedtest"

    def __init__(self, config_handler, db_storage, web_interface, check_interval=300, **options):
        super().__init__(check_interval)
        self._config_handler = config_handler
        self._db_storage = SpeedtestStorage(db_storage.db_path)
        self._web_interface = web_interface
        self._api_client = None
        self._cached_url = None

    def is_active(self) -> bool:
        return self._config_handler.is_speedtest_enabled()

    def _setup_client(self):
        """Re-initialize the API client if the configured URL has changed."""
        url = self._config_handler.get("speedtest_tracker_url")
        if url != self._cached_url:
            token = self._config_handler.get("speedtest_tracker_token")
            self._api_client = SpeedtestClient(url, token)
            self._cached_url = url
            logger.info("Speedtest Tracker endpoint: %s", url)

    def run_collection(self) -> CollectorResult:
        self._setup_client()

        # Fetch latest result for dashboard display
        latest_results = self._api_client.fetch_latest(1)
        if latest_results:
            self._web_interface.set_state(speedtest_latest=latest_results[0])

        # Update cache incrementally (errors here shouldn't affect overall collection status)
        try:
            last_record_id = self._db_storage.get_latest_speedtest_id()
            current_count = self._db_storage.get_speedtest_count()

            if current_count < 50:
                batch_results = self._api_client.fetch_all(per_page=2000)
            else:
                batch_results = self._api_client.fetch_since(last_record_id)

            if batch_results:
                self._db_storage.store_speedtest_data(batch_results)
                logger.info(
                    "Stored %d new speedtest entries (cumulative: %d)",
                    len(batch_results),
                    current_count + len(batch_results),
                )
        except Exception as err:
            logger.warning("Incremental cache update failed: %s", err)

        return CollectorResult(source=self.name)

# Custom exception classes for request-related errors
from pip._vendor.urllib3.exceptions import HTTPError as BaseHTTPError
from .compat import JSONDecodeError as CompatJSONDecodeError

class RequestException(IOError):
    """An ambiguous exception occurred during request handling."""
    def __init__(self, *args, **kwargs):
        """Initialize with `request` and `response` objects."""
        response = kwargs.pop("response", None)
        self.response = response
        self.request = kwargs.pop("request", None)
        if response is not None and not self.request and hasattr(response, "request"):
            self.request = self.response.request
        super().__init__(*args, **kwargs)

class InvalidJSONError(RequestException):
    """An error occurred while processing JSON."""

class JSONDecodeError(InvalidJSONError, CompatJSONDecodeError):
    """Unable to decode text into JSON format."""
    def __init__(self, *args, **kwargs):
        """
        Initialize JSONDecodeError using provided arguments.
        First initialize CompatJSONDecodeError, then use its args
        to initialize InvalidJSONError to preserve the original message.
        """
        CompatJSONDecodeError.__init__(self, *args)
        InvalidJSONError.__init__(self, *self.args, **kwargs)

