# Import necessary modules for process management and threading
import subprocess
from subprocess import Popen
from threading import Event, Thread

def terminate_threads(thread_list: list[Thread]):
    """Gracefully terminate a collection of threads"""
    for t in thread_list:
        t.join(timeout=5)

def terminate_subprocesses(proc_list: list[Popen]):
    """Safely terminate a collection of subprocesses"""
    for proc in proc_list:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=60)
            except subprocess.TimeoutExpired:
                proc.kill()

def watch_process(proc: Popen, shutdown_flag: Event, error_buffer: list, name: str):
    """Observe a subprocess and report failures through a shared buffer."""
    proc.wait()
    if proc.returncode != 0:
        msg = f"{name.capitalize()} failed with exit code {proc.returncode}"
        if proc.stderr:
            msg += f"\n{proc.stderr.read().decode('utf-8')}"
        error_buffer.append(RuntimeError(msg))
    shutdown_flag.set()

# Compute the token denominator for statistics tracking
from __future__ import annotations
from typing import Any
import torch

def infer_token_denominator(
    data: dict[str, Any],
    default_tensor: torch.Tensor,
) -> torch.Tensor:
    """Determine the full token mask for logging metrics.
    When context parallelism is used, intermediate tensors like ``loss_mask`` or
    model outputs may be partitioned, but the original micro-batch metadata still
    represents the complete logical sequence. Prioritize this metadata for ``n_tokens``
    to ensure metric consistency regardless of context parallelism.
    """
    shared_kwargs = {"dtype": torch.bool, "device": default_tensor.device}

    # Check attention mask first
    attn_mask = data.get("attention_mask")
    if isinstance(attn_mask, torch.Tensor):
        return torch.ones_like(attn_mask, **shared_kwargs)

    # Then check cumulative sequence lengths
    cu_seqlens = data.get("cu_seqlens")
    if isinstance(cu_seqlens, torch.Tensor) and cu_seqlens.numel() > 0:
        return torch.ones(int(cu_seqlens[-1].item()), **shared_kwargs)

    # Finally check input IDs, but only if shape matches the target tensor
    input_ids = data.get("input_ids")
    if isinstance(input_ids, torch.Tensor) and input_ids.shape == default_tensor.shape:
        return torch.ones_like(input_ids, **shared_kwargs)

    # Fallback to creating a mask matching the default tensor
    return torch.ones_like(default_tensor, **shared_kwargs)

