# Module for handling LLM streaming capability checks
import logging
import litellm
import config.config as _config

logger = logging.getLogger(__name__)

class StreamingNotSupportedError(Exception):
  """Exception raised when a required LLM lacks native streaming support."""
  def __init__(self, agent_name: str, model: str, message: str):
    self.agent_name = agent_name
    self.model = model
    self.message = message
    super().__init__(message)

def check_streaming_support(model: str) -> tuple[bool, BaseException | None]:
  """Determine if the specified LLM supports native streaming.

  Returns:
    (True, None) if streaming is supported,
    (False, None) if metadata indicates no support or key missing,
    (False, exception) if an error occurred during check.
  """
  try:
    model_details = litellm.get_model_info(model=model)
    if model_details.get("supports_native_streaming") is True:
      return (True, None)
    return (False, None)
  except (litellm.NotFoundError, litellm.BadRequestError, litellm.APIConnectionError, litellm.APIError, litellm.Timeout) as e:
    logger.debug("Failed to retrieve streaming info for model %s: %s", model, e)
    return (False, e)
  except Exception as e:
    logger.debug("Unexpected error while fetching model info for %s: %s", model, e)
    return (False, e)

def enforce_streaming_requirement(agent_name: str, model: str) -> None:
  """Validate that the specified LLM supports streaming if ENSURE_STREAMING_LLM is enabled.

  Raises StreamingNotSupportedError if streaming is required but not supported.
  """
  if not _config.ENSURE_STREAMING_LLM:
    return

  has_support, error = check_streaming_support(model)
  if has_support:
    logger.info("[%s] Streaming requirement verified.", agent_name or "agent")
    return

  error_msg = (
    f"Selected model does not support streaming. "
    f"Please choose a streaming-capable model (e.g. openai/gpt-4o)."
  )

  if error is not None:
    if agent_name:
      logger.error("[%s] %s Model: %s (underlying cause: %s)", agent_name, error_msg, model, error)
    else:
      logger.error("%s Model: %s (underlying cause: %s)", error_msg, model, error)
    raise StreamingNotSupportedError(agent_name=agent_name, model=model, message=error_msg) from error

  if agent_name:
    logger.error("[%s] %s Model: %s", agent_name, error_msg, model)
  else:
    logger.error("%s Model: %s", error_msg, model)
  raise StreamingNotSupportedError(agent_name=agent_name, model=model, message=error_msg)

