# Monitor MinIO buckets for new files and download them
import logging
import time
from pathlib import Path
from threading import Thread
from common.dependencies import get_file_scheduling_service, get_lazybytes_service
from minio import Minio
from minio.datatypes import Bucket
from crawler.settings import settings

logger = logging.getLogger(__name__)

# Configuration constants
BUCKET_POLLING_INTERVAL_SEC: int = 300
DOWNLOAD_CHUNK_SIZE: int = 64 * 1024


class MinioBucketMonitor:
    def __init__(self, minio_connection: Minio):
        self.connection = minio_connection
        self.active_monitors: dict[Bucket, Thread] = {}

    def _cleanup_stopped_threads(self):
        # First gather buckets with inactive threads
        inactive_buckets = []
        for bucket, monitor in self.active_monitors.items():
            if not monitor.is_alive():
                logger.info("Cleaning up stopped monitor for bucket: %s", bucket)
                inactive_buckets.append(bucket)
        # Then remove those entries
        for bucket in inactive_buckets:
            del self.active_monitors[bucket]

    def _start_monitor_for_new_buckets(self):
        for bucket in self.connection.list_buckets():
            if bucket not in self.active_monitors:
                logger.info("New bucket detected: %s", bucket)
                self._spawn_bucket_monitor(bucket)

    def _spawn_bucket_monitor(self, bucket: Bucket):
        monitor_thread = _FileMonitorThread(self.connection, bucket)
        monitor_thread.start()
        self.active_monitors[bucket] = monitor_thread

    def run(self):
        while True:
            self._cleanup_stopped_threads()
            self._start_monitor_for_new_buckets()
            time.sleep(BUCKET_POLLING_INTERVAL_SEC)


class _FileMonitorThread(Thread):
    def __init__(self, client: Minio, bucket: Bucket):
        super().__init__()
        self.client = client
        self.bucket = bucket

    def run(self):
        self._process_existing_files()
        self._watch_for_new_files()

    def _download_object(self, object_key: str):
        logger.info("Downloading file %s", object_key)
        full_path = Path(f"//{self.bucket.name}/{object_key}")
        source = f"{settings.crawler_source_id}/{self.bucket.name}"
        get_file_scheduling_service().index_file(
            full_name=str(full_path),
            file_content=get_lazybytes_service().from_generator(
                self.client.get_object(self.bucket.name, object_key).stream(
                    DOWNLOAD_CHUNK_SIZE
                )  # type: ignore
            ),
            source_id=source,
            parent_id=None,
        )

    def _process_existing_files(self):
        objects = self.client.list_objects(self.bucket.name, recursive=True)
        for obj in objects:
            if obj.object_name is not None:
                self._download_object(obj.object_name)

    def _watch_for_new_files(self):
        with self.client.listen_bucket_notification(
            self.bucket.name,
            prefix="",
            events=["s3:ObjectCreated:*"],  # type: ignore
        ) as events:
            for event in events:
                for record in event.get("Records", []):
                    file_key = record["s3"]["object"]["key"]
                    self._download_object(file_key)

