    def __init__(self, model_path, config, device, lora_path=None, lora_strength=1.0):
        super().__init__(model_path, config, device, lora_path=lora_path, lora_strength=lora_strength)

    def _load_ckpt(self, unified_dtype, sensitive_layer):
        file_path = self.config["sf_model_path"]
        raw_weight_dict = torch.load(file_path)
        raw_weight_dict = raw_weight_dict.get("generator_ema", raw_weight_dict)
        processed_weight_dict = {}
        for key, value in raw_weight_dict.items():
            new_name = key[7:]
            tensor = value.to(GET_DTYPE()).to(self.device)
            processed_weight_dict.update({new_name: tensor})
        del raw_weight_dict
        return processed_weight_dict

    def _load_quant_ckpt(self, unified_dtype, sensitive_layer):
        quant_weight_dict = super()._load_quant_ckpt(unified_dtype, sensitive_layer)
        final_weight_dict = {}
        for key, value in quant_weight_dict.items():
            final_weight_dict.update({key[7:]: value})
        del quant_weight_dict
        return final_weight_dict

    def _init_infer_class(self):
        self.pre_infer_class = WanSFPreInfer
        self.post_infer_class = WanPostInfer
        self.transformer_infer_class = WanSFTransformerInfer

    @torch.no_grad()
    def infer(self, inputs):
        if self.cpu_offload:
            if self.offload_granularity == "model" and self.scheduler.step_index == 0:
                self.cuda()
            elif self.offload_granularity != "model":
                self.pre_weight.cuda()
                self.transformer_weights.non_block_weights_cuda()

        start_frame_idx = self.scheduler.seg_index * self.scheduler.num_frame_per_block
        end_frame_idx = (self.scheduler.seg_index + 1) * self.scheduler.num_frame_per_block
        prediction = self._infer_cond_uncond(inputs, infer_condition=True)
        self.scheduler.noise_pred[:, start_frame_idx:end_frame_idx] = prediction

        if self.cpu_offload:
            if self.offload_granularity == "model" and self.scheduler.step_index == self.scheduler.infer_steps - 1:
                self.cpu()
            elif self.offload_granularity != "model":
                self.pre_weight.cpu()
                self.transformer_weights.non_block_weights_cpu()

