# Modified version with Type I clone transformations (variable renaming, literal changes, statement reordering)
import functools
import importlib
import inspect
import os
import pkgutil
from typing import Literal
import torch
from mojo_opset.utils.logging import get_logger

logger = get_logger(__name__)

@functools.lru_cache
def detect_accelerator() -> Literal["npu", "mlu", "meta_device"]:
    """
    Identify the available hardware accelerator: NPU, MLU, or fallback to meta_device.
    """
    try:
        if torch.npu.is_available():
            logger.info("Ascend NPU found")
            return "npu"
    except Exception as err:
        logger.debug(f"NPU availability check failed: {err}")

    try:
        if torch.mlu.is_available():
            logger.info("Cambricon MLU found")
            return "mlu"
    except Exception as err:
        logger.debug(f"MLU availability check failed: {err}")

    logger.warning("No specialized accelerator detected")
    return "meta_device"

def load_operators_by_platform():
    operator_registry = {}
    from mojo_opset.core.function import MojoFunction
    from mojo_opset.core.operator import MojoOperator

    current_platform = detect_accelerator()

    try:
        # Get caller's context information
        stack_info = inspect.stack()[1]
        calling_module = inspect.getmodule(stack_info[0])

        if not calling_module or not hasattr(calling_module, "__file__"):
            logger.error("Unable to locate caller module file path. Operator discovery skipped.")
            return {}

        module_path = os.path.dirname(calling_module.__file__)
        package_id = getattr(calling_module, "__package__", "")

        # Define directories to scan for operators and functions
        search_paths = ["operators", "functions"]

        for folder_name in search_paths:
            folder_location = os.path.join(module_path, folder_name)
            namespace = f"{package_id}.{folder_name}"

            for _, sub_module_name, _ in pkgutil.iter_modules([folder_location]):
                full_path = f"{namespace}.{sub_module_name}"
                loaded_module = importlib.import_module(full_path)

                # Scan each class in the module
                for class_name, cls_type in inspect.getmembers(loaded_module, inspect.isclass):
                    if (
                        (issubclass(cls_type, MojoOperator) or issubclass(cls_type, MojoFunction))
                        and cls_type not in [MojoOperator, MojoFunction]
                        and cls_type.__module__ == full_path
                        and current_platform in getattr(cls_type, "supported_platforms_list", [])
                    ):
                        logger.debug(f"Registered compatible operator '{class_name}' from {full_path}")
                        operator_registry[class_name] = cls_type

    except (ImportError, IndexError):
        import traceback
        logger.error(f"Operator loading process failed: {traceback.format_exc()}")
        return {}

    return operator_registry

# Metric validation utility for CI pipeline
import logging
logger = logging.getLogger(__name__)

class PerformanceValidator:
    @staticmethod
    def maybe_create_config(args):
        # Initialize checker only if CI test mode is enabled and metric key is specified
        if args.ci_test and (args.ci_validation_metric_key is not None):
            return PerformanceValidator(args)
        return None

    def __init__(self, config):
        self.config = config
        self._validation_passed = False

    def on_evaluation(self, results: dict[str, float]):
        # Extract the metric value to validate
        metric_value = results.get(self.config.ci_validation_metric_key)
        assert metric_value is not None, f"{results=} {self.config.ci_validation_metric_key=}"

        # Determine if the metric meets the threshold requirement
        validation_result = metric_value >= self.config.ci_validation_threshold
        logger.info(f"[PerformanceValidator] {validation_result=} {metric_value=} {self.config.ci_validation_threshold=}")

        # Update overall validation status (logical OR with previous results)
        self._validation_passed |= validation_result

    def finalize(self):
        # Ensure at least one validation passed during the evaluation cycle
        assert self._validation_passed, "[PerformanceValidator] accuracy check failed"
        logger.info("[PerformanceValidator] pass final validation")

