# Convert LangChain messages to string format 
from langchain_core.messages import AIMessage, BaseMessage, HumanMessage

def convert_message_to_string(msg: BaseMessage):
    if isinstance(msg, HumanMessage):
        speaker = 'User'
    elif isinstance(msg, AIMessage):
        speaker = 'AI'
    else:
        raise ValueError(f"Unexpected message type: {type(msg)}")
    return f"{speaker}: {msg.content}"

def convert_history_to_string(messages: list[BaseMessage]):
    return '\n'.join(convert_message_to_string(m) for m in messages)

def enclose_in_curly_braces(content: str):
    """Enclose the provided text within curly braces. Helpful for injecting dynamic variables into LangChain prompt templates"""
    return f'{{{content}}}'

# Fill PDF form fields from JSON data
import json
import sys
from pypdf import PdfReader, PdfWriter
from extract_form_field_info import get_field_info

def populate_pdf_forms(input_file: str, json_data_path: str, output_file: str):
    with open(json_data_path) as file:
        field_data = json.load(file)

    organized_fields = {}
    for item in field_data:
        if "data_value" in item:
            field_identifier = item["field_id"]
            page_number = item["page"]
            if page_number not in organized_fields:
                organized_fields[page_number] = {}
            organized_fields[page_number][field_identifier] = item["data_value"]

    pdf_reader = PdfReader(input_file)
    encountered_error = False
    form_field_details = get_field_info(pdf_reader)
    field_lookup = {f["field_id"]: f for f in form_field_details}

    for item in field_data:
        current_field = field_lookup.get(item["field_id"])
        if not current_field:
            encountered_error = True
            print(f"ERROR: `{item['field_id']}` is not a valid field ID")
        elif item["page"] != current_field["page"]:
            encountered_error = True
            print(f"ERROR: Incorrect page number for `{item['field_id']}` (got {item['page']}, expected {current_field['page']})")
        else:
            if "data_value" in item:
                validation_msg = validate_field_value(current_field, item["data_value"])
                if validation_msg:
                    print(validation_msg)
                    encountered_error = True

    if encountered_error:
        sys.exit(1)

    pdf_writer = PdfWriter(clone_from=pdf_reader)
    for page_num, field_values in organized_fields.items():
        pdf_writer.update_page_form_field_values(pdf_writer.pages[page_num - 1], field_values, auto_regenerate=False)

    pdf_writer.set_need_appearances_writer(True)

    with open(output_file, "wb") as output:
        pdf_writer.write(output)

def validate_field_value(field_details, provided_value):
    field_category = field_details["type"]
    field_name = field_details["field_id"]

    if field_category == "checkbox":
        selected_val = field_details["checked_value"]
        deselected_val = field_details["unchecked_value"]
        if provided_value != selected_val and provided_value != deselected_val:
            return f'ERROR: Invalid value "{provided_value}" for checkbox field "{field_name}". The checked value is "{selected_val}" and the unchecked value is "{deselected_val}"'

    elif field_category == "radio_group":
        available_options = [opt["value"] for opt in field_details["radio_options"]]
        if provided_value not in available_options:
            return f'ERROR: Invalid value "{provided_value}" for radio group field "{field_name}". Valid values are: {available_options}'

    elif field_category == "choice":
        available_choices = [opt["value"] for opt in field_details["choice_options"]]
        if provided_value not in available_choices:
            return f'ERROR: Invalid value "{provided_value}" for choice field "{field_name}". Valid values are: {available_choices}'

    return None

def patch_pypdf_functionality():
    from pypdf.generic import DictionaryObject
    from pypdf.constants import FieldDictionaryAttributes

    original_method = DictionaryObject.get_inherited

    def modified_get_inherited(self, key: str, default=None):
        result = original_method(self, key, default)
        if key == FieldDictionaryAttributes.Opt:
            if isinstance(result, list) and all(isinstance(v, list) and len(v) == 2 for v in result):
                result = [r[0] for r in result]
        return result

    DictionaryObject.get_inherited = modified_get_inherited

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    patch_pypdf_functionality()
    input_pdf_path = sys.argv[1]
    json_fields_file = sys.argv[2]
    output_pdf_path = sys.argv[3]

    populate_pdf_forms(input_pdf_path, json_fields_file, output_pdf_path)

# Modified version of the original audio processing module
import base64
import io
from pathlib import Path
import numpy as np
import soundfile as sf
from scipy import signal

def check_audio_size(audio_bytes: bytes, limit_mb: int = 10) -> bool:
    try:
        size_in_mb = len(audio_bytes) / (1024 * 1024)
        if size_in_mb > limit_mb:
            return False
        temp_buffer = io.BytesIO(audio_bytes)
        audio_data, sample_rate = sf.read(temp_buffer)
        length_seconds = len(audio_data) / sample_rate
        if length_seconds < 1.0 or length_seconds > 30.0:
            return False
        return True
    except Exception:
        return False

def prepare_reference_audio(audio_bytes: bytes) -> tuple[np.ndarray, int]:
    temp_buffer = io.BytesIO(audio_bytes)
    audio_data, original_sample_rate = sf.read(temp_buffer)
    if audio_data.ndim > 1:
        audio_data = np.mean(audio_data, axis=1)
    desired_sample_rate = 24000
    if original_sample_rate != desired_sample_rate:
        audio_data = resample_signal(audio_data, original_sample_rate, desired_sample_rate)
    audio_data = audio_data.astype(np.float32)
    return audio_data, desired_sample_rate

def resample_signal(audio_data: np.ndarray, original_sr: int, target_sr: int = 24000) -> np.ndarray:
    if original_sr == target_sr:
        return audio_data
    number_of_samples = int(len(audio_data) * target_sr / original_sr)
    resampled_data = signal.resample(audio_data, number_of_samples)
    return resampled_data.astype(np.float32)

def compute_audio_properties(audio_data: np.ndarray, sample_rate: int) -> dict:
    duration = len(audio_data) / sample_rate
    rms_value = np.sqrt(np.mean(audio_data ** 2))
    return {
        'duration': float(duration),
        'sample_rate': int(sample_rate),
        'num_samples': int(len(audio_data)),
        'rms_energy': float(rms_value)
    }

def convert_to_base64(audio_data: np.ndarray, sample_rate: int) -> str:
    buffer = io.BytesIO()
    sf.write(buffer, audio_data, sample_rate, format='WAV')
    buffer.seek(0)
    raw_audio = buffer.read()
    return base64.b64encode(raw_audio).decode('utf-8')

def convert_from_base64(base64_string: str) -> tuple[np.ndarray, int]:
    decoded_bytes = base64.b64decode(base64_string)
    buffer = io.BytesIO(decoded_bytes)
    audio_data, sample_rate = sf.read(buffer)
    return audio_data, sample_rate

def verify_audio_format(audio_bytes: bytes) -> bool:
    try:
        temp_buffer = io.BytesIO(audio_bytes)
        sf.read(temp_buffer)
        return True
    except Exception:
        return False

def calculate_duration(audio_data: np.ndarray, sample_rate: int) -> float:
    return len(audio_data) / sample_rate

def write_audio_file(
    audio_data: np.ndarray,
    sample_rate: int,
    file_path: str | Path
) -> str:
    file_path = Path(file_path)
    file_path.parent.mkdir(parents=True, exist_ok=True)
    if not isinstance(audio_data, np.ndarray):
        audio_data = np.array(audio_data, dtype=np.float32)
    if audio_data.ndim == 1:
        pass
    elif audio_data.ndim == 2:
        if audio_data.shape[0] < audio_data.shape[1]:
            audio_data = audio_data.T
    else:
        raise ValueError(f"Unexpected audio array shape: {audio_data.shape}")
    audio_data = audio_data.astype(np.float32)
    sf.write(str(file_path), audio_data, sample_rate, format='WAV', subtype='PCM_16')
    return str(file_path)

# Test suite for dataset setup functionality
import unittest
from unittest.mock import patch, MagicMock
from torch.utils.data import Dataset
from cosmos_rl.utils.util import call_setup

class _DatasetWithoutSetup(Dataset):
    pass

class _NewStyleDataset(Dataset):
    def __init__(self):
        super().__init__()
        self.received_config = None

    def setup(self, config):
        self.received_config = config

class _LegacyDataset(Dataset):
    def __init__(self):
        super().__init__()
        self.invocations = []

    def setup(self, config, tokenizer):
        self.invocations.append((config, tokenizer))

class _MalformedSignatureDataset(Dataset):
    def setup(self, config, tokenizer, additional_param):
        self.config = config
        self.tokenizer = tokenizer
        self.additional_param = additional_param

class _MockPolicy:
    def __init__(self, model_path: str):
        self.model_path = model_path

class _MockConfig:
    def __init__(self, model_path: str = "dummy/model"):
        self.policy = _MockPolicy(model_path)

class TestDatasetSetup(unittest.TestCase):
    def setUp(self):
        self.test_config = _MockConfig()
        mock_patcher = patch("transformers.AutoTokenizer.from_pretrained")
        self.mock_tokenizer_loader = mock_patcher.start()
        self.addCleanup(mock_patcher.stop)
        self.dummy_tokenizer = MagicMock()
        self.mock_tokenizer_loader.return_value = self.dummy_tokenizer

    def test_missing_setup_method_skips_processing(self):
        dataset_instance = _DatasetWithoutSetup()
        call_setup(dataset_instance, self.test_config)
        self.mock_tokenizer_loader.assert_not_called()

    def test_new_style_setup_receives_config_only(self):
        dataset_instance = _NewStyleDataset()
        call_setup(dataset_instance, self.test_config)
        self.assertIs(dataset_instance.received_config, self.test_config)
        self.mock_tokenizer_loader.assert_not_called()

    def test_legacy_style_triggers_warning_and_provides_tokenizer(self):
        dataset_instance = _LegacyDataset()
        with self.assertWarns(DeprecationWarning):
            call_setup(dataset_instance, self.test_config)
        self.assertEqual(dataset_instance.invocations, [(self.test_config, self.dummy_tokenizer)])

    def test_unsupported_signature_throws_error(self):
        dataset_instance = _MalformedSignatureDataset()
        with self.assertRaises(TypeError):
            call_setup(dataset_instance, self.test_config)

if __name__ == "__main__":
    unittest.main()

