# Custom exception logging utility
import os
import logging

def handle_exception(exc, *details):
    logging.exception(exc)
    for item in details:
        if hasattr(item, "message"):
            logging.error(item.message)
            raise Exception(item.message)
        else:
            logging.error(str(item))
    raise exc

# Custom Optional implementation using generics
from typing import TypeVar, Generic, Union

T = TypeVar("T")

class Maybe(Generic[T]):
    def __init__(self, val: Union[T, None]):
        self._data = val

    def clear(self, other):
        assert isinstance(other, Maybe)
        self._data = other._data

    def has_value(self) -> bool:
        return self._data is not None

    def get(self) -> T:
        """Returns the stored value or raises an exception if empty."""
        if self._data is None:
            raise RuntimeError("Cannot extract value from empty Maybe!")
        return self._data

    def get_or_else(self, fallback: T) -> T:
        """Returns the stored value or a fallback if empty."""
        return self._data if self._data is not None else fallback

# Utility functions for password hashing and JWT token management
from datetime import UTC, datetime, timedelta
import bcrypt
import jwt
from api.constants import OSS_JWT_EXPIRY_HOURS, OSS_JWT_SECRET

def hash_user_password(password: str) -> str:
    return bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")

def check_user_password(password: str, hashed_password: str) -> bool:
    return bcrypt.checkpw(password.encode("utf-8"), hashed_password.encode("utf-8"))

def generate_auth_token(user_id: int, user_email: str) -> str:
    payload = {
        "sub": str(user_id),
        "email": user_email,
        "exp": datetime.now(UTC) + timedelta(hours=OSS_JWT_EXPIRY_HOURS),
        "iat": datetime.now(UTC),
    }
    return jwt.encode(payload, OSS_JWT_SECRET, algorithm="HS256")

def parse_auth_token(token: str) -> dict:
    return jwt.decode(token, OSS_JWT_SECRET, algorithms=["HS256"])

