# Calculate 20-day realized volatility and fetch quotes from Stooq
from __future__ import annotations
import csv
import io
import math
import urllib.request
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Tuple

def _current_utc_timestamp() -> str:
    return datetime.now(timezone.utc).isoformat()

def _fetch_url_content(url: str, timeout_seconds: float = 10.0) -> str:
    request = urllib.request.Request(url, headers={"User-Agent": "invest-agent/1.0"})
    with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
        return response.read().decode("utf-8", errors="replace")

def _normalize_stooq_symbol(ticker: str) -> str:
    t = (ticker or "").strip().lower()
    # Adjust for index tickers starting with ^
    if t.startswith("^"):
        t = t[1:]
    # Add .us suffix for US equities/ETFs
    if "." not in t:
        return f"{t}.us"
    return t

def fetch_quote(ticker: str) -> Dict[str, Any]:
    """Retrieve latest quote snapshot (best-effort) from Stooq."""
    fetch_time = _current_utc_timestamp()
    symbol = _normalize_stooq_symbol(ticker)
    url = f"https://stooq.com/q/l/?s={symbol}&f=sd2t2ohlcv&h&e=csv"
    try:
        content = _fetch_url_content(url)
        data_rows = list(csv.DictReader(io.StringIO(content)))
        if not data_rows:
            raise RuntimeError("empty csv")
        record = data_rows[0]

        def parse_number(value: Optional[str]) -> Optional[float]:
            try:
                return float(value) if value not in (None, "", "N/A") else None
            except Exception:
                return None

        close_price = parse_number(record.get("Close"))
        low_price = parse_number(record.get("Low"))
        high_price = parse_number(record.get("High"))
        daily_range = None
        if low_price is not None or high_price is not None:
            daily_range = {"low": low_price, "high": high_price}

        # Combine Date + Time fields; fallback to fetch timestamp if missing
        quote_timestamp = f"{record.get('Date','')}T{record.get('Time','')}".strip("T") or fetch_time
        return {
            "ticker": ticker,
            "price": close_price,
            "day_range": daily_range,
            "timestamp": quote_timestamp,
            "source": "stooq",
            "fetched_at": fetch_time,
        }
    except Exception as error:
        return {
            "ticker": ticker,
            "price": None,
            "day_range": None,
            "timestamp": fetch_time,
            "source": "stooq",
            "error": f"public quote failed: {error}",
        }

def fetch_daily_prices(ticker: str, max_records: int = 60) -> List[Tuple[str, float]]:
    """Return list of (date, close) sorted ascending by date."""
    symbol = _normalize_stooq_symbol(ticker)
    url = f"https://stooq.com/q/d/l/?s={symbol}&i=d"
    content = _fetch_url_content(url)
    data_rows = list(csv.DictReader(io.StringIO(content)))
    result: List[Tuple[str, float]] = []

    for record in data_rows[-max_records:]:
        try:
            result.append((record["Date"], float(record["Close"])))
        except Exception:
            continue
    return result

def compute_realized_volatility_20d(ticker: str) -> Dict[str, Any]:
    fetch_time = _current_utc_timestamp()
    try:
        price_history = fetch_daily_prices(ticker, max_records=40)
        if len(price_history) < 21:
            raise RuntimeError("insufficient history")

        closing_prices = [price for _, price in price_history]
        log_returns = [math.log(closing_prices[i] / closing_prices[i - 1]) 
                       for i in range(1, len(closing_prices))]

        recent_returns = log_returns[-20:]
        mean_return = sum(recent_returns) / len(recent_returns)
        variance = sum((x - mean_return) ** 2 for x in recent_returns) / (len(recent_returns) - 1)
        rv20 = math.sqrt(variance) * math.sqrt(252.0)

        return {"ticker": ticker, "rv20": rv20, "timestamp": fetch_time, "source": "stooq"}
    except Exception as exception:
        return {"ticker": ticker, "rv20": None, "timestamp": fetch_time, "source": "stooq", "error": str(exception)}

