# Convert DALL-E checkpoint to Hugging Face FlavaImageCodebook format
import argparse
import os
import torch
from transformers import FlavaImageCodebook, FlavaImageCodebookConfig

def rreplace_str(s, old, new, count):
    parts = s.rsplit(old, count)
    return new.join(parts)

def compute_param_sum(state_dict):
    # Skip embeddings as they are duplicated in original FLAVA implementation
    total = 0
    for name, param in state_dict.items():
        if "encoder.embeddings" not in name:
            total += param.float().sum()
    return total

def transform_state_dict(original_dict):
    upgraded = {}
    layer_groups = ["group_1", "group_2", "group_3", "group_4"]

    for key, value in original_dict.items():
        # Adjust group key naming
        for group_name in layer_groups:
            if group_name in key:
                key = key.replace(f"{group_name}.", f"{group_name}.group.")

        # Fix res_path naming
        if "res_path" in key:
            key = key.replace("res_path.", "res_path.path.")

        # Rename .w to .weight (only last occurrence)
        if key.endswith(".w"):
            key = rreplace_str(key, ".w", ".weight", 1)

        # Rename .b to .bias (only last occurrence)
        if key.endswith(".b"):
            key = rreplace_str(key, ".b", ".bias", 1)

        upgraded[key] = value.float()

    return upgraded

@torch.no_grad()
def convert_dalle_to_hf(checkpoint_url, output_dir, config_file=None, save_model=True):
    """
    Adapt DALL-E encoder weights to match Hugging Face FlavaImageCodebook structure.
    """
    from dall_e import Encoder

    # Load DALL-E encoder
    encoder = Encoder()

    # Load checkpoint from local path or URL
    if os.path.exists(checkpoint_url):
        checkpoint = torch.load(checkpoint_url)
    else:
        checkpoint = torch.hub.load_state_dict_from_url(checkpoint_url)

    # Extract state dict if needed
    if isinstance(checkpoint, Encoder):
        checkpoint = checkpoint.state_dict()

    # Load encoder weights
    encoder.load_state_dict(checkpoint)

    # Load configuration
    if config_file is not None:
        hf_config = FlavaImageCodebookConfig.from_pretrained(config_file)
    else:
        hf_config = FlavaImageCodebookConfig()

    # Create HF model and load transformed weights
    hf_model = FlavaImageCodebook(hf_config).eval()
    transformed_weights = transform_state_dict(encoder.state_dict())
    hf_model.load_state_dict(transformed_weights)

    # Verify parameter counts match
    hf_params = compute_param_sum(hf_model.state_dict())
    original_params = compute_param_sum(encoder.state_dict())
    assert torch.allclose(hf_params, original_params, atol=1e-3)

    # Save model or return weights
    if save_model:
        hf_model.save_pretrained(output_dir)
    else:
        return hf_model.state_dict()

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Convert DALL-E checkpoint to Hugging Face format")
    parser.add_argument("--output_dir", default=None, type=str, help="Directory to save the converted model")
    parser.add_argument("--checkpoint_url", default=None, type=str, help="Path or URL to DALL-E checkpoint")
    parser.add_argument("--config_file", default=None, type=str, help="Path to Hugging Face config.json")

    args = parser.parse_args()
    convert_dalle_to_hf(args.checkpoint_url, args.output_dir, args.config_file)

# Security scanner for agent skill directories
import os
import re
import json
import argparse
import sys

# Configuration constants
DEFAULT_PATTERNS_FILE = os.path.join(os.path.dirname(__file__), "../references/threat_patterns.json")

def fetch_patterns(filepath):
    try:
        with open(filepath, "r") as file:
            return json.load(file)
    except Exception as error:
        print(f"Failed to load patterns: {error}")
        sys.exit(1)

def scan_directory(directory_path, threat_patterns):
    audit_result = {
        "target": directory_path,
        "issues": [],
        "risk_level": 0,
        "classification": "SAFE"
    }

    if not os.path.isdir(directory_path):
        print(f"Error: {directory_path} is not a valid directory.")
        sys.exit(1)

    for current_dir, subdirs, filenames in os.walk(directory_path):
        for filename in filenames:
            # Exclude hidden files and certain binary/compiled extensions
            if filename.startswith('.') or filename.endswith(('.pyc', '.skill', '.zip')):
                continue

            full_path = os.path.join(current_dir, filename)
            try:
                with open(full_path, "r", encoding="utf-8", errors="ignore") as content_file:
                    text_content = content_file.read()

                    for threat_type, regex_patterns in threat_patterns.items():
                        for regex in regex_patterns:
                            if re.search(regex, text_content, re.IGNORECASE):
                                issue = {
                                    "location": os.path.relpath(full_path, directory_path),
                                    "type": threat_type,
                                    "regex_matched": regex
                                }
                                audit_result["issues"].append(issue)
                                # Assign risk points: 20 per match, no cap per category
                                audit_result["risk_level"] += 20
            except Exception as err:
                print(f"Unable to process {full_path}: {err}")

    # Determine overall classification based on risk level
    if audit_result["risk_level"] >= 80:
        audit_result["classification"] = "DANGEROUS"
    elif audit_result["risk_level"] >= 40:
        audit_result["classification"] = "SUSPICIOUS"
    elif audit_result["risk_level"] > 0:
        audit_result["classification"] = "CAUTION"

    return audit_result

def execute():
    parser = argparse.ArgumentParser(description="ClawGuard: Scan agent skills for potential security threats.")
    parser.add_argument("directory", help="The directory path containing skills to be scanned.")
    parser.add_argument("--json-output", action="store_true", dest="json_format", help="Display report in JSON format.")
    arguments = parser.parse_args()

    patterns = fetch_patterns(DEFAULT_PATTERNS_FILE)
    result = scan_directory(arguments.directory, patterns)

    if arguments.json_format:
        print(json.dumps(result, indent=2))
    else:
        print(f"\n--- ClawGuard Security Scan Report ---")
        print(f"Scanned Path: {result['target']}")
        print(f"Classification: {result['classification']}")
        print(f"Risk Level: {result['risk_level']}")
        print(f"Issues Found: {len(result['issues'])}")
        print("-" * 35)
        for item in result['issues']:
            print(f"[{item['type'].upper()}] in {item['location']}: Matched '{item['regex_matched']}'")
        print("-" * 35 + "\n")

if __name__ == "__main__":
    execute()

# Network connectivity testing utilities for V2Ray configurations
import socket
import time
from typing import Iterable, Optional
from src.models.config import Config
from src.utils.logger import setup_logger

logger = setup_logger(__name__)

def resolve_hostname(hostname: str, port_number: int) -> Iterable[tuple[int, tuple]]:
    """Resolve hostname to IP addresses for TCP connection attempts."""
    try:
        return [
            (address_family, address)
            for address_family, _, _, _, address in socket.getaddrinfo(
                hostname, port_number, type=socket.SOCK_STREAM
            )
        ]
    except socket.gaierror:
        return []

def measure_connection_latency(
    hostname: str, port_number: int, timeout_duration: float, max_attempts: int
) -> Optional[int]:
    """Measure TCP connection latency in milliseconds or return None if unreachable."""
    resolved_addresses = resolve_hostname(hostname, port_number)
    if not resolved_addresses:
        return None

    for _ in range(max_attempts + 1):
        for address_family, address in resolved_addresses:
            start_timestamp = time.perf_counter()
            try:
                with socket.socket(address_family, socket.SOCK_STREAM) as connection_socket:
                    connection_socket.settimeout(timeout_duration)
                    connection_socket.connect(address)
                end_timestamp = time.perf_counter()
                return int((end_timestamp - start_timestamp) * 1000)
            except (socket.timeout, OSError) as error:
                logger.debug("Connection attempt failed: %s", error)
                continue
    return None

class ConfigurationValidator:
    """Validates V2Ray configurations for network connectivity."""
    def __init__(self, timeout: float, attempts: int, latency_limit_ms: int) -> None:
        self.connection_timeout = timeout
        self.max_retries = attempts
        self.latency_threshold_ms = latency_limit_ms

    def validate(self, configuration: Config) -> Config:
        """Validate a single configuration and set latency if within threshold."""
        measured_latency = measure_connection_latency(
            configuration.host, configuration.port, 
            self.connection_timeout, self.max_retries
        )
        if measured_latency is not None and measured_latency < self.latency_threshold_ms:
            configuration.latency_ms = measured_latency
        return configuration

