# Round a positive number to the nearest odd integer
from math import ceil, floor
def nearest_odd_value(value: float):
    assert value > 0
    upper = ceil(value)
    lower = floor(value)
    if upper % 2 == 1:
        return upper
    elif lower % 2 == 1:
        return lower
    else:
        return round(value) + 1

# Custom joke validation checker implementation
from ucagent.checkers.base import Checker

class JokeValidator(Checker):
    def __init__(self, joke_filename, min_length, max_length, **options):
        self.joke_filename = joke_filename
        self.min_length = min_length
        self.max_length = max_length
        self.set_human_check_needed(options.get("requires_human_review", False))

    def perform_validation(self, timeout=0, **kwargs) -> tuple[bool, object]:
        """Validates the submitted joke based on content and length constraints."""
        joke_filepath = self.get_path(self.joke_filename)
        try:
            with open(joke_filepath, 'r', encoding='utf-8') as file:
                joke_text = file.read().strip()

            if "jimmy" not in joke_text.lower():
                return False, {"error": "The required name 'Jimmy' is missing from the joke."}

            if len(joke_text) < self.min_length:
                return False, {"error": f"Joke length ({len(joke_text)}) is below minimum allowed ({self.min_length})."}

            if len(joke_text) > self.max_length:
                return False, {"error": f"Joke length ({len(joke_text)}) exceeds maximum allowed ({self.max_length})."}

            return True, {"content": joke_text}
        except Exception as error:
            return False, {"error": str(error)}

