def pass_through(x):
    # Identity function: returns input unchanged
    return x

def merge_lora_weights(unet_model, vae_model=None, checkpoint_path=None, blend_factor=1.0, base_model_path=""):
    # Load LoRA weights and merge with base model
    if checkpoint_path is None:
        return unet_model

    # Load checkpoint based on file extension
    if checkpoint_path.endswith(".ckpt"):
        raw_state_dict = torch.load(checkpoint_path)['state_dict']
    elif checkpoint_path.endswith(".safetensors"):
        loaded_state_dict = {}
        with safe_open(checkpoint_path, framework="pt", device="cpu") as f:
            for tensor_key in f.keys():
                loaded_state_dict[tensor_key] = f.get_tensor(tensor_key)

        # Determine if it's a LoRA checkpoint
        is_lora_format = all("lora" in key for key in loaded_state_dict.keys())
        if not is_lora_format:
            raw_state_dict = loaded_state_dict
        else:
            # For LoRA, load base model to blend with
            raw_state_dict = {}
            with safe_open(base_model_path, framework="pt", device="cpu") as f:
                for base_key in f.keys():
                    raw_state_dict[base_key] = f.get_tensor(base_key)

    # Convert checkpoint to UNet format
    updated_unet_checkpoint = convert_ldm_unet_checkpoint(raw_state_dict, unet_model.config)
    current_unet_state = unet_model.state_dict()

    # Blend weights using interpolation factor
    for param_name in updated_unet_checkpoint:
        updated_unet_checkpoint[param_name] = blend_factor * updated_unet_checkpoint[param_name] + (1.0 - blend_factor) * current_unet_state[param_name]

    # Apply updated weights to UNet
    unet_model.load_state_dict(updated_unet_checkpoint, strict=False)

    # Handle VAE if provided
    if vae_model is not None:
        updated_vae_checkpoint = convert_ldm_vae_checkpoint(raw_state_dict, vae_model.config)
        vae_model.load_state_dict(updated_vae_checkpoint)

    return unet_model, vae_model

