class ColoredRelPathFormatter(logging.Formatter):
    # ANSI color codes for different log levels
    COLOR_MAP = {
        logging.CRITICAL: "\033[1;35m",  # bright/bold magenta
        logging.ERROR:    "\033[1;31m",  # bright/bold red
        logging.WARNING:  "\033[1;33m",  # bright/bold yellow
        logging.INFO:     "\033[0;37m",  # white / light gray
        logging.DEBUG:    "\033[1;30m",  # bright/bold dark gray
    }
    RESET_COLOR = "\033[0m"

    def __init__(self, use_color, *args, **kwargs):
        super(ColoredRelPathFormatter, self).__init__(*args, **kwargs)
        self.use_color = use_color
        base_dir = pathlib.Path(__file__).resolve()
        self.base_path = base_dir.parent.parent.parent

    def format(self, record, *args, **kwargs):
        if self.use_color and record.levelno in self.COLOR_MAP:
            record.color_start = self.COLOR_MAP[record.levelno]
            record.color_end = self.RESET_COLOR
        else:
            record.color_start = ""
            record.color_end = ""

        # Convert absolute path to relative path from project root
        record.pathname = os.path.relpath(record.pathname, self.base_path)
        return super(ColoredRelPathFormatter, self).format(record, *args, **kwargs)

@cache
def setup_logging(run_id=None, config_dict=None):
    """
    Set up logging system for the application.

    This function initializes all logger handlers and resets existing configurations.
    It uses a singleton pattern - only executes once per process.

    Parameters:
    run_id (str, optional): Unique identifier for the current run, used for output directory naming
    config_dict (dict, optional): Custom logging configuration dictionary. If None, uses default

    Note: When run_id is provided, log files are placed under ./output/{run_id}/
    """
    # Determine output directory based on run_id
    output_folder = ""
    if run_id is not None:
        output_folder = f"./output/{run_id}"

    # Load default configuration if none provided
    if config_dict is None:
        config_dict = json.loads(DEFAULT_LOGGING_CONFIG)

        # Remove file handlers when no run_id is specified
        if run_id is None:
            del config_dict["handlers"]["debug_file"]
            del config_dict["handlers"]["error_file"]
            del config_dict["root"]["handlers"][2:]

    # Process each handler configuration
    for handler_name, handler_config in config_dict["handlers"].items():
        for key, value in handler_config.items():
            if key == "formatter":
                handler_config[key] = value
            elif key == "filename":
                # Construct full path for log files
                filename = f"{output_folder}/{run_id}-{value}" if run_id else f"{output_folder}/{value}"
                log_file = pathlib.Path(filename)

                # Ensure absolute path using shared working directory if needed
                if not log_file.is_absolute():
                    private_config = _load_private_conf()
                    work_dir = pathlib.Path(private_config.get("path_shared_working_dir"))
                    log_file = work_dir / log_file

                # Create parent directories if they don't exist
                pathlib.Path(log_file.parent).mkdir(parents=True, exist_ok=True)
                handler_config[key] = log_file
            else:
                continue

    # Apply the logging configuration
    logging.config.dictConfig(config_dict)

    # Log setup confirmation
    if output_folder:
        logging.info(f"Logging initialized. Logs stored at {output_folder}")
    else:
        logging.info("Logging initialized. No log files created.")

