import numpy as np
import pytest

class UnitQuaternion:
    def __init__(self, w_val, x_val, y_val, z_val):
        self.w_component = w_val
        self.x_component = x_val
        self.y_component = y_val
        self.z_component = z_val

    @property
    def identity(self):
        return UnitQuaternion(1.0, 0.0, 0.0, 0.0)

    @property
    def i_basis(self):
        return UnitQuaternion(0.0, 1.0, 0.0, 0.0)

    @property
    def j_basis(self):
        return UnitQuaternion(0.0, 0.0, 1.0, 0.0)

    @property
    def k_basis(self):
        return UnitQuaternion(0.0, 0.0, 0.0, 1.0)

    def __rmul__(self, scalar):
        new_w = self.w_component * scalar
        new_x = self.x_component * scalar
        new_y = self.y_component * scalar
        new_z = self.z_component * scalar

        norm_value = np.sqrt(new_w**2 + new_x**2 + new_y**2 + new_z**2)
        if not np.isclose(norm_value, 1.0):
            raise ValueError("Scalar multiplication results in non-unit quaternion")

        return UnitQuaternion(new_w, new_x, new_y, new_z)

# Test suite for unit quaternions
def test_quaternion_identity_elements():
    assert np.allclose([UnitQuaternion.identity.w_component, 
                        UnitQuaternion.identity.x_component,
                        UnitQuaternion.identity.y_component,
                        UnitQuaternion.identity.z_component], 
                       [1.0, 0.0, 0.0, 0.0])

    assert np.allclose([UnitQuaternion.i_basis.w_component, 
                        UnitQuaternion.i_basis.x_component,
                        UnitQuaternion.i_basis.y_component,
                        UnitQuaternion.i_basis.z_component], 
                       [0.0, 1.0, 0.0, 0.0])

    assert np.allclose([UnitQuaternion.j_basis.w_component, 
                        UnitQuaternion.j_basis.x_component,
                        UnitQuaternion.j_basis.y_component,
                        UnitQuaternion.j_basis.z_component], 
                       [0.0, 0.0, 1.0, 0.0])

def test_scalar_product_validation():
    q_obj = UnitQuaternion(0.6, 0.8, 0.0, 0.0)  # Already normalized: sqrt(0.36+0.64)=1
    with pytest.raises(ValueError):
        _ = 1.5 * q_obj

