SPOTS_KEY = "spots"

class SpotStorage:
    def __init__(self, spot_data: np.ndarray):
        self._spot_data = spot_data

    @staticmethod
    def generate_spots() -> 'SpotStorage':
        initial_spots = np.array([[1, 2], [3, 4], [5, 6]])
        return SpotStorage(initial_spots)

    def persist_to_zarr(self, path: str) -> None:
        store = zarr.DirectoryStore(path)
        group = zarr.group(store=store)
        group[SPOTS_KEY] = self._spot_data

    @classmethod
    def retrieve_from_zarr(cls, path: str) -> 'SpotStorage':
        store = zarr.DirectoryStore(path)
        group = zarr.group(store=store)
        retrieved_data = group[SPOTS_KEY][:]
        return cls(retrieved_data)

    def matches(self, other: 'SpotStorage') -> bool:
        return np.array_equal(self._spot_data, other._spot_data)

def verify_io_operation() -> None:
    original_spots = SpotStorage.generate_spots()
    with TemporaryDirectory() as temp_dir:
        zarr_path = Path(temp_dir) / "data.zarr"
        original_spots.persist_to_zarr(str(zarr_path))

        # Load using the correct Zarr path (note: original code had incorrect suffix)
        loaded_spots = SpotStorage.retrieve_from_zarr(str(zarr_path))

        # Verify data integrity after round-trip
        assert loaded_spots.matches(original_spots)

