# Compute standard deviation and write to Excel cell

import math
import statistics
import openpyxl

def write_std_dev_to_excel(sheet, row, column, data):
    result = 0.0
    if len(data) > 0:
        # Filter out NaN values from the data list
        filtered_data = []
        for value in data:
            if not math.isnan(value):
                filtered_data.append(value)

        # Calculate standard deviation only if sufficient data points exist
        if len(filtered_data) > 1:
            try:
                result = statistics.stdev(filtered_data)
                # Ensure result is not NaN before assignment
                if math.isnan(result):
                    result = 0.0
            except Exception:
                result = 0.0

    # Write final value to specified cell
    sheet.cell(row=row, column=column).value = result

