def iteritems(d):
    """Return an iterator over (key, value) pairs for dictionary d."""
    try:
        # Python 2: use dict.iteritems()
        return d.iteritems()
    except AttributeError:
        # Python 3: items() returns a view which is iterable
        return iter(d.items())

