import traceback
from typing import Any, Dict, Tuple, Optional
from io import BytesIO

class MessageHandler:
    def __init__(self, storage_backend, logger):
        self.storage = storage_backend
        self.logger = logger

    def normalize_request_headers(self, raw_headers: Dict[str, str]) -> Dict[str, str]:
        # Normalize header keys to lowercase and process values
        normalized = {}
        for key, value in raw_headers.items():
            normalized[key.lower()] = value
        return normalized

    def handle_message(self, input_data: Dict[str, Any]) -> Tuple[Optional[Any], Dict[str, str], str, Dict[str, Any], str]:
        try:
            # Extract body variable name from message
            body_key_name = input_data.pop('bodyVariable', None)
            if body_key_name is not None:
                # Read body content using the storage backend
                raw_body = self.storage.fetch(request_key, body_key_name)
                if raw_body is not None:
                    # Convert bytes to BytesIO stream for API service (non-base64 encoded data)
                    body_stream = BytesIO(raw_body)
                else:
                    body_stream = None
            else:
                body_stream = None
        except Exception as error:
            self.logger.error(f'feature=api-service, event=body-read-failure, error="""{error}"""')
            self.logger.debug(traceback.format_exc())

        # Process remaining message components
        processed_headers = self.normalize_request_headers(input_data.pop('headers'))
        http_method = input_data.pop('method')
        query_parameters = input_data.pop('queryParams')
        request_path = input_data.pop('path')

        return body_stream, processed_headers, http_method, query_parameters, request_path

