import subprocess
import re

def get_repo_name(remote_url):
    try:
        # Execute git command to get the remote URL for 'origin'
        output = subprocess.run(
            ["git", "remote", "get-url", "origin"],
            capture_output=True,
            text=True,
            check=False
        )
        if output.returncode != 0:
            return None
        result = output.stdout.strip()
    except Exception:
        # Handle any exceptions during subprocess execution
        return None

    # Use regex to extract repository name from URL
    pattern = r".*[:/]([\w\d_\-]+\/[\w\d_\-]+)"
    match = re.search(pattern, result)

    if match:
        return match.group(1)
    return None

