# Generate a sorted list of integer values within a given domain

from sympy import Symbol, Interval, S
import sympy.sets.sets as sets

def generate_integer_values(symbolic_var_name, domain_str):
    # Create a symbolic variable with integer assumption
    var = Symbol(symbolic_var_name, integer=True)

    # Parse the domain string into a SymPy expression using the variable
    domain_expr = eval(domain_str, {symbolic_var_name: var})

    # Convert the domain expression to a finite set of integers
    if isinstance(domain_expr, Interval):
        # For interval domains, extract integer points within the bounds
        start = domain_expr.start
        end = domain_expr.end
        # Handle open/closed intervals appropriately
        if domain_expr.left_open:
            start_val = int(start) + 1 if float(start).is_integer() else int(start) + 1
        else:
            start_val = int(start) if float(start).is_integer() else int(start) + (start > int(start))

        if domain_expr.right_open:
            end_val = int(end) - 1 if float(end).is_integer() else int(end) - 1
        else:
            end_val = int(end) if float(end).is_integer() else int(end) - (end < int(end))

        # Generate all integers in the range
        interval_set = sets.FiniteSet(*range(start_val, end_val + 1))
    else:
        # For other types of sets, use the provided method
        interval_set = sets.FiniteSet(*list(Interval(*domain_expr.args)))

    # Return sorted list of unique integer elements
    return sorted(list(interval_set))

# Simulate subscription management logic using a dictionary-based approach

class SubscriptionManager:
    def __init__(self):
        # Store subscriptions: {user_id: {service_id: service_name}}
        self.subscriptions = {}

    def subscribe(self, user_id, service_id, service_name):
        if user_id not in self.subscriptions:
            self.subscriptions[user_id] = {}

        if service_id in self.subscriptions[user_id]:
            return "Already subscribed to this service."
        else:
            self.subscriptions[user_id][service_id] = service_name
            return "Subscribed successfully."

    def unsubscribe(self, user_id, service_id):
        if user_id not in self.subscriptions or service_id not in self.subscriptions[user_id]:
            return "Not subscribed to this service."
        else:
            del self.subscriptions[user_id][service_id]
            return "Unsubscribed successfully."

