# Check for deadlock using Banker's algorithm logic

def is_safe_state(process_allocations, process_max_requirements, available_resources):
    num_processes = len(process_allocations)
    num_resource_types = len(available_resources)

    # Create working copy of available resources
    current_available = list(available_resources)
    completed_processes = [False] * num_processes

    while True:
        progress_made = False

        for process_id in range(num_processes):
            if not completed_processes[process_id]:
                # Check if process requirements can be satisfied with current resources
                can_fulfill = True
                for resource_type in range(num_resource_types):
                    required = process_max_requirements[process_id][resource_type]
                    if required > current_available[resource_type]:
                        can_fulfill = False
                        break

                if can_fulfill:
                    # Simulate completing this process and releasing its resources
                    progress_made = True
                    completed_processes[process_id] = True

                    for resource_type in range(num_resource_types):
                        current_available[resource_type] += process_allocations[process_id][resource_type]

                    break

        if not progress_made:
            break

    return all(completed_processes)

