def find_homomorphisms(source_graph, target_graph, max_results, count_only, partial_mapping, depth_limit):
    from homsearch import HomsearchInterface, convert_to_adjacency_list, mapping_to_function_map

    # Ensure both graphs are undirected
    assert not source_graph.is_directed()
    assert not target_graph.is_directed()

    # Initialize the search interface with converted graph representations
    hs = HomsearchInterface(
        convert_to_adjacency_list(source_graph),
        convert_to_adjacency_list(target_graph),
        max_results,
        not count_only,
        False,
        max_depth=depth_limit
    )

    # Perform search either from scratch or using a partial mapping
    if partial_mapping is None:
        hs.search()
    else:
        hs.search_from(mapping_to_function_map(source_graph, target_graph, partial_mapping))

    # Return either count or actual mappings based on flag
    if count_only:
        return hs.get_count()
    else:
        return hs.get_mappings()

