# Apache Beam pipeline to filter adults and compute average age

import apache_beam as beam
from apache_beam.options.pipeline_options import PipelineOptions
import csv

class AdultFilter(beam.DoFn):
    def process(self, record):
        # Include only individuals aged 18 or older
        if int(record['age']) >= 18:
            yield record

class AgeStatsCombiner(beam.CombineFn):
    def create_accumulator(self):
        # Initialize with (total_age_sum, person_count)
        return (0, 0)

    def add_input(self, acc, item):
        # Add current record's age to sum and increment count
        total, count = acc
        return (total + int(item['age']), count + 1)

    def merge_accumulators(self, partials):
        # Combine multiple accumulators by summing totals and counts
        totals, counts = zip(*partials)
        return (sum(totals), sum(counts))

    def extract_output(self, final_acc):
        # Compute average if at least one person exists
        total, count = final_acc
        return total / count if count > 0 else 0

def execute_pipeline(source_path, dest_path):
    # Set up pipeline options
    opts = PipelineOptions()

    with beam.Pipeline(options=opts) as pipeline:
        # Read input file and skip header
        raw_lines = pipeline | 'LoadData' >> beam.io.ReadFromText(source_path, skip_header_lines=1)

        # Parse each line as CSV row into dictionary
        parsed_data = raw_lines | 'ConvertToDict' >> beam.Map(
            lambda line: next(csv.DictReader([line], fieldnames=['id', 'name', 'age']))
        )

        # Filter records to keep only adults
        adult_records = parsed_data | 'KeepAdults' >> beam.ParDo(AdultFilter())

        # Compute global average age of filtered records
        avg_age = adult_records | 'ComputeAvgAge' >> beam.CombineGlobally(AgeStatsCombiner())

        # Write result to output file
        avg_age | 'SaveResult' >> beam.io.WriteToText(dest_path)

if __name__ == '__main__':
    # Define input and output paths
    input_file = 'input.csv'
    output_file = 'output.csv'
    execute_pipeline(input_file, output_file)

# Find the nth node from the end of a linked list
def get_node_from_tail(linked_list_head, position):
    if linked_list_head is None or position <= 0:
        return None

    lead_pointer = linked_list_head
    follow_pointer = linked_list_head

    # Advance the lead pointer by 'position' nodes
    for _ in range(position):
        if lead_pointer is None:
            return None
        lead_pointer = lead_pointer.next

    # Move both pointers until lead reaches the end
    while lead_pointer is not None:
        follow_pointer = follow_pointer.next
        lead_pointer = lead_pointer.next

    return follow_pointer.value if follow_pointer is not None else None

