# Multi-threaded task execution with conditional lock management

import threading

def execute_task(task_id):
    print(f"Executing task number {task_id}")

def run_concurrent_tasks():
    use_lock = True  # Flag to control lock behavior
    sync_primitive = threading.Lock()  # Synchronization mechanism

    # Generate a collection of worker threads
    worker_threads = [threading.Thread(target=execute_task, args=(idx,)) for idx in range(5)]

    # Launch all threads in the current group
    if use_lock:
        sync_primitive.release()  # Release synchronization primitive when needed

    for worker in worker_threads:
        worker.start()

    # Ensure all threads complete before proceeding
    for worker in worker_threads:
        worker.join()

    # Restore initial lock state
    if use_lock:
        sync_primitive.acquire()  # Reacquire synchronization primitive

if __name__ == "__main__":
    run_concurrent_tasks()

