def extract_license_info(license_text: str) -> dict:
    result = {"license_type": "", "permissions": [], "limitations": []}
    lines = license_text.split('\n')

    # Find the first non-comment line to determine license type
    for line in lines:
        cleaned_line = line.strip()
        if cleaned_line and not cleaned_line.startswith('#'):
            result["license_type"] = cleaned_line
            break

    # Process permissions and limitations sections
    collecting_permissions = False
    collecting_limitations = False

    for line in lines:
        current_line = line.strip()

        # Detect start of permissions section
        if "WITHOUT WARRANTIES OR CONDITIONS OF ANY" in line:
            collecting_permissions = True
            continue

        # Detect start of limitations section
        if "limitations" in line.lower():
            collecting_permissions = False
            collecting_limitations = True
            continue

        # Collect permissions entries
        if collecting_permissions and current_line and not current_line.startswith('#'):
            result["permissions"].append(current_line)

        # Collect limitations entries
        if collecting_limitations and current_line and not current_line.startswith('#'):
            result["limitations"].append(current_line)

    return result

