# Alternative implementation for dictionary comparison with OrderedDict support

def compare_nested_dicts(d1, d2):
    # Get all unique keys from both dictionaries
    all_keys = set(d1.keys()).union(set(d2.keys()))

    for key in all_keys:
        val1 = d1.get(key)
        val2 = d2.get(key)

        # If both values are dictionaries, compare them using OrderedDict
        if isinstance(val1, dict) and isinstance(val2, dict):
            if not (OrderedDict(val1) == OrderedDict(val2)):
                return False
        # Otherwise, directly compare the values
        elif val1 != val2:
            return False

    return True

# Test case
def test_compare_nested_dicts():
    # Test case 1: Identical nested dictionaries
    dict1 = {
        'a': {'x': 1, 'y': 2},
        'b': {'z': 3}
    }
    dict2 = {
        'a': {'x': 1, 'y': 2},
        'b': {'z': 3}
    }
    assert compare_nested_dicts(dict1, dict2) == True

    # Test case 2: Nested dictionaries with same content but different key order
    dict3 = {
        'a': {'x': 1, 'y': 2},
        'b': {'z': 3}
    }
    dict4 = {
        'a': {'y': 2, 'x': 1},
        'b': {'z': 3}
    }
    # OrderedDict preserves insertion order, so different key order makes them unequal
    assert compare_nested_dicts(dict3, dict4) == False

    # Test case 3: Different values in nested dictionary
    dict5 = {
        'a': {'x': 1, 'y': 2},
        'b': {'z': 3}
    }
    dict6 = {
        'a': {'x': 1, 'y': 2},
        'b': {'z': 4}
    }
    assert compare_nested_dicts(dict5, dict6) == False

test_compare_nested_dicts()

