        self._bound_protocol = None

    def bind_protocol(self, protocol: IJSONResource) -> None:
        self._bound_protocol = protocol

    def check_integrity(self, incoming_data: dict) -> bool:
        if self._bound_protocol is None:
            raise ValueError("No protocol has been bound for integrity verification")

        signature_in_request = incoming_data.get('signature', None)
        if signature_in_request is None:
            raise ValueError("Signature missing in the incoming request")

        expected_signature = self._bound_protocol.produce_signature()
        return signature_in_request == expected_signature

# Validate bracket pairing and nesting in a string

def multi_bracket_validation(input_string):
    stack = []
    opening_chars = {'(', '{', '['}
    closing_to_opening = {')': '(', '}': '{', ']': '['}

    for symbol in input_string:
        if symbol in opening_chars:
            stack.append(symbol)
        elif symbol in closing_to_opening:
            if len(stack) == 0 or stack.pop() != closing_to_opening[symbol]:
                return False

    return len(stack) == 0  # True only if all brackets are matched

# Alternative implementation using built-in list operations
class CustomList:
    def __init__(self):
        self.elements = []

    def insert_front(self, value):
        # Insert at the beginning to simulate stack-like behavior
        self.elements.insert(0, value)

    def delete_value(self, target):
        # Remove first occurrence of target
        if target in self.elements:
            self.elements.remove(target)

    def __str__(self):
        # Format as arrow-separated string
        return " -> ".join(map(str, self.elements))

