import discord
from discord.ext import commands
import asyncio

class TimeoutSettings:
    def __init__(self, length: int = 0, note: str = ''):
        self.length = length
        self.note = note

async def apply_voice_timeout(
    context: commands.Context,
    targets: commands.Greedy[discord.Member],
    *,
    duration_and_note: TimeoutSettings = {},
):
    for target in targets:
        if context.author.guild_permissions.mute_members:
            if target.voice and target.voice.channel:
                if duration_and_note.length > 0:
                    await target.edit(mute=True, reason=duration_and_note.note)
                    await context.send(f'{target.display_name} has been muted for {duration_and_note.length} minutes.')
                    await asyncio.sleep(duration_and_note.length * 60)
                    await target.edit(mute=False, reason='Timeout period ended')
                    await context.send(f'{target.display_name} has been unmuted.')
                else:
                    await target.edit(mute=True, reason=duration_and_note.note)
                    await context.send(f'{target.display_name} has been permanently muted.')
            else:
                await context.send(f'{target.display_name} is not connected to a voice channel.')
        else:
            await context.send('You lack the required permissions to mute other members.')

import boto3
from pathlib import Path
import secrets as secret_generator

class AWSSecretManager:
    def __init__(self, parameter_store_prefix):
        self.parameter_store_prefix = parameter_store_prefix

    def retrieve_secrets(self):
        if self.parameter_store_prefix is None:
            return secret_generator.token_hex(16)  # fallback placeholder

        param_path = Path(self.parameter_store_prefix)
        ssm_client = boto3.client('ssm')

        parameters = []
        next_token = None

        # Handle pagination for large result sets
        while True:
            if next_token:
                response = ssm_client.get_parameters_by_path(
                    Path=param_path,
                    Recursive=True,
                    WithDecryption=True,
                    NextToken=next_token
                )
            else:
                response = ssm_client.get_parameters_by_path(
                    Path=param_path,
                    Recursive=True,
                    WithDecryption=True
                )

            parameters.extend(response['Parameters'])

            if 'NextToken' not in response:
                break
            next_token = response['NextToken']

        secret_map = {}
        for item in parameters:
            key_name = item['Name'].split('/')[-1]
            value = item['Value']
            secret_map[key_name] = value

        return secret_map

