from typing import List, Set

class ScoreTracker:
    def __init__(self):
        self.recorded_scores = [None for _ in range(6)]  # Track 6 scoring categories

    def check_triple(self, rolls: List[int]) -> int:
        """Check for three of a kind and return sum if found"""
        if self.recorded_scores[0] is None:
            unique_values = set(rolls)
            result = 0
            for val in unique_values:
                if rolls.count(val) >= 3:
                    result = sum(rolls)
                    break
            self.recorded_scores[0] = result
        return self.recorded_scores[0]

    def check_quadruple(self, rolls: List[int]) -> int:
        """Check for four of a kind and return sum if found"""
        if self.recorded_scores[1] is None:
            unique_values = set(rolls)
            result = 0
            for val in unique_values:
                if rolls.count(val) >= 4:
                    result = sum(rolls)
                    break
            self.recorded_scores[1] = result
        return self.recorded_scores[1]

    def check_full_house(self, rolls: List[int]) -> int:
        """Check for full house (3 of one, 2 of another)"""
        if self.recorded_scores[2] is None:
            frequency_map = {}
            for die in rolls:
                frequency_map[die] = frequency_map.get(die, 0) + 1

            counts = list(frequency_map.values())
            has_three = 3 in counts
            has_two = 2 in counts
            self.recorded_scores[2] = 25 if (has_three and has_two) or len(counts) == 1 else 0
        return self.recorded_scores[2]

    def check_small_run(self, rolls: List[int]) -> int:
        """Check for small straight (4 consecutive dice)"""
        if self.recorded_scores[3] is None:
            distinct = sorted(list(set(rolls)))
            consecutive_count = 1
            max_consecutive = 1

            for i in range(1, len(distinct)):
                if distinct[i] == distinct[i-1] + 1:
                    consecutive_count += 1
                    max_consecutive = max(max_consecutive, consecutive_count)
                else:
                    consecutive_count = 1

            self.recorded_scores[3] = 30 if max_consecutive >= 4 else 0
        return self.recorded_scores[3]

    def check_large_run(self, rolls: List[int]) -> int:
        """Check for large straight (5 consecutive dice)"""
        if self.recorded_scores[4] is None:
            distinct = sorted(list(set(rolls)))
            consecutive_count = 1
            max_consecutive = 1

            for i in range(1, len(distinct)):
                if distinct[i] == distinct[i-1] + 1:
                    consecutive_count += 1
                    max_consecutive = max(max_consecutive, consecutive_count)
                else:
                    consecutive_count = 1

            self.recorded_scores[4] = 40 if max_consecutive == 5 else 0
        return self.recorded_scores[4]

    def calculate_chance(self, rolls: List[int]) -> int:
        """Calculate sum of all dice"""
        if self.recorded_scores[5] is None:
            self.recorded_scores[5] = sum(rolls)
        return self.recorded_scores[5]

    def get_total(self) -> int:
        """Calculate total of all scored categories"""
        return sum(score for score in self.recorded_scores if score is not None)

