import boto3
from boto3.dynamodb import types as dynamodb_types

class TableManager:
    def __init__(self, aws_region):
        self.client = boto3.client('dynamodb', region_name=aws_region)
        self.resource = boto3.resource('dynamodb', region_name=aws_region)

    def establish_table(self, table_identifier, key_field, key_data_type):
        # Create table with standard capacity settings
        response = self.client.create_table(
            TableName=table_identifier,
            KeySchema=[
                {
                    'AttributeName': key_field,
                    'KeyType': 'HASH'
                }
            ],
            AttributeDefinitions=[
                {
                    'AttributeName': key_field,
                    'AttributeType': key_data_type
                }
            ],
            BillingMode='PROVISIONED',
            ProvisionedThroughput={
                'ReadCapacityUnits': 5,
                'WriteCapacityUnits': 5
            }
        )

        # Wait for table to become active
        waiter = self.client.get_waiter('table_exists')
        waiter.wait(TableName=table_identifier)

        return response

