import re

def check_package_info(data):
    # Define the list of mandatory keys
    mandatory_keys = ['name', 'version', 'packages', 'url', 'license', 'author']

    # Ensure all required keys exist in the input dictionary
    for key in mandatory_keys:
        if key not in data:
            return False

    # Validate package name
    name = data['name']
    if not isinstance(name, str) or len(name) == 0:
        return False

    # Validate version string format (e.g., "1.2.3")
    version = data['version']
    if not isinstance(version, str):
        return False
    version_regex = re.compile(r'^[0-9]+\.[0-9]+\.[0-9]+$')
    if not version_regex.match(version):
        return False

    # Validate packages list
    packages = data['packages']
    if not isinstance(packages, list):
        return False
    for pkg in packages:
        if not isinstance(pkg, str):
            return False

    # Validate URL format
    url = data['url']
    if not isinstance(url, str):
        return False
    url_regex = re.compile(r'^(https?://)[a-zA-Z0-9\-._~:/?#\[\]@!$&\'()*+,;=]+$')
    if not url_regex.match(url):
        return False

    # Validate license field
    license_val = data['license']
    if not isinstance(license_val, str) or len(license_val) == 0:
        return False

    # Validate author field
    author = data['author']
    if not isinstance(author, str) or len(author) == 0:
        return False

    return True

class Attachment:
    def __init__(self, content_type):
        self._content_type = None
        self.content_type = content_type

    @property
    def content_type(self):
        return self._content_type

    @content_type.setter
    def content_type(self, value):
        """Validates and sets the content type for this Attachment.

        Args:
            value: The content type string to set (e.g., 'text/plain')

        Raises:
            ValueError: If the content type is not a valid string format
        """
        if not isinstance(value, str):
            raise TypeError("Content type must be a string")

        # Validate content type format
        parts = value.split('/')
        if len(parts) != 2 or any(not part.strip() for part in parts):
            raise ValueError("Invalid content type format. Expected 'type/subtype'")

        self._content_type = value.strip()

