# Calculate the score based on move types in a game

from typing import List, Tuple
from enforce_typing import enforce_types

# Define scoring constants
draw_score: int = 0
loss_penalty: int = -25
illegal_action: int = -1
valid_action: int = 1
capture_action: int = 5
royal_action: int = 5

@enforce_types
def vector_difference(pos1: Tuple[int, int], pos2: Tuple[int, int]) -> Tuple[int, int]:
    """Calculate the difference between two coordinate pairs."""
    return (pos1[0] - pos2[0], pos1[1] - pos2[1])

@enforce_types
def vector_sum(pos1: Tuple[int, int], pos2: Tuple[int, int]) -> Tuple[int, int]:
    """Calculate the sum of two coordinate pairs."""
    return (pos1[0] + pos2[0], pos1[1] + pos2[1])

@enforce_types
def evaluate_moves(action_sequence: List[Tuple[Tuple[int, int], Tuple[int, int]]]) -> int:
    """Evaluate a sequence of moves and calculate total score."""
    total_points = 0

    for action in action_sequence:
        origin, destination = action
        displacement = vector_difference(destination, origin)

        # Check for diagonal movement patterns
        if displacement in [(1, 1), (-1, -1), (1, -1), (-1, 1)]:
            total_points += valid_action
        elif displacement in [(2, 2), (-2, -2), (2, -2), (-2, 2)]:
            total_points += capture_action
        elif displacement in [(3, 3), (-3, -3), (3, -3), (-3, 3)]:
            total_points += royal_action
        else:
            total_points += illegal_action

    return total_points

