# Custom decorators for method behavior modification

def enable_chaining(decorated_func):
    """
    Decorator that allows method calls to be chained by returning the instance.
    """
    def enhanced_wrapper(instance, *arguments, **keyword_args):
        decorated_func(instance, *arguments, **keyword_args)
        return instance
    return enhanced_wrapper


def schedule_execution(func):
    """
    Decorator that schedules a method's execution for later (deferred).
    """
    def delayed_wrapper(instance, *args, **kwargs):
        def execute_later():
            func(instance, *args, **kwargs)
        setattr(instance, f"schedule_{func.__name__}", execute_later)
    return delayed_wrapper


def constant_output(constant):
    """
    Decorator that ignores original function and returns a fixed value.
    """
    def apply_decorator(original_func):
        def override_wrapper(instance, *args, **kwargs):
            return constant
        return override_wrapper
    return apply_decorator


def prevent_invocation(func):
    """
    Decorator that raises an error when the method is invoked.
    """
    def blocked_wrapper(instance, *args, **kwargs):
        raise RuntimeError(f"Function {func.__name__} has been disabled")
    return blocked_wrapper


