def add_nodes_and_edges_to_graph(graph, node, universe):
    """
    :param pybel.BELGraph graph: The graph to add stuff to
    :param node: A BEL node
    """
    processed_predecessors = set()

    # First pass: add predecessor nodes that aren't already in the graph
    for pred in universe.predecessors(node):
        if pred not in graph:
            graph.add_node_from_data(pred)
        else:
            processed_predecessors.add(pred)

    # Second pass: add edges from predecessors that weren't previously processed
    edges_to_add = []
    for pred in universe.predecessors(node):
        if pred not in processed_predecessors:
            for key, data in universe.get_edge_data(pred, node).items():
                edges_to_add.append((pred, node, key, data))

    graph.add_edges_from(edges_to_add)

