import json

class Stream:
    @staticmethod
    def parse_error_channel(error_message: bytes) -> dict:
        try:
            # Extract the length of the JSON payload from the first byte
            payload_length = error_message[0]

            # Ensure we have enough bytes to extract the JSON payload
            if len(error_message) < 1 + payload_length:
                raise IndexError("Insufficient data for JSON payload")

            # Extract and decode the JSON payload
            json_bytes = error_message[1:1 + payload_length]
            parsed_data = json.loads(json_bytes.decode('utf-8'))

            return parsed_data
        except (ValueError, IndexError, json.JSONDecodeError, UnicodeDecodeError):
            return {"exit_code": 1}

