import sys

def transform_file(input_path, output_path, password):
    try:
        with open(input_path, 'rb') as in_file, open(output_path, 'wb') as out_file:
            pwd_bytes = password.encode('utf-8')
            pwd_len = len(pwd_bytes)
            pos = 0
            while True:
                chunk = in_file.read(1)
                if not chunk:
                    break
                transformed_byte = bytes([chunk[0] ^ pwd_bytes[pos]])
                out_file.write(transformed_byte)
                pos = (pos + 1) % pwd_len
    except FileNotFoundError:
        print("Input file missing!")
        sys.exit(2)

def reverse_file(input_path, output_path, password):
    transform_file(input_path, output_path, password)  # Reversal uses identical process

def main():
    if len(sys.argv) < 4:
        print("Syntax: cryptolocker.py <INPUT_FILE> <OUTPUT_FILE> <PASSWORD>")
