# Function to detect duplicate keys in a dictionary

def validate_unique_keys(data):
    """
    Validates that all keys in the provided dictionary are unique.

    Args:
        data: Dictionary to be validated for key uniqueness

    Raises:
        ValueError: If any duplicate keys exist, listing all duplicated keys
    """
    seen_keys = set()
    duplicate_keys = []

    for key in data.keys():
        if key in seen_keys:
            if key not in duplicate_keys:
                duplicate_keys.append(key)
        else:
            seen_keys.add(key)

    if duplicate_keys:
        raise ValueError(
            'The document contains duplicate keys: {}'
            .format(','.join(duplicate_keys))
