class SecureConfigParser(ConfigParser):
    def __init__(self, *args, **kwargs):
        encryption_key = kwargs.pop('encryption_password', None)
        if encryption_key is not None:
            self._secret_key = encryption_key
        else:
            self._secret_key = None
        ConfigParser.__init__(self, *args, **kwargs)

    def get(self, section, option, *args, **kwargs):
        raw_value = ConfigParser.get(self, section, option, *args, **kwargs)

        if self._secret_key is not None and raw_value.startswith('SECURED:'):
            encoded_content = base64.b64decode(raw_value[len('SECURED:'):])
            salt_material = encoded_content[:16]
            encrypted_payload = encoded_content[16:]

            derived_key = PBKDF2(self._secret_key, salt_material, dkLen=32)
            decryption_cipher = AES.new(derived_key, AES.MODE_GCM, nonce=encrypted_payload[:16])

            decrypted_data = decryption_cipher.decrypt_and_verify(
                encrypted_payload[16:], 
                encrypted_payload[16:]
            )
            return decrypted_data.decode('utf-8')
        else:
            return raw_value

