            # Find the end of the comment block
            while j < len(code) - 1:
                if code[j:j+2] == '*/':
                    comment_blocks.append(code[start:j])
                    i = j + 2
                    break
                j += 1
            else:
                # No closing found, take until end
                comment_blocks.append(code[start:])
                break
        else:
            i += 1

    # Clean up each comment block
    cleaned_comments = []
    for comment in comment_blocks:
        # Remove leading asterisks and spaces from each line
        lines = comment.split('\n')
        cleaned_lines = []
        for line in lines:
            # Remove leading whitespace and asterisks
            stripped = line.lstrip()
            if stripped.startswith('*'):
                stripped = stripped[1:].lstrip()
            cleaned_lines.append(stripped)

        # Join and clean up
        cleaned_comment = '\n'.join(cleaned_lines).strip()
        if cleaned_comment:
            cleaned_comments.append(cleaned_comment)

    return cleaned_comments

