# Ansible module to manage Foreman locations (Type III clone)
from ansible.module_utils.basic import AnsibleModule
import requests

def execute_module():
    # Define module arguments
    module_args = dict(
        location_name=dict(type='str', required=True),
        extra_attrs=dict(type='dict', required=False, default={}),
        desired_state=dict(type='str', required=False, default='present', 
                          choices=['present', 'absent'])
    )

    module = AnsibleModule(
        argument_spec=module_args,
        supports_check_mode=False
    )

    # Configuration for Foreman API
    api_endpoint = 'https://foreman.example.com/api/v2/locations'
    request_headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    }
    credentials = ('username', 'password')  # Replace with real Foreman credentials

    # Extract parameters from module
    loc_name = module.params['location_name']
    additional_attrs = module.params['extra_attrs']
    target_state = module.params['desired_state']

    if target_state == 'present':
        # Create or update location
        payload = {'name': loc_name}
        payload.update(additional_attrs)

        response = requests.post(
            api_endpoint, 
            json=payload, 
            auth=credentials, 
            headers=request_headers
        )

    elif target_state == 'absent':
        # Find location ID and delete if exists
        found_id = locate_location(loc_name, credentials, request_headers)

        if found_id is not None:
            delete_url = f'{api_endpoint}/{found_id}'
            response = requests.delete(
                delete_url, 
                auth=credentials, 
                headers=request_headers
            )
        else:
            module.exit_json(
                changed=False, 
                msg=f"Location '{loc_name}' does not exist, no changes needed."
            )

    # Handle response based on status code
    if response.status_code in [200, 201]:
        module.exit_json(
            changed=True, 
            msg=f"Location '{loc_name}' {target_state}ed successfully."
        )
    else:
        module.fail_json(
            msg=f"Operation failed for location '{loc_name}'. Details: {response.text}"
        )

def locate_location(name, auth, headers):
    base_api = 'https://foreman.example.com/api/v2/locations'
    response = requests.get(base_api, auth=auth, headers=headers)

    if response.status_code != 200:
        return None

    locations_list = response.json().get('results', [])

    for location in locations_list:
        if location.get('name') == name:
            return location.get('id')

    return None

if __name__ == '__main__':
    execute_module()

