# Generate a date query for database filtering

from datetime import datetime

def create_date_filter(start: str = None, finish: str = None, specific_date: str = None) -> dict:
    if start and finish:
        # Parse and validate date range
        begin_date = datetime.strptime(start, "%d/%m/%Y")
        conclude_date = datetime.strptime(finish, "%d/%m/%Y")
        assert (begin_date < conclude_date), "Start date must be earlier than end date."
        return {POST_PUB_DATE: {
            "$gte": begin_date,
            "$lt": conclude_date
        }}
    elif specific_date:
        # Handle single date filter
        target_date = datetime.strptime(specific_date, "%d/%m/%Y")
        return {POST_PUB_DATE: target_date}
    else:
        raise ValueError("You must specify either a date range (start and finish) or a specific date.")

import base64

class AuthenticationException(Exception):
    pass

class SimpleAuthValidator:
    def validate(self, request_headers):
        auth_header = request_headers.get('HTTP_AUTHORIZATION')

        if not auth_header:
            raise AuthenticationException("Invalid credentials in HTTP_AUTHORIZATION header")

        parts = auth_header.split()
        if len(parts) != 2 or parts[0] != 'Basic':
            raise AuthenticationException("Invalid credentials in HTTP_AUTHORIZATION header")

        encoded_data = parts[1]
        try:
            decoded_bytes = base64.b64decode(encoded_data)
            decoded_str = decoded_bytes.decode('utf-8')
            return decoded_str
        except (ValueError, UnicodeDecodeError):
            raise AuthenticationException("Invalid credentials in HTTP_AUTHORIZATION header")

# Verification tests
