# Test scenario 1: No HTTP_AUTHORIZATION header present
try:
    validator.validate({})
except AuthenticationException as error:
    assert str(error) == "Invalid credentials in HTTP_AUTHORIZATION header"

# Test scenario 2: Empty HTTP_AUTHORIZATION header value
try:
    validator.validate({'HTTP_AUTHORIZATION': ''})
except AuthenticationException as error:
    assert str(error) == "Invalid credentials in HTTP_AUTHORIZATION header"

# Test scenario 3: Improperly formatted base64 data in header
try:
    validator.validate({'HTTP_AUTHORIZATION': 'Basic \x000'})
except AuthenticationException as error:
    assert str(error) == "Invalid credentials in HTTP_AUTHORIZATION header"

