import copy
from typing import MutableMapping, List
import types

def validate_output_artifacts(output_artifacts, executor_output):
    # Make a deep copy of output_artifacts if it exists, otherwise initialize as empty dict
    validated_artifacts = copy.deepcopy(output_artifacts) if output_artifacts is not None else {}
    validated_artifacts = cast(MutableMapping[str, List[types.Artifact]], validated_artifacts)

    # Proceed only if executor_output is provided
    if executor_output:
        # Check that all keys in executor_output's artifacts are present in our validated artifacts
        if not set(executor_output.output_artifacts.keys()).issubset(validated_artifacts.keys()):
            raise RuntimeError('Executor output contains more keys than output skeleton.')

        # Iterate through each artifact list in the validated artifacts
        for artifact_key, artifact_list in validated_artifacts.items():
            # Skip processing if this key is missing from executor output
            if artifact_key not in executor_output.output_artifacts:
                continue

import numpy as np
from scipy.spatial import cKDTree

class NearestNeighborData(LowResHighResDataset):
    def __init__(self, dataset: LowResHighResDataset, num_models=None, model_index=None, k=16):
        super().__init__(dataset.low_res_data, dataset.high_res_data, dataset.region_geometries)
        self.num_models = num_models if num_models is not None else len(dataset)
        self.model_index = model_index
        self.k = k
        self.high_res_kdtree = self._construct_high_res_kdtree()

    def _construct_high_res_kdtree(self):
        # Select high-resolution data points based on model_index
        if self.model_index is None:
            points = self.high_res_data
        else:
            points = self.high_res_data[self.model_index]
        return cKDTree(points)

    def find_closest_neighbors(self, low_res_point):
        # Prepare input point for query if needed
        if self.model_index is not None:
            low_res_point = np.atleast_2d(low_res_point)

        # Query the KD-tree for nearest neighbors
        distances, neighbor_indices = self.high_res_kdtree.query(low_res_point, k=self.k)

        # Adjust output format when single point is queried
        if self.model_index is not None:
            neighbor_indices = neighbor_indices[0]

        # Return corresponding high-resolution data points
        return self.high_res_data[neighbor_indices]

