    if start_with is not None and end_with is not None:
        def matches_conditions(filename):
            return filename.startswith(start_with) and filename.endswith(end_with)
    elif start_with is not None:
        def matches_conditions(filename):
            return filename.startswith(start_with)
    elif end_with is not None:
        def matches_conditions(filename):
            return filename.endswith(end_with)
    else:
        def matches_conditions(filename):
            return True

