class PowerState(Enum):
    active = 1
    inactive = 0

class Settings:
    def __init__(self, name: str, identifier: str, payload: str, state: PowerState):
        self.name = name
        self.identifier = identifier
        self.payload = payload
        self.state = state

def check_settings(config: Settings) -> List[str]:
    issues = []

    # Check label/name field
    if not config.name or len(config.name) > 200:
        issues.append("Name must not be empty and should not exceed 200 characters.")

    # Check key/identifier field
    if not config.identifier or len(config.identifier) > 20:
        issues.append("Identifier must not be empty and should not exceed 20 characters.")

    # Validate JSON payload
    try:
        json.loads(config.payload)
    except json.JSONDecodeError:
        issues.append("Payload must be a valid JSON object.")

    # Verify power state is valid
    if config.state not in [PowerState.active, PowerState.inactive]:
        issues.append("State must be a valid enumeration value.")

    return issues

