import json
import sys
from pathlib import Path

def extract_repo_description(repo_dir):
    """Attempt to retrieve a brief description from README files."""
    readme_candidates = ["README.md", "README.MD", "readme.md", "README", "README.txt"]

    for readme_name in readme_candidates:
        readme_file = repo_dir / readme_name
        if readme_file.is_file():
            try:
                with open(readme_file, 'r', encoding='utf-8') as f:
                    text = f.read()
                    # Split into non-empty lines
                    lines = [line.strip() for line in text.splitlines() if line.strip()]

                    if not lines:
                        continue

                    # Look for first non-header line
                    for line in lines:
                        if not line.startswith('#'):
                            return line[:200]

                    # Otherwise take the first header line and strip '#'
                    first_line = lines[0].lstrip('#').strip()
                    return first_line[:200]
            except Exception:
                continue

    return "No description available"

def list_github_repos(base_dir):
    """Traverse directory and collect GitHub repository metadata."""
    base_path = Path(base_dir)

    if not base_path.exists():
        return {"error": "Specified path does not exist", "directory": str(base_path)}

    repositories = []

    for entry in base_path.iterdir():
        # Skip hidden directories and non-directories
        if entry.is_dir() and not entry.name.startswith('.'):
            # Check for .git subdirectory to confirm it's a repo
            git_dir = entry / ".git"
            if git_dir.exists():
                repositories.append({
                    "name": entry.name,
                    "location": str(entry),
                    "description": extract_repo_description(entry)
                })

    return {
        "repositories": repositories,
        "base_directory": str(base_path)
    }

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: scan_repos.py <github_directory>")
        sys.exit(1)

    output = list_github_repos(sys.argv[1])
    print(json.dumps(output, indent=2, ensure_ascii=False))

