import torch
import torch.nn as nn
from cosmos_rl.utils.logging import logger
from transformers.activations import ACT2CLS

class FusedActivationMultiplication(nn.Module):
    def __init__(self, custom_op: torch.autograd.Function):
        super().__init__()
        self.custom_op = custom_op

    def forward(self, input_a: torch.Tensor, input_b: torch.Tensor) -> torch.Tensor:
        return self.custom_op.apply(input_a, input_b)

class ActivationMultiplicationLayer(nn.Module):
    def __init__(self, activation_module: nn.Module):
        super().__init__()
        self.activation_module = activation_module

    def forward(self, tensor_x: torch.Tensor, tensor_y: torch.Tensor) -> torch.Tensor:
        return self.activation_module(tensor_x) * tensor_y

    def to_liger_implementation(self):
        # Check if the activation function matches SiLU
        if isinstance(self.activation_module, ACT2CLS["silu"]):
            from liger_kernel.ops.swiglu import LigerSiLUMulFunction
            return FusedActivationMultiplication(LigerSiLUMulFunction)

        # Check if the activation function matches GELU
        elif isinstance(self.activation_module, ACT2CLS["gelu"]):
            from liger_kernel.ops.geglu import LigerGELUMulFunction
            return FusedActivationMultiplication(LigerGELUMulFunction)

        # Fallback for unsupported activation functions
        else:
            logger.warning(
