import base64
import re
import time
from io import BytesIO
from cosmos_rl_reward.handler.reward_base import BaseRewardHandler
from cosmos_rl_reward.handler.registry import RewardRegistry
from cosmos_rl_reward.utils.logging import logger

@RewardRegistry.register()
class UnifiedReward(BaseRewardHandler):
    NEEDS_LATENT_DECODER = False
    reward_name = "unified_reward"

    def __init__(self, endpoint_url="", endpoint_api_key="", **kwargs):
        super().__init__()
        self.api_endpoint = endpoint_url
        self.api_token = endpoint_api_key

    def setup(self):
        from openai import OpenAI
        self.llm_client = OpenAI(api_key=self.api_token, base_url=self.api_endpoint)

    def encode_image_to_base64(self, img):
        buffer = BytesIO()
        img.save(buffer, format="PNG")
        raw_bytes = buffer.getvalue()
        encoded = base64.b64encode(raw_bytes).decode("utf-8")
        return f"data:image/png;base64,{encoded}"

    def parse_scores_from_response(self, responses):
        extracted = []
        score_pattern = r"Final Score:\s*([1-5](?:\.\d+)?)"
        for resp_text in responses:
            found = re.search(score_pattern, resp_text)
            if found:
                try:
                    val = float(found.group(1))
                    extracted.append(val)
                except ValueError:
                    extracted.append(0.0)
            else:
                extracted.append(0.0)
        return extracted

    def assess_single_image(self, caption, image_obj):
        prompt_template = (
            "<image>\n"
            "You are given a text caption and a generated image based on that caption. "
            "Your task is to evaluate this image based on two key criteria:\n"
            "1. Alignment with the Caption: Assess how well this image aligns with the provided caption. "
            "Consider the accuracy of depicted objects, their relationships, and attributes as described in the caption.\n"
            "2. Overall Image Quality: Examine the visual quality of this image, including clarity, detail preservation, "
            "color accuracy, and overall aesthetic appeal.\n"
            "Based on the above criteria, assign a score from 1 to 5 after 'Final Score:'.\n"
            "Your task is provided as follows:\n"
            f"Text Caption: [{caption}]"
        )
        encoded_img = self.encode_image_to_base64(image_obj)
        completion = self.llm_client.chat.completions.create(
            model="UnifiedReward-7b-v1.5",
            messages=[
                {
                    "role": "user",
                    "content": [
                        {"type": "image_url", "image_url": {"url": encoded_img}},
                        {"type": "text", "text": prompt_template},
                    ],
                }
            ],
            temperature=0.0,
            stream=False,
        )
        return completion.choices[0].message.content

    def batch_assess_images(self, images_list, captions_list):
        outputs = []
        for cap, img in zip(captions_list, images_list):
            outputs.append(self.assess_single_image(cap, img))
        return outputs

    def compute_reward(self, image_batch, meta_info):
        import torch
        from PIL import Image

        def _fail_with(msg: str):
            logger.error(msg)
            return {
                "error": msg,
                "scores": None,
                "input_info": meta_info.get("input_info", {}),
                "duration": "0.00",
                "decoded_duration": meta_info.get("decode_duration", "N/A"),
                "type": self.reward_name,
            }

        start_time = time.perf_counter()

        # Validate inputs
        if image_batch is None:
            return _fail_with("[unified_reward] image tensor is missing.")
        if not isinstance(image_batch, torch.Tensor) or image_batch.ndim != 4:
            return _fail_with(
                f"[unified_reward] expects 4D torch.Tensor in BHWC/NHWC layout; got type={type(image_batch)}, "
                f"shape={getattr(image_batch, 'shape', None)}, dtype={getattr(image_batch, 'dtype', None)}"
            )
        if image_batch.size(0) == 0:
            return _fail_with("[unified_reward] empty batch size.")

        data = image_batch
        if data.dtype != torch.uint8:
            data = data.to(torch.uint8)

        # Ensure NHWC layout
        if data.shape[-1] == 3:
            nhwc_data = data
        elif data.shape[1] == 3:
            nhwc_data = data.permute(0, 2, 3, 1).contiguous()
        else:
            raise ValueError(f"channel dimension must be 3; actual shape: {data.shape}")

        pil_images = [
            Image.fromarray(nhwc_data[i].cpu().numpy()) for i in range(nhwc_data.shape[0])
        ]

        prompts = meta_info.get("prompts")
        if prompts is None:
            return _fail_with("[unified_reward] prompts are required.")
        if isinstance(prompts, str):
            prompts = [prompts]
        if len(prompts) != len(pil_images):
            return _fail_with(
                f"[unified_reward] mismatch: prompts count ({len(prompts)}) vs images count ({len(pil_images)})"
            )

        llm_outputs = self.batch_assess_images(pil_images, prompts)
        raw_scores = self.parse_scores_from_response(llm_outputs)
        normalized_scores = [score / 5.0 for score in raw_scores]

        elapsed = time.perf_counter() - start_time
        duration_str = f"{elapsed:.2f}"

        return {
            "scores": {"unified_reward": normalized_scores},
            "input_info": meta_info.get("input_info", {}),
            "duration": duration_str,
            "decoded_duration": meta_info.get("decode_duration", "N/A"),
            "type": self.reward_name,
        }

from typing import Any, Dict, List, Optional

class ValidateResult:
    """A simplified validation result representation for volcengine-api.
    Designed to be minimal: indicates if validation succeeded, lists error messages,
    and optionally holds additional contextual data.
    """
    __slots__ = ("passed", "messages", "metadata")

    def __init__(self, passed: bool, messages: Optional[List[str]] = None, metadata: Optional[Dict[str, Any]] = None):
        self.passed = bool(passed)
        self.messages = list(messages) if messages is not None else []
        self.metadata = dict(metadata) if metadata is not None else {}

    def as_dict(self) -> Dict[str, Any]:
        return {"passed": self.passed, "messages": self.messages, "metadata": self.metadata}

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ValidateResult):
            return NotImplemented
        return (self.passed == other.passed and 
                self.messages == other.messages and 
                self.metadata == other.metadata)

    def __repr__(self) -> str:
        return f"ValidateResult(passed={self.passed}, messages={self.messages}, metadata={self.metadata})"

