import logging
import threading
import time
from typing import Dict

logger = logging.getLogger(__name__)

class FaultToleranceMechanism:
    """
    Fault tolerance mechanism that disables a provider when failures exceed a threshold.
    """
    def __init__(self, max_failures: int = 5, cooldown_period: int = 60):
        self.max_failures = max_failures
        self.cooldown_period = cooldown_period
        self.failure_counts: Dict[str, int] = {}
        self.timestamp_of_last_failure: Dict[str, float] = {}
        self.status: Dict[str, str] = {}  # 'active', 'disabled', 'testing'
        self._mutex = threading.Lock()

    def permit_request(self, service_name: str) -> bool:
        """Determine whether to allow a request to the service."""
        with self._mutex:
            current_status = self.status.get(service_name, "active")

            if current_status == "active":
                return True

            elif current_status == "disabled":
                elapsed = time.time() - self.timestamp_of_last_failure.get(service_name, 0)
                if elapsed > self.cooldown_period:
                    self.status[service_name] = "testing"
                    logger.info(f"Service {service_name} entering testing phase")
                    return True
                return False

            elif current_status == "testing":
                return True

    def handle_successful_request(self, service_name: str):
        """Update state after a successful request."""
        with self._mutex:
            current = self.status.get(service_name)
            if current == "testing":
                self.status[service_name] = "active"
                self.failure_counts[service_name] = 0
                logger.info(f"Service {service_name} re-enabled after recovery")
            elif current == "active":
                self.failure_counts[service_name] = 0

    def handle_failed_request(self, service_name: str):
        """Update state after a failed request."""
        with self._mutex:
            self.failure_counts[service_name] = self.failure_counts.get(service_name, 0) + 1
            self.timestamp_of_last_failure[service_name] = time.time()

            if self.failure_counts[service_name] >= self.max_failures:
                self.status[service_name] = "disabled"
                logger.warning(
                    f"Service {service_name} disabled after {self.failure_counts[service_name]} consecutive failures"
                )

# Global instance for system-wide use
fault_mechanism = FaultToleranceMechanism()

def trigger_protection(service: str, failure_ratio: float):
    """Callback invoked when failure metrics indicate potential issues."""
    fault_mechanism.handle_failed_request(service)

def can_proceed_with_request(service: str) -> bool:
    """Check if outgoing request should be allowed."""
    return fault_mechanism.permit_request(service)

def acknowledge_success(service: str):
    """Mark a completed successful interaction."""
    fault_mechanism.handle_successful_request(service)

