import torch
import habana_frameworks.torch.core as htcore
import habana_frameworks.torch.utils.experimental as htexp

# Detect device type once at import time
_is_gaudi2 = htexp._get_device_type() == htexp.synDeviceType.synDeviceGaudi2

def _is_gaudi(device_name: str) -> bool:
    return device_name == "GAUDI2" if _is_gaudi2 else device_name == "GAUDI3"

def _get_supported_dtype_max(dtype):
    """Safely get max finite value for supported dtypes."""
    try:
        return torch.finfo(dtype).max
    except AttributeError:
        return None

# Exponent width per dtype
EXPONENT_WIDTH_MAP = {
    torch.float32: 8,
    torch.bfloat16: 8,
    torch.float8_e4m3fn: 4,
    torch.float8_e5m2: 5,
}

def _compute_default_exp_bias(dtype):
    """Compute default exponent bias based on exponent width."""
    width = EXPONENT_WIDTH_MAP.get(dtype)
    if width is None:
        raise ValueError(f"Unsupported dtype {dtype} for exponent bias calculation")
    return (1 << (width - 1)) - 1  # 2^(width-1) - 1

# Predefined exponent bias sets per device and dtype
EXPLICIT_BIAS_SETS = {
    ("GAUDI2", torch.float8_e4m3fn): [3, 7, 11, 15],
    ("GAUDI2", torch.float8_e5m2): [15],
    ("GAUDI3", torch.float8_e4m3fn): list(range(63)),
    ("GAUDI3", torch.float8_e5m2): list(range(63)),
}

# Max representable finite values per dtype
FINITE_MAX_VALUES = {
    torch.float32: _get_supported_dtype_max(torch.float32),
    torch.bfloat16: _get_supported_dtype_max(torch.bfloat16),
    torch.float8_e4m3fn: _get_supported_dtype_max(torch.float8_e4m3fn),
    torch.float8_e5m2: _get_supported_dtype_max(torch.float8_e5m2),
}

# Handle optional float8_e4m3fnuz support conditionally
if hasattr(torch, 'float8_e4m3fnuz'):
    FINITE_MAX_VALUES[torch.float8_e4m3fnuz] = _get_supported_dtype_max(torch.float8_e4m3fnuz)

def _get_fullscale_raw(dtype, device):
    """Get base fullscale value depending on device and dtype."""
    if _is_gaudi(device) and dtype == torch.float8_e4m3fn:
        return FINITE_MAX_VALUES.get(torch.float8_e4m3fnuz)
    return FINITE_MAX_VALUES.get(dtype)

def compute_fullscale(dtype, device, exp_bias=None):
    """Compute fullscale factor considering exponent bias adjustment."""
    default_bias = _compute_default_exp_bias(dtype)
    raw_fullscale = _get_fullscale_raw(dtype, device)
    if raw_fullscale is None:
        raise RuntimeError(f"No max value defined for dtype {dtype}")
    effective_bias = default_bias if exp_bias is None else exp_bias
    scale_adjust = 2.0 ** (default_bias - effective_bias)
    return float(raw_fullscale * scale_adjust)

def compute_fullscales_for_bias_set(dtype, device, bias_list):
    """Generate list of fullscale values for given exponent biases."""
    return [compute_fullscale(dtype, device, eb) for eb in bias_list]

def align_scales_to_hardware(dtype, device):
    """Return hardware-aligned FP8 scales for given dtype and device."""
    bias_set = EXPLICIT_BIAS_SETS.get((device, dtype))
    if bias_set is None:
        return None
    base_fullscale = compute_fullscale(dtype, device)
    fullscale_list = compute_fullscales_for_bias_set(dtype, device, bias_set)
    return [fs / base_fullscale for fs in fullscale_list]

# Device-specific scaling factors
DEVICE_SCALE_FACTORS = {
    "GAUDI2": 4,
    "GAUDI3": 1,
}

# Precompute aligned FP8 scales per device
FP8_E4M3_SCALES_PER_DEVICE = {
    dev: align_scales_to_hardware(torch.float8_e4m3fn, dev)
    for dev in DEVICE_SCALE_FACTORS.keys()
}

# Extract min/max/scale_factor traits per device
FP8_E4M3_TRAITS_PER_DEVICE = {
    dev: (
        min(FP8_E4M3_SCALES_PER_DEVICE[dev]),
        max(FP8_E4M3_SCALES_PER_DEVICE[dev]),
        DEVICE_SCALE_FACTORS[dev],
    )
    for dev in DEVICE_SCALE_FACTORS.keys()
}

class ScaleToNearestPowerOfTwo:
    """Rounds a scale up to the nearest power of two."""
    def compute(self, scale_tensor):
        log2_scale = torch.log2(scale_tensor)
        ceil_log2 = torch.ceil(log2_scale)
        return 2.0 ** ceil_log2

class HardwareAlignedScaleConverter:
    """Converts arbitrary scale to hardware-aligned power-of-two scale."""
    def __init__(self, preferred_device="AUTO"):
        self.device_type = "GAUDI2" if _is_gaudi2 else "GAUDI3"
        if preferred_device != "AUTO":
            self.device_type = preferred_device

    def compute(self, scale_tensor):
        # Apply Gaudi2-specific scaling factor if needed
        if self.device_type == "GAUDI2":
            gaudi2_factor = self._gaudi2_scale_factor()
            scale_tensor = scale_tensor * gaudi2_factor

        # Round up to nearest power of two
        pow2_scaled = ScaleToNearestPowerOfTwo().compute(scale_tensor)

        # Clamp within hardware-supported range
        min_val, max_val, step_size = FP8_E4M3_TRAITS_PER_DEVICE[self.device_type]
        clamped = torch.clamp(
            torch.pow(
                torch.tensor(2.0, dtype=scale_tensor.dtype, device=scale_tensor.device),
                torch.round(torch.log2(pow2_scaled) / step_size) * step_size
            ),
            min=min_val,
            max=max_val
        )
        return clamped

    @staticmethod
    def _gaudi2_scale_factor():
        """Returns ratio of max float8_e4m3fn to float8_e4m3fnuz."""
        return torch.finfo(torch.float8_e4m3fn).max / torch.finfo(torch.float8_e4m3fnuz).max

import re
import sys
from pathlib import Path

def extract_version(version_str: str) -> tuple[int, int, int]:
    """Extract major, minor, and patch numbers from a semantic version string."""
    pattern = r"^(\d+)\.(\d+)\.(\d+)$"
    match = re.match(pattern, version_str)
    if not match:
        raise ValueError(f"Malformed version string: {version_str}")
    return (int(match.group(1)), int(match.group(2)), int(match.group(3)))

def increment_version(current_version: str, level: str) -> str:
    """Generate the next version by bumping at the specified level."""
    major, minor, patch = extract_version(current_version)

    if level == "major":
        return f"{major + 1}.0.0"
    elif level == "minor":
        return f"{major}.{minor + 1}.0"
    elif level == "patch":
        return f"{major}.{minor}.{patch + 1}"
    else:
        raise ValueError(f"Unknown bump level '{level}'. Valid options: major, minor, patch.")

def main() -> None:
    # Validate command-line arguments
    if len(sys.argv) != 2:
        print("Usage: bump_version.py <major|minor|patch>")
        sys.exit(1)

    target_level = sys.argv[1].strip().lower()
    if target_level not in ("major", "minor", "patch"):
        print(f"Error: Invalid bump level '{target_level}'. Choose from major, minor, or patch.")
        sys.exit(1)

    config_file = Path("pyproject.toml")
    if not config_file.is_file():
        print("Error: pyproject.toml file is missing in the current directory.")
        sys.exit(1)

    try:
        content = config_file.read_text()
    except Exception as e:
        print(f"Error reading pyproject.toml: {e}")
        sys.exit(1)

    # Extract current version from configuration file
    version_pattern = re.compile(r'^version\s*=\s*"([^"]+)"', re.MULTILINE)
    version_match = version_pattern.search(content)
    if not version_match:
        print("Error: Could not locate version declaration in pyproject.toml.")
        sys.exit(1)

    old_version = version_match.group(1)
    new_version = increment_version(old_version, target_level)

    # Update version in file content
    updated_content = version_pattern.sub(
        lambda m: f'version = "{new_version}"' if m.group(1) == old_version else m.group(0),
        content,
        count=1
    )

    try:
        config_file.write_text(updated_content)
    except Exception as e:
        print(f"Error writing updated version to pyproject.toml: {e}")
        sys.exit(1)

    print(f"Version updated: {old_version} → {new_version}")

if __name__ == "__main__":
    main()

import json
import sys

def clear_execution_data(file_path: str) -> bool:
    """Clear output cells and execution counts. Returns True if changes were made."""
    with open(file_path, 'r', encoding='utf-8') as file:
        notebook = json.load(file)

    changed = False

    for cell in notebook.get("cells", []):
        if cell.get("cell_type") == "code":
            # Clear outputs if any exist
            if cell.get("outputs"):
                cell["outputs"] = []
                changed = True

            # Clear execution count if present
            if cell.get("execution_count") is not None:
                cell["execution_count"] = None
                changed = True

    # Save the modified notebook only if changes occurred
    if changed:
        with open(file_path, 'w', encoding='utf-8') as file:
            json.dump(notebook, file, indent=1, ensure_ascii=False)
            file.write("\n")

    return changed

if __name__ == "__main__":
    for path in sys.argv[1:]:
        if clear_execution_data(path):
            print(f"Cleaned execution data: {path}")

