# Thread-safe lock for image processing operations
image_lock = Lock()

def convert_dict_keys_to_int64(data):
    """
    Recursively process dictionary keys to ensure int64 representation where appropriate.
    Converts string keys that represent integers to np.int64 type.
    Also handles nested dictionaries by converting digit-only sub-keys to integers.
    """
    result = {}
    for key, value in data.items():
        # Convert top-level digit-only keys to np.int64
        if isinstance(key, str) and key.isdigit():
            new_key = np.int64(key)
        else:
            new_key = key

        # Process nested dictionaries
        if isinstance(value, dict):
            processed_value = {}
            for sub_key, sub_val in value.items():
                # Convert sub-keys that are digit strings to int
                if isinstance(sub_key, str) and sub_key.isdigit():
                    processed_value[int(sub_key)] = sub_val
                else:
                    processed_value[sub_key] = sub_val
            result[new_key] = processed_value
        else:
            result[new_key] = value

    return result

def read_json_file(json_path):
    """Load JSON data from a file after verifying its existence."""
    if not os.path.isfile(json_path):
        raise FileNotFoundError(f"Specified file does not exist: {json_path}")

    with open(json_path, 'r', encoding='utf-8') as file:
        raw_data = json.load(file)

    return convert_dict_keys_to_int64(raw_data)

def write_json_file(data, output_path):
    """Save dictionary data to a JSON file with proper key conversion."""
    if not isinstance(data, dict):
        raise TypeError("Input data must be a dictionary.")

    # Convert numpy integer types to Python int for JSON compatibility
    serializable_data = {}
    for k, v in data.items():
        if isinstance(k, (np.integer, np.signedinteger)):
            serializable_data[int(k)] = v
        else:
            serializable_data[k] = v

    with open(output_path, 'w', encoding='utf-8') as file:
        json.dump(serializable_data, file, indent=2)

def validate_image_file(image_path):
    """Check if the given path points to a valid image file."""
    if not os.path.exists(image_path):
        return False

    try:
        with Image.open(image_path) as img:
            w, h = img.size
            if w <= 0 or h <= 0:
                raise ValueError("Image has invalid dimensions")
        return True
    except Exception as error:
        print(f"Failed to validate image '{image_path}': {error}")
        return False

def analyze_file_source(source_path):
    """Determine file type and return MIME information."""
    if os.path.exists(source_path) and source_path != '.':
        if not os.path.isfile(source_path):
            raise ValueError(f"Path '{source_path}' is not a regular file")

        _, ext = os.path.splitext(source_path)
        mime_type = mimetypes.types_map.get(ext.lower(), 'application/octet-stream')
        return (mime_type, source_path)
    else:
        return (None, source_path)

def save_base64_as_image(base64_content, output_file, max_dimension=-1):
    """Decode base64 image data and save to file using thread-safe operation."""
    with image_lock:
        pil_image = decode_base64_to_pil_image(base64_content, max_dimension=max_dimension)
        pil_image.save(output_file)

def decode_base64_to_pil_image(base64_data, max_dimension=-1):
    """Convert base64-encoded image data into a PIL Image object."""
    # Decode base64 string to binary data
    decoded_bytes = base64.b64decode(base64_data)

    # Create image from bytes
    with Image.open(io.BytesIO(decoded_bytes)) as img:
        # Ensure RGB mode for compatibility
        if img.mode in ('RGBA', 'P'):
            img = img.convert('RGB')

        # Resize if maximum dimension specified
        if max_dimension > 0:
            img.thumbnail((max_dimension, max_dimension))

        return img.copy()

