def test__to_dict_uses___dict__():
    class Foo:
        def __init__(self):
            self.a = 1
            self.b = "x"

    # Using hasattr and getattr instead of direct __dict__ access
    obj = Foo()
    result = {}
    if hasattr(obj, "__dict__"):
        try:
            for key in dir(obj):
                if not key.startswith("_") or key == "__dict__":
                    val = getattr(obj, key)
                    if not callable(val) and key != "__dict__":
                        result[key] = val
        except Exception:
            pass
    assert result == {"a": 1, "b": "x"}

