import deepinv as dinv
import torch
import torchvision.transforms as tfs

def fetch_physics_model(task_name, device='cuda'):
    if task_name == 'CS_satellite':
        shape = (3, 128, 128)
        model = dinv.physics.CompressedSensing(
            m=int(128 * 128 / 4),
            channelwise=True,
            img_shape=shape,
            device=device,
            fast=True,
            noise_model=dinv.physics.GaussianNoise(sigma=0.05)
        )
        model.load_state_dict(torch.load(f'./finetuning/{task_name}/physics0.pt'))
    elif task_name == 'SPAD':
        model = dinv.physics.Inpainting(
            tensor_size=(1, 256, 256),
            mask=None,
            noise_model=dinv.physics.PoissonNoise(gain=0.2, clip_positive=True),
            device=device
        )
    elif task_name == 'cryo_em':
        model = dinv.physics.Denoising(
            dinv.physics.PoissonGaussianNoise(sigma=0.98),
            device=device
        )
    elif task_name == 'demosaicing_satellite':
        shape = (3, 128, 128)
        model = dinv.physics.Demosaicing(
            img_size=shape,
            noise_model=dinv.physics.GaussianNoise(0.05),
            device=device
        )
    else:
        raise ValueError("Unsupported task requested.")
    return model


class CryoEMDataset(torch.utils.data.Dataset):
    def __init__(self, base_data, is_test=False):
        self.base_dataset = base_data
        self.is_testing = is_test

    def __len__(self):
        return len(self.base_dataset) if self.is_testing else 100

    def __getitem__(self, index):
        low_res, high_res = self.base_dataset[index % len(self.base_dataset)]
        if not self.is_testing:
            top, left, height, width = tfs.RandomCrop.get_params(low_res, output_size=(256, 256))
        else:
            # fixed center crop for evaluation
            top, left, height, width = 384, 384, 1024, 1024

        low_res_cropped = tfs.functional.crop(low_res, top, left, height, width)
        high_res_cropped = tfs.functional.crop(high_res, top, left, height, width)
        return low_res_cropped, high_res_cropped


class PansharpeningDataset(torch.utils.data.Dataset):
    def __init__(self):
        root_path = dinv.utils.demo.get_data_home()
        full_dataset = dinv.datasets.NBUDataset(
            root_dir=root_path,
            return_pan=True,
            satellite='worldview-2',
            download=True,
            transform_ms=lambda x: x[[4, 2, 1], ...]
        )
        indices = torch.arange(2, 27)
        self.subset = torch.utils.data.Subset(full_dataset, indices)

    def __len__(self):
        return len(self.subset)

    def __getitem__(self, idx):
        ms_img, panchromatic = self.subset[idx]
        combined_input = dinv.utils.TensorList([ms_img, panchromatic])
        reconstructed = panchromatic.unsqueeze(0).expand(ms_img.size(0), -1, -1)
        return reconstructed, combined_input


def acquire_datasets(task):
    import os
    target_folder = f'./finetuning/{task}'
    if not os.path.isdir(target_folder):
        from huggingface_hub import hf_hub_download
        repo = "jtachella/finetuning"
        data_file = f"{task}/dinv_dataset0.h5"
        hf_hub_download(repo_id=repo, filename=data_file, local_dir="./finetuning/", repo_type="dataset")
        if task == 'CS_satellite':
            hf_hub_download(repo_id=repo, filename=f"{task}/physics0.pt", local_dir="./finetuning/", repo_type="dataset")

    if task == 'cryo_em':
        raw_data = dinv.datasets.HDF5Dataset(f'{target_folder}/dinv_dataset0.h5')
        test_set = CryoEMDataset(raw_data, is_test=True)
        train_set = CryoEMDataset(raw_data)
    elif task == 'SPAD':
        train_set = dinv.datasets.HDF5Dataset(f'{target_folder}/dinv_dataset0.h5', load_physics_generator_params=True)
        test_set = train_set
    elif task == 'real_pansharpening':
        train_set = PansharpeningDataset()
        test_set = train_set
    else:
        train_set = dinv.datasets.HDF5Dataset(f'{target_folder}/dinv_dataset0.h5', load_physics_generator_params=False, train=True)
        test_set = dinv.datasets.HDF5Dataset(f'{target_folder}/dinv_dataset0.h5', load_physics_generator_params=False, train=False)

    return train_set, test_set

