# Function to register replay list for MoE (Mixture of Experts) models

from megatron.core.transformer.transformer_block import get_num_layers_to_build
from megatron.core.transformer.transformer_layer import get_transformer_layer_offset
from miles.utils.replay_base import BaseReplayManager, RoutingReplayManager

def _assign_replay_data_moe(replay_list, replay_data, models):
    active_layers = []
    current_index = 0

    # Iterate through virtual pipeline stages and collect MOE layer indices
    for vp_idx, model in enumerate(models):
        cfg = model.module.config
        layers_in_stage = get_num_layers_to_build(cfg, vp_stage=vp_idx)
        base_layer_id = get_transformer_layer_offset(cfg, vp_stage=vp_idx)

        for local_layer_pos in range(layers_in_stage):
            global_layer_id = base_layer_id + local_layer_pos

            # Check if this layer is an MOE layer based on frequency configuration
            if isinstance(cfg.moe_layer_freq, int):
                if cfg.moe_layer_freq > 0 and global_layer_id % cfg.moe_layer_freq != 0:
                    continue
            elif isinstance(cfg.moe_layer_freq, list):
                assert len(cfg.moe_layer_freq) == cfg.num_layers, "MOE layer frequency list length mismatch"
                if cfg.moe_layer_freq[global_layer_id] == 0:
                    continue

            active_layers.append(global_layer_id)

    # Assign replay data to corresponding layers
    for idx, layer_id in enumerate(active_layers):
        layer_data_slice = replay_data[:, layer_id]
        replay_list[idx].store(layer_data_slice)

def obtain_replay_registration_handler(replay_manager: BaseReplayManager):
    if isinstance(replay_manager, RoutingReplayManager):
        return _assign_replay_data_moe
    else:
        raise TypeError(f"Unsupported replay manager type: {type(replay_manager)}")

