from ripperdoc.utils.file_watch import ChangedFileNotice

def _format_changed_file_notice(notices: List[ChangedFileNotice]) -> str:
    """Generate a formatted message regarding files that have been modified on disk."""
    output_lines = [
        "System notice: Files you previously read have changed on disk.",
        "Please re-read the affected files before making further edits.",
        "",
    ]

    for item in notices:
        output_lines.append(f"- {item.file_path}")
        summary_text = (item.summary or "").rstrip()
        if summary_text:
            # Split into lines and indent each line by 4 spaces
            indented_summary = "\n".join(
                "    " + line for line in summary_text.splitlines()
            )
            output_lines.append(indented_summary)

    return "\n".join(output_lines)

# Script to detect newly added virtual rides from Strava and notify the user

import json
import sys
from pathlib import Path
import requests
import time
from cache_manager import get_stored_activities, append_to_cache

CONFIG_FILE = Path.home() / ".config" / "strava" / "settings.json"

def retrieve_configuration():
    """Load configuration from JSON file or exit if missing."""
    if not CONFIG_FILE.is_file():
        print("Configuration file not found.", file=sys.stderr)
        sys.exit(1)

    with open(CONFIG_FILE) as config_file:
        return json.load(config_file)

def ensure_valid_token(config):
    """Ensure access token is valid by refreshing if necessary."""
    current_time = time.time()
    if config['token_expiry'] < current_time:
        endpoint = "https://www.strava.com/oauth/token"
        payload = {
            'client_id': config['app_id'],
            'client_secret': config['app_secret'],
            'refresh_token': config['refresh_key'],
            'grant_type': 'refresh_token'
        }

        api_response = requests.post(endpoint, data=payload)
        api_response.raise_for_status()

        new_tokens = api_response.json()
        config['access_token'] = new_tokens['access_token']
        config['refresh_key'] = new_tokens['refresh_token']
        config['token_expiry'] = new_tokens['expires_at']

        with open(CONFIG_FILE, 'w') as cfg_file:
            json.dump(config, cfg_file, indent=2)

    return config

def pull_latest_activities(config, max_count=10):
    """Retrieve latest activities using authenticated API call."""
    config = ensure_valid_token(config)

    api_url = "https://www.strava.com/api/v3/athlete/activities"
    auth_headers = {'Authorization': f"Bearer {config['access_token']}"}
    query_params = {'per_page': max_count}

    result = requests.get(api_url, headers=auth_headers, params=query_params)
    result.raise_for_status()

    return result.json()

def discover_new_virtual_sessions():
    """Identify new virtual cycling sessions since last execution."""
    app_config = retrieve_configuration()

    # Load previously stored activity IDs
    previous = get_stored_activities()
    previous_ids = {item['identifier'] for item in previous}

    # Fetch current recent activities
    latest = pull_latest_activities(app_config, max_count=20)

    # Filter for new virtual rides
    fresh_rides = []
    for session in latest:
        if session['identifier'] not in previous_ids and session.get('category') == 'VirtualRide':
            fresh_rides.append(session)

    # Update local cache if new items found
    if fresh_rides:
        append_to_cache(latest)

    return fresh_rides

def execute():
    try:
        fresh_rides = discover_new_virtual_sessions()

        if fresh_rides:
            print(f"Detected {len(fresh_rides)} new virtual ride(s):")
            for ride in fresh_rides:
                print(f"  - {ride['title']} ({ride['identifier']})")

            # Emit identifiers for downstream tools
            for ride in fresh_rides:
                print(f"NEW_RIDE:{ride['identifier']}")
        else:
            print("No fresh rides detected")

    except Exception as error:
        print(f"An issue occurred: {error}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    execute()

import requests
from typing import Tuple, Dict, Any
import logging
from .base import BaseDnsProvider

logger = logging.getLogger(__name__)

class PorkbunDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "porkbun"
    PROVIDER_NAME = "Porkbun"
    PROVIDER_DESCRIPTION = "Porkbun DNS API"
    REQUIRED_CREDENTIALS = ["api_key", "secret_api_key"]

    API_ENDPOINT = "https://api.porkbun.com/api/json/v3"

    def _build_auth_payload(self, additional_params=None):
        payload = {
            'apikey': self.credentials['api_key'],
            'secretapikey': self.credentials['secret_api_key'],
        }
        if additional_params:
            payload.update(additional_params)
        return payload

    def _send_request(self, endpoint_path, payload_data=None):
        auth_payload = self._build_auth_payload(payload_data)
        try:
            response = requests.post(f"{self.API_ENDPOINT}{endpoint_path}", json=auth_payload, timeout=30)
            json_response = response.json()
            if json_response.get('status') == 'SUCCESS':
                return True, json_response
            return False, json_response.get('message', 'Unknown error')
        except requests.RequestException as exc:
            logger.error(f"Porkbun API request failed: {exc}")
            return False, str(exc)

    def add_txt_record(self, domain_name, record_label, record_content, ttl_value=300):
        zone_name = self.get_zone_for_domain(domain_name)
        relative_name = self.get_relative_record_name(record_label, zone_name)
        success, result_data = self._send_request(f'/dns/create/{zone_name}', {
            'name': relative_name, 'type': 'TXT', 'content': record_content, 'ttl': str(ttl_value)
        })
        if not success:
            return False, f"Failed to create record: {result_data}"
        return True, "TXT record added successfully"

    def remove_txt_record(self, domain_name, record_label):
        zone_name = self.get_zone_for_domain(domain_name)
        relative_name = self.get_relative_record_name(record_label, zone_name)

        success, result_data = self._send_request(f'/dns/retrieveByNameType/{zone_name}/TXT/{relative_name}')
        if success:
            for record_entry in result_data.get('records', []):
                self._send_request(f'/dns/delete/{zone_name}/{record_entry["id"]}')
        return True, "TXT record removed"

    def verify_connection(self):
        success, result_data = self._send_request('/ping')
        if success:
            return True, "Connection established successfully"
        return False, f"Connection verification failed: {result_data}"

    @classmethod
    def get_configuration_schema(cls):
        return [
            {'name': 'api_key', 'label': 'API Key', 'type': 'password', 'required': True,
             'help': 'Obtain from porkbun.com > Account > API Access'},
            {'name': 'secret_api_key', 'label': 'Secret API Key', 'type': 'password', 'required': True,
             'help': 'Generate via Porkbun dashboard under API settings'},
        ]

