import json
import fitz  # pymupdf alias

def read_pdf_content(pdf_path, limit=None):
    try:
        document = fitz.open(pdf_path)
        content = ""
        for idx, page in enumerate(document):
            if limit is not None and idx >= int(limit):
                break
            content += page.get_text() + "\n"
        return content.strip()
    except Exception as error:
        return f"Error: {str(error)}"

def fetch_document_info(pdf_path):
    try:
        document = fitz.open(pdf_path)
        return dict(document.metadata)
    except Exception as error:
        return {"error": str(error)}

