# Reconstruct image using VQ-VAE model with optional checkpoint loading

import importlib
import torch
import yaml
from omegaconf import OmegaConf
from taming.models.vqgan import VQModel

def fetch_configuration(config_file, show=False):
    cfg = OmegaConf.load(config_file)
    if show:
        print(yaml.dump(OmegaConf.to_container(cfg)))
    return cfg

def initialize_vqgan_model(device, config_file=None, checkpoint_file=None):
    if config_file is None:
        config_file = "./model_checkpoints/vqgan_only.yaml"

    cfg = fetch_configuration(config_file, show=False)
    model = VQModel(**cfg.model.params)

    if checkpoint_file is None:
        checkpoint_file = "./model_checkpoints/vqgan_only.pt"

    weights = torch.load(checkpoint_file, map_location=device)

    if ".ckpt" in checkpoint_file:
        weights = weights["state_dict"]

    model.load_state_dict(weights, strict=True)
    model = model.to(device)
    del weights
    return model

def reconstruct_image_with_vqgan(input_tensor, model):
    latent, _, [_, _, indices] = model.encode(input_tensor)
    print(f"VQGAN --- {model.__class__.__name__}: latent dimensions: {latent.shape[2:]}")
    reconstructed = model.decode(latent)
    return reconstructed

def retrieve_class_from_string(class_path, reload_module=False):
    module_name, class_name = class_path.rsplit(".", 1)
    if reload_module:
        imported_module = importlib.import_module(module_name)
        importlib.reload(imported_module)
    else:
        imported_module = importlib.import_module(module_name, package=None)
    return getattr(imported_module, class_name)

def create_instance_from_config(config_dict):
    if "target" not in config_dict:
        raise KeyError("Missing required key 'target' for instantiation.")
    cls = retrieve_class_from_string(config_dict["target"])
    params = config_dict.get("params", {})
    return cls(**params)

def build_model_from_config(model_config, state_dict, use_gpu=True, set_eval=True):
    model = create_instance_from_config(model_config)

    if state_dict is not None:
        model.load_state_dict(state_dict)

    if use_gpu:
        model.cuda()

    if set_eval:
        model.eval()

    return {"model": model}

def load_complete_model(config_data, checkpoint_path, use_gpu, evaluation_mode):
    # Load checkpoint if provided
    if checkpoint_path:
        raw_state_dict = torch.load(checkpoint_path, map_location="cpu")
        training_step = raw_state_dict.get("global_step", None)
        print(f"Loaded model from global step {training_step}.")
    else:
        raw_state_dict = {"state_dict": None}
        training_step = None

    model = build_model_from_config(
        config_data.model, 
        raw_state_dict["state_dict"], 
        use_gpu=use_gpu, 
        set_eval=evaluation_mode
    )["model"]

    return model, training_step

# Safe file validation module

import os
import mimetypes

# Define allowed file extensions
SAFE_EXTENSIONS = {".txt", ".md", ".json", ".csv"}

def is_file_valid(path):
    """Validate a file in a secure manner"""
    # Extract only the filename to avoid path traversal attacks
    base_name = os.path.basename(path)

    # Verify file extension is permitted
    _, extension = os.path.splitext(base_name)
    if extension not in SAFE_EXTENSIONS:
        return {"valid": False, "message": "Unsupported file type"}

    # Restrict operations to a designated safe directory
    restricted_folder = os.path.expanduser("~/documents/")
    absolute_path = os.path.join(restricted_folder, base_name)

    # Confirm file existence
    if not os.path.isfile(absolute_path):
        return {"valid": False, "message": "File does not exist"}

    # Enforce size restriction (max 10MB)
    file_size = os.path.getsize(absolute_path)
    if file_size > 10 * 1024 * 1024:
        return {"valid": False, "message": "Exceeds maximum size limit"}

    return {"valid": True, "name": base_name, "bytes": file_size}

def get_media_type(filepath):
    """Determine MIME type securely"""
    # Use standard library for safe MIME detection
    media_type, _ = mimetypes.guess_type(filepath)
    return media_type

