    }

def _normalize_and_rearrange_image(raw_image) -> np.ndarray:
    # Convert input to numpy array if not already
    img_array = np.asarray(raw_image)

    # Handle floating-point images: scale to [0, 255] and convert to uint8
    if np.issubdtype(img_array.dtype, np.floating):
        img_array = (255 * img_array).astype(np.uint8)

    # Reorder channels from CHW to HWC if needed
    if img_array.shape[0] == 3:
        img_array = einops.rearrange(img_array, "c h w -> h w c")

    return img_array

@dataclasses.dataclass(frozen=True)
class CalvinInputPreprocessor(transforms.DataTransformFn):
    architecture_type: _model.ModelType

    def __call__(self, sample: dict) -> dict:
        # Process visual inputs
        main_view = _normalize_and_rearrange_image(sample["observation/image"])
        wrist_view = _normalize_and_rearrange_image(sample["observation/wrist_image"])

        # Assemble robot state vector
        ee_position = sample["observation/state_ee_pos"]
        ee_orientation = sample["observation/state_ee_rot"]
        gripper_state = sample["observation/state_gripper"]
        full_state = np.concatenate([ee_position, ee_orientation, gripper_state])

        # Construct structured input dictionary
        processed_inputs = {
            "state": full_state,
            "image": {
                "base_rgb": main_view,
                "left_wrist_rgb": wrist_view,
                "right_wrist_rgb": np.zeros_like(main_view),
            },
            "image_mask": {
                "base_rgb": np.True_,
                "left_wrist_rgb": np.True_,
                "right_wrist_rgb": (
                    np.True_ 
                    if self.architecture_type == _model.ModelType.PI0_FAST 
                    else np.False_
                ),
            },
        }

        # Add action data if present
        if "actions/delta_ee_pos" in sample:
            delta_pos = sample["actions/delta_ee_pos"]
            delta_rot = sample["actions/delta_ee_rot"]
            gripper_cmd = sample["actions/gripper"]
            combined_actions = np.concatenate([delta_pos, delta_rot, gripper_cmd], axis=1)
            processed_inputs["actions"] = combined_actions

        # Preserve natural language prompt if available
        if "prompt" in sample:
            processed_inputs["instruction"] = sample["prompt"]

        return processed_inputs

@dataclasses.dataclass(frozen=True)
class CalvinOutputFormatter(transforms.DataTransformFn):
    def __call__(self, raw_data: dict) -> dict:
        # Extract first 7 dimensions of action trajectory
        action_tensor = np.asarray(raw_data["actions"])
        truncated_actions = action_tensor[:, :7]
        return {"actions": truncated_actions}

