import pydantic
import numpy as np


# Mapping from dihedral transform ID to its inverse.
# The index represents the original transform ID, and the value is the corresponding inverse ID.
DIHEDRAL_INVERSE_MAP = [0, 3, 2, 1, 4, 7, 6, 5]


class PuzzleDatasetMetadata(pydantic.BaseModel):
    padding_token_id: int
    mask_token_id: Optional[int]
    blank_token_id: int

    vocabulary_size: int
    maximum_sequence_length: int
    number_of_puzzle_tokens: int

    total_partition_count: int
    average_examples_per_partition: float

    partition_names: List[str]


def apply_dihedral_symmetry(image: np.ndarray, operation_id: int) -> np.ndarray:
    """Apply one of the 8 dihedral group operations (rotations and reflections)"""

    if operation_id == 0:
        return image.copy()  # identity transformation
    elif operation_id == 1:
        return np.rot90(image, k=1)
    elif operation_id == 2:
        return np.rot90(image, k=2)
    elif operation_id == 3:
        return np.rot90(image, k=3)
    elif operation_id == 4:
        return np.flipud(image)       # vertical flip
    elif operation_id == 5:
        return np.fliplr(image)       # horizontal flip
    elif operation_id == 6:
        return image.T                # transpose (reflection across main diagonal)
    elif operation_id == 7:
        return np.flipud(np.rot90(image, k=1))  # anti-diagonal reflection
    else:
        return image.copy()


def reverse_dihedral_symmetry(image: np.ndarray, operation_id: int) -> np.ndarray:
    """Apply the inverse operation of a given dihedral symmetry"""
    return apply_dihedral_symmetry(image, DIHEDRAL_INVERSE_MAP[operation_id])

