@dataclasses.dataclass(frozen=True)
class MetaworldInputFormatter(transforms.DataTransformFn):
    architecture: _model.ModelType

    def __call__(self, sample: dict) -> dict:
        primary_img = _normalize_and_rearrange_image(sample["observation/image"])

