# Utility functions for file read/write operations

import os

def load_file_content(file_path: str) -> str:
    # Ensure the directory exists before reading
    dir_path = os.path.dirname(file_path)
    if dir_path and not os.path.exists(dir_path):
        os.makedirs(dir_path, exist_ok=True)

    with open(file_path, 'r', encoding='utf-8') as f:
        return f.read()

def save_file_content(file_path: str, data: str) -> None:
    # Create parent directories if they don't exist
    dir_path = os.path.dirname(file_path)
    if dir_path and not os.path.exists(dir_path):
        os.makedirs(dir_path, exist_ok=True)

    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(data)

from abc import ABC, abstractmethod
from pydantic import field_validator
from openhands.sdk.security.risk import SecurityRisk
from openhands.sdk.utils.models import DiscriminatedUnionMixin

class ConfirmationStrategyBase(DiscriminatedUnionMixin, ABC):
    @abstractmethod
    def requires_approval(self, threat_level: SecurityRisk = SecurityRisk.UNKNOWN) -> bool:
        """Evaluate whether an operation with the specified threat level needs user approval.
        This method implements the core decision-making process for determining if explicit
        user consent is necessary before proceeding with an operation based on its security
        threat classification.
        Args:
            threat_level: The security threat classification of the operation to be assessed.
                         Defaults to SecurityRisk.UNKNOWN if not provided.
        Returns:
            True if the operation must obtain user approval before execution,
            False if the operation may proceed without manual intervention.
        """

class AlwaysSeekApproval(ConfirmationStrategyBase):
    def requires_approval(
        self,
        threat_level: SecurityRisk = SecurityRisk.UNKNOWN,  # noqa: ARG002
    ) -> bool:
        return True

class NeverSeekApproval(ConfirmationStrategyBase):
    def requires_approval(
        self,
        threat_level: SecurityRisk = SecurityRisk.UNKNOWN,  # noqa: ARG002
    ) -> bool:
        return False

class ApproveOnlyForHighThreats(ConfirmationStrategyBase):
    risk_threshold: SecurityRisk = SecurityRisk.HIGH
    treat_unknown_as_risky: bool = True

    @field_validator("risk_threshold")
    def validate_risk_threshold(cls, v: SecurityRisk) -> SecurityRisk:
        if v == SecurityRisk.UNKNOWN:
            raise ValueError("Risk threshold cannot be UNKNOWN")
        return v

    def requires_approval(self, threat_level: SecurityRisk = SecurityRisk.UNKNOWN) -> bool:
        if threat_level == SecurityRisk.UNKNOWN:
            return self.treat_unknown_as_risky
        # This comparison follows reflexive ordering, so when threshold is HIGH,
        # HIGH-risk operations will also require approval. Since the validator ensures
        # the threshold is never UNKNOWN, we always obtain a definitive boolean result.
        return threat_level.is_riskier(self.risk_threshold)

