# Slack integration utility using environment-based authentication

import os
import json
import sys
import requests

class SlackConnector:
    def __init__(self):
        self.api_token = os.environ.get("SLACK_BOT_TOKEN")
        self.endpoint_prefix = "https://slack.com/api"

    def _execute_request(self, method, path, payload=None, extra_headers=None):
        base_headers = {
            "Authorization": f"Bearer {self.api_token}",
            "Content-Type": "application/json; charset=utf-8"
        }
        if extra_headers:
            base_headers.update(extra_headers)

        url = f"{self.endpoint_prefix}/{path}"
        if method.upper() == "GET":
            result = requests.get(url, headers=base_headers, params=payload)
        else:
            result = requests.post(url, headers=base_headers, json=payload)

        return result.json()

    def deliver(self, destination, content, parent_thread=None):
        message_payload = {"channel": destination, "text": content}
        if parent_thread:
            message_payload["thread_ts"] = parent_thread
        return self._execute_request("POST", "chat.postMessage", message_payload)

    def find_messages(self, search_term):
        query_params = {"query": search_term}
        auth_header = {"Authorization": f"Bearer {self.api_token}"}
        response = requests.get(
            f"{self.endpoint_prefix}/search.messages",
            headers=auth_header,
            params=query_params
        )
        return response.json()

if __name__ == "__main__":
    import argparse

    connector = SlackConnector()

    cli_parser = argparse.ArgumentParser(description="Slack workspace operations")
    cli_parser.add_argument("operation", choices=["send", "find", "list"])
    cli_parser.add_argument("--destination")
    cli_parser.add_argument("--content")
    cli_parser.add_argument("--search-term")
    arguments = cli_parser.parse_args()

    if arguments.operation == "list":
        print(json.dumps(connector._execute_request("POST", "conversations.list", {"types": "public_channel,private_channel"})))
    elif arguments.operation == "send":
        print(json.dumps(connector.deliver(arguments.destination, arguments.content)))
    elif arguments.operation == "find":
        print(json.dumps(connector.find_messages(arguments.search_term)))

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

class EntropyTemperature(nn.Module):
    """
    Temperature module for SAC automatic entropy tuning.
    """
    def __init__(
        self,
        initial_alpha: float,
        alpha_type: str = "softplus",
        device=None,
        dtype=torch.float32,
    ):
        super().__init__()
        self.alpha_type = alpha_type

        # Initialize based on the specified alpha transformation type
        if alpha_type == "exp":
            # For exponential mapping, initialize with log of target alpha
            init_value = np.log(initial_alpha)
        elif alpha_type == "softplus":
            # For softplus mapping, use inverse softplus: log(exp(x) - 1)
            init_value = np.log(np.exp(initial_alpha) - 1.0)
        elif alpha_type == "fixed_alpha":
            # For fixed alpha, store as buffer and set init to actual value
            self.register_buffer(
                "fixed_alpha",
                torch.tensor(
                    [initial_alpha],
                    device=device,
                    dtype=dtype,
                ),
                persistent=True,
            )
            init_value = initial_alpha
        else:
            raise ValueError(f"Unsupported alpha_type: {alpha_type}")

        # Create learnable parameter with computed initialization
        self.base_alpha = nn.Parameter(
            torch.tensor(init_value, device=device, dtype=dtype)
        )

    def compute_alpha(self) -> torch.Tensor:
        """Compute current alpha value based on transformation type."""
        if self.alpha_type == "exp":
            return torch.exp(self.base_alpha)
        elif self.alpha_type == "softplus":
            return F.softplus(self.base_alpha)
        elif self.alpha_type == "fixed_alpha":
            return self.fixed_alpha
        else:
            raise RuntimeError(f"Unknown alpha_type encountered: {self.alpha_type}")

    @property
    def alpha(self) -> float:
        """Return current alpha as a Python float."""
        return self.compute_alpha().detach().item()

