class DiagnosisService(Service.Service):
    def __init__(self, region: str, endpoint: str, api_definitions: dict, service_name: str, access_key: str, secret_key: str):
        # Initialize timeout and connection settings
        self.connect_timeout = 10
        self.socket_read_timeout = 10
        self.protocol = 'https'
        self.request_headers = {}
        self.request_headers["Content-Type"] = "application/json"

        # Set up service configuration
        self.gateway_endpoint = endpoint
        self.credentials = Credentials.Credentials(access_key, secret_key, service_name, region)
        self.service_config = ServiceInfo.ServiceInfo(
            self.gateway_endpoint,
            self.request_headers,
            self.credentials,
            self.connect_timeout,
            self.socket_read_timeout,
            self.protocol
        )
        self.api_specs = api_definitions

        # Initialize parent class
        Service.Service.__init__(self, self.service_config, self.api_specs)

    def execute_get_request(self, operation_name: str, query_params: dict, multi_value: bool = False) -> dict:
        raw_response = super(DiagnosisService, self).get(operation_name, query_params, multi_value)
        try:
            parsed_response = json.loads(raw_response)
        except json.JSONDecodeError as e:
            raise Exception(f"Failed to parse response as JSON: {e}, Response: {raw_response}")

        if "ResponseMetadata" not in parsed_response:
            raise Exception(f"Missing ResponseMetadata in response for operation '{operation_name}': {raw_response}")

        if "Error" in parsed_response["ResponseMetadata"]:
            error_info = parsed_response["ResponseMetadata"]["Error"]
            raise Exception(f"Operation '{operation_name}' failed with error: {error_info}")

        return parsed_response

