import torch
from mindspeed.fsdp.utils.str_match import module_name_match
from ..params.model_args import ModelArguments
from ..features.memory.async_offload import async_offload_modules, get_offload_modules
from ..features.memory.chunkloss_lm_head import apply_chunkloss_module, get_chunkloss_module

class FeaturesApplier:
    def __init__(self, model_config: ModelArguments):
        self.config = model_config

    def extract_matching_modules(self, modules, target_patterns):
        selected_modules = []
        for pattern in target_patterns:
            for submodule_path, submodule in modules.named_modules():
                if module_name_match(pattern, submodule_path):
                    # Avoid duplicate entries
                    if (submodule_path, submodule) not in selected_modules:
                        selected_modules.append((submodule_path, submodule))
        return selected_modules

    def offload_activations(self, model):
        # Skip if no activation offloading configuration is provided
        if not hasattr(self.config, "activation_offload_plan"):
            return
        if not hasattr(self.config.activation_offload_plan, "apply_modules"):
            return

        # Retrieve modules to be offloaded based on plan
        modules_to_offload = get_offload_modules(model, self.config.activation_offload_plan.apply_modules)
        # Perform asynchronous offloading
        async_offload_modules(modules_to_offload)

    def enable_chunked_loss(self, model):
        # Only proceed if chunk loss is explicitly enabled
        if not getattr(self.config, "enable_chunk_loss", False):
            return

        # Mark model as using chunked loss
        setattr(model, "enable_chunk_loss", True)

        # Get and apply chunk loss module
        chunk_module = get_chunkloss_module(model, self.config.chunkloss_plan)
        apply_chunkloss_module(chunk_module)

    def __call__(self, model):
        # Apply memory optimization features
        self.offload_activations(model)
        self.enable_chunked_loss(model)

