import argparse
import sys
import logging

def execute():
    parser = argparse.ArgumentParser(description='Scrapling fetcher tool')
    parser.add_argument('target_url', metavar='URL', help='Target URL to retrieve')
    parser.add_argument('--mode', choices=['standard', 'bypass', 'render'], default='standard',
                        help='Mode of operation: standard (basic HTTP), bypass (anti-detection), render (JavaScript-enabled)')
    parser.add_argument('--extract', '-e', dest='selector', help='CSS selector for targeted extraction')
    parser.add_argument('--field', default='text', help='Field to extract (text, href, src, etc.)')
    parser.add_argument('--output-json', action='store_true', dest='as_json', help='Format output as JSON array')
    parser.add_argument('-v', '--verbose', action='store_false', dest='quiet', default=True,
                        help='Enable verbose logging (INFO level)')
    arguments = parser.parse_args()

    if arguments.quiet:
        logging.getLogger().setLevel(logging.WARNING)

    try:
        response_page = _retrieve_page(arguments.target_url, arguments.mode)
    except Exception as error:
        print(f"Fetch failed: {error}", file=sys.stderr)
        sys.exit(1)

    if not arguments.selector:
        # Extract all visible text content by default
        full_text = response_page.extract_all_text(separator=' ', excluded_tags=('script', 'style', 'noscript'))
        print(full_text)
        return

    matched_nodes = response_page.select(arguments.selector)
    if not matched_nodes:
        print(f"No elements found matching: {arguments.selector}", file=sys.stderr)
        sys.exit(1)

    extracted_values = []
    for node in matched_nodes:
        if arguments.field == 'text':
            content = node.text_content() or node.text.strip() if node.text else ''
        elif arguments.field == 'html':
            content = node.html
        else:
            content = node.get(arguments.field, '')
        extracted_values.append(content.strip())

    if arguments.as_json:
        import json
        print(json.dumps(extracted_values, ensure_ascii=False, indent=2))
    else:
        for item in extracted_values:
            if item:
                print(item)

def _retrieve_page(url, mode_type):
    if mode_type == 'standard':
        from scrapling.fetchers import Fetcher
        return Fetcher.get(url)
    elif mode_type == 'bypass':
        from scrapling.fetchers import StealthyFetcher
        return StealthyFetcher.fetch(url, headless=True, wait_for_network_idle=True)
    elif mode_type == 'render':
        from scrapling.fetchers import DynamicFetcher
        return DynamicFetcher.fetch(url, headless=True, wait_for_network_idle=True)

if __name__ == '__main__':
    execute()

