# Default empty API info dictionary
api_info = {}

class BaseTrait(Service):
    def __init__(self, config=None):
        # Initialize with provided configuration or empty dict
        config = config if config is not None else {}
        self.config = config

        # Extract region and service info map from config
        region = config.get('region', REGION_CN_NORTH1)
        service_map = config.get('service_info_map', {})

        # Set up service and API info
        self.service_info = BaseTrait._fetch_service_info(region, service_map)
        self.api_info = BaseTrait._retrieve_api_info()

        # Handle authentication if credentials provided
        if config.get('ak') and config.get('sk'):
            self.set_access_key(config['ak'])
            self.set_secret_key(config['sk'])

        # Initialize parent class with service and API info
        super(BaseTrait, self).__init__(self.service_info, self.api_info)

    @staticmethod
    def _fetch_service_info(region, service_map):
        """Fetch service info for given region from the map"""
        service_info = service_map.get(region)
        if not service_info:
            raise Exception(f'BaseService does not support region: {region}')
        return service_info

    @staticmethod
    def _retrieve_api_info():
        """Return current API info dictionary"""
        return api_info

    def update_api_info(self, new_api_info):
        """Merge new API info into existing API info"""
        self.api_info = {**self.api_info, **new_api_info}
        return self

    def mcp_get(self, endpoint, query_params=None, allow_list=False):
        """Execute GET request and parse JSON response"""
        if query_params is None:
            query_params = {}

        response = self.get(endpoint, query_params, allow_list)
        if not response:
            raise Exception(f"{endpoint}: no response received")

        # Convert response to JSON-compatible format
        response_json = json.loads(json.dumps(response))
        return response_json

    def mcp_post(self, endpoint, query_params=None, payload=None):
        """Execute POST request with JSON body and parse response"""
        if query_params is None:
            query_params = {}
        if payload is None:
            payload = {}

        response = self.json(endpoint, query_params, payload)
        if not response:
            raise Exception(f"{endpoint}: no response received")

        # Convert response to JSON-compatible format
        response_json = json.loads(json.dumps(response))
        return response_json

