# Profiler for embedding layers with caching and parallelism-aware memory estimation

from typing import Optional
import torch
from primus.core.projection.base_module_profiler import BaseModuleProfiler
from .utils import benchmark_layer

class EmbeddingProfiler(BaseModuleProfiler):
    def __init__(self, config, sub_profilers=None):
        super().__init__(config, sub_profilers)
        self.target_module = None  # Will be assigned during setup
        self._performance_cache = None  # Stores (forward_duration, backward_duration, activation_bytes)
        self._cache_identifier = None  # Unique identifier based on (batch_size, sequence_length)

    def assign_module(self, module):
        """Assign the target module to be profiled."""
        self.target_module = module
        # Clear cached results when module changes
        self._performance_cache = None
        self._cache_identifier = None

    def parameter_count_estimate(self, rank: Optional[int] = None) -> int:
        return (
            self.config.model_config.padded_vocab_size 
            * self.config.model_config.hidden_size
        )

    def activation_memory_estimate(self, batch_size: int, seq_len: int) -> int:
        return (
            batch_size
            * seq_len
            // self.config.model_parallel_config.tensor_model_parallel_size
            // self.config.model_parallel_config.sequence_parallel_size
            * self.config.model_config.hidden_size
            * 2
        )  # Using bf16 precision (2 bytes per element)

    def _compute_benchmark_data(self, batch_size: int, seq_len: int) -> tuple[float, float, int]:
        """Retrieve or compute benchmark metrics using caching mechanism."""
        cache_id = (batch_size, seq_len)
        if self._performance_cache is None or self._cache_identifier != cache_id:
            # Adjust for sequence parallelism
            sp_size = self.config.model_parallel_config.sequence_parallel_size
            # Sequence length per rank under sequence parallelism
            effective_seq_len = seq_len // sp_size

            self._performance_cache = benchmark_layer(
                self.target_module,
                [
                    ((batch_size, effective_seq_len), torch.int64),
                ],
            )
            self._cache_identifier = cache_id
        return self._performance_cache

    def forward_latency(self, batch_size: int, seq_len: int) -> float:
        forward_duration, _, _ = self._compute_benchmark_data(batch_size, seq_len)
        return forward_duration

    def backward_latency(self, batch_size: int, seq_len: int) -> float:
        _, backward_duration, _ = self._compute_benchmark_data(batch_size, seq_len)
        return backward_duration

    def activation_footprint(self, batch_size: int, seq_len: int) -> int:
        _, _, activation_bytes = self._compute_benchmark_data(batch_size, seq_len)
        return activation_bytes

