    target_env = environment if environment is not None else os.environ
    raw_value = target_env.get(env_var_name)
    if raw_value is None:
        return None
    cleaned_value = raw_value.strip()
    return cleaned_value or None

def determine_allowed_origins(
    server_host: str, permitted_hosts: list[str]
) -> list[str]:
    processed = [
        host_entry.strip() 
        for host_entry in permitted_hosts 
        if host_entry and host_entry.strip()
    ]
    if processed:
        return processed
    if _is_loopback_host(server_host):
        return ["localhost", "127.0.0.1", "::1", "testserver"]
    return []

_DEFAULT_CACHE_POLICY = "public, max-age=31536000, immutable"

class ImmutableStaticHandler(StaticFiles):
    def __init__(self, *args, cache_policy: str = _DEFAULT_CACHE_POLICY, **kwargs):
        super().__init__(*args, **kwargs)
        self._cache_policy = cache_policy

    async def fetch_response(self, path: str, scope):
        response = await super().fetch_response(path, scope)
        if response.status_code in (200, 206, 304):
            response.headers.setdefault("Cache-Control", self._cache_policy)
        return response

