def determine_attention_backend():
    # Use environment variable if specified, otherwise use priority order
    env_backend = os.environ.get('DIFFSYNTH_ATTENTION_IMPLEMENTATION')
    if env_backend is not None:
        return env_backend.strip().lower()

    # Priority order: flash_attention_3 > flash_attention_2 > sage_attention > xformers > torch
    if FLASH_ATTN_3_AVAILABLE:
        return "flash_attention_3"
    elif FLASH_ATTN_2_AVAILABLE:
        return "flash_attention_2"
    elif SAGE_ATTN_AVAILABLE:
        return "sage_attention"
    elif XFORMERS_AVAILABLE:
        return "xformers"
    else:
        return "torch"

# Set the global attention backend
ATTENTION_IMPLEMENTATION = determine_attention_backend()

def reshape_tensor_for_pattern(tensor, src_pattern, dst_pattern, shape_dict=None):
    shape_dict = {} if shape_dict is None else shape_dict
    if src_pattern != dst_pattern:
        tensor = rearrange(tensor, f"{src_pattern} -> {dst_pattern}", **shape_dict)
    return tensor

def apply_rearrangement_to_qkv(query, key, value, q_src="b n s d", k_src="b n s d", v_src="b n s d", target="b n s d", shape_params=None):
    shape_params = {} if shape_params is None else shape_params
    query = reshape_tensor_for_pattern(query, q_src, target, shape_params)
    key = reshape_tensor_for_pattern(key, k_src, target, shape_params)
    value = reshape_tensor_for_pattern(value, v_src, target, shape_params)
    return query, key, value

def transform_output(output, output_format="b n s d", desired_format="b n s d", shape_params=None):
    shape_params = {} if shape_params is None else shape_params
    if output_format != desired_format:
        output = rearrange(output, f"{desired_format} -> {output_format}", **shape_params)
    return output

def pytorch_scaled_dot_product_attention(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", shape_params=None, mask=None, temperature=None):
    input_format, output_format = "b n s d", "b n s d"
    query, key, value = apply_rearrangement_to_qkv(query, key, value, q_format, k_format, v_format, input_format, shape_params)
    result = torch.nn.functional.scaled_dot_product_attention(query, key, value, mask, scale=temperature)
    result = transform_output(result, out_format, output_format, shape_params)
    return result

def flash_attn_v3_forward(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", shape_params=None, temperature=None):
    input_format, output_format = "b s n d", "b s n d"
    query, key, value = apply_rearrangement_to_qkv(query, key, value, q_format, k_format, v_format, input_format, shape_params)
    result = flash_attn_interface.flash_attn_func(query, key, value, softmax_scale=temperature)
    if isinstance(result, tuple):
        result = result[0]
    result = transform_output(result, out_format, output_format, shape_params)
    return result

def flash_attn_v2_forward(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", shape_params=None, temperature=None):
    input_format, output_format = "b s n d", "b s n d"
    query, key, value = apply_rearrangement_to_qkv(query, key, value, q_format, k_format, v_format, input_format, shape_params)
    result = flash_attn.flash_attn_func(query, key, value, softmax_scale=temperature)
    result = transform_output(result, out_format, output_format, shape_params)
    return result

def sage_attn_forward(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", shape_params=None, temperature=None):
    input_format, output_format = "b n s d", "b n s d"
    query, key, value = apply_rearrangement_to_qkv(query, key, value, q_format, k_format, v_format, input_format, shape_params)
    result = sageattn(query, key, value, sm_scale=temperature)
    result = transform_output(result, out_format, output_format, shape_params)
    return result

def xformers_mem_efficient_forward(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", shape_params=None, temperature=None):
    input_format, output_format = "b s n d", "b s n d"
    query, key, value = apply_rearrangement_to_qkv(query, key, value, q_format, k_format, v_format, input_format, shape_params)
    result = xops.memory_efficient_attention(query, key, value, scale=temperature)
    result = transform_output(result, out_format, output_format, shape_params)
    return result

def execute_attention(query, key, value, q_format="b n s d", k_format="b n s d", v_format="b n s d", out_format="b n s d", shape_params=None, mask=None, temperature=None, legacy_mode=False):
    # Use PyTorch SDPA if compatibility mode is enabled or if attention mask is provided
    if legacy_mode or (mask is not None):
        return pytorch_scaled_dot_product_attention(query, key, value, q_format, k_format, v_format, out_format, shape_params, mask, temperature)

    # Dispatch to appropriate attention implementation based on priority
    if ATTENTION_IMPLEMENTATION == "flash_attention_3":
        return flash_attn_v3_forward(query, key, value, q_format, k_format, v_format, out_format, shape_params, temperature)
    elif ATTENTION_IMPLEMENTATION == "flash_attention_2":
        return flash_attn_v2_forward(query, key, value, q_format, k_format, v_format, out_format, shape_params, temperature)
    elif ATTENTION_IMPLEMENTATION == "sage_attention":
        return sage_attn_forward(query, key, value, q_format, k_format, v_format, out_format, shape_params, temperature)
    elif ATTENTION_IMPLEMENTATION == "xformers":
        return xformers_mem_efficient_forward(query, key, value, q_format, k_format, v_format, out_format, shape_params, temperature)
    else:
        return pytorch_scaled_dot_product_attention(query, key, value, q_format, k_format, v_format, out_format, shape_params, None, temperature)

