import re
from scraper.config import MONGO_URI, MONGO_DATABASE, MONGO_COLLECTION
from scraper.logger import log

class MongoDBHandler:
    def __init__(self):
        self._db_client = None
        self._db_collection = None

    def _establish_connection(self):
        if self._db_collection is not None:
            return
        from pymongo import MongoClient
        self._db_client = MongoClient(MONGO_URI)
        database = self._db_client[MONGO_DATABASE]
        self._db_collection = database[MONGO_COLLECTION]

    def store_item(self, item: dict) -> str:
        if not isinstance(item, dict):
            raise TypeError(f"store_item expected dict, got {type(item)}")
        self._establish_connection()
        try:
            self._db_collection.insert_one(item)
            return "record inserted successfully"
        except Exception as err:
            log(f"failed to insert record: {err}", "error")
            return "storage operation failed"

    def search_by_url_prefix(self, url_pattern: str) -> list:
        self._establish_connection()
        safe_pattern = re.escape(url_pattern)
        compiled_regex = re.compile(rf"^{safe_pattern}", re.IGNORECASE)
        return list(self._db_collection.find({"url": compiled_regex}))

    def search_by_attribute(self, attr_name: str, value_pattern: str) -> list:
        self._establish_connection()
        try:
            safe_value = re.escape(value_pattern)
            regex_pattern = re.compile(rf"^{safe_value}", re.IGNORECASE)
            return list(self._db_collection.find({attr_name: regex_pattern}))
        except Exception as exception:
            log(f"query error on attribute '{attr_name}': {exception}", "error")
            return []

_default_handler = MongoDBHandler()

def persist_data(data: dict) -> str:
    return _default_handler.store_item(data)

def fetch_by_domain(domain_name: str) -> list:
    return _default_handler.search_by_url_prefix(domain_name)

def fetch_by_category(category_name: str, category_field: str) -> list:
    return _default_handler.search_by_attribute(category_field, category_name)

import os
import subprocess
import sys
import json
import re

def fetch_video_formats(url):
    try:
        # Execute yt-dlp to extract format info without playlist
        process = subprocess.run(
            ['yt-dlp', '--dump-json', '--no-playlist', url], 
            stdout=subprocess.PIPE, 
            stderr=subprocess.PIPE, 
            text=True
        )

        if process.returncode != 0:
            return {"error": process.stderr.strip()}

        video_info = json.loads(process.stdout)
        available_formats = video_info.get('formats', [])

        # Process and deduplicate formats by resolution
        simplified_list = []
        resolutions_seen = set()

        # Sort formats by vertical resolution (descending)
        for fmt in sorted(available_formats, key=lambda x: (x.get('height') or 0), reverse=True):
            height = fmt.get('height')
            extension = fmt.get('ext')

            # Only include formats with valid video streams
            if height and height > 0 and fmt.get('vcodec') != 'none':
                res_label = f"{height}p"

                if res_label not in resolutions_seen:
                    simplified_list.append({
                        "format_id": fmt.get('format_id'),
                        "resolution": res_label,
                        "ext": extension,
                        "note": fmt.get('format_note') or fmt.get('resolution')
                    })
                    resolutions_seen.add(res_label)

        return {
            "formats": simplified_list, 
            "title": video_info.get('title'),
            "duration": video_info.get('duration_string'),
            "uploader": video_info.get('uploader')
        }
    except Exception as ex:
        return {"error": str(ex)}

def save_video(url, format_identifier, target_filename):
    try:
        # Sanitize filename to prevent injection issues
        sanitized = re.sub(r'[^a-zA-Z0-9._-]', '_', target_filename)
        if not sanitized.lower().endswith('.mp4'):
            sanitized += '.mp4'

        # Build download command with audio+video merge
        command = [
            'yt-dlp', 
            '-f', f'{format_identifier}+bestaudio/best', 
            '--merge-output-format', 'mp4', 
            '--no-playlist',
            '-o', sanitized, 
            url
        ]

        execution = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

        if execution.returncode != 0:
            return {"error": execution.stderr.strip()}

        if os.path.isfile(sanitized):
            return {"success": True, "path": sanitized}
        else:
            return {"error": "Download failed - file not found."}

    except Exception as err:
        return {"error": str(err)}
    finally:
        # Note: File cleanup is intentionally omitted here
        # to allow the calling process to handle it after confirmation
        pass

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print(json.dumps({"error": "Usage: python3 download.py [info|download] [url] [format_id]"}))
        sys.exit(1)

    mode = sys.argv[1]
    link = sys.argv[2]

    if mode == "info":
        print(json.dumps(fetch_video_formats(link)))
    elif mode == "download":
        if len(sys.argv) < 4:
            print(json.dumps({"error": "Format ID required for download operation"}))
            sys.exit(1)
        fmt_id = sys.argv[3]
        temp_name = f"dl_{fmt_id}.mp4"
        print(json.dumps(save_video(link, fmt_id, temp_name)))

import json
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
from pathlib import Path

# Configuration paths
ATP_DIR = Path.home() / ".atp"
TRUST_DB = ATP_DIR / "trust.json"
INTERACTIONS_DB = ATP_DIR / "interactions.jsonl"
DASHBOARD_FILE = Path(__file__).parent / "dashboard.html"
SERVER_PORT = 8420

class ATPRequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/api/trust":
            trust_data = self._get_trust_data()
            self._send_json(trust_data)
        elif self.path == "/api/interactions":
            interactions_data = self._get_interactions()
            self._send_json(interactions_data)
        elif self.path in ["/", "/dashboard"]:
            self.send_response(200)
            self.send_header("Content-Type", "text/html")
            self.end_headers()
            self.wfile.write(DASHBOARD_FILE.read_bytes())
        else:
            self.send_error(404, "Not Found")

    def _send_json(self, data):
        response_body = json.dumps(data).encode('utf-8')
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", len(response_body))
        self.end_headers()
        self.wfile.write(response_body)

    def _get_trust_data(self):
        if TRUST_DB.is_file():
            try:
                return json.loads(TRUST_DB.read_text())
            except (json.JSONDecodeError, IOError):
                pass
        return {"agents": {}, "edges": [], "self": {}}

    def _get_interactions(self):
        if not INTERACTIONS_DB.exists():
            return []

        interaction_records = []
        try:
            content = INTERACTIONS_DB.read_text().strip()
            if content:
                for line in content.splitlines():
                    stripped_line = line.strip()
                    if stripped_line:
                        try:
                            interaction_records.append(json.loads(stripped_line))
                        except json.JSONDecodeError:
                            continue
        except IOError:
            pass

        return interaction_records

    def log_message(self, format_str, *args):
        # Suppress logging output
        pass

if __name__ == "__main__":
    server_address = ("127.0.0.1", SERVER_PORT)
    httpd = HTTPServer(server_address, ATPRequestHandler)
    print(f"ATP Dashboard running at http://localhost:{SERVER_PORT}")
    httpd.serve_forever()

