import torch
from megatron.training import get_args
from megatron.core import mpu
from megatron.core.transformer.module import fp32_to_float16, float16_to_fp32, Float16Module

def _apply_dtype_conversion(module, convert_fn, exclude_modules):
    """Apply dtype conversion to module unless it's in the exclusion list."""
    if module in exclude_modules:
        return module
    return convert_fn(module)

def _convert_module_dtype(module, target_dtype, exclude_modules):
    """Recursively apply dtype conversion to all submodules except excluded ones."""
    for name, submodule in module.named_modules():
        if submodule in exclude_modules:
            continue
        # Skip non-leaf modules (they'll be handled via their parameters)
        if not list(submodule.children()):
            converted = _apply_dtype_conversion(submodule, 
                                                (lambda m: m.to(target_dtype)), 
                                                exclude_modules)
            # Replace submodule in parent if needed (simplified here)
            # In practice, Megatron may handle this differently; we keep original semantics
    return module

def float16Module_init(self, config, module):
    super(Float16Module, self).__init__(config)

    ae_config = getattr(config.mm.model, "ae", None)
    ae_uses_fp32 = False

    # Handle AE model separately if it's configured as FP32
    if ae_config is not None and getattr(ae_config, "dtype", None) == torch.float32:
        module.ae = module.ae.float()
        ae_uses_fp32 = True

    # Determine target dtype based on config
    if config.fp16:
        if ae_uses_fp32:
            exclude_list = [module.ae]
            converted_module = _convert_module_dtype(module, torch.float16, exclude_list)
        else:
            converted_module = module.half()
        def convertor(val):
            return val.half()
    elif config.bf16:
        if ae_uses_fp32:
            exclude_list = [module.ae]
            converted_module = _convert_module_dtype(module, torch.bfloat16, exclude_list)
        else:
            converted_module = module.bfloat16()
        def convertor(val):
            return val.bfloat16()
    else:
        raise RuntimeError("Unsupported precision mode: neither fp16 nor bf16 enabled")

    self.add_module("module", converted_module)
    self.dtype_convert_func = convertor

def float16Module_forward(self, *inputs, **kwargs):
    args = get_args()

    # Convert inputs to half precision only on first pipeline stage
    if mpu.is_pipeline_first_stage():
        ae_cfg = getattr(args.mm.model, "ae", None)
        if ae_cfg is None or getattr(ae_cfg, "dtype", None) != torch.float32:
            inputs = fp32_to_float16(inputs, self.dtype_convert_func)

    # Run forward pass
    outputs = self.module(*inputs, **kwargs)

    # Convert outputs back to FP32 on last pipeline stage
    if mpu.is_pipeline_last_stage():
        outputs = float16_to_fp32(outputs)

