# Helper functions to convert Narwhals frames to Polars equivalents

import polars as pl
import narwhals as nw
from typing import Any, overload
from narwhals.typing import DataFrameT, Frame, FrameT, LazyFrameT


def to_eager_polars(frame: Frame) -> pl.DataFrame:
    """Convert any Narwhals frame to an eager Polars DataFrame."""
    return frame.lazy().collect().to_polars()


def to_lazy_polars(nw_lazy_frame: nw.LazyFrame[Any]) -> pl.LazyFrame:
    """Convert a Narwhals lazy frame to a Polars lazy frame.

    If the input is already backed by Polars, return its native representation directly.
    Otherwise, collect and convert to Polars, then make it lazy again.
    """
    if nw_lazy_frame.implementation == nw.Implementation.POLARS:
        return nw_lazy_frame.to_native()
    else:
        return nw_lazy_frame.collect().to_polars().lazy()


@overload
def adapt_to_polars_backend(df: DataFrameT) -> DataFrameT: ...
@overload
def adapt_to_polars_backend(lf: LazyFrameT) -> LazyFrameT: ...


def adapt_to_polars_backend(frame: FrameT) -> FrameT:
    """Ensure the given frame uses Polars as its backend implementation.

    - If already using Polars, return unchanged.
    - For Narwhals DataFrames backed by other implementations, convert via Polars.
    - For Narwhals LazyFrames backed by other implementations, collect first, then convert.
    """
    if frame.implementation == nw.Implementation.POLARS:
        return frame

    elif isinstance(frame, nw.DataFrame):
        return nw.from_native(frame.to_polars())

    elif isinstance(frame, nw.LazyFrame):
        return nw.from_native(
            frame.collect().to_polars(),
        ).lazy()

    else:
        raise TypeError(f"Unsupported frame type encountered: {type(frame)}")


__all__ = ["to_eager_polars", "to_lazy_polars", "adapt_to_polars_backend"]

import math
import torch
import torch.nn as nn
from einops import rearrange, repeat

def generate_time_embeddings(time_indices, embedding_dim, max_duration=10000, only_duplicate=False, tensor_type=torch.float32):
    if not only_duplicate:
        half_dim = embedding_dim // 2
        angular_freqs = torch.exp(-math.log(max_duration) * torch.arange(start=0, end=half_dim, dtype=torch.float32, device=time_indices.device) / half_dim)
        scaled_inputs = time_indices.unsqueeze(1).float() * angular_freqs.unsqueeze(0)
        combined_features = torch.cat([torch.cos(scaled_inputs), torch.sin(scaled_inputs)], dim=-1)
        if embedding_dim % 2 == 1:
            combined_features = torch.cat([combined_features, torch.zeros_like(combined_features[:, :1])], dim=-1)
    else:
        combined_features = repeat(time_indices, "b -> b d", d=embedding_dim)
    return combined_features.to(tensor_type)

class TemporalFeatureMapper(nn.Module):
    def __init__(self, feature_size, projection_dim=None, max_duration=10000, only_duplicate=False):
        super().__init__()
        self.feature_size = feature_size
        self.projection_dim = projection_dim if projection_dim is not None else feature_size
        self.max_duration = max_duration
        self.only_duplicate = only_duplicate
        self.temporal_projector = nn.Sequential(
            nn.Linear(self.feature_size, projection_dim),
            nn.SiLU(),
            nn.Linear(projection_dim, projection_dim),
        )

    @property
    def data_type(self) -> torch.dtype:
        """Determines the data type of the module (assuming uniform parameter types)."""
        parameters = tuple(self.parameters())
        if len(parameters) > 0:
            return parameters[0].dtype
        else:
            buffers = tuple(self.buffers())
            return buffers[0].dtype

    def forward(self, time_steps):
        encoded = generate_time_embeddings(time_steps, self.feature_size, self.max_duration, self.only_duplicate, tensor_type=self.data_type)
        return self.temporal_projector(encoded)

from collections.abc import Mapping as _Mapping

class JavaScriptCode(str):
    """Represents BSON's JavaScript code type with optional scope.

    Raises :class:`TypeError` if `code` is not a string or `scope` is 
    neither None nor a dictionary-like object.

    The scope can be provided via the `scope` parameter or through 
    keyword arguments. Keyword arguments take precedence over the 
    `scope` dictionary for overlapping keys.

    :Parameters:
      - `code`: A string containing JavaScript code or another Code-like 
        object. If it's another Code instance, its scope will be inherited.
      - `scope` (optional): Dictionary mapping variable names to values.
        Defaults to ``None``.
      - `**kwargs` (optional): Additional scope variables passed as 
        keyword arguments, overriding any conflicting entries in `scope`.

    .. versionchanged:: 3.4
      Default value for :attr:`scope` changed from ``{}`` to ``None``.
    """
    _type_marker = 13

    def __new__(cls, code, scope=None, **kwargs):
        # Validate input types
        if not isinstance(code, str):
            raise TypeError("code must be an instance of str")

        # Create the string subclass instance
        self = str.__new__(cls, code)

        # Initialize scope from parent Code object if applicable
        try:
            parent_scope = code.scope
        except AttributeError:
            parent_scope = None

        # Build final scope
        final_scope = parent_scope

        # Apply explicit scope parameter if provided
        if scope is not None:
            if not isinstance(scope, _Mapping):
                raise TypeError("scope must be an instance of dict")
            if final_scope is not None:
                merged_scope = dict(final_scope)
                merged_scope.update(scope)
                final_scope = merged_scope
            else:
                final_scope = dict(scope)

        # Apply keyword arguments (highest priority)
        if kwargs:
            if final_scope is not None:
                merged_scope = dict(final_scope)
                merged_scope.update(kwargs)
                final_scope = merged_scope
            else:
                final_scope = dict(kwargs)

        # Store private scope reference
        self._JavaScriptCode__scope = final_scope
        return self

    @property
    def scope(self):
        """Return the scope dictionary associated with this JavaScript code."""
        return self._JavaScriptCode__scope

    def __repr__(self):
        return "JavaScriptCode(%s, %r)" % (str.__repr__(self), self._JavaScriptCode__scope)

    def __eq__(self, other):
        if isinstance(other, JavaScriptCode):
            return (self._JavaScriptCode__scope, str(self)) == (
                other._JavaScriptCode__scope, str(other)
            )
        return False

    __hash__ = None

    def __ne__(self, other):
        return not self.__eq__(other)

import re

def extract_sections(text: str):
    """Parse character blocks from combined SOUL markdown (approximate parsing)."""
    regex = r'## ([^\n]+)\n(.*?)(?=\n## [^\n]+\n|$)'
    return re.findall(regex, text, re.DOTALL)

def combine_soul_text(base: str, addition: str) -> str:
    """Merge without duplication by matching section header and body content."""
    if not base.strip():
        return addition
    if addition.strip() in base:
        return base
    return base.rstrip() + "\n\n" + addition.lstrip()

