from ..process import Process
from ..command_decorators import command
from . import register_command

@command(needs_path_resolution=True)
@register_command('delete')
def cmd_delete_file(process: Process) -> int:
    """
    Delete file or directory (alias for 'rm')
    Usage: delete [-r] path...
    """
    if len(process.args) == 0:
        process.stderr.write("delete: no arguments provided\n")
        return 1

    if not hasattr(process, 'filesystem') or not process.filesystem:
        process.stderr.write("delete: filesystem is unavailable\n")
        return 1

    force_recursive = False
    target_paths = []

    for item in process.args:
        if item in ['-r', '-rf']:
            force_recursive = True
        else:
            target_paths.append(item)

    if len(target_paths) == 0:
        process.stderr.write("delete: no target specified\n")
        return 1

    overall_status = 0

    for location in target_paths:
        try:
            # Delegates removal to AGFS client
            process.filesystem.client.remove(location, recursive=force_recursive)
        except Exception as ex:
            detail = str(ex)
            process.stderr.write(f"delete: cannot remove '{location}': {detail}\n")
            overall_status = 1

    return overall_status

import binascii
import os
