def hex_string_to_binary(hex_input: str) -> bytes:
    """Transform a hexadecimal string into its binary representation."""
    return binascii.unhexlify(hex_input)

def persist_to_file(binary_data: bytes, destination: str) -> str:
    # Ensure the directory structure exists
    directory = os.path.dirname(destination)
    if directory and not os.path.exists(directory):
        os.makedirs(directory, exist_ok=True)

    with open(destination, 'wb') as file:
        file.write(binary_data)

    return destination

def fetch_from_web(source_url: str, target_file: str) -> str:
    with urllib.request.urlopen(source_url, timeout=60) as response:
        response.raise_for_status()
        content = response.read()
    return persist_to_file(content, target_file)

