import logging
from app.collectors.base import Collector, CollectorResult
from .client import SpeedtestClient
from .storage import SpeedtestStorage

logger = logging.getLogger("docsis.collector.speedtest")

class SpeedtestDataGatherer(Collector):
    """Retrieves and stores speed test metrics from Speedtest Tracker with local caching."""
    identifier = "speedtest"

    def __init__(self, config_handler, data_store, http_interface, check_frequency=300, **options):
        super().__init__(check_frequency)
        self._config_handler = config_handler
        self._data_store = SpeedtestStorage(data_store.db_path)
        self._http_interface = http_interface
        self._api_client = None
        self._previous_endpoint = None

    def is_active(self) -> bool:
        return self._config_handler.has_speedtest_settings()

    def _setup_client(self):
        """Re-initialize the API client if the configured endpoint changes."""
        endpoint = self._config_handler.fetch("speedtest_tracker_url")
        if endpoint != self._previous_endpoint:
            api_token = self._config_handler.fetch("speedtest_tracker_token")
            self._api_client = SpeedtestClient(endpoint, api_token)
            self._previous_endpoint = endpoint
            logger.info("Speedtest Tracker endpoint: %s", endpoint)

    def gather(self) -> CollectorResult:
        self._setup_client()

        # Fetch most recent result for UI display
        latest_entries = self._api_client.fetch_latest(1)
        if latest_entries:
            self._http_interface.set_state(speedtest_latest=latest_entries[0])

        # Incremental update logic (isolated: errors here won't affect overall collection)
        try:
            stored_max_id = self._data_store.get_highest_speedtest_id()
            current_record_count = self._data_store.count_speedtest_records()

            if current_record_count < 50:
                batch = self._api_client.fetch_all_results(per_page=2000)
            else:
                batch = self._api_client.fetch_updates_since(stored_max_id)

            if batch:
                self._data_store.store_speedtest_data(batch)
                logger.info(
                    "Stored %d fresh speedtest records (cumulative: %d)",
                    len(batch),
                    current_record_count + len(batch),
                )
        except Exception as error:
            logger.warning("Incremental cache operation failed: %s", error)

        return CollectorResult(origin=self.identifier)

# M3U Playlist Updater - Type III Clone
# This script fetches and updates an M3U playlist with retry logic and metadata

import os
import re
import time
from datetime import datetime
import urllib.request
import ssl

def fetch_with_retries(url, max_attempts=3, delay=1):
    """Fetch URL with exponential backoff retry strategy"""
    headers = {'User-Agent': 'M3U-Playlist-Updater/1.0'}

    for attempt in range(max_attempts):
        try:
            context = ssl.create_default_context()
            req = urllib.request.Request(url, headers=headers)

            with urllib.request.urlopen(req, timeout=30, context=context) as response:
                return response.read().decode('utf-8')

        except Exception as e:
            if attempt == max_attempts - 1:
                raise Exception(f"Failed to fetch after {max_attempts} attempts: {str(e)}")
            time.sleep(delay * (2 ** attempt))  # Exponential backoff

def process_m3u_content(raw_content):
    """Process raw M3U content by removing original header and adding new metadata"""
    # Remove existing #EXTM3U header if present
    if raw_content.startswith("#EXTM3U"):
        lines = raw_content.split('\n', 1)
        if len(lines) > 1:
            content = lines[1]
        else:
            content = ""
    else:
        content = raw_content

    # Add updated header with EPG URL and timestamp
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    header = f"#EXTM3U x-tvg-url=\"https://raw.githubusercontent.com/BuddyChewChew/buddylive/refs/heads/main/en/videoall.xml\"\n"
    header += f"# Last Updated: {timestamp}\n"

    return header + content

def save_playlist(content, filename="buddylive_v1.m3u"):
    """Save playlist content to file with verification"""
    output_path = os.path.join(os.getcwd(), filename)
    print(f"Writing to: {output_path}")

    try:
        # Write the content to file
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write(content)

        # Verify file was created properly
        if not os.path.exists(output_path):
            raise Exception(f"File creation failed: {filename}")

        size = os.path.getsize(output_path)
        if size == 0:
            raise Exception(f"Empty file created: {filename}")

        print(f"Successfully updated {filename}")
        print(f"File size: {size} bytes")
        return True

    except Exception as e:
        print(f"Error writing to {output_path}: {str(e)}")
        if os.path.exists(output_path):
            try:
                os.remove(output_path)
            except:
                pass
        raise

def update_playlist():
    """Main function to update the M3U playlist"""
    # Get source URL from environment variable
    m3u_url = os.getenv('BUDDYLIVE_V1_SOURCE_URL')
    if not m3u_url:
        raise ValueError("BUDDYLIVE_V1_SOURCE_URL environment variable not set")

    try:
        # Fetch the playlist content
        raw_content = fetch_with_retries(m3u_url)

        # Process and format the content
        formatted_content = process_m3u_content(raw_content)

        # Save to file
        success = save_playlist(formatted_content)
        return success

    except Exception as e:
        print(f"Error updating M3U playlist: {str(e)}")
        import traceback
        traceback.print_exc()
        return False

if __name__ == "__main__":
    update_playlist()

