import subprocess
from subprocess import Popen
from threading import Event, Thread
from typing import List

def terminate_threads(thread_list: List[Thread]):
    """Gracefully terminate a collection of threads"""
    for t in thread_list:
        t.join(timeout=5)

def terminate_subprocesses(proc_list: List[Popen]):
    """Safely terminate a collection of subprocesses"""
    for proc in proc_list:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=60)
            except subprocess.TimeoutExpired:
                proc.kill()

def watch_subprocess(proc: Popen, termination_flag: Event, error_log: list, label: str):
    """Observe a subprocess and log errors to shared queue."""
    proc.wait()
    if proc.returncode != 0:
        err_msg = f"{label.capitalize()} failed with exit code {proc.returncode}"
        if proc.stderr:
            try:
                stderr_output = proc.stderr.read().decode('utf-8')
                if stderr_output.strip():
                    err_msg += f"\n{stderr_output}"
            except Exception:
                pass
        error_log.append(RuntimeError(err_msg))
    termination_flag.set()

from __future__ import annotations
from typing import Any
import torch

def infer_token_denominator(
    input_data: dict[str, Any],
    fallback: torch.Tensor,
) -> torch.Tensor:
    """Compute the token mask for statistics logging.
    When context parallelism is used, intermediate tensors like ``loss_mask`` or
    model outputs may be partitioned, but the original micro-batch metadata still
    represents the complete logical sequence. Prioritize this metadata for
    determining ``n_tokens`` to ensure consistent statistics regardless of
    context parallelism.
    """
    device = fallback.device
    common_kwargs = {"dtype": torch.bool, "device": device}

    # First, try using attention_mask if available
    attention_mask = input_data.get("attention_mask")
    if isinstance(attention_mask, torch.Tensor):
        return torch.ones_like(attention_mask, **common_kwargs)

    # Next, try cu_seqlens if present and non-empty
    cu_seqlens = input_data.get("cu_seqlens")
    if isinstance(cu_seqlens, torch.Tensor) and cu_seqlens.numel() > 0:
        total_len = int(cu_seqlens[-1].item())
        return torch.ones(total_len, **common_kwargs)

    # Finally, consider input_ids only if its shape matches fallback
    input_ids = input_data.get("input_ids")
    if isinstance(input_ids, torch.Tensor) and input_ids.shape == fallback.shape:
        return torch.ones_like(input_ids, **common_kwargs)

    # Default case: use fallback tensor's shape
    return torch.ones_like(fallback, **common_kwargs)

