class WeiboAPI:
    def __init__(self, access_token: str, endpoint_base: str):
        self.access_token = access_token
        self.endpoint_base = endpoint_base

    def fetch_search_results_v2(self, query: str, begin_date: str, begin_hour: int, 
                                finish_date: str, finish_hour: int, current_page: int):
        api_path = f"{self.endpoint_base}/api/weibo/search-all/v2"
        parameters = {
            "token": self.access_token,
            "q": query,
            "startDay": begin_date,
            "startHour": begin_hour,
            "endDay": finish_date,
            "endHour": finish_hour,
            "page": current_page,
        }

        pagination_flag = False
        response_status, payload, error_msg = request_util.get_request_page(api_path, parameters)

        try:
            if payload and isinstance(payload, dict):
                if payload.get("has_next_page", False):
                    pagination_flag = True
        except Exception as err:
            logger.warning(f"Pagination parsing failed at {api_path}. Please contact support for assistance.")

        return response_status, payload, error_msg, pagination_flag

    def fetch_search_results_v3(self, search_term: str, page_number: int):
        api_endpoint = f"{self.endpoint_base}/api/weibo/search-all/v3"
        query_params = {
            "token": self.access_token,
            "q": search_term,
            "page": page_number,
        }

        has_more_pages = False
        status_code, response_body, error_description = request_util.get_request_page(api_endpoint, query_params)

        try:
            if response_body and isinstance(response_body, dict):
                if response_body.get("cards"):
                    has_more_pages = True
        except Exception as exc:
            logger.warning(f"Pagination parsing issue at {api_endpoint}. Reach out to developers for resolution.")

        return status_code, response_body, error_description, has_more_pages

