# Calculate total embedding cost based on token count and provider model

from decimal import Decimal
from typing import Dict
from api.services.configuration.registry import ServiceProviders
from .models import PricingModel


class TokenBasedEmbeddingCost(PricingModel):
    """Pricing calculator for tokenized embedding services."""

    def __init__(self, cost_per_million_tokens: Decimal):
        """Initialize with price per million tokens.
        Args:
            cost_per_million_tokens: Cost for one million tokens
        """
        self.cost_per_million = cost_per_million_tokens

    def compute_expense(self, tokens_used: int) -> Decimal:
        """Compute cost for given number of tokens."""
        return (Decimal(tokens_used) * self.cost_per_million) / 1_000_000


