import logging
import litellm
import config.config as _config

logger = logging.getLogger(__name__)

class StreamingNotSupportedException(Exception):
    """Raised when the selected LLM lacks streaming support but it's required."""

    def __init__(self, agent_id: str, model_name: str, explanation: str):
        self.agent_id = agent_id
        self.model_name = model_name
        self.explanation = explanation
        super().__init__(explanation)

def check_streaming_support(model_identifier: str) -> tuple[bool, Exception | None]:
    """
    Determine if the specified model supports native streaming.

    Returns:
        (True, None) if streaming is supported,
        (False, None) if metadata indicates no support or field missing,
        (False, exception) if an error occurred during lookup.
    """
    try:
        model_details = litellm.get_model_info(model=model_identifier)
        if model_details.get("supports_native_streaming"):
            return (True, None)
        return (False, None)
    except (litellm.NotFoundError, litellm.BadRequestError, 
            litellm.APIConnectionError, litellm.APIError, litellm.Timeout) as exc:
        logger.debug("Failed to retrieve streaming info for %s: %s", model_identifier, exc)
        return (False, exc)
    except Exception as exc:
        logger.warning("Unexpected issue while checking model %s: %s", model_identifier, exc)
        return (False, exc)

def enforce_streaming_requirement(agent_label: str, model_id: str) -> None:
    """
    Validate that the model supports streaming when strict enforcement is enabled.

    Raises StreamingNotSupportedException if streaming is required but not available.
    """
    if not _config.ENSURE_STREAMING_LLM:
        return

    has_support, failure = check_streaming_support(model_id)

    if has_support:
        logger.info("[%s] Streaming requirement verified.", agent_label or "agent")
        return

    error_msg = (
        f"Selected model does not support streaming. "
        f"Choose a model with streaming capability (e.g., openai/gpt-4o)."
    )

    if failure is not None:
        if agent_label:
            logger.error("[%s] %s Model: %s (root cause: %s)", 
                        agent_label, error_msg, model_id, failure)
        else:
            logger.error("%s Model: %s (root cause: %s)", 
                        error_msg, model_id, failure)
        raise StreamingNotSupportedException(
            agent_id=agent_label, 
            model_name=model_id, 
            explanation=error_msg
        ) from failure

    if agent_label:
        logger.error("[%s] %s Model: %s", agent_label, error_msg, model_id)
    else:
        logger.error("%s Model: %s", error_msg, model_id)
    raise StreamingNotSupportedException(
        agent_id=agent_label, 
        model_name=model_id, 
        explanation=error_msg
    )

