class SimpleKVCache:
    def __init__(self, num_layers: int):
        self.key_storage = {layer: None for layer in range(num_layers)}
        self.value_storage = {layer: None for layer in range(num_layers)}

    @property
    def layers_count(self) -> int:
        return len(self.key_storage)

