# Adapted from https://github.com/Shenyi-Z/TaylorSeer/blob/main/TaylorSeers-xDiT/taylorseer_flux/cache_functions/cache_init.py
def setup_cache_system(self, step_count: int) -> tuple:
    """
    Prepare cache structures for inference.
    """
    cache_map = {}
    storage = {}
    index_tracker = {}

    # Initialize base level (-1)
    storage[-1] = {}
    index_tracker[-1] = {}
    index_tracker["layer_index"] = {}

    # Stream-specific containers
    storage[-1]["layers_stream"] = {}
    index_tracker[-1]["layer_streams"] = {}

    # Global counter
    cache_map["step_counter"] = 0

    # Setup per-layer structures
    for idx in range(len(self.language_model.model.layers)):
        storage[-1]["layers_stream"][idx] = {}
        index_tracker[-1][idx] = {}

    # Configuration flags and parameters
    cache_map["Delta-DiT"] = False
    cache_map["cache_mode"] = "random"
    cache_map["index_store"] = index_tracker
    cache_map["data_store"] = storage
    cache_map["freshness_policy"] = "ToCa"
    cache_map["freshness_ratio"] = 0.0
    cache_map["freshness_limit"] = 3
    cache_map["soft_fresh_coefficient"] = 0.0
    cache_map["taylor_enabled"] = True
    cache_map["highest_order"] = 6
    cache_map["initial_boost"] = 5

    # Current state tracking
    current_state = {}
    current_state["active_steps"] = [0]
    current_state["current_step"] = 0
    current_state["total_steps"] = step_count

    return cache_map, current_state

