# Extract text content from a DOCX file using python-docx library

from docx import Document
import sys
import os

def get_text_from_docx(file_path):
    content = ""
    try:
        doc = Document(file_path)
        for para in doc.paragraphs:
            content += para.text + "\n"
        return content
    except Exception as error:
        return f"Failed to extract text: {error}"

if __name__ == "__main__":
    if len(sys.argv) >= 2:
        input_file = sys.argv[1]
        if os.path.isfile(input_file):
            result = get_text_from_docx(input_file)
            print(result)
        else:
            print(f"Error: File does not exist at {input_file}")
    else:
        print("Usage: python extract_docx.py <path_to_docx_file>")

