# Monitor MinIO buckets for new objects and process them

import logging
import time
from pathlib import Path
from threading import Thread
from common.dependencies import get_file_scheduling_service, get_lazybytes_service
from minio import Minio
from minio.datatypes import Bucket
from crawler.settings import settings

logger = logging.getLogger(__name__)

CHECK_INTERVAL_SECONDS: int = 300
READ_BUFFER_SIZE: int = 64 * 1024


class MinioBucketMonitor:
    def __init__(self, client: Minio):
        self.minio_client = client
        self.active_monitors: dict[Bucket, Thread] = {}

    def _cleanup_inactive_threads(self):
        # Identify dead threads first to avoid modifying dict during iteration
        inactive_buckets = []
        for bucket, monitor in self.active_monitors.items():
            if not monitor.is_alive():
                logger.info("Cleaning up stopped monitor for bucket: %s", bucket)
                inactive_buckets.append(bucket)
        # Remove dead monitors after collection
        for bucket in inactive_buckets:
            del self.active_monitors[bucket]

    def _start_monitoring_for_new_buckets(self):
        for bucket in self.minio_client.list_buckets():
            if bucket not in self.active_monitors:
                logger.info("New bucket found: %s", bucket)
                self._spawn_bucket_monitor(bucket)

    def _spawn_bucket_monitor(self, bucket: Bucket):
        monitor_thread = BucketFileMonitor(self.minio_client, bucket)
        monitor_thread.start()
        self.active_monitors[bucket] = monitor_thread

    def run_forever(self):
        while True:
            self._cleanup_inactive_threads()
            self._start_monitoring_for_new_buckets()
            time.sleep(CHECK_INTERVAL_SECONDS)


class BucketFileMonitor(Thread):
    def __init__(self, client: Minio, bucket: Bucket):
        super().__init__()
        self.client = client
        self.bucket = bucket

    def run(self):
        self._process_existing_files()
        self._watch_for_new_files()

    def _store_file(self, object_key: str):
        logger.info("Processing file %s from bucket %s", object_key, self.bucket.name)
        full_path = Path(f"//{self.bucket.name}/{object_key}")
        source_identifier = f"{settings.crawler_source_id}/{self.bucket.name}"

        # Stream object content in chunks
        object_stream = self.client.get_object(
            self.bucket.name, object_key
        ).stream(READ_BUFFER_SIZE)  # type: ignore

        get_file_scheduling_service().index_file(
            full_name=str(full_path),
            file_content=get_lazybytes_service().from_generator(object_stream),
            source_id=source_identifier,
            parent_id=None,
        )

    def _process_existing_files(self):
        objects = self.client.list_objects(self.bucket.name, recursive=True)
        for obj in objects:
            if obj.object_name is not None:
                self._store_file(obj.object_name)

    def _watch_for_new_files(self):
        with self.client.listen_bucket_notification(
            self.bucket.name,
            prefix="",
            events=["s3:ObjectCreated:*"],  # type: ignore
        ) as notification_events:
            for event_batch in notification_events:
                for record in event_batch.get("Records", []):
                    key = record["s3"]["object"]["key"]
                    self._store_file(key)

