    def __init__(self, model_path, config, device, lora_path=None, lora_strength=1.0):
        super().__init__(model_path, config, device, lora_path=lora_path, lora_strength=lora_strength)

    def _load_ckpt(self, unified_dtype, sensitive_layer):
        # Load from configured path and extract generator weights if EMA present
        ckpt_path = self.config["sf_model_path"]
        raw_state = torch.load(ckpt_path, map_location="cpu")
        generator_key = "generator_ema"
        state_dict = raw_state.get(generator_key, raw_state)

        # Strip 'module.' prefix and cast to target dtype + device
        cleaned_state = {
            key[6:]: val.to(GET_DTYPE()).to(self.device)
            for key, val in state_dict.items()
        }
        del raw_state, state_dict
        return cleaned_state

    def _load_quant_ckpt(self, unified_dtype, sensitive_layer):
        base_state = super()._load_quant_ckpt(unified_dtype, sensitive_layer)
        # Remove leading 'module.' prefix only
        optimized_state = {k[6:]: v for k, v in base_state.items()}
        del base_state
        return optimized_state

    def _init_infer_class(self):
        self.pre_infer_obj = WanSFPreInfer
        self.post_infer_obj = WanPostInfer
        self.transformer_infer_obj = WanSFTransformerInfer

    @torch.no_grad()
    def infer(self, inputs):
        if self.cpu_offload:
            if self.offload_granularity == "model" and self.scheduler.step_index == 0:
                self.cuda()
            elif self.offload_granularity != "model":
                self.pre_weight.cuda()
                self.transformer_weights.non_block_cuda()

        # Compute current frame range based on segment index and block size
        seg_idx = self.scheduler.seg_index
        frames_per_seg = self.scheduler.num_frame_per_block
        start_frame = seg_idx * frames_per_seg
        end_frame = (seg_idx + 1) * frames_per_seg

        # Predict noise for both condition and unconditional paths
        predicted_noise = self._infer_cond_uncond(inputs, infer_condition=True)
        self.scheduler.noise_pred[:, start_frame:end_frame] = predicted_noise

        if self.cpu_offload:
            final_step = self.scheduler.infer_steps - 1
            if self.offload_granularity == "model" and self.scheduler.step_index == final_step:
                self.cpu()
            elif self.offload_granularity != "model":
                self.pre_weight.cpu()
                self.transformer_weights.non_block_cpu()

