import logging

logger = logging.getLogger(__name__)

class PerformanceValidator:
    @staticmethod
    def instantiate_if_needed(config):
        if config.run_ci and (config.ci_validation_metric is not None):
            return PerformanceValidator(config)
        return None

    def __init__(self, config):
        self.config = config
        self._validation_passed = False

    def evaluate(self, results: dict[str, float]):
        measured_value = results.get(self.config.ci_validation_metric)
        assert measured_value is not None, f"{results=} {self.config.ci_validation_metric=}"
        validation_result = measured_value >= self.config.ci_validation_threshold
        logger.info(f"[PerformanceValidator] {validation_result=} {measured_value=} {self.config.ci_validation_threshold=}")
        self._validation_passed |= validation_result

    def finalize(self):
        assert self._validation_passed, "[PerformanceValidator] accuracy requirement not met"
        logger.info("[PerformanceValidator] passed final verification")

