from langchain_core.messages import AIMessage, BaseMessage, HumanMessage

def convert_message_to_string(message: BaseMessage) -> str:
    """Convert a LangChain message to a formatted string with role and content."""
    if isinstance(message, HumanMessage):
        speaker = 'User'
    elif isinstance(message, AIMessage):
        speaker = 'AI'
    else:
        raise ValueError(f"Unexpected message type: {type(message)}")
    return f"{speaker}: {message.content}"

def format_conversation_history(messages: list[BaseMessage]) -> str:
    """Format a list of LangChain messages into a single string with each message on a new line."""
    lines = []
    for msg in messages:
        lines.append(convert_message_to_string(msg))
    return '\n'.join(lines)

def enclose_in_curly_brackets(text: str) -> str:
    """Enclose the input text within curly braces. Useful for dynamic field substitution in prompt templates."""
    return '{' + text + '}'

import json
import sys
from pypdf import PdfReader, PdfWriter
from extract_form_field_info import get_field_info

def populate_pdf_form(input_pdf_path: str, fields_json_path: str, output_pdf_path: str):
    with open(fields_json_path) as file:
        form_fields = json.load(file)

    organized_fields = {}
    for field in form_fields:
        if "value" in field:
            field_identifier = field["field_id"]
            page_number = field["page"]
            if page_number not in organized_fields:
                organized_fields[page_number] = {}
            organized_fields[page_number][field_identifier] = field["value"]

    reader = PdfReader(input_pdf_path)
    error_occurred = False

    # Extract and index field information
    form_field_metadata = get_field_info(reader)
    field_index = {f["field_id"]: f for f in form_field_metadata}

    # Validate all provided fields
    for field in form_fields:
        existing_field = field_index.get(field["field_id"])
        if not existing_field:
            error_occurred = True
            print(f"ERROR: `{field['field_id']}` is not a valid field ID")
        elif field["page"] != existing_field["page"]:
            error_occurred = True
            print(f"ERROR: Incorrect page number for `{field['field_id']}` (got {field['page']}, expected {existing_field['page']})")
        else:
            if "value" in field:
                validation_issue = validate_field_value(existing_field, field["value"])
                if validation_issue:
                    print(validation_issue)
                    error_occurred = True

    if error_occurred:
        sys.exit(1)

    # Prepare writer with cloned PDF
    writer = PdfWriter(clone_from=reader)

    # Fill form fields per page
    for page_num, field_values in organized_fields.items():
        writer.update_page_form_field_values(
            writer.pages[page_num - 1], 
            field_values, 
            auto_regenerate=False
        )

    # Ensure appearance streams are regenerated
    writer.set_need_appearances_writer(True)

    # Write output PDF
    with open(output_pdf_path, "wb") as output_file:
        writer.write(output_file)

def validate_field_value(field_metadata, submitted_value):
    field_type = field_metadata["type"]
    field_name = field_metadata["field_id"]

    if field_type == "checkbox":
        checked_val = field_metadata["checked_value"]
        unchecked_val = field_metadata["unchecked_value"]
        if submitted_value != checked_val and submitted_value != unchecked_val:
            return f'ERROR: Invalid value "{submitted_value}" for checkbox field "{field_name}". The checked value is "{checked_val}" and the unchecked value is "{unchecked_val}"'

    elif field_type == "radio_group":
        available_options = [opt["value"] for opt in field_metadata["radio_options"]]
        if submitted_value not in available_options:
            return f'ERROR: Invalid value "{submitted_value}" for radio group field "{field_name}". Valid values are: {available_options}'

    elif field_type == "choice":
        available_choices = [opt["value"] for opt in field_metadata["choice_options"]]
        if submitted_value not in available_choices:
            return f'ERROR: Invalid value "{submitted_value}" for choice field "{field_name}". Valid values are: {available_choices}'

    return None

def apply_pypdf_patch():
    from pypdf.generic import DictionaryObject
    from pypdf.constants import FieldDictionaryAttributes

    original_get_inherited = DictionaryObject.get_inherited

    def patched_get_inherited(self, key: str, default=None):
        result = original_get_inherited(self, key, default)
        if key == FieldDictionaryAttributes.Opt:
            if isinstance(result, list) and all(isinstance(v, list) and len(v) == 2 for v in result):
                result = [r[0] for r in result]
        return result

    DictionaryObject.get_inherited = patched_get_inherited

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    apply_pypdf_patch()
    input_pdf_file = sys.argv[1]
    fields_json_file = sys.argv[2]
    output_pdf_file = sys.argv[3]

    populate_pdf_form(input_pdf_file, fields_json_file, output_pdf_file)

def format_cost(value: float) -> str:
    """
    Format cost with smart precision to show meaningful values even for small amounts.
    Args:
        value: The cost value to format (must be a numeric value)
    Returns:
        Formatted cost string with appropriate precision
    """
    if value == 0.0:
        return "$0.00"
    elif abs(value) >= 1e-2:
        return f"${value:.2f}"
    elif abs(value) >= 1e-3:
        return f"${value:.2g}"
    else:
        return f"${value:.1e}"

import torch
from graph_net.optional import Optional
from torch.profiler import profile, record_function, ProfilerActivity

class KernelCounterModule(torch.nn.Module):
    def __init__(self, base_model, kernel_counter_storage: Optional):
        super().__init__()
        self.base_model = base_model
        self.optimized_model = torch.compile(self.base_model)
        self.kernel_counter_storage = kernel_counter_storage

    def forward(self, *args, **kwargs):
        # Handle both positional and keyword arguments
        if kwargs:
            outputs, kernel_count = measure_kernel_launches(
                self.optimized_model, args, kwargs
            )
        else:
            outputs, kernel_count = measure_kernel_launches(
                self.optimized_model, args
            )

        # Store the measured kernel count in the optional container
        self.kernel_counter_storage.reset(Optional(kernel_count))
        return outputs

def measure_kernel_launches(model, inputs, kw_inputs=None) -> tuple:
    """
    Measure the number of CUDA kernel launches during model execution.

    Returns:
        tuple: (model_outputs, total_kernel_launch_count)
    """
    model.eval()

    def execute_inference():
        if kw_inputs is not None:
            return model(*inputs, **kw_inputs)
        elif isinstance(inputs, dict):
            return model(**inputs)
        elif isinstance(inputs, (list, tuple)):
            return model(*inputs)
        else:
            raise TypeError(f"Unsupported input type: {type(inputs)}")

    # Perform warm-up runs to stabilize performance measurements
    for _ in range(3):
        execute_inference()

    # Profile the execution to capture kernel launch events
    with profile(
        activities=[ProfilerActivity.CUDA, ProfilerActivity.CPU],
        record_shapes=True,
        use_cuda=True  # Explicitly enable CUDA profiling
    ) as profiler:
        with record_function("inference_phase"):
            model_outputs = execute_inference()

    # Aggregate profiling events and count kernel launches
    event_stats = profiler.key_averages()
    kernel_launches = 0

    for event in event_stats:
        # Check for both possible kernel launch event names
        if "LaunchKernel" in event.key:
            kernel_launches += event.count

    return model_outputs, kernel_launches

