# Custom optional type implementation with safe unwrapping

from typing import TypeVar, Generic, Union

T = TypeVar("T")

class Maybe(Generic[T]):
    def __init__(self, data: Union[T, None] = None):
        self._data = data

    def assign(self, other):
        assert isinstance(other, Maybe)
        self._data = other._data

    def has_value(self) -> bool:
        return self._data is not None

    def get(self) -> T:
        """Extracts the contained value or raises an exception if empty."""
        if self._data is None:
            raise RuntimeError("Cannot extract value from empty Maybe!")
        return self._data

    def get_or_else(self, fallback: T) -> T:
        """Provides a fallback value when the Maybe is empty."""
        return self._data if self._data is not None else fallback

# Utility functions for password hashing and JWT token management

import bcrypt
import jwt
from datetime import datetime, timedelta, timezone
from api.constants import OSS_JWT_EXPIRY_HOURS, OSS_JWT_SECRET


def hash_user_password(plain_password: str) -> str:
    """Generate a bcrypt hash for the given password."""
    salt = bcrypt.gensalt()
    hashed_bytes = bcrypt.hashpw(plain_password.encode("utf-8"), salt)
    return hashed_bytes.decode("utf-8")


def check_user_password(plain_password: str, stored_hash: str) -> bool:
    """Verify if the provided password matches the stored hash."""
    try:
        return bcrypt.checkpw(
            plain_password.encode("utf-8"),
            stored_hash.encode("utf-8")
        )
    except (ValueError, TypeError):
        return False


def generate_auth_token(user_identifier: int, user_email: str) -> str:
    """Create a signed JWT token with expiration and issuer information."""
    current_time = datetime.now(timezone.utc)
    token_payload = {
        "uid": str(user_identifier),
        "email_address": user_email,
        "expiration_time": current_time + timedelta(hours=OSS_JWT_EXPIRY_HOURS),
        "issued_at": current_time,
    }
    return jwt.encode(token_payload, OSS_JWT_SECRET, algorithm="HS256")


def parse_auth_token(auth_token: str) -> dict:
    """Decode and validate a JWT token, returning its payload."""
    return jwt.decode(auth_token, OSS_JWT_SECRET, algorithms=["HS256"])

