def _fetch_url_content(url: str, timeout_seconds: float = 10.0) -> str:
    """Fetch content from URL with custom User-Agent header."""
    request = urllib.request.Request(
        url, 
        headers={"User-Agent": "invest-agent/1.0"}
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
            return response.read().decode("utf-8", errors="replace")
    except Exception:
        raise RuntimeError(f"Failed to fetch URL: {url}")

def _normalize_ticker_symbol(ticker: Optional[str]) -> str:
    """Normalize ticker symbol for Stooq compatibility."""
    normalized = (ticker or "").strip().lower()

    # Remove caret prefix for indices
    if normalized.startswith("^"):
        normalized = normalized[1:]

    # Add .us suffix for US equities/ETFs without domain
    if "." not in normalized:
        normalized = f"{normalized}.us"

    return normalized

def _parse_numeric_value(value: Optional[str]) -> Optional[float]:
    """Safely parse string to float, handling missing values."""
    if value is None or value.strip() == "" or value.strip().upper() == "N/A":
        return None
    try:
        return float(value)
    except (ValueError, TypeError):
        return None

def get_quote(ticker: str) -> Dict[str, Any]:
    """Retrieve latest market quote for a given ticker from Stooq."""
    fetch_time = _current_utc_timestamp()
    symbol = _normalize_ticker_symbol(ticker)
    endpoint = f"https://stooq.com/q/l/?s={symbol}&f=sd2t2ohlcv&h&e=csv"

    try:
        raw_data = _fetch_url_content(endpoint)
        parsed_rows = list(csv.DictReader(io.StringIO(raw_data)))

        if not parsed_rows:
            raise ValueError("No data returned from API")

        record = parsed_rows[0]

        # Extract and convert numeric fields
        close_price = _parse_numeric_value(record.get("Close"))
        low_price = _parse_numeric_value(record.get("Low"))
        high_price = _parse_numeric_value(record.get("High"))

        # Construct day range if either low or high available
        daily_range = None
        if low_price is not None or high_price is not None:
            daily_range = {"low": low_price, "high": high_price}

        # Combine date and time fields, fallback to fetch timestamp
        quote_datetime = (
            f"{record.get('Date', '')}T{record.get('Time', '')}".strip("T") 
            or fetch_time
        )

        return {
            "ticker": ticker,
            "price": close_price,
            "day_range": daily_range,
            "timestamp": quote_datetime,
            "source": "stooq",
            "fetched_at": fetch_time,
        }

    except Exception as error:
        return {
            "ticker": ticker,
            "price": None,
            "day_range": None,
            "timestamp": fetch_time,
            "source": "stooq",
            "error": f"public quote failed: {str(error)}",
        }

def get_daily_history(ticker: str, max_records: int = 60) -> List[Tuple[str, float]]:
    """Fetch historical daily closing prices in ascending order."""
    symbol = _normalize_ticker_symbol(ticker)
    endpoint = f"https://stooq.com/q/d/l/?s={symbol}&i=d"

    raw_csv = _fetch_url_content(endpoint)
    records = list(csv.DictReader(io.StringIO(raw_csv)))

    result = []
    # Process only the last max_records entries
    for row in records[-max_records:]:
        try:
            date_str = row["Date"]
            close_val = float(row["Close"])
            result.append((date_str, close_val))
        except (KeyError, ValueError, TypeError):
            continue

    return result

def realized_volatility_20d(ticker: str) -> Dict[str, Any]:
    """Calculate 20-day realized volatility using daily closing prices."""
    fetch_time = _current_utc_timestamp()

    try:
        # Get enough history to compute 20-day volatility (need at least 21 days)
        price_history = get_daily_history(ticker, limit=40)

        if len(price_history) < 21:
            raise ValueError("Insufficient historical data points")

        # Extract closing prices
        closing_prices = [price for _, price in price_history]

        # Calculate log returns
        log_returns = [
            math.log(closing_prices[i] / closing_prices[i - 1])
            for i in range(1, len(closing_prices))
        ]

        # Use last 20 returns for calculation
        recent_returns = log_returns[-20:]

        # Compute sample variance
        mean_return = sum(recent_returns) / len(recent_returns)
        variance = sum((r - mean_return) ** 2 for r in recent_returns) / (len(recent_returns) - 1)

        # Annualize volatility (assuming 252 trading days)
        annualized_vol = math.sqrt(variance) * math.sqrt(252.0)

        return {
            "ticker": ticker,
            "rv20": annualized_vol,
            "timestamp": fetch_time,
            "source": "stooq",
        }

    except Exception as exception:
        return {
            "ticker": ticker,
            "rv20": None,
            "timestamp": fetch_time,
            "source": "stooq",
            "error": str(exception),
        }

# Utility functions for mapping and string replacement

def invert_and_reverse_dict(input_dict):
    if input_dict:
        # Create a new dictionary with keys and values swapped
        inverted = {v: k for k, v in input_dict.items()}
        # Return an OrderedDict with items in reversed order
        from collections import OrderedDict
        return OrderedDict(reversed(list(inverted.items())))
    else:
        return None

def substitute_substrings(original_text, substitution_rules):
    result = original_text
    for target, replacement in substitution_rules.items():
        if len(target) > 1:
            result = result.replace(target, replacement)
    return result

# Decorator to verify method availability in converter classes
def validate_method_availability(method_func):
    from functools import wraps

    @wraps(method_func)
    def guarded_call(instance, *arguments, **options):
        # Retrieve the set of supported methods from the instance
        allowed_methods = getattr(instance, '_supported_methods', set())
        # Get version information
        release_version = getattr(instance, 'version', '')
        # Determine the name of the method being invoked
        called_method = method_func.__name__

        # Validate that the method is permitted
        if called_method not in allowed_methods:
            raise NotImplementedError(
                f"Method '{called_method}' is unsupported in Converter '{instance.__class__.__name__}.{release_version}'."
            )

        return method_func(instance, *arguments, **options)

    return guarded_call

# Decorator to validate parallel configuration compatibility
def validate_parallel_configuration(method_func):
    from functools import wraps

    @wraps(method_func)
    def guarded_call(instance, *arguments, **options):
        release_version = getattr(instance, 'version', '')

        # Extract configuration object (from keyword args or positional args)
        config = options.get('cfg', None) or arguments[1] if len(arguments) > 1 else None

        # Extract parallelism parameters
        tensor_parallel_degree = config.tp_size
        pipeline_layer_distribution = config.pp_layers

        # Validate tensor parallel support
        if tensor_parallel_degree > 1 and not getattr(instance, '_enable_tp', False):
            raise NotImplementedError(
                f"Tensor Parallel execution is unavailable in Converter '{instance.__class__.__name__}.{release_version}'"
            )

        # Validate pipeline parallel support
        if len(pipeline_layer_distribution) > 1 and not getattr(instance, '_enable_pp', False):
            raise NotImplementedError(
                f"Pipeline Parallel execution is unavailable in Converter '{instance.__class__.__name__}.{release_version}'"
            )

        # Validate virtual pipeline parallel support
        if (len(pipeline_layer_distribution) > 1 and 
            isinstance(pipeline_layer_distribution[0], list) and 
            not getattr(instance, '_enable_vpp', False)):
            raise NotImplementedError(
                f"Virtual Pipeline Parallel execution is unavailable in Converter '{instance.__class__.__name__}.{release_version}'"
            )

        return method_func(instance, *arguments, **options)

    return guarded_call

