# Convert DALL-E checkpoint to Hugging Face FlavaImageCodebook format

import argparse
import os
import torch
from transformers import FlavaImageCodebook, FlavaImageCodebookConfig

def replace_last_occurrence(text, target, replacement):
    parts = text.rsplit(target, 1)
    return replacement.join(parts)

def compute_model_size(state_dict):
    # Skip parameters related to encoder.embeddings due to duplication in original FLAVA
    total = 0.0
    for name, param in state_dict.items():
        if "encoder.embeddings" not in name:
            total += param.float().sum()
    return total

def transform_state_dict(original_dict):
    updated = {}
    group_names = ["group_1", "group_2", "group_3", "group_4"]

    for original_key, tensor_value in original_dict.items():
        modified_key = original_key

        # Adjust group key naming convention
        for group_name in group_names:
            if group_name in modified_key:
                modified_key = modified_key.replace(f"{group_name}.", f"{group_name}.group.")

        # Fix res_path path naming
        if "res_path" in modified_key:
            modified_key = modified_key.replace("res_path.", "res_path.path.")

        # Standardize weight and bias suffixes
        if modified_key.endswith(".w"):
            modified_key = replace_last_occurrence(modified_key, ".w", ".weight")
        if modified_key.endswith(".b"):
            modified_key = replace_last_occurrence(modified_key, ".b", ".bias")

        # Store with float precision
        updated[modified_key] = tensor_value.float()

    return updated

@torch.no_grad()
def convert_dalle_to_hf(dalle_checkpoint_url, output_directory, hf_config_path=None, export_model=True):
    """
    Adapt DALL-E model weights to match Hugging Face FlavaImageCodebook structure.
    """
    from dall_e import Encoder

    # Load DALL-E encoder checkpoint
    dalle_encoder = Encoder()

    if os.path.isfile(dalle_checkpoint_url):
        raw_checkpoint = torch.load(dalle_checkpoint_url, map_location="cpu")
    else:
        raw_checkpoint = torch.hub.load_state_dict_from_url(dalle_checkpoint_url, map_location="cpu")

    # Extract state dict if needed
    if hasattr(raw_checkpoint, "state_dict"):
        raw_checkpoint = raw_checkpoint.state_dict()

    # Initialize HF config and model
    if hf_config_path is not None:
        hf_config = FlavaImageCodebookConfig.from_pretrained(hf_config_path)
    else:
        hf_config = FlavaImageCodebookConfig()

    hf_flava_model = FlavaImageCodebook(hf_config).eval()

    # Apply transformations to align keys and data types
    transformed_weights = transform_state_dict(raw_checkpoint)
    hf_flava_model.load_state_dict(transformed_weights)

    # Validate parameter counts match (accounting for skipped embeddings)
    hf_params = compute_model_size(hf_flava_model.state_dict())
    original_params = compute_model_size(raw_checkpoint)

    assert torch.allclose(hf_params, original_params, atol=1e-3), \
        "Parameter count mismatch after conversion"

    # Save or return model weights
    if export_model:
        hf_flava_model.save_pretrained(output_directory)
    else:
        return hf_flava_model.state_dict()

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Convert DALL-E checkpoint to Hugging Face Flava format")
    parser.add_argument("--pytorch_dump_folder_path", type=str, required=True,
                        help="Directory to save the converted PyTorch model")
    parser.add_argument("--checkpoint_path", type=str, required=True,
                        help="Path or URL to DALL-E checkpoint")
    parser.add_argument("--config_path", type=str, default=None,
                        help="Optional path to Hugging Face config.json")

    arguments = parser.parse_args()
    convert_dalle_to_hf(arguments.checkpoint_path, arguments.pytorch_dump_folder_path, 
                       arguments.config_path)

# Security scanning tool for agent skill directories
import os
import re
import json
import argparse
import sys

# Configuration constants
PATTERN_FILE_PATH = os.path.join(os.path.dirname(__file__), "../references/threat_patterns.json")

def fetch_security_patterns(filepath):
    try:
        with open(filepath, "r") as pattern_file:
            return json.load(pattern_file)
    except Exception as error:
        print(f"Failed to load security patterns: {error}")
        sys.exit(1)

def scan_directory(scan_location, threat_patterns):
    audit_result = {
        "location": scan_location,
        "detected_issues": [],
        "risk_level": 0,
        "classification": "CLEAN"
    }

    if not os.path.isdir(scan_location):
        print(f"Error: {scan_location} is not a valid directory.")
        sys.exit(1)

    for current_dir, subdirs, filenames in os.walk(scan_location):
        for filename in filenames:
            # Exclude hidden files and certain binary/compiled extensions
            if filename.startswith('.') or filename.endswith(('.pyc', '.skill', '.zip')):
                continue

            full_path = os.path.join(current_dir, filename)
            try:
                with open(full_path, "r", encoding="utf-8", errors="ignore") as file_handle:
                    file_content = file_handle.read()

                    for threat_type, regex_patterns in threat_patterns.items():
                        for regex_rule in regex_patterns:
                            if re.search(regex_rule, file_content, re.IGNORECASE):
                                issue_record = {
                                    "filename": os.path.relpath(full_path, scan_location),
                                    "threat_category": threat_type,
                                    "matched_regex": regex_rule
                                }
                                audit_result["detected_issues"].append(issue_record)
                                # Assign risk points: 20 per match, no cap per category
                                audit_result["risk_level"] += 20
            except Exception as read_error:
                print(f"Unable to process {full_path}: {read_error}")

    # Determine overall risk classification based on accumulated score
    if audit_result["risk_level"] >= 80:
        audit_result["classification"] = "HIGH_RISK"
    elif audit_result["risk_level"] >= 40:
        audit_result["classification"] = "MEDIUM_RISK"
    elif audit_result["risk_level"] > 0:
        audit_result["classification"] = "LOW_RISK"

    return audit_result

def execute_audit():
    parser = argparse.ArgumentParser(description="ClawGuard: Analyze agent skills for potential security threats.")
    parser.add_argument("directory", help="The directory containing skills to be analyzed.")
    parser.add_argument("--json-output", action="store_true", dest="json_format", help="Produce output in JSON format.")
    arguments = parser.parse_args()

    security_patterns = fetch_security_patterns(PATTERN_FILE_PATH)
    audit_summary = scan_directory(arguments.directory, security_patterns)

    if arguments.json_format:
        print(json.dumps(audit_summary, indent=2))
    else:
        print(f"\n--- ClawGuard Security Analysis ---")
        print(f"Scanned Location: {audit_summary['location']}")
        print(f"Risk Classification: {audit_summary['classification']}")
        print(f"Risk Level: {audit_summary['risk_level']}")
        print(f"Issues Found: {len(audit_summary['detected_issues'])}")
        print("-" * 35)
        for issue in audit_summary['detected_issues']:
            print(f"[{issue['threat_category'].upper()}] in {issue['filename']}: Pattern '{issue['matched_regex']}'")
        print("-" * 35 + "\n")

if __name__ == "__main__":
    execute_audit()

import socket
import time
from typing import List, Tuple, Optional
from src.models.config import Config
from src.utils.logger import setup_logger

logger = setup_logger(__name__)

def get_address_candidates(host: str, port: int) -> List[Tuple[int, Tuple]]:
    """Attempt to resolve host to potential connection endpoints."""
    try:
        addr_info = socket.getaddrinfo(
            host, port, type=socket.SOCK_STREAM
        )
        return [
            (family, sockaddr)
            for family, _, _, _, sockaddr in addr_info
        ]
    except socket.gaierror:
        return []

def measure_tcp_connect_time(
    target_host: str, 
    target_port: int, 
    max_wait: float, 
    attempt_limit: int
) -> Optional[int]:
    """Estimate TCP handshake duration in milliseconds or None if unreachable."""
    candidates = get_address_candidates(target_host, target_port)
    if not candidates:
        return None

    attempts_remaining = attempt_limit + 1
    while attempts_remaining > 0:
        for sock_type, address in candidates:
            begin_measurement = time.perf_counter()
            try:
                with socket.socket(sock_type, socket.SOCK_STREAM) as connection:
                    connection.settimeout(max_wait)
                    connection.connect(address)
                elapsed = time.perf_counter() - begin_measurement
                return int(elapsed * 1000)
            except (socket.timeout, OSError) as error:
                logger.debug("TCP connection failed: %s", error)
                continue
        attempts_remaining -= 1

    return None

class ConfigurationValidator:
    """Validates V2Ray configurations by checking network connectivity."""

    def __init__(self, connection_timeout: float, retry_count: int, latency_limit_ms: int) -> None:
        self.connection_timeout = connection_timeout
        self.retry_count = retry_count
        self.latency_limit_ms = latency_limit_ms

    def validate(self, config: Config) -> Config:
        """Evaluate configuration and attach latency if it meets performance criteria."""
        measured_latency = measure_tcp_connect_time(
            config.host, 
            config.port, 
            self.connection_timeout, 
            self.retry_count
        )

        if measured_latency is not None and measured_latency < self.latency_limit_ms:
            config.latency_ms = measured_latency

        return config

