from ucagent.checkers.base import Checker

class MyCustomChecker(Checker):
    def __init__(self, joke_file, min_length, max_length, **kwargs):
        self.joke_file = joke_file
        self.min_length = min_length
        self.max_length = max_length
        self.set_human_check_needed(kwargs.get("need_human_check", False))

    def do_check(self, timeout=0, **kwargs) -> tuple[bool, object]:
        """A checker that validates a joke file for content and length."""
        joke_path = self.get_path(self.joke_file)
        try:
            with open(joke_path, 'r', encoding='utf-8') as f:
                joke_text = f.read().strip()

            # Check if "jimmy" appears in the joke (case-insensitive)
            if "jimmy" not in joke_text.lower():
                return False, {"error": "Missing required name 'Jimmy' in the joke."}

            # Validate minimum length constraint
            if len(joke_text) < self.min_length:
                return False, {"error": f"Joke too short. Minimum allowed length is {self.min_length}."}

            # Validate maximum length constraint
            if len(joke_text) > self.max_length:
                return False, {"error": f"Joke too long. Maximum allowed length is {self.max_length}."}

            return True, {"joke": joke_text}
        except Exception as e:
            return False, {"error": str(e)}

import os
import binascii
from safetensors import safe_open
import torch
from diffusers.pipelines.stable_diffusion.convert_from_ckpt import convert_ldm_unet_checkpoint, convert_ldm_vae_checkpoint

def generate_random_name(length=8, extension=''):
    # Generate a random hexadecimal string as base name
    random_bytes = os.urandom(length)
    hex_string = binascii.hexlify(random_bytes).decode('utf-8')

    # Handle optional file extension
    if extension:
        if not extension.startswith('.'):
            extension = '.' + extension
        hex_string += extension

    return hex_string

def infinite_iterator(data_loader):
    # Create an infinite loop over the data loader
    while True:
        for item in data_loader:
            yield item

def check_exists(value):
    # Check if value is not None
    return value is not None

def pass_through(x):
    # Identity function - returns input unchanged
    return x

def merge_dreambooth_lora_weights(unet_model, vae_model=None, checkpoint_path=None, blend_factor=1.0, base_model_path=""):
    # Return early if no checkpoint path provided
    if checkpoint_path is None:
        return unet_model

    loaded_state_dict = {}

    # Load checkpoint based on file extension
    if checkpoint_path.endswith(".ckpt"):
        checkpoint_data = torch.load(checkpoint_path, map_location="cpu")
        loaded_state_dict = checkpoint_data.get("state_dict", {})
    elif checkpoint_path.endswith(".safetensors"):
        with safe_open(checkpoint_path, framework="pt", device="cpu") as f:
            loaded_state_dict = {key: f.get_tensor(key) for key in f.keys()}

        # Determine if this is a LoRA model by checking all keys contain "lora"
        is_lora_format = all("lora" in key for key in loaded_state_dict.keys())

        # If not LoRA format, use directly; otherwise load base model
        if not is_lora_format:
            base_state_dict = loaded_state_dict
        else:
            base_state_dict = {}
            with safe_open(base_model_path, framework="pt", device="cpu") as f:
                base_state_dict = {key: f.get_tensor(key) for key in f.keys()}

    # Convert UNet checkpoint and apply blending
    converted_unet_dict = convert_ldm_unet_checkpoint(base_state_dict, unet_model.config)
    current_unet_state = unet_model.state_dict()

    # Apply weighted interpolation between converted weights and current weights
    for param_name in converted_unet_dict:
        converted_unet_dict[param_name] = (
            blend_factor * converted_unet_dict[param_name] + 
            (1.0 - blend_factor) * current_unet_state[param_name]
        )

    # Load updated UNet weights (allow missing keys)
    unet_model.load_state_dict(converted_unet_dict, strict=False)

    # Process VAE if provided
    if vae_model is not None:
        converted_vae_dict = convert_ldm_vae_checkpoint(base_state_dict, vae_model.config)
        vae_model.load_state_dict(converted_vae_dict)

    return unet_model, vae_model

