        texts.append(gf.components.text(str(i), layer="M1_DRAW"))

    # Arrange the text components in a 2x3 grid with specified spacing
    return gf.grid(texts, shape=(2, 3), spacing=(10, 10))

from fastapi import APIRouter, Depends, HTTPException, Query, Body, status
from typing import List, Optional, Dict, Any
from ..services.feature_flags import get_feature_service
from ..routers.auth import require_admin
from ..models import User

router = APIRouter(prefix="/flags", tags=["Feature Flags"])

@router.get("/")
async def retrieve_all_flags(current_user: User = Depends(require_admin)):
    """Fetch and return all feature flags stored in Consul."""
    flag_service = get_feature_service()
    return flag_service.fetch_all_flags()

@router.post("/")
async def manage_flag(
    feature_name: str = Query(...),
    settings: Dict[str, Any] = Body(...),  # {enabled: bool, rollout_percentage: int, tenant_overrides: {...}}
    current_user: User = Depends(require_admin)
):
    """Admin-only endpoint to create or modify a feature flag configuration."""
    flag_service = get_feature_service()

    # Validate required fields in the configuration
    if 'enabled' not in settings or not isinstance(settings['enabled'], bool):
        raise HTTPException(status_code=400, detail="'enabled' must be a boolean value")

    result = flag_service.apply_flag(feature_name, settings)
    if not result:
        raise HTTPException(status_code=500, detail="Unable to persist changes to Consul")

    return {"message": f"Flag '{feature_name}' has been updated.", "settings": settings}

@router.delete("/")
async def remove_flag(
    feature_name: str = Query(...),
    current_user: User = Depends(require_admin)
):
    """Admin-only endpoint to delete a feature flag completely."""
    flag_service = get_feature_service()
    try:
        # Delete the key from Consul's KV store
        flag_service.client.kv.delete(f"soulsense/features/{feature_name}")
        # Clear the associated cache to reflect the change immediately
        flag_service.invalidate_cache()
        return {"message": f"Flag '{feature_name}' has been removed."}
    except Exception as error:
        raise HTTPException(status_code=500, detail=str(error))

